        #region Tool Click Handlers

        private void btn1_Pen_Click(object sender, RoutedEventArgs e)
        {
            var button = sender as Button;
            DateTime currentTime = DateTime.Now;

            // Check for double-click (kept for backward compatibility)
            bool isDoubleClick = (currentTime - _lastPenClickTime) <= DoubleClickInterval;
            _lastPenClickTime = currentTime;

            // If already in Pen mode → single click opens SubMenu directly
            bool isPenAlreadyActive = (_selectedTool == button);

            if (isDoubleClick || isPenAlreadyActive)
            {
                // Already selected OR double-clicked: Show pen settings menu
                ShowPenSettingsMenu(button);
            }
            else
            {
                // First click: Activate pen tool
                DeactivateAllTools();
                CloseAllSubmenus();

                if (_activeSubMenu != null && _activeSubMenuButton == button)
                {
                    CloseActiveSubMenu();
                    return;
                }

                SelectTool(button);
                HideWelcomeState();

                // Apply saved pen settings immediately
                EnableDrawingMode(_savedBrushType, _savedPenSize, _savedPenColor);
            }
        }

        private void ShowPenSettingsMenu(Button button)
        {
            // If clicking the same button that opened current submenu, just close it
            if (_activeSubMenu != null && _activeSubMenuButton == button)
            {
                CloseActiveSubMenu();
                return;
            }
            
            SelectTool(button);
            HideWelcomeState();
            
            // Open SubMenu Pen
            var penMenu = new Form2_1_SubMenuPen();
            
            // Set current settings to show saved values
            penMenu.BrushType = _savedBrushType;
            penMenu.PenSize = _savedPenSize;
            penMenu.PenColor = _savedPenColor;
            
            _activeSubMenu = penMenu;
            _activeSubMenuButton = button;
            
            // Position menu above toolbar, centered horizontally
            var windowPosition = this.PointToScreen(new Point(0, 0));
            var windowWidth = this.ActualWidth;
            var windowHeight = this.ActualHeight;
            var toolbarHeight = 80; // Toolbar height from XAML
            
            penMenu.Left = windowPosition.X + (windowWidth - penMenu.Width) / 2; // Centered
            penMenu.Top = windowPosition.Y + windowHeight - toolbarHeight - penMenu.Height - 10; // 10px above toolbar
            
            // Handle window closed event
            penMenu.Closed += (s, args) =>
            {
                // Save settings after dialog closes
                _savedBrushType = penMenu.BrushType;
                _savedPenSize = penMenu.PenSize;
                _savedPenColor = penMenu.PenColor;
                
                // Apply pen settings
                EnableDrawingMode(_savedBrushType, _savedPenSize, _savedPenColor);
                
                // Cleanup
                _activeSubMenu = null;
                _activeSubMenuButton = null;
                
                // Reset button appearance
                if (button != null)
                {
                    button.Background = new SolidColorBrush(Color.FromRgb(241, 242, 246)); // #F1F2F6
                }
                _selectedTool = null;
            };
            
            penMenu.Show();
        }

