        /// <summary>
        /// QC_4.2_STATE_GUARD: Kiểm tra element xem có thuộc danh sách System UI / System Overlay hay không.
        /// </summary>
        private bool IsSystemElement(UIElement element)
        {
            if (element == null) return false;
            if (_systemUIControls.Contains(element)) return true;
            if (element == _selectionBox || element == _contextToolbar || 
                element == _thicknessPicker || element == _colorPicker || 
                element == _moreMenu || element == _floatingTouchKeyboard ||
                element == _eraserPreview || element == _rectangleSelectionPreview ||
                element == _zoomAreaPreview || element == _dragErasePreview ||
                element == _currentSpotlightOverlay || element == _smartStatusBadge ||
                element == panelWelcomeState)
                return true;

            if (Panel.GetZIndex(element) >= ZIndexConstants.SystemUIBase) return true;

            return false;
        }

        private void ShowEraserMenuInternal(Button button)
        {
            
            // Open SubMenu Eraser
            var eraserMenu = new Form2_2_SubMenuEraser();
            
            // Set current settings to show saved values
            eraserMenu.EraserMode = _savedEraserMode;
            eraserMenu.EraserSize = _savedEraserSize;
            
            _activeSubMenu = eraserMenu;
            _activeSubMenuButton = button;
            
            // Position menu above toolbar, centered horizontally
            var windowPosition = this.PointToScreen(new Point(0, 0));
            var windowWidth = this.ActualWidth;
            var windowHeight = this.ActualHeight;
            var toolbarHeight = 80; // Toolbar height from XAML
            
            eraserMenu.Left = windowPosition.X + (windowWidth - eraserMenu.Width) / 2; // Centered
            eraserMenu.Top = windowPosition.Y + windowHeight - toolbarHeight - eraserMenu.Height - 10; // 10px above toolbar
            
            // ✅ QC_4.2_SMART_TOUCH_SUBMENU_SYNC: Áp dụng chế độ Tẩy NGAY LẬP TỨC khi giáo viên bấm nút trên SubMenu
            eraserMenu.SettingsChanged += (s, args) =>
            {
                _savedEraserMode = eraserMenu.EraserMode;
                _savedEraserSize = eraserMenu.EraserSize;
                if (_savedEraserMode != "ClearAll")
                {
                    EnableEraserMode(_savedEraserSize, _savedEraserMode);
                }
            };

            // Handle window closed event
            eraserMenu.Closed += (s, args) =>
            {
                // Save settings after dialog closes
                _savedEraserMode = eraserMenu.EraserMode;
                _savedEraserSize = eraserMenu.EraserSize;
                
                // Check if user selected "Clear All" mode - execute immediately
                if (_savedEraserMode == "ClearAll")
                {
                    // [BUG_CLEARALL_DESTROYS_UI] Reset selection state trước khi clear
                    _selectionBox?.Detach();
                    _selectionManager?.DeselectAll();
                    _objectSelectionMode = false;

                    // Clear all content except background layers AND system UI controls
                    var elementsToRemove = new System.Collections.Generic.List<UIElement>();
                    foreach (UIElement element in MainInteractiveBoard.Children)
                    {
                        // Keep background layers (grid, pattern, background canvas)
                        if (SelectionManager.IsBackgroundElement(element, Rect.Empty, MainInteractiveBoard.ActualWidth, MainInteractiveBoard.ActualHeight))
                            continue;
                        
                        // [BUG_CLEARALL_DESTROYS_UI] Keep system UI controls & overlays via IsSystemElement (QC_4.2_STATE_GUARD)
                        if (IsSystemElement(element))
                            continue;

                        elementsToRemove.Add(element);
                    }
                    
                    if (elementsToRemove.Count > 0)
                    {
                        var batchUndo = new UndoRedoAction
                        {
                            Type = ActionType.Batch,
                            Description = $"Clear All ({elementsToRemove.Count} elements)"
                        };

                        // Remove all non-background elements and record for Undo
                        foreach (var element in elementsToRemove)
                        {
                            MainInteractiveBoard.Children.Remove(element);
                            batchUndo.BatchActions.Add(new UndoRedoAction
                            {
                                Type = ActionType.Remove,
                                Element = element,
                                Parent = MainInteractiveBoard,
                                Description = $"Clear All sub-item {element.GetType().Name}"
                            });
                        }

                        RecordAction(batchUndo);
                        _selectionManager?.ClearRegistrations();
                    }
                    
                    // Show welcome state again since board is empty
                    ShowWelcomeState();
                }
                else
                {
                    // Enable eraser mode for other modes (Stroke, Drag)
                    EnableEraserMode(_savedEraserSize, _savedEraserMode);
                }
                
                // Cleanup
                _activeSubMenu = null;
                _activeSubMenuButton = null;
                
                // Reset button appearance
                if (button != null)
                {
                    button.Background = new SolidColorBrush(Color.FromRgb(241, 242, 246)); // #F1F2F6
                }
                _selectedTool = null;
            };
            
            eraserMenu.Show();
        }

        private void btn3_Undo_Click(object sender, RoutedEventArgs e)
        {
            if (_undoStack.Count > 0)
            {
                var action = _undoStack.Pop();
                ExecuteUndoAction(action);
                _redoStack.Push(action);
                UpdateButtonStates();
                _selectionManager?.DeselectAll();
                RefreshSelectableObjects();
            }
        }

        private void btn4_Redo_Click(object sender, RoutedEventArgs e)
        {
            if (_redoStack.Count > 0)
            {
                var action = _redoStack.Pop();
                ExecuteRedoAction(action);
                _undoStack.Push(action);
                UpdateButtonStates();
                _selectionManager?.DeselectAll();
                RefreshSelectableObjects();
            }
        }

        // ==================== UNDO/REDO SYSTEM ====================
        
        /// <summary>
        /// Core method to record an action into undo stack
        /// </summary>
        private void RecordAction(UndoRedoAction action)
        {
            _undoStack.Push(action);
            _redoStack.Clear(); // Clear redo stack when new action is performed
            
            // Limit stack size to prevent memory issues
            if (_undoStack.Count > MAX_UNDO_LEVELS)
            {
                var temp = _undoStack.ToList();
                temp.RemoveAt(temp.Count - 1); // Remove oldest action (at the bottom/end of the list)
                _undoStack = new System.Collections.Generic.Stack<UndoRedoAction>(
                    ((IEnumerable<UndoRedoAction>)temp).Reverse()
                );
            }
            
            UpdateButtonStates();
        }

        /// <summary>
        /// Convenience method to record Add action (drawing, shape creation)
        /// </summary>
        private void RecordAddAction(UIElement element, string? description = null)
        {
            if (element == null) return;

            // Accidental touch filtering for drawn strokes (Polyline / Path)
            if (element is Polyline polyline)
            {
                if (polyline.Points != null && polyline.Points.Count > 0)
                {
                    double minX = double.MaxValue, minY = double.MaxValue;
                    double maxX = double.MinValue, maxY = double.MinValue;
                    foreach (var pt in polyline.Points)
                    {
                        if (pt.X < minX) minX = pt.X;
                        if (pt.X > maxX) maxX = pt.X;
                        if (pt.Y < minY) minY = pt.Y;
                        if (pt.Y > maxY) maxY = pt.Y;
                    }
                    if (polyline.Points.Count == 1 || ((maxX - minX) <= 5.0 && (maxY - minY) <= 5.0))
                    {
                        System.Diagnostics.Debug.WriteLine("Ignoring accidental touch Polyline in Undo/Redo registration");
                        return;
                    }
                }
            }
            else if (element is System.Windows.Shapes.Path path)
            {
                if (path.Data != null)
                {
                    var bounds = path.Data.Bounds;
                    if (bounds.Width <= 5.0 && bounds.Height <= 5.0)
                    {
                        System.Diagnostics.Debug.WriteLine("Ignoring accidental touch Path in Undo/Redo registration");
                        return;
                    }
                }
            }

            var action = new UndoRedoAction
            {
                Type = ActionType.Add,
                Element = element,
                Parent = MainInteractiveBoard,
                Description = description ?? $"Add {element.GetType().Name}"
            };
            RecordAction(action);
        }

        /// <summary>
        /// Public method for external tool windows (Ruler, Protractor, SetSquare, Compass)
        /// to register drawn elements with the undo/redo system
        /// </summary>
        public void RecordToolDrawAction(UIElement element, string description)
        {
            RecordAddAction(element, description);
        }

        /// <summary>
        /// Convenience method to record Remove action (erasing, delete)
        /// </summary>
        private void RecordRemoveAction(UIElement element, string? description = null)
        {
            var action = new UndoRedoAction
            {
                Type = ActionType.Remove,
                Element = element,
                Parent = MainInteractiveBoard,
                Description = description ?? $"Remove {element.GetType().Name}"
            };
            RecordAction(action);
        }

        /// <summary>
        /// Convenience method to record Modify action (move, rotate, resize)
        /// </summary>
        private void RecordModifyAction(UIElement element, object oldValue, object newValue, string? description = null)
        {
            var action = new UndoRedoAction
            {
                Type = ActionType.Modify,
                Element = element,
                Parent = MainInteractiveBoard,
                OldValue = oldValue,
                NewValue = newValue,
                Description = description ?? $"Modify {element.GetType().Name}"
            };
            RecordAction(action);
        }

        /// <summary>
        /// Overload for property-specific modifications
        /// </summary>
        private void RecordModifyAction(UIElement element, string propertyName, object oldValue, object newValue, string? description = null)
        {
            var action = new UndoRedoAction
            {
                Type = ActionType.Modify,
                Element = element,
                Parent = MainInteractiveBoard,
                OldValue = new { Property = propertyName, Value = oldValue },
                NewValue = new { Property = propertyName, Value = newValue },
                Description = description ?? $"Modify {propertyName}"
            };
            RecordAction(action);
        }

        /// <summary>
        /// Update button states based on stack counts
        /// </summary>
        private void UpdateButtonStates()
        {
            // Update enabled state
            bool canUndo = _undoStack.Count > 0;
            bool canRedo = _redoStack.Count > 0;
            
            btn3_Undo.IsEnabled = canUndo;
            btn4_Redo.IsEnabled = canRedo;
            
            // Update visual appearance with opacity for better feedback
            btn3_Undo.Opacity = canUndo ? 1.0 : 0.5;
            btn4_Redo.Opacity = canRedo ? 1.0 : 0.5;
            
            // Update tooltips with action counts and descriptions
            if (canUndo)
            {
                var lastAction = _undoStack.Peek();
                btn3_Undo.ToolTip = $"Undo: {lastAction.Description} ({_undoStack.Count} actions)";
            }
            else
            {
                btn3_Undo.ToolTip = "Undo (no actions available)";
            }
            
            if (canRedo)
            {
                var nextAction = _redoStack.Peek();
                btn4_Redo.ToolTip = $"Redo: {nextAction.Description} ({_redoStack.Count} actions)";
            }
            else
            {
                btn4_Redo.ToolTip = "Redo (no actions available)";
            }
        }

        /// <summary>
        /// Execute an undo action
        /// </summary>
        private void ExecuteUndoAction(UndoRedoAction action)
        {
            switch (action.Type)
            {
                case ActionType.Add:
                    // Undo Add = Remove from canvas and selection manager
                    if (action.Element != null)
                        _selectionManager?.RemoveObjectByElement(action.Element);
                    break;
                    
                case ActionType.Remove:
                    // Undo Remove = Add back to canvas and register selection
                    if (action.Element != null)
                        RegisterNewObjectWithSelectionManager(action.Element);
                    break;
                    
                case ActionType.Modify:
                    // Undo Modify = Restore old value
                    // TODO: Implement when needed (move, rotate, resize)
                    break;
                    
                case ActionType.Batch:
                    // Undo batch operations in reverse order
                    for (int i = action.BatchActions.Count - 1; i >= 0; i--)
                    {
                        ExecuteUndoAction(action.BatchActions[i]);
                    }
                    break;
                    
                case ActionType.ClearAll:
                    // Undo ClearAll = Add all elements back and register selection
                    foreach (var batchAction in action.BatchActions)
                    {
                        if (batchAction.Element != null)
                            RegisterNewObjectWithSelectionManager(batchAction.Element);
                    }
                    break;
            }
        }

        /// <summary>
        /// Execute a redo action
        /// </summary>
        private void ExecuteRedoAction(UndoRedoAction action)
        {
            switch (action.Type)
            {
                case ActionType.Add:
                    // Redo Add = Add back to canvas and register selection
                    if (action.Element != null)
                        RegisterNewObjectWithSelectionManager(action.Element);
                    break;
                    
                case ActionType.Remove:
                    // Redo Remove = Remove from canvas and selection manager
                    if (action.Element != null)
                        _selectionManager?.RemoveObjectByElement(action.Element);
                    break;
                    
                case ActionType.Modify:
                    // Redo Modify = Apply new value
                    // TODO: Implement when needed (move, rotate, resize)
                    break;
                    
                case ActionType.Batch:
                    // Redo batch operations in normal order
                    foreach (var batchAction in action.BatchActions)
                    {
                        ExecuteRedoAction(batchAction);
                    }
                    break;
                    
                case ActionType.ClearAll:
                    // Redo ClearAll = Remove all elements and selection
                    foreach (var batchAction in action.BatchActions)
                    {
                        if (batchAction.Element != null)
                            _selectionManager?.RemoveObjectByElement(batchAction.Element);
                    }
                    break;
            }
        }

        // ==================== END UNDO/REDO SYSTEM ====================

        private void btn5_Shapes_Click(object sender, RoutedEventArgs e)
        {
            var button = sender as Button;
            
            // ✅ PHASE 2: Deactivate tools and close other submenus
            DeactivateAllTools();
            CloseAllSubmenus();
            
            // Toggle: If clicking same button, close submenu
            if (_activeSubMenu != null && _activeSubMenuButton == button)
            {
                CloseActiveSubMenu();
                return;
            }
            
            SelectTool((Button)sender);
            HideWelcomeState();
            
            // Open SubMenu Draw Shapes
            var shapesMenu = new Form2_5_SubMenuDrawShapes(this);
            _activeSubMenu = shapesMenu;
            _activeSubMenuButton = button;
            
            // Position menu above toolbar, centered horizontally
            // Get window position and size
            var windowPosition = this.PointToScreen(new Point(0, 0));
            var windowWidth = this.ActualWidth;
            var windowHeight = this.ActualHeight;
            
            // Calculate exact toolbar top position
            // Toolbar is always 80px from bottom (Grid.Row 2 with Height="80")
            var toolbarTop = windowPosition.Y + windowHeight - 80;
            
            // Center menu horizontally between left and right edges of window
            shapesMenu.Left = windowPosition.X + (windowWidth - shapesMenu.Width) / 2;
            // Position menu so bottom edge touches top of toolbar (0px gap)
            shapesMenu.Top = toolbarTop - shapesMenu.Height;
            
            // DEBUG: Log positioning calculations
            System.Diagnostics.Debug.WriteLine($"=== MENU POSITIONING DEBUG ===");
            System.Diagnostics.Debug.WriteLine($"Window Position: X={windowPosition.X}, Y={windowPosition.Y}");
            System.Diagnostics.Debug.WriteLine($"Window Size: W={windowWidth}, H={windowHeight}");
            System.Diagnostics.Debug.WriteLine($"Menu Size: W={shapesMenu.Width}, H={shapesMenu.Height}");
            System.Diagnostics.Debug.WriteLine($"Toolbar Top: {toolbarTop}");
            System.Diagnostics.Debug.WriteLine($"Menu Position: Left={shapesMenu.Left}, Top={shapesMenu.Top}");
            System.Diagnostics.Debug.WriteLine($"Menu Bottom: {shapesMenu.Top + shapesMenu.Height}");
            System.Diagnostics.Debug.WriteLine($"Gap (should be 0): {toolbarTop - (shapesMenu.Top + shapesMenu.Height)}");
            System.Diagnostics.Debug.WriteLine($"==============================");
            
            // Handle window closed event
            shapesMenu.Closed += (s, args) =>
            {
                // Check if user selected a shape
                // ✅ Check UserSelected flag instead of DialogResult
                if (shapesMenu.UserSelected && !string.IsNullOrEmpty(shapesMenu.SelectedShape))
                {
                    EnableShapeDrawingMode(shapesMenu.SelectedShape);
                }
                
                // Cleanup
                _activeSubMenu = null;
                _activeSubMenuButton = null;
                
                // Reset button appearance
                if (button != null)
                {
                    button.Background = new SolidColorBrush(Color.FromRgb(241, 242, 246)); // #F1F2F6
                }
                _selectedTool = null;
            };
            
            shapesMenu.Show();
        }

        private void btn6_Inserts_Click(object sender, RoutedEventArgs e)
        {
            var button = sender as Button;
            
            // ✅ PHASE 2: Deactivate tools and close other submenus
            DeactivateAllTools();
            CloseAllSubmenus();
            
            SelectTool((Button)sender);
            HideWelcomeState();
            
            // Open SubMenu Insert Content
            var insertMenu = new Form2_4_SubMenuInsertContent(this);
            _activeSubMenu = insertMenu;
            _activeSubMenuButton = button;
            
            // Position menu above toolbar, centered horizontally
            var windowPosition = this.PointToScreen(new Point(0, 0));
            var windowWidth = this.ActualWidth;
            var windowHeight = this.ActualHeight;
            var toolbarHeight = 80; // Toolbar height from XAML
            
            insertMenu.Left = windowPosition.X + (windowWidth - insertMenu.Width) / 2; // Centered
            insertMenu.Top = windowPosition.Y + windowHeight - toolbarHeight - insertMenu.Height - 10; // 10px above toolbar
            
            // Handle window closed event
            insertMenu.Closed += (s, args) =>
            {
                // ✨ Fix WPF touch/modal focus freeze on IFP touch screens:
                // Run action asynchronously after insertMenu finishes closing completely
                this.Dispatcher.BeginInvoke(new Action(() =>
                {
                    if (insertMenu.SelectedInsertType == "Text")
                    {
                        EnableTextTool();
                    }
                    else if (insertMenu.SelectedInsertType == "Image" || insertMenu.SelectedInsertType == "ImageLibrary")
                    {
                        ImportImage();
                    }
                    else if (insertMenu.SelectedInsertType == "Video")
                    {
                        ImportVideo();
                    }
                    else if (insertMenu.SelectedInsertType == "Camera")
                    {
                        ImportImage(); // Falls back to image file import or camera dialog
                    }
                    else if (insertMenu.SelectedInsertType == "Ruler")
                    {
                        OpenRulerTool();
                    }
                    else if (insertMenu.SelectedInsertType == "Compass")
                    {
                        OpenCompassTool();
                    }
                    else if (insertMenu.SelectedInsertType == "Triangle")
                    {
                        OpenSetSquareTool();
                    }
                    else if (insertMenu.SelectedInsertType == "Protractor")
                    {
                        OpenProtractorTool();
                    }
                }), System.Windows.Threading.DispatcherPriority.Input);
                
                // Cleanup
                _activeSubMenu = null;
                _activeSubMenuButton = null;
                
                // Reset button appearance
                if (button != null)
                {
                    button.Background = new SolidColorBrush(Color.FromRgb(241, 242, 246)); // #F1F2F6
                }
                _selectedTool = null;
            };
            
            insertMenu.Show();
        }

