        /// <summary>
        /// Apply zoom to canvas based on mode
        /// </summary>
        private void ApplyZoom(string mode, double level)
        {
            System.Diagnostics.Debug.WriteLine($"🔍 Applying Zoom: Mode={mode}, Level={level}, Current={_currentZoomLevel}x");
            
            double newZoomLevel = _currentZoomLevel;
            
            switch (mode)
            {
                case "Fixed":
                    // Set zoom to exact level (1x = reset to 100%, 2x = 200%, etc.)
                    newZoomLevel = level;
                    System.Diagnostics.Debug.WriteLine($"📌 Fixed zoom to {newZoomLevel}x");
                    break;
                    
                case "Increment":
                    // Increase zoom by level amount (e.g., +0.25)
                    newZoomLevel = _currentZoomLevel + level;
                    // Limit max zoom to 4x
                    if (newZoomLevel > 4.0)
                        newZoomLevel = 4.0;
                    System.Diagnostics.Debug.WriteLine($"➕ Increment zoom: {_currentZoomLevel}x → {newZoomLevel}x");
                    break;
                    
                case "Decrement":
                    // Decrease zoom by level amount (e.g., -0.25)
                    newZoomLevel = _currentZoomLevel - level;
                    // Limit min zoom to 0.5x
                    if (newZoomLevel < 0.5)
                        newZoomLevel = 0.5;
                    System.Diagnostics.Debug.WriteLine($"➖ Decrement zoom: {_currentZoomLevel}x → {newZoomLevel}x");
                    break;
                    
                case "Area":
                    // Enable area selection mode for zooming
                    EnableZoomAreaSelectionMode();
                    System.Diagnostics.Debug.WriteLine("🎯 Zoom Area Selection mode enabled");
                    return; // Exit early, no zoom applied yet
            }
            
            // Apply the new zoom level
            _currentZoomLevel = newZoomLevel;
            
            // If zoom level is 1.0, reset both transforms to original state
            if (Math.Abs(_currentZoomLevel - 1.0) < 0.001)
            {
                MainInteractiveBoard.LayoutTransform = null;
                MainInteractiveBoard.RenderTransform = null;
                _panTransform = null;
                
                // Reset canvas size to auto
                MainInteractiveBoard.Width = double.NaN;
                MainInteractiveBoard.Height = double.NaN;
                
                MainInteractiveBoard.Cursor = Cursors.Arrow;
                System.Diagnostics.Debug.WriteLine($"✅ Canvas RESET to original view (1x) - All transforms cleared");
            }
            else
            {
                // Get current canvas actual size
                double canvasWidth = MainInteractiveBoard.ActualWidth;
                double canvasHeight = MainInteractiveBoard.ActualHeight;
                
                // Set canvas size explicitly for proper zoom behavior
                if (double.IsNaN(MainInteractiveBoard.Width))
                {
                    MainInteractiveBoard.Width = canvasWidth;
                    MainInteractiveBoard.Height = canvasHeight;
                }
                
                // Create transform group with scale and translate
                var transformGroup = new TransformGroup();
                
                // Scale transform (zoom)
                var scaleTransform = new ScaleTransform(_currentZoomLevel, _currentZoomLevel);
                transformGroup.Children.Add(scaleTransform);
                
                // Translate transform (pan) - initialize at (0, 0)
                _panTransform = new TranslateTransform(0, 0);
                transformGroup.Children.Add(_panTransform);
                
                // Apply combined transform to RenderTransform (better quality than LayoutTransform)
                MainInteractiveBoard.RenderTransform = transformGroup;
                
                // Update RenderTransformOrigin to center (0.5, 0.5) for better zoom experience
                MainInteractiveBoard.RenderTransformOrigin = new Point(0.5, 0.5);
                
                // Change cursor to indicate panning is available
                MainInteractiveBoard.Cursor = Cursors.Hand;
                
                System.Diagnostics.Debug.WriteLine($"✅ Canvas zoomed to {_currentZoomLevel}x (High Quality DPI)");
                System.Diagnostics.Debug.WriteLine($"👆 You can now drag canvas to pan (Press 1x to reset)");
            }
        }

        /// <summary>
        /// Enable area selection mode for zooming into a specific region
        /// </summary>
        private void EnableZoomAreaSelectionMode()
        {
            // Disable all other tools
            _drawingEnabled = false;
            if (_eraserEnabled)
                DisableEraserMode();
            _eraserEnabled = false;
            _shapeDrawingEnabled = false;
            _textToolEnabled = false;
            _selectionToolEnabled = false;
            
            // QC_4.2_TOUCH_ZOOM_AREA: Đặt TouchHandler về mode None để touch events
            // được pass through (không bị capture/vẽ nét) khi đang chọn vùng zoom
            _touchHandler?.SetToolMode(QASmartTouch.Handlers.TouchToolMode.None);
            
            // Enable zoom area selection
            _zoomAreaSelectionEnabled = true;
            
            // Change cursor to crosshair
            MainInteractiveBoard.Cursor = Cursors.Cross;
            
            // Remove eraser preview if exists
            RemoveEraserCursorPreview();
            
            System.Diagnostics.Debug.WriteLine("🎯 Zoom Area Selection: Drag to select region to zoom");
        }

        /// <summary>
        /// Update zoom area preview rectangle
        /// </summary>
        private void UpdateZoomAreaPreview(Rectangle preview, Point start, Point current)
        {
            double left = Math.Min(start.X, current.X);
            double top = Math.Min(start.Y, current.Y);
            double width = Math.Abs(current.X - start.X);
            double height = Math.Abs(current.Y - start.Y);
            
            Canvas.SetLeft(preview, left);
            Canvas.SetTop(preview, top);
            preview.Width = width;
            preview.Height = height;
        }

        /// <summary>
        /// Update selection area preview rectangle
        /// </summary>
        private void UpdateSelectionAreaPreview(Rectangle preview, Point start, Point current)
        {
            double left = Math.Min(start.X, current.X);
            double top = Math.Min(start.Y, current.Y);
            double width = Math.Abs(current.X - start.X);
            double height = Math.Abs(current.Y - start.Y);
            
            Canvas.SetLeft(preview, left);
            Canvas.SetTop(preview, top);
            preview.Width = width;
            preview.Height = height;
        }

        /// <summary>
        /// Zoom to specific area of canvas
        /// </summary>
        private void ZoomToArea(double left, double top, double width, double height)
        {
            // Save bounds for later use
            _zoomAreaBounds = new Rect(left, top, width, height);
            
            // Create HIGH DPI snapshot by capturing the entire canvas first
            // Use 2x DPI (192) for better quality when zooming
            var highDPI = 192.0;
            var scaleFactor = highDPI / 96.0; // 2.0
            
            var fullCanvasSnapshot = new RenderTargetBitmap(
                (int)(MainInteractiveBoard.ActualWidth * scaleFactor),
                (int)(MainInteractiveBoard.ActualHeight * scaleFactor),
                highDPI, highDPI,
                PixelFormats.Pbgra32);
            
            // Apply scale transform to canvas for high DPI rendering
            var originalTransform = MainInteractiveBoard.LayoutTransform;
            MainInteractiveBoard.LayoutTransform = new ScaleTransform(scaleFactor, scaleFactor);
            
            // Render entire canvas to bitmap with high DPI
            fullCanvasSnapshot.Render(MainInteractiveBoard);
            
            // Restore original transform
            MainInteractiveBoard.LayoutTransform = originalTransform;
            
            // Create cropped bitmap for selected area (use original coordinates, bitmap is already scaled)
            var croppedBitmap = new CroppedBitmap(fullCanvasSnapshot, 
                new Int32Rect(
                    (int)(left * scaleFactor), 
                    (int)(top * scaleFactor), 
                    (int)(width * scaleFactor), 
                    (int)(height * scaleFactor)
                ));
            
            // Store the cropped bitmap directly as our snapshot
            _zoomAreaSnapshot = croppedBitmap;
            
            // Create overlay with snapshot and controls
            CreateZoomAreaOverlay(left, top, width, height);
            
            System.Diagnostics.Debug.WriteLine($"✅ Created HIGH DPI zoom area overlay at ({left:F0}, {top:F0}) size {width:F0}x{height:F0} (DPI: {highDPI})");
        }
        
        /// <summary>
        /// Create overlay border with image and control buttons
        /// </summary>
        private void CreateZoomAreaOverlay(double left, double top, double width, double height)
        {
            // Remove existing overlay if any
            if (_zoomAreaOverlay != null)
            {
                MainInteractiveBoard.Children.Remove(_zoomAreaOverlay);
            }
            
            // Reset overlay scale
            _zoomAreaOverlayScale = 1.0;
            
            // Create main container for both overlay and external buttons
            var container = new Canvas();
            
            // Create main border container for image
            var imageBorder = new Border
            {
                Background = Brushes.White,
                BorderBrush = new SolidColorBrush(Color.FromRgb(46, 134, 222)), // #2E86DE
                BorderThickness = new Thickness(3),
                CornerRadius = new CornerRadius(8),
                Effect = new System.Windows.Media.Effects.DropShadowEffect
                {
                    Color = Colors.Black,
                    BlurRadius = 15,
                    Opacity = 0.3,
                    ShadowDepth = 5
                },
                Cursor = Cursors.SizeAll  // Indicate draggable
            };
            
            // Add drag functionality to container (not border to avoid conflict with image)
            container.MouseDown += ZoomAreaOverlay_MouseDown;
            container.MouseMove += ZoomAreaOverlay_MouseMove;
            container.MouseUp += ZoomAreaOverlay_MouseUp;
            container.Background = Brushes.Transparent; // Required for mouse events
            
            // QC_4.2_TOUCH_ZOOM_AREA: Bật ManipulationDelta cho touch drag & pinch-to-zoom trên overlay
            container.IsManipulationEnabled = true;
            container.ManipulationStarting += ZoomAreaOverlay_ManipulationStarting;
            container.ManipulationDelta += ZoomAreaOverlay_ManipulationDelta;
            container.ManipulationCompleted += ZoomAreaOverlay_ManipulationCompleted;
            
            // Image to display snapshot with HIGH QUALITY scaling
            var image = new Image
            {
                Source = _zoomAreaSnapshot,
                Stretch = Stretch.Fill
            };
            
            // Set high quality rendering options for crisp scaling
            RenderOptions.SetBitmapScalingMode(image, BitmapScalingMode.HighQuality);
            RenderOptions.SetEdgeMode(image, EdgeMode.Aliased);
            image.UseLayoutRounding = true;
            image.SnapsToDevicePixels = true;
            
            imageBorder.Child = image;
            
            // Position and size the image border
            Canvas.SetLeft(imageBorder, 0);
            Canvas.SetTop(imageBorder, 0);
            imageBorder.Width = width;
            imageBorder.Height = height;
            
            // Add image border to container
            container.Children.Add(imageBorder);
            
            // Control buttons panel - OUTSIDE the overlay (above it)
            var controlPanel = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Background = new SolidColorBrush(Color.FromArgb(240, 30, 30, 30)), // Semi-transparent dark
                Height = 40
            };
            
            // Zoom Out button (-)
            var btnZoomOut = new Button
            {
                Content = "−",
                Width = 35,
                Height = 35,
                Margin = new Thickness(2),
                Background = new SolidColorBrush(Color.FromRgb(30, 30, 30)),
                Foreground = Brushes.White,
                FontSize = 18,
                FontWeight = FontWeights.Bold,
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                Style = null
            };
            btnZoomOut.Click += ZoomAreaOverlay_ZoomOut;
            // QC_4.2_TOUCH_ZOOM_AREA: Touch isolation cho nút Thu nhỏ — đảm bảo touch/stylus kích hoạt trực tiếp
            btnZoomOut.PreviewTouchDown += (s, te) => { ZoomAreaOverlay_ZoomOut(s, new RoutedEventArgs()); te.Handled = true; };
            btnZoomOut.PreviewStylusDown += (s, se) => { ZoomAreaOverlay_ZoomOut(s, new RoutedEventArgs()); se.Handled = true; };
            
            // Zoom In button (+)
            var btnZoomIn = new Button
            {
                Content = "+",
                Width = 35,
                Height = 35,
                Margin = new Thickness(2),
                Background = new SolidColorBrush(Color.FromRgb(30, 30, 30)),
                Foreground = Brushes.White,
                FontSize = 18,
                FontWeight = FontWeights.Bold,
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                Style = null
            };
            btnZoomIn.Click += ZoomAreaOverlay_ZoomIn;
            // QC_4.2_TOUCH_ZOOM_AREA: Touch isolation cho nút Phóng to
            btnZoomIn.PreviewTouchDown += (s, te) => { ZoomAreaOverlay_ZoomIn(s, new RoutedEventArgs()); te.Handled = true; };
            btnZoomIn.PreviewStylusDown += (s, se) => { ZoomAreaOverlay_ZoomIn(s, new RoutedEventArgs()); se.Handled = true; };
            
            // Close button (X)
            var btnClose = new Button
            {
                Content = "✕",
                Width = 35,
                Height = 35,
                Margin = new Thickness(2),
                Background = new SolidColorBrush(Color.FromRgb(220, 53, 69)),
                Foreground = Brushes.White,
                FontSize = 18,
                FontWeight = FontWeights.Bold,
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                Style = null
            };
            btnClose.Click += ZoomAreaOverlay_Close;
            // QC_4.2_TOUCH_ZOOM_AREA: Touch isolation cho nút Đóng
            btnClose.PreviewTouchDown += (s, te) => { ZoomAreaOverlay_Close(s, new RoutedEventArgs()); te.Handled = true; };
            btnClose.PreviewStylusDown += (s, se) => { ZoomAreaOverlay_Close(s, new RoutedEventArgs()); se.Handled = true; };
            
            controlPanel.Children.Add(btnZoomOut);
            controlPanel.Children.Add(btnZoomIn);
            controlPanel.Children.Add(btnClose);
            
            // Position control panel ABOVE the overlay
            Canvas.SetLeft(controlPanel, 0);
            Canvas.SetTop(controlPanel, -40); // Above the overlay
            controlPanel.Width = width; // Same width as overlay
            
            // Add control panel to container
            container.Children.Add(controlPanel);
            
            // Set container size to encompass both image and control panel
            container.Width = width;
            container.Height = height + 40; // Include control panel height
            
            // Position entire container on canvas
            Canvas.SetLeft(container, left);
            Canvas.SetTop(container, top - 40); // Adjust for control panel above
            
            // Store reference to container
            _zoomAreaOverlay = container;
            
            // Add to canvas with high z-index
            MainInteractiveBoard.Children.Add(container);
            Canvas.SetZIndex(container, ZIndexConstants.SystemUIBase);
        }
        
        /// <summary>
        /// Zoom in the overlay (scale up)
        /// </summary>
        private void ZoomAreaOverlay_ZoomIn(object sender, RoutedEventArgs e)
        {
            _zoomAreaOverlayScale += 0.2;
            if (_zoomAreaOverlayScale > 3.0) _zoomAreaOverlayScale = 3.0;
            
            ApplyZoomAreaOverlayScale();
            System.Diagnostics.Debug.WriteLine($"🔍 Zoom Area Overlay: Zoom In to {_zoomAreaOverlayScale:F1}x");
        }
        
        /// <summary>
        /// Zoom out the overlay (scale down)
        /// </summary>
        private void ZoomAreaOverlay_ZoomOut(object sender, RoutedEventArgs e)
        {
            _zoomAreaOverlayScale -= 0.2;
            if (_zoomAreaOverlayScale < 0.5) _zoomAreaOverlayScale = 0.5;
            
            ApplyZoomAreaOverlayScale();
            System.Diagnostics.Debug.WriteLine($"🔍 Zoom Area Overlay: Zoom Out to {_zoomAreaOverlayScale:F1}x");
        }
        
        /// <summary>
        /// Apply scale transform to overlay
        /// </summary>
        private void ApplyZoomAreaOverlayScale()
        {
            if (_zoomAreaOverlay == null) return;
            
            // Apply scale transform
            var scaleTransform = new ScaleTransform(_zoomAreaOverlayScale, _zoomAreaOverlayScale);
            _zoomAreaOverlay.RenderTransform = scaleTransform;
            _zoomAreaOverlay.RenderTransformOrigin = new Point(0.5, 0.5);
        }
        
        /// <summary>
        /// Close and remove zoom area overlay
        /// </summary>
        private void ZoomAreaOverlay_Close(object sender, RoutedEventArgs e)
        {
            if (_zoomAreaOverlay != null)
            {
                MainInteractiveBoard.Children.Remove(_zoomAreaOverlay);
                _zoomAreaOverlay = null;
                _zoomAreaSnapshot = null;
                _zoomAreaOverlayScale = 1.0;
                _isDraggingOverlay = false;
                System.Diagnostics.Debug.WriteLine("✅ Zoom Area Overlay closed");
            }
        }
        
        /// <summary>
        /// Start dragging overlay
        /// </summary>
        private void ZoomAreaOverlay_MouseDown(object sender, MouseButtonEventArgs e)
        {
            if (_drawingEnabled || _eraserEnabled || _shapeDrawingEnabled) return;

            if (e.LeftButton == MouseButtonState.Pressed)
            {
                _isDraggingOverlay = true;
                _overlayDragStartPoint = e.GetPosition(MainInteractiveBoard);
                
                if (_zoomAreaOverlay is UIElement element)
                {
                    element.CaptureMouse();
                }
                
                System.Diagnostics.Debug.WriteLine("🖱️ Started dragging zoom overlay");
                e.Handled = true;
            }
        }
        
        /// <summary>
        /// Drag overlay to new position
        /// </summary>
        private void ZoomAreaOverlay_MouseMove(object sender, MouseEventArgs e)
        {
            if (_isDraggingOverlay && e.LeftButton == MouseButtonState.Pressed && _zoomAreaOverlay != null)
            {
                Point currentPoint = e.GetPosition(MainInteractiveBoard);
                double deltaX = currentPoint.X - _overlayDragStartPoint.X;
                double deltaY = currentPoint.Y - _overlayDragStartPoint.Y;
                
                // Get current position
                double currentLeft = Canvas.GetLeft(_zoomAreaOverlay);
                double currentTop = Canvas.GetTop(_zoomAreaOverlay);
                
                // Apply new position
                Canvas.SetLeft(_zoomAreaOverlay, currentLeft + deltaX);
                Canvas.SetTop(_zoomAreaOverlay, currentTop + deltaY);
                
                _overlayDragStartPoint = currentPoint;
                
                System.Diagnostics.Debug.WriteLine($"📍 Dragging overlay to ({currentLeft + deltaX:F0}, {currentTop + deltaY:F0})");
                e.Handled = true;
            }
        }
        
        /// <summary>
        /// End dragging overlay
        /// </summary>
        private void ZoomAreaOverlay_MouseUp(object sender, MouseButtonEventArgs e)
        {
            if (_isDraggingOverlay)
            {
                _isDraggingOverlay = false;
                
                if (_zoomAreaOverlay is UIElement element)
                {
                    element.ReleaseMouseCapture();
                }
                
                System.Diagnostics.Debug.WriteLine("✅ Finished dragging zoom overlay");
                e.Handled = true;
            }
        }

        #region QC_4.2_TOUCH_ZOOM_AREA: Multi-touch Manipulation cho Zoom Area Overlay

        /// <summary>
        /// [QC_4.2_TOUCH_ZOOM_AREA] Khởi tạo gesture manipulation — gán ManipulationContainer = MainInteractiveBoard
        /// để toạ độ Translation luôn nhất quán với Canvas coordinates.
        /// </summary>
        private void ZoomAreaOverlay_ManipulationStarting(object sender, ManipulationStartingEventArgs e)
        {
            e.ManipulationContainer = MainInteractiveBoard;
            e.Handled = true;
        }

        /// <summary>
        /// [QC_4.2_TOUCH_ZOOM_AREA] Xử lý multi-touch gesture trên overlay:
        /// - 1 ngón tay: Translation (kéo di chuyển overlay)
        /// - 2 ngón tay: Pinch-to-Zoom (phóng to/thu nhỏ overlay)
        /// </summary>
        private void ZoomAreaOverlay_ManipulationDelta(object sender, ManipulationDeltaEventArgs e)
        {
            if (_zoomAreaOverlay == null) return;

            // --- 1-finger: Translation (kéo di chuyển) ---
            double tx = e.DeltaManipulation.Translation.X;
            double ty = e.DeltaManipulation.Translation.Y;

            if (Math.Abs(tx) > 0.5 || Math.Abs(ty) > 0.5)
            {
                double curLeft = Canvas.GetLeft(_zoomAreaOverlay);
                double curTop = Canvas.GetTop(_zoomAreaOverlay);

                // Bảo vệ NaN nếu Canvas.Left/Top chưa được set
                if (double.IsNaN(curLeft)) curLeft = 0;
                if (double.IsNaN(curTop)) curTop = 0;

                Canvas.SetLeft(_zoomAreaOverlay, curLeft + tx);
                Canvas.SetTop(_zoomAreaOverlay, curTop + ty);

                System.Diagnostics.Debug.WriteLine($"👆 Touch dragging overlay to ({curLeft + tx:F0}, {curTop + ty:F0})");
            }

            // --- 2-finger: Pinch-to-Zoom ---
            double scaleFactor = (e.DeltaManipulation.Scale.X + e.DeltaManipulation.Scale.Y) / 2.0;

            if (scaleFactor != 1.0 && scaleFactor > 0.1 && scaleFactor < 5.0)
            {
                _zoomAreaOverlayScale *= scaleFactor;
                _zoomAreaOverlayScale = Math.Clamp(_zoomAreaOverlayScale, 0.5, 3.0);

                ApplyZoomAreaOverlayScale();

                System.Diagnostics.Debug.WriteLine($"🔍 Touch pinch overlay scale: {_zoomAreaOverlayScale:F2}x");
            }

            e.Handled = true;
        }

        /// <summary>
        /// [QC_4.2_TOUCH_ZOOM_AREA] Kết thúc gesture manipulation trên overlay.
        /// </summary>
        private void ZoomAreaOverlay_ManipulationCompleted(object sender, ManipulationCompletedEventArgs e)
        {
            System.Diagnostics.Debug.WriteLine("✅ Touch manipulation completed on zoom overlay");
            e.Handled = true;
        }

