        private void btn8_Select_Click(object sender, RoutedEventArgs e)
        {
            var button = sender as Button;
            
            // If clicking same button that opened selection mode, open the submenu
            if (_objectSelectionMode)
            {
                ShowSelectionSubMenu(button);
                return;
            }

            DeactivateAllTools();
            CloseAllSubmenus();

            // ✅ GĐ1-FIX: Đồng bộ hoàn toàn với ActivateRectangleSelectionMode
            SelectTool(btn8_Select);                // Highlight button trên toolbar (cố định tham chiếu)
            HideWelcomeState();
            _objectSelectionMode = true;
            MainInteractiveBoard.Cursor = Cursors.Hand;
            _selectionManager?.DeselectAll();        // Reset selection cũ
            RefreshSelectableObjects();              // Scan canvas, đăng ký objects với bounds chính xác
            _touchHandler?.SetToolMode(QASmartTouch.Handlers.TouchToolMode.Selection);
            
            System.Diagnostics.Debug.WriteLine("Selection Mode: Standard Selection Activated via btn8_Select_Click");
        }

