        private Color ExtractPrimaryColor(SelectableObject obj)
        {
            if (obj == null) return Colors.Transparent;

            if (obj.StrokeColor.A > 20 && obj.StrokeColor != Colors.Transparent)
                return obj.StrokeColor;

            if (obj.FillColor.A > 20 && obj.FillColor != Colors.Transparent)
                return obj.FillColor;

            if (obj.Element is TextBlock tb && tb.Foreground is SolidColorBrush scb1)
                return scb1.Color;
            if (obj.Element is TextBox tbx && tbx.Foreground is SolidColorBrush scb2)
                return scb2.Color;

            return Colors.Black;
        }

        private void ShowMagicSparkleEffect(Point point)
        {
            try
            {
                System.Windows.Shapes.Ellipse sparkle = new System.Windows.Shapes.Ellipse
                {
                    Width = 30,
                    Height = 30,
                    Fill = new RadialGradientBrush(Colors.Gold, Colors.Transparent),
                    IsHitTestVisible = false
                };

                Canvas.SetLeft(sparkle, point.X - 15);
                Canvas.SetTop(sparkle, point.Y - 15);
                Canvas.SetZIndex(sparkle, ZIndexConstants.SystemUIBase);

                MainInteractiveBoard.Children.Add(sparkle);

                var timer = new System.Windows.Threading.DispatcherTimer
                {
                    Interval = TimeSpan.FromMilliseconds(300)
                };
                timer.Tick += (s, e) =>
                {
                    timer.Stop();
                    MainInteractiveBoard.Children.Remove(sparkle);
                };
                timer.Start();
            }
            catch { }
        }

        private void PerformMagicWandSelection(Point clickPoint)
        {
            if (_selectionManager == null) return;
            
            // 1. Hiển thị hiệu ứng ánh sáng phép thuật tại vị trí chạm cảm ứng
            ShowMagicSparkleEffect(clickPoint);

            // 2. Làm tươi danh sách đối tượng trên Canvas
            RefreshSelectableObjects();

            // 3. Hit test cho đối tượng tại vị trí chạm (mở rộng TouchBox 40x40px)
            var targetObj = _selectionManager.HitTest(clickPoint);
            if (targetObj == null)
            {
                var touchBox = new Rect(clickPoint.X - 20, clickPoint.Y - 20, 40, 40);
                var candidates = _selectionManager.GetObjectsInRect(touchBox);
                if (candidates != null && candidates.Count > 0)
                {
                    targetObj = candidates.OrderByDescending(o => o.ZIndex).First();
                }
            }
            
            if (targetObj == null)
            {
                ShowSmartStatusBadge("🪄 Đũa phép: Hãy chạm trực tiếp vào một nét vẽ hoặc hình để chọn các đối tượng CÙNG MÀU");
                return;
            }
            
            // 4. Trích xuất màu mục tiêu
            Color targetColor = ExtractPrimaryColor(targetObj);
            if (targetColor.A <= 20)
            {
                ShowSmartStatusBadge("⚠️ Đối tượng được chạm có màu trong suốt, không thể chọn theo màu.");
                return;
            }
            
            // 5. Tìm tất cả đối tượng trên Canvas có màu tương đồng Euclidean (Delta E <= 35)
            var allObjects = _selectionManager.GetAllObjects();
            var matchingObjects = new System.Collections.Generic.List<SelectableObject>();
            
            foreach (var obj in allObjects)
            {
                if (obj.IsLocked) continue;
                
                Color col = ExtractPrimaryColor(obj);
                if (col.A <= 20) continue;
                
                int dr = col.R - targetColor.R;
                int dg = col.G - targetColor.G;
                int db = col.B - targetColor.B;
                int distanceSq = dr * dr + dg * dg + db * db;
                
                // Ngưỡng sai lệch màu (35^2 = 1225)
                if (distanceSq <= 1225)
                {
                    matchingObjects.Add(obj);
                }
            }
            
            // 6. Chọn nhóm đa đối tượng và hiển thị Bounding Box & Toolbar
            if (matchingObjects.Count > 0)
            {
                _selectionManager.SelectMultiple(matchingObjects);
                
                if (matchingObjects.Count == 1)
                {
                    _selectionBox?.AttachTo(matchingObjects[0]);
                    ShowContextToolbarForObject(matchingObjects[0]);
                }
                else
                {
                    double gMinX = double.MaxValue, gMinY = double.MaxValue;
                    double gMaxX = double.MinValue, gMaxY = double.MinValue;
                    foreach (var obj in matchingObjects)
                    {
                        var b = obj.Bounds;
                        gMinX = Math.Min(gMinX, b.Left);  gMinY = Math.Min(gMinY, b.Top);
                        gMaxX = Math.Max(gMaxX, b.Right);  gMaxY = Math.Max(gMaxY, b.Bottom);
                    }
                    var groupRect = new Rect(gMinX, gMinY, gMaxX - gMinX, gMaxY - gMinY);
                    var toolbarPos = CalculateOptimalToolbarPosition(groupRect);

                    var groupObject = new SelectableObject
                    {
                        Element = null,
                        Type = ObjectType.Group,
                        IsGroup = true,
                        GroupMembers = matchingObjects.ToList(),
                        Position = new Point(gMinX, gMinY),
                        Size = new Size(groupRect.Width, groupRect.Height),
                        Bounds = groupRect
                    };
                    _selectionBox?.AttachTo(groupObject);
                    _contextToolbar?.ShowAt(toolbarPos, matchingObjects[0]);
                }
                
                // ✅ FIX: Chuyển sang ObjectSelectionMode để kích hoạt Drag-to-Move và Resize cho Magic Wand
                _isMagicWandMode = false;
                _objectSelectionMode = true;
                MainInteractiveBoard.Cursor = Cursors.Hand;

                string colorName = GetFriendlyColorName(targetColor);
                string hexColor = $"#{targetColor.R:X2}{targetColor.G:X2}{targetColor.B:X2}";
                ShowSmartStatusBadge($"🪄 Đũa phép: Đã tự động chọn {matchingObjects.Count} đối tượng cùng màu {colorName} ({hexColor})");
            }
            else
            {
                _isMagicWandMode = false;
            }
        }

        private string GetFriendlyColorName(Color c)
        {
            if (c.R > 200 && c.G < 100 && c.B < 100) return "Đỏ";
            if (c.R < 100 && c.G < 150 && c.B > 200) return "Xanh dương";
            if (c.R < 100 && c.G > 180 && c.B < 100) return "Xanh lá";
            if (c.R > 200 && c.G > 200 && c.B < 100) return "Vàng";
            if (c.R > 150 && c.G < 100 && c.B > 150) return "Tím";
            if (c.R > 220 && c.G > 120 && c.B < 50) return "Cam";
            if (c.R < 50 && c.G < 50 && c.B < 50) return "Đen";
            if (c.R > 220 && c.G > 220 && c.B > 220) return "Trắng";
            return "nét vẽ";
        }

        public async System.Threading.Tasks.Task<string> PerformOCRAsync(Rect? customBounds = null)
        {
            try
            {
                if (_selectionManager == null) return string.Empty;

                var selectedObjects = _selectionManager.SelectedObjects;
                string searchText = string.Empty;
                Rect bounds = Rect.Empty;

                if (selectedObjects != null && selectedObjects.Count > 0)
                {
                    // 1. Thử trích xuất text trực tiếp (đối với TextBlock/TextBox)
                    foreach (var obj in selectedObjects)
                    {
                        string? text = ExtractTextFromObject(obj);
                        if (!string.IsNullOrWhiteSpace(text))
                        {
                            searchText += text + " ";
                        }
                        bounds.Union(obj.Bounds);
                    }
                    searchText = searchText.Trim();
                }

                // Nếu chưa có bounds từ selectedObjects, kiểm tra customBounds hoặc vùng kéo chữ nhật gần nhất
                if (bounds.IsEmpty || bounds.Width <= 0 || bounds.Height <= 0)
                {
                    if (customBounds.HasValue && customBounds.Value.Width > 5 && customBounds.Value.Height > 5)
                    {
                        bounds = customBounds.Value;
                    }
                    else if (!_lastDraggedSelectionRect.IsEmpty && _lastDraggedSelectionRect.Width > 5 && _lastDraggedSelectionRect.Height > 5)
                    {
                        bounds = _lastDraggedSelectionRect;
                    }
                }

                // 2. Nếu không có text trực tiếp (nét vẽ tay Polyline/Hình ảnh/vùng canvas) -> Dùng Windows OCR Offline
                if (string.IsNullOrWhiteSpace(searchText) && !bounds.IsEmpty && bounds.Width > 5 && bounds.Height > 5)
                {
                    System.Diagnostics.Debug.WriteLine($"Attempting offline Windows OCR for bounds ({bounds.X:F0},{bounds.Y:F0},{bounds.Width:F0},{bounds.Height:F0})...");
                    if (_windowsOcrService == null)
                    {
                        _windowsOcrService = new WindowsOCRService();
                    }
                    if (_captureService == null)
                    {
                        _captureService = new SelectionCaptureService();
                    }

                    bounds.Inflate(15, 15);
                    double maxW = Math.Max(MainInteractiveBoard.ActualWidth, 1000);
                    double maxH = Math.Max(MainInteractiveBoard.ActualHeight, 1000);
                    bounds.Intersect(new Rect(0, 0, maxW, maxH));

                    if (bounds.Width > 5 && bounds.Height > 5)
                    {
                        var bitmap = _captureService.CaptureSelectionAreaAsBitmap(bounds, MainInteractiveBoard);
                        var ocrRes = await _windowsOcrService.RecognizeTextAsync(bitmap);
                        if (ocrRes != null && ocrRes.IsSuccess)
                        {
                            searchText = ocrRes.Text;
                        }
                        else
                        {
                            ShowSmartStatusBadge($"⚠️ {ocrRes?.ErrorMessage ?? "Không tìm thấy chữ trong vùng chọn."}");
                            return string.Empty;
                        }
                    }
                }

                if (!string.IsNullOrWhiteSpace(searchText))
                {
                    ShowSmartStatusBadge($"☑ Nhận diện OCR thành công: \"{searchText.Trim()}\"");
                }
                else
                {
                    ShowSmartStatusBadge("⚠️ Không tìm thấy chữ viết rõ ràng trong vùng được chọn");
                }

                return searchText ?? string.Empty;
            }
            catch (Exception ex)
            {
                ShowSmartStatusBadge($"❌ Lỗi nhận diện OCR: {ex.Message}");
                return string.Empty;
            }
        }

        private void ShowSelectionSubMenu(Button button)
        {
            if (_activeSubMenu != null && _activeSubMenuButton == button)
            {
                CloseActiveSubMenu();
                return;
            }

            // Preserving active selection when opening selection/recognition submenu
            bool hasSelection = _selectionManager != null && _selectionManager.SelectedObjects.Count > 0;
            if (hasSelection)
            {
                CloseActiveSubMenu();
                if (_selectedTool != null && _selectedTool != button)
                {
                    _selectedTool.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F1F2F6"));
                }
                _selectedTool = button;
                _selectedTool.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#2E86DE"));
                UpdateIconColor(_selectedTool, Colors.White);
            }
            else
            {
                SelectTool(button);
            }

            HideWelcomeState();

            var selectionMenu = new Form2_6_SubMenuSelectionRecognition(this);
            _activeSubMenu = selectionMenu;
            _activeSubMenuButton = button;

            var windowPosition = this.PointToScreen(new Point(0, 0));
            var windowWidth = this.ActualWidth;
            var windowHeight = this.ActualHeight;
            var toolbarHeight = 80;

            selectionMenu.Left = windowPosition.X + (windowWidth - selectionMenu.Width) / 2;
            selectionMenu.Top = windowPosition.Y + windowHeight - toolbarHeight - selectionMenu.Height - 10;

            selectionMenu.Closed += (s, args) =>
            {
                _activeSubMenu = null;
                _activeSubMenuButton = null;
            };

            selectionMenu.Show();
        }

        /// <summary>
        /// Chèn văn bản nhận diện từ OCR lên bảng dưới dạng thẻ chữ in đẹp
        /// </summary>
        public void InsertTextFromOCR(string text)
        {
            if (string.IsNullOrWhiteSpace(text)) return;

            Point pos = new Point(300, 200);
            var selectedObjects = _selectionManager?.SelectedObjects;
            if (selectedObjects != null && selectedObjects.Count > 0)
            {
                var first = selectedObjects[0];
                pos = new Point(first.Position.X, first.Position.Y);
            }

            var textBlock = new TextBlock
            {
                Text = text,
                FontFamily = new System.Windows.Media.FontFamily("Inter, Outfit, Segoe UI"),
                FontSize = 24,
                FontWeight = FontWeights.Medium,
                Foreground = new SolidColorBrush(Color.FromRgb(47, 53, 66)),
                TextWrapping = TextWrapping.Wrap,
                Padding = new Thickness(10, 5, 10, 5)
            };

            var border = new Border
            {
                Child = textBlock,
                Background = new SolidColorBrush(Color.FromArgb(240, 255, 255, 255)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(46, 134, 222)),
                BorderThickness = new Thickness(2),
                CornerRadius = new CornerRadius(10),
                Padding = new Thickness(5),
                Effect = new System.Windows.Media.Effects.DropShadowEffect
                {
                    Color = Colors.Black,
                    Direction = 270,
                    ShadowDepth = 2,
                    BlurRadius = 8,
                    Opacity = 0.2
                }
            };

            Canvas.SetLeft(border, pos.X);
            Canvas.SetTop(border, pos.Y);
            Canvas.SetZIndex(border, 1000);

            MainInteractiveBoard.Children.Add(border);
            RecordAddAction(border, "OCRText");
            RefreshSelectableObjects();

            ShowSmartStatusBadge("📝 Đã chèn chữ nhận diện OCR lên bảng thành công!");
        }

        public void ShowBilingualCardOnCanvas(string originalText, string translatedText)
        {
            Point pos = new Point(300, 200);
            var selectedObjects = _selectionManager?.SelectedObjects;
            if (selectedObjects != null && selectedObjects.Count > 0)
            {
                var first = selectedObjects[0];
                pos = new Point(first.Position.X, first.Position.Y);
            }

            StackPanel panel = new StackPanel { Orientation = Orientation.Vertical };

            StackPanel row1 = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Center };
            TextBlock txtOrig = new TextBlock
            {
                Text = originalText,
                FontFamily = new System.Windows.Media.FontFamily("Inter, Outfit, Segoe UI"),
                FontSize = 22,
                FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush(Color.FromRgb(15, 23, 42))
            };
            Button btnSpeak = new Button
            {
                Content = "🔊",
                FontSize = 18,
                Margin = new Thickness(10, 0, 0, 0),
                Background = Brushes.Transparent,
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = "Phát âm từ vựng"
            };
            btnSpeak.Click += (s, e) =>
            {
                if (_speechService == null) _speechService = new QASmartTouch.Services.SpeechSynthesizerService();
                _speechService.SpeakText(originalText);
            };

            row1.Children.Add(txtOrig);
            row1.Children.Add(btnSpeak);

            Separator sep = new Separator { Margin = new Thickness(0, 6, 0, 6), Background = Brushes.LightGray };

            TextBlock txtTrans = new TextBlock
            {
                Text = translatedText,
                FontFamily = new System.Windows.Media.FontFamily("Inter, Outfit, Segoe UI"),
                FontSize = 20,
                FontWeight = FontWeights.Medium,
                Foreground = new SolidColorBrush(Color.FromRgb(52, 152, 219)),
                HorizontalAlignment = HorizontalAlignment.Center
            };

            panel.Children.Add(row1);
            panel.Children.Add(sep);
            panel.Children.Add(txtTrans);

            Border cardBorder = new Border
            {
                Child = panel,
                Background = Brushes.White,
                BorderBrush = new SolidColorBrush(Color.FromRgb(16, 185, 129)),
                BorderThickness = new Thickness(2),
                CornerRadius = new CornerRadius(8),
                Padding = new Thickness(14, 10, 14, 10),
                Effect = new System.Windows.Media.Effects.DropShadowEffect
                {
                    Color = Colors.Black,
                    Direction = 270,
                    ShadowDepth = 3,
                    Opacity = 0.2,
                    BlurRadius = 8
                }
            };

            Canvas.SetLeft(cardBorder, pos.X);
            Canvas.SetTop(cardBorder, pos.Y);
            Canvas.SetZIndex(cardBorder, 1000);

            MainInteractiveBoard.Children.Add(cardBorder);
            RecordAddAction(cardBorder, "BilingualTextCard");
            RefreshSelectableObjects();

            ShowSmartStatusBadge("✨ Đã chèn Thẻ chữ Song ngữ có phát âm lên bảng!");
        }

        private QASmartTouch.Services.SpeechSynthesizerService? _speechService;

        /// <summary>
        /// Thực thi các tính năng Nhận diện thông minh (OCR, Dịch, Đọc, Tìm kiếm, AI Chat)
        /// Tự động xử lý khoanh vùng chọn khi chưa chọn đối tượng
        /// </summary>
        public async System.Threading.Tasks.Task ExecuteSmartActionAsync(SmartActionType actionType, string initialText = "")
        {
            try
            {
                string text = initialText;

                // Nếu chưa truyền text -> Lấy từ OCR các đối tượng đang chọn
                if (string.IsNullOrWhiteSpace(text))
                {
                    var selectedObjects = _selectionManager?.SelectedObjects;
                    if (selectedObjects == null || selectedObjects.Count == 0)
                    {
                        // Chưa có đối tượng chọn -> Đặt cờ pending action & bật chế độ kéo khoanh vùng Chữ nhật
                        _pendingSmartAction = actionType;
                        ActivateRectangleSelectionMode();

                        string actionPrompt = actionType switch
                        {
                            SmartActionType.Translate => "🔤 Hãy khoanh vùng chữ viết trên bảng để DỊCH VĂN BẢN",
                            SmartActionType.Read => "🔊 Hãy khoanh vùng chữ viết trên bảng để ĐỌC VĂN BẢN",
                            SmartActionType.Search => "🔍 Hãy khoanh vùng chữ viết trên bảng để TÌM KIẾM GOOGLE",
                            SmartActionType.AIChat => "🤖 Hãy khoanh vùng chữ viết trên bảng để HỎI AI CHAT",
                            _ => "📝 Hãy khoanh vùng chữ viết trên bảng để NHẬN DIỆN OCR"
                        };
                        ShowSmartStatusBadge(actionPrompt);
                        return;
                    }

                    text = await PerformOCRAsync();
                }

                if (string.IsNullOrWhiteSpace(text))
                {
                    ShowSmartStatusBadge("⚠️ Không tìm thấy văn bản hợp lệ để xử lý");
                    return;
                }

                // Thực hiện tính năng theo actionType
                switch (actionType)
                {
                    case SmartActionType.OCR:
                        {
                            try { Clipboard.SetText(text); } catch { }
                            var result = MessageBox.Show(
                                $"☑ Nhận diện chữ (OCR) thành công:\n\n\"{text.Trim()}\"\n\n(Đã sao chép vào bộ nhớ tạm)\n\nBạn có muốn CHÈN THẺ CHỮ IN NÀY LÊN BẢNG không?",
                                "Nhận diện chữ OCR - SMART TOUCH",
                                MessageBoxButton.YesNo,
                                MessageBoxImage.Information);

                            if (result == MessageBoxResult.Yes)
                            {
                                InsertTextFromOCR(text);
                            }
                        }
                        break;

                    case SmartActionType.Translate:
                        {
                            if (string.IsNullOrWhiteSpace(text) || text.Length < 2)
                            {
                                ShowSmartStatusBadge("⚠️ Vui lòng khoanh chọn văn bản hợp lệ để dịch.");
                                return;
                            }

                            bool isOnline = System.Net.NetworkInformation.NetworkInterface.GetIsNetworkAvailable();
                            if (isOnline)
                            {
                                var bingTranslator = new Form2_24_BingTranslator(text)
                                {
                                    Owner = this
                                };
                                bingTranslator.Show();
                                ShowSmartStatusBadge($"🌐 Đã mở công cụ Dịch văn bản cho: \"{text.Trim()}\"");
                            }
                            else
                            {
                                string offlineResult = QASmartTouch.Services.VocabularyService.LookupOffline(text);
                                ShowSmartStatusBadge($"📖 Tra từ điển Offline: \"{text}\" -> \"{offlineResult}\"");
                                MessageBox.Show($"📖 Kết quả Dịch thuật Offline:\n\nTừ gốc: {text}\nBản dịch: {offlineResult}", "Dịch thuật Offline - SMART TOUCH", MessageBoxButton.OK, MessageBoxImage.Information);
                            }
                        }
                        break;

                    case SmartActionType.Read:
                        {
                            if (string.IsNullOrWhiteSpace(text) || text.Length < 2)
                            {
                                ShowSmartStatusBadge("⚠️ Vui lòng khoanh chọn văn bản hợp lệ để phát âm.");
                                return;
                            }

                            if (_speechService == null)
                            {
                                _speechService = new QASmartTouch.Services.SpeechSynthesizerService();
                            }

                            string cleanText = text.Trim();
                            _speechService.SpeakText(cleanText);
                            ShowSmartStatusBadge($"🔊 Đang phát âm văn bản: \"{cleanText}\"");
                        }
                        break;

                    case SmartActionType.Search:
                        {
                            if (string.IsNullOrWhiteSpace(text) || text.Length < 2)
                            {
                                ShowSmartStatusBadge("⚠️ Vui lòng khoanh chọn từ khóa hợp lệ để tìm kiếm.");
                                return;
                            }

                            bool isOnline = System.Net.NetworkInformation.NetworkInterface.GetIsNetworkAvailable();
                            if (isOnline)
                            {
                                try
                                {
                                    var searchBrowser = new Form2_26_GoogleSearchBrowser
                                    {
                                        Owner = this
                                    };
                                    searchBrowser.Show();

                                    string encoded = Uri.EscapeDataString(text.Trim());
                                    searchBrowser.webView.Source = new Uri($"https://www.google.com/search?q={encoded}");

                                    ShowSmartStatusBadge($"🔍 Đang tìm kiếm Google nhúng cho: \"{text.Trim()}\"");
                                }
                                catch (Exception ex)
                                {
                                    ShowSmartStatusBadge($"❌ Không thể mở trình duyệt nhúng: {ex.Message}");
                                }
                            }
                            else
                            {
                                string offlineResult = QASmartTouch.Services.VocabularyService.LookupOffline(text);
                                ShowSmartStatusBadge($"📖 Trụ sở Mạng Offline - Tra từ điển tri thức: \"{text.Trim()}\"");
                                MessageBox.Show($"📖 Kết quả Tra cứu Tri thức Offline:\n\nTừ khóa: {text}\nThông tin tra cứu: {offlineResult}", "Tra cứu Tri thức Offline - SMART TOUCH", MessageBoxButton.OK, MessageBoxImage.Information);
                            }
                        }
                        break;

                    case SmartActionType.AIChat:
                        {
                            var askAI = new AskAIWindow(text);
                            WindowHelper.ShowChildDialog(askAI, this);
                            ShowSmartStatusBadge($"🤖 Đã mở Trợ lý AI cho văn bản: \"{text.Trim()}\"");
                        }
                        break;
                }
            }
            catch (Exception ex)
            {
                ShowSmartStatusBadge($"❌ Lỗi xử lý nhận diện thông minh: {ex.Message}");
            }
        }

        private void btn9_BoardManagement_Click(object sender, RoutedEventArgs e)
        {
            var button = sender as Button;
            
            // ✅ PHASE 2: Close other submenus first
            CloseAllSubmenus();
            
            SelectTool((Button)sender);
            HideWelcomeState();
            
            // âœ¨ Open SubMenu Board Management (not Chart!)
            var boardMenu = new Form2_7_SubMenuBoardManagement(this);
            _activeSubMenu = boardMenu;
            _activeSubMenuButton = button;
            
            // Position menu above toolbar, centered horizontally
            var windowPosition = this.PointToScreen(new Point(0, 0));
            var windowWidth = this.ActualWidth;
            var windowHeight = this.ActualHeight;
            var toolbarHeight = 80; // Toolbar height from XAML
            
            boardMenu.Left = windowPosition.X + (windowWidth - boardMenu.Width) / 2; // Centered
            boardMenu.Top = windowPosition.Y + windowHeight - toolbarHeight - boardMenu.Height - 10; // 10px above toolbar
            
            // Handle window closed event
            boardMenu.Closed += (s, args) =>
            {
                // Cleanup
                _activeSubMenu = null;
                _activeSubMenuButton = null;
                
                // Reset button appearance
                if (button != null)
                {
                    button.Background = new SolidColorBrush(Color.FromRgb(241, 242, 246)); // #F1F2F6
                }
                _selectedTool = null;
            };
            
            boardMenu.Show();
        }

        /// <summary>
        /// Open chart editor based on chart type
        /// </summary>
        private void OpenChartEditor(string chartType)
        {
            try
            {
                Window? chartEditor = null;
                
                switch (chartType)
                {
                    case "Bar":
                        chartEditor = new Form2_8_BarChartEditor(this);
                        System.Diagnostics.Debug.WriteLine("📊 Opening Bar Chart Editor");
                        break;
                        
                    case "Line":
                        chartEditor = new Form2_9_LineChartEditor();
                        System.Diagnostics.Debug.WriteLine("📈 Opening Line Chart Editor");
                        break;
                        
                    case "Pie":
                        chartEditor = new Form2_10_PieChartEditor(this);
                        System.Diagnostics.Debug.WriteLine("🥧 Opening Pie Chart Editor");
                        break;
                        
                    case "Radar":
                        chartEditor = new Form2_14_RadarChartEditor(this);
                        System.Diagnostics.Debug.WriteLine("📡 Opening Radar Chart Editor");
                        break;
                }
                
                if (chartEditor != null)
                {
                    // Position chart editor at center of screen
                    chartEditor.Owner = this;
                    chartEditor.WindowStartupLocation = WindowStartupLocation.CenterOwner;
                    
                    // Show as dialog
                    chartEditor.ShowDialog();
                    
                    System.Diagnostics.Debug.WriteLine($"✅ {chartType} Chart Editor closed");
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ Error opening chart editor: {ex.Message}");
                MessageBox.Show(
                    $"Lỗi khi mở trình chỉnh sửa biểu đồ:\n{ex.Message}\n\nVui lòng thử lại.", 
                    "Lỗi", 
                    MessageBoxButton.OK, 
                    MessageBoxImage.Error);
            }
        }

        /// <summary>
        /// Add chart UIElement to canvas and record for undo
        /// NOTE: This method is reserved for future implementation when chart editors support exporting UIElement
        /// </summary>
        private void AddChartToCanvas(UIElement chartElement)
        {
            // Position chart at center of canvas
            double left = (MainInteractiveBoard.ActualWidth - (chartElement as FrameworkElement)?.ActualWidth ?? 300) / 2;
            double top = (MainInteractiveBoard.ActualHeight - (chartElement as FrameworkElement)?.ActualHeight ?? 200) / 2;
            
            Canvas.SetLeft(chartElement, left);
            Canvas.SetTop(chartElement, top);
            
            // Add to canvas
            MainInteractiveBoard.Children.Add(chartElement);
            
            // Record for undo
            RecordAddAction(chartElement, $"Add {chartElement.GetType().Name}");
            
            System.Diagnostics.Debug.WriteLine($"✅ Chart added to canvas at ({left:F0}, {top:F0})");
        }

