        #region Canvas Interaction Handlers

        /// <summary>
        /// QC_4.2_DRAG_HANDLE_GUARD: Kiểm tra xem điểm hạ bút/chạm ngón tay có thuộc thanh kéo di chuyển (DragHandle), điểm kéo thu nhỏ/mở rộng (ResizeHandle sang Trái/Phải), viền khung nhúng (Google Maps, YouTube, Widget) hay nút tương tác không.
        /// </summary>
        private bool IsDragHandleOrEmbeddedWidget(object originalSource)
        {
            var element = originalSource as DependencyObject;
            while (element != null && element != MainInteractiveBoard)
            {
                if (element is FrameworkElement fe)
                {
                    if (fe.Tag is string tag)
                    {
                        if (tag == "DragHandle" || tag == "ResizeHandle" || tag == "GoogleMaps" || tag == "InteractiveYouTubeVideo" || tag == "InteractiveGoogleMaps" || tag == "SelectionBox" || tag == "YouTubeControlPanel" || tag == "GoogleMapsControlPanel")
                        {
                            return true;
                        }
                    }

                    // Backup check by object reference in tag
                    if (fe.Tag != null && fe.Tag.GetType().Name.Contains("AnonymousType"))
                    {
                        return true;
                    }

                    if (fe.Name != null && (fe.Name.Contains("Handle") || fe.Name.Contains("Resize") || fe.Name.Contains("Grip") || fe.Name.Contains("Adorner") || fe.Name.Contains("Toolbar") || fe.Name.Contains("Selection")))
                    {
                        return true;
                    }
                }
                if (element is System.Windows.Controls.Primitives.ButtonBase || element is System.Windows.Controls.TextBox || element is System.Windows.Controls.Slider || element is System.Windows.Controls.Primitives.Thumb)
                {
                    return true;
                }
                // ✅ FIX: FlowDocument/Run/Paragraph là ContentElement, KHÔNG phải Visual
                // → VisualTreeHelper.GetParent() ném InvalidOperationException
                // → Dùng LogicalTreeHelper cho ContentElement, VisualTreeHelper cho Visual
                if (element is System.Windows.Media.Visual || element is System.Windows.Media.Media3D.Visual3D)
                    element = System.Windows.Media.VisualTreeHelper.GetParent(element);
                else
                    element = LogicalTreeHelper.GetParent(element);
            }
            return false;
        }

        /// <summary>
        /// QC_4.2_INTERACTIVE_PASSTHROUGH: Đảm bảo khi giáo viên chạm bút/ngón tay vào bảng chính bên cạnh bất kỳ công cụ/cửa sổ nhúng nào (Google Search, YouTube, PhET, ChatGPT, Wikipedia, Máy tính...)
        /// Hệ thống tự động kích hoạt Focus cho MainDashboard, tự động khôi phục chế độ Bút vẽ nếu đang chạm ngoài cửa sổ, và phát nét vẽ tức thì từ điểm chạm đầu tiên.
        /// </summary>
        private void EnsurePassthroughFocusAndPenMode(object originalSource)
        {
            if (!this.IsActive)
            {
                this.Activate();
                this.Focus();
                System.Diagnostics.Debug.WriteLine("⚡ Passthrough Focus: Reactivated MainDashboard on first touch alongside Tool/Browser window.");
            }

            // NẾU ĐANG Ở CHẾ ĐỘ CHỈ BẢNG (POINTER MODE ACTIVE): TUYỆT ĐỐI KHÔNG TỰ ĐỘNG BẬT BÚT VẼ!
            if (_isPointerModeActive)
            {
                _isDrawing = false;
                _currentStroke = null;
                System.Diagnostics.Debug.WriteLine("📌 Pointer Mode Guard: Touch on Canvas while Pointer Mode Active - Keeping pointer tool enabled.");
                return;
            }

            // NẾU ĐANG Ở CHẾ ĐỘ DI CHUYỂN BẢNG (PAN MODE ACTIVE): TUYỆT ĐỐI KHÔNG TỰ ĐỘNG BẬT BÚT VẼ!
            if (_isPanModeActive)
            {
                _isDrawing = false;
                _currentStroke = null;
                System.Diagnostics.Debug.WriteLine("🖐️ Pan Mode Guard: Touch on Canvas while Pan Mode Active - Skipping drawing auto-enable.");
                return;
            }

            // NẾU CHẠM VÀO THANH KÉO DI CHUYỂN HOẶC KHUNG NHÚNG: NGẮT NÉT VẼ VÀ KHÔNG BẬT BÚT VẼ
            if (IsDragHandleOrEmbeddedWidget(originalSource))
            {
                _isDrawing = false;
                _currentStroke = null;
                System.Diagnostics.Debug.WriteLine("🛡️ DragHandle Guard: Touch on DragHandle/Embedded Widget - Cancelled drawing to allow smooth drag-move.");
                return;
            }

            // ✅ AUD-01 FIX: Bổ sung !_selectionToolEnabled, !_isMultiUserModeActive
            // LÝ DO: _selectionToolEnabled (Legacy Selection Tool) và _isMultiUserModeActive (Multi-User Split)
            //   là 2 tool-mode flags KHÔNG được guard bảo vệ → Auto-Pen ghi đè khi user chạm Canvas.
            //   Các flags _isLassoMode, _isMagicWandMode đã được bảo vệ gián tiếp qua _objectSelectionMode.
            if (!_drawingEnabled && !_shapeDrawingEnabled && !_textToolEnabled && !_zoomAreaSelectionEnabled
                && !_objectSelectionMode && !_eraserEnabled && !_isPanModeActive && !_isPointerModeActive
                && !_selectionToolEnabled && !_isMultiUserModeActive)
            {
                if (!QASmartTouch.Utilities.InputValidationHelper.IsEventFromInteractiveControl(originalSource, MainInteractiveBoard))
                {
                    EnableDrawingMode(_currentBrushType, _currentPenSize, _currentPenColor);
                    System.Diagnostics.Debug.WriteLine("⚡ Passthrough Auto-Pen: Auto-enabled Drawing Mode on touch outside Tool/Browser window.");
                }
            }
        }

        private void MainInteractiveBoard_PreviewMouseDown(object sender, MouseButtonEventArgs e)
        {
            EnsurePassthroughFocusAndPenMode(e.OriginalSource);

            // [LOI_VID_52] Auto-dismiss submenus khi chạm Canvas bằng chuột
            if (_activeSubMenu != null) CloseAllSubmenus();

            // [LOI_VID_53] Auto-dismiss keyboard khi chạm Canvas ngoài TextBox/Keyboard
            AutoDismissKeyboardIfNeeded(e.OriginalSource);
        }

        private void MainInteractiveBoard_PreviewTouchDown(object? sender, TouchEventArgs e)
        {
            EnsurePassthroughFocusAndPenMode(e.OriginalSource);

            // [LOI_VID_53] Auto-dismiss keyboard khi chạm Canvas ngoài TextBox/Keyboard
            AutoDismissKeyboardIfNeeded(e.OriginalSource);
        }

        private void MainInteractiveBoard_PreviewStylusDown(object? sender, StylusDownEventArgs e)
        {
            EnsurePassthroughFocusAndPenMode(e.OriginalSource);

            // [LOI_VID_53] Auto-dismiss keyboard khi chạm Canvas ngoài TextBox/Keyboard
            AutoDismissKeyboardIfNeeded(e.OriginalSource);
        }

        /// <summary>
        /// [LOI_VID_53] Kiểm tra và auto-dismiss bàn phím ảo nếu chạm ngoài TextBox/Keyboard.
        /// Cancel dismiss nếu chạm vào TextBlock khác (chuyển focus, giữ keyboard mở).
        /// </summary>
        private void AutoDismissKeyboardIfNeeded(object originalSource)
        {
            if (_floatingTouchKeyboard == null || !_floatingTouchKeyboard.IsKeyboardVisible)
                return;

            // Kiểm tra xem target có phải là TextBlock/TextBox hay keyboard
            var source = originalSource as DependencyObject;
            if (source == null) return;

            // Duyệt lên visual tree để tìm xem có chạm vào keyboard hay TextBlock không
            var current = source;
            while (current != null)
            {
                if (current is QASmartTouch.Controls.FloatingTouchKeyboard)
                {
                    // Chạm vào keyboard → không dismiss
                    _floatingTouchKeyboard.CancelAutoDismiss();
                    return;
                }
                if (current is System.Windows.Controls.TextBlock)
                {
                    // Chạm vào TextBlock khác → cancel dismiss (sẽ chuyển focus)
                    _floatingTouchKeyboard.CancelAutoDismiss();
                    return;
                }
                if (current is System.Windows.Controls.TextBox)
                {
                    _floatingTouchKeyboard.CancelAutoDismiss();
                    return;
                }
                current = VisualTreeHelper.GetParent(current);
            }

            // Chạm vào Canvas (ngoài TextBox và Keyboard) → auto-dismiss với debounce
            _floatingTouchKeyboard.RequestAutoDismiss();
        }

        private void MainInteractiveBoard_MouseDown(object sender, MouseButtonEventArgs e)
        {
            // Tự động kích hoạt lại Focus cho MainDashboard nếu đang bị trình duyệt nhúng chiếm Focus
            if (!this.IsActive)
            {
                this.Activate();
                this.Focus();
            }

            if (_isPointerModeActive)
            {
                Point pos = e.GetPosition(MainInteractiveBoard);
                UpdatePointerPosition(pos);
                e.Handled = true;
                return;
            }

            // QC_4.2_DRAG_HANDLE_GUARD: Nếu chạm vào DragHandle hoặc khung nhúng (Google Maps, YouTube...), ngắt ngay chế độ vẽ nét
            if (IsDragHandleOrEmbeddedWidget(e.OriginalSource))
            {
                _isDrawing = false;
                _currentStroke = null;
                System.Diagnostics.Debug.WriteLine("🖱️ MouseDown on DragHandle/Embedded Widget - Skipping drawing handling");
                return;
            }
            // Check if click is on a child button or control that should handle its own event
            if (QASmartTouch.Utilities.InputValidationHelper.IsEventFromInteractiveControl(e.OriginalSource, MainInteractiveBoard))
            {
                _isDraggingSelection = false;
                _draggedSelectionObject = null;
                if (MainInteractiveBoard.IsMouseCaptured)
                    MainInteractiveBoard.ReleaseMouseCapture();
                System.Diagnostics.Debug.WriteLine("🖱️ Click on child Button/Interactive control - releasing drag state and skipping canvas mouse down handling");
                return;
            }
            
            // ✅ Auto-close any open SubMenu when user clicks/touches on the canvas
            // (Replaces Deactivated handler which is incompatible with touch input)
            if (_activeSubMenu != null)
            {
                CloseAllSubmenus();
            }

            // QC_4.2_TOUCH_ERASER_FIX: Skip mouse events promoted from touch/stylus
            // cho CẢ drawing VÀ eraser (Stroke mode) để tránh xung đột capture kép
            // Guard 1: e.StylusDevice != null → standard WPF stylus→mouse promotion
            // Guard 2: _touchHandler.HasActiveTouches → IR/HID screens send mouse WITHOUT StylusDevice
            // Drag eraser được phép qua vì TouchHandler đã return sớm cho Drag mode (L203)
            if ((_drawingEnabled || _eraserEnabled) && (e.StylusDevice != null || (_touchHandler?.HasActiveTouches == true)))
                return;

            // Hide welcome state when user starts interacting with canvas
            HideWelcomeState();
            
            // PRIORITY CHECK: If any picker/menu is visible, check if click is outside them
            if (e.LeftButton == MouseButtonState.Pressed)
            {
                // ✅ N25 FIX: Auto-refresh selectable objects if canvas children exist but SelectionManager is empty
            if (_selectionManager.AllObjects.Count == 0 && MainInteractiveBoard.Children.Count > 0)
            {
                RefreshSelectableObjects();
            }

            Point clickPoint = e.GetPosition(MainInteractiveBoard);
                bool shouldClosePickerAndReturn = false;
                
                // Check ColorPicker
                if (_colorPicker != null && _colorPicker.Visibility == Visibility.Visible)
                {
                    Rect pickerBounds = new Rect(
                        Canvas.GetLeft(_colorPicker),
                        Canvas.GetTop(_colorPicker),
                        _colorPicker.ActualWidth,
                        _colorPicker.ActualHeight
                    );
                    
                    if (pickerBounds.Contains(clickPoint))
                    {
                        // Click inside ColorPicker - let it handle the event
                        System.Diagnostics.Debug.WriteLine("🎨 Click inside ColorPicker - event handled by picker");
                        return;
                    }
                    else
                    {
                        // Click outside - close picker and prevent further processing
                        _colorPicker.Hide();
                        System.Diagnostics.Debug.WriteLine("❌ ColorPicker closed - clicked outside");
                        shouldClosePickerAndReturn = true;
                    }
                }
                
                // Check ThicknessPicker
                if (_thicknessPicker != null && _thicknessPicker.Visibility == Visibility.Visible)
                {
                    Rect pickerBounds = new Rect(
                        Canvas.GetLeft(_thicknessPicker),
                        Canvas.GetTop(_thicknessPicker),
                        _thicknessPicker.ActualWidth,
                        _thicknessPicker.ActualHeight
                    );
                    
                    if (pickerBounds.Contains(clickPoint))
                    {
                        // Click inside ThicknessPicker - let it handle the event
                        System.Diagnostics.Debug.WriteLine("📏 Click inside ThicknessPicker - event handled by picker");
                        return;
                    }
                    else
                    {
                        // Click outside - close picker and prevent further processing
                        _thicknessPicker.Hide();
                        System.Diagnostics.Debug.WriteLine("❌ ThicknessPicker closed - clicked outside");
                        shouldClosePickerAndReturn = true;
                    }
                }
                
                // Check MoreMenu
                if (_moreMenu != null && _moreMenu.Visibility == Visibility.Visible)
                {
                    Rect menuBounds = new Rect(
                        Canvas.GetLeft(_moreMenu),
                        Canvas.GetTop(_moreMenu),
                        _moreMenu.ActualWidth,
                        _moreMenu.ActualHeight
                    );
                    
                    if (menuBounds.Contains(clickPoint))
                    {
                        // Click inside MoreMenu - let it handle the event
                        System.Diagnostics.Debug.WriteLine("📋 Click inside MoreMenu - event handled by menu");
                        return;
                    }
                    else
                    {
                        // Click outside - close menu and prevent further processing
                        _moreMenu.Hide();
                        System.Diagnostics.Debug.WriteLine("❌ MoreMenu closed - clicked outside");
                        shouldClosePickerAndReturn = true;
                    }
                }
                
                // If we closed any picker/menu, return without processing selection
                if (shouldClosePickerAndReturn)
                {
                    e.Handled = true;
                    return;
                }
            }
            
            // Paste mode - if clipboard has content, paste at clicked position
            if (_selectionManager?.HasClipboardContent() == true && e.LeftButton == MouseButtonState.Pressed)
            {
                Point clickPoint = e.GetPosition(MainInteractiveBoard);
                var pasted = _selectionManager?.PasteAtPosition(clickPoint);
                
                if (pasted != null && pasted.Element != null)
                {
                    System.Diagnostics.Debug.WriteLine($"📋 Pasted at ({clickPoint.X:F0}, {clickPoint.Y:F0})");
                    
                    // Add to undo stack
                    RecordAddAction(pasted.Element, $"Paste {pasted.Type}");
                    
                    // Visual feedback
                    AnimateFadeIn(pasted.Element);
                    
                    // Auto-clear clipboard after paste to exit paste mode
                    _selectionManager?.ClearClipboard();
                    System.Diagnostics.Debug.WriteLine("✅ Clipboard cleared - Paste mode ended");
                }
                
                return;
            }
            
            // Object Selection Mode - delegate to full selection handler
            // Supports: click select, drag to move, rectangle area selection
            if (_objectSelectionMode && e.LeftButton == MouseButtonState.Pressed)
            {
                // CRITICAL FIX: Nếu SelectionBox đang xử lý kéo rê/resize/rotate,
                // KHÔNG gọi MainBoard_SelectionMouseDown và KHÔNG cướp mouse capture.
                // Tránh xung đột kép gây state leak _isMoving bị kẹt true vĩnh viễn.
                if (_selectionBox != null && _selectionBox.IsTransforming)
                {
                    return;
                }
                
                // Reset trạng thái SelectionBox trước khi MainDashboard xử lý
                _selectionBox?.ResetMoveState();
                
                MainBoard_SelectionMouseDown(sender, e);
                // ✅ QC_4.2_CAPTURE_FIX: Chỉ capture mouse khi SelectionMouseDown
                // thực sự khởi tạo hành động (kéo đối tượng hoặc chờ chọn/vẽ khung chọn).
                // Tránh capture vô nghĩa khi chạm vào nút bấm/thân bảng StackPanel.
                if (_draggedSelectionObject != null || _pendingHitObject != null)
                    MainInteractiveBoard.CaptureMouse();
                return;
            }
            
            // Pan mode - drag canvas when zoomed and no tools active
            if (_currentZoomLevel > 1.0 && !_drawingEnabled && !_eraserEnabled && !_shapeDrawingEnabled && 
                !_textToolEnabled && !_selectionToolEnabled && !_zoomAreaSelectionEnabled && !_objectSelectionMode &&
                e.LeftButton == MouseButtonState.Pressed)
            {
                _isPanning = true;
                _panStartPoint = e.GetPosition(this);
                MainInteractiveBoard.Cursor = Cursors.SizeAll; // Change to move cursor
                MainInteractiveBoard.CaptureMouse();
                System.Diagnostics.Debug.WriteLine($"🖐️ Pan mode started at ({_panStartPoint.X:F0}, {_panStartPoint.Y:F0})");
                return;
            }
            
            // Zoom Area Selection mode - drag to select region
            if (_zoomAreaSelectionEnabled && e.LeftButton == MouseButtonState.Pressed)
            {
                _zoomAreaStartPoint = e.GetPosition(MainInteractiveBoard);
                _isDrawing = true;
                
                // Create preview rectangle for selection
                _zoomAreaPreview = new Rectangle
                {
                    Stroke = Brushes.DodgerBlue,
                    StrokeThickness = 2,
                    StrokeDashArray = new DoubleCollection { 5, 5 },
                    Fill = new SolidColorBrush(Color.FromArgb(30, 33, 150, 243))
                };
                
                MainInteractiveBoard.Children.Add(_zoomAreaPreview);
                Canvas.SetZIndex(_zoomAreaPreview, 9999);
                MainInteractiveBoard.CaptureMouse();
                
                System.Diagnostics.Debug.WriteLine("🎯 Zoom Area: Started selecting region");
                return;
            }
            
            // Selection tool mode - select element on click
            if (_selectionToolEnabled && e.LeftButton == MouseButtonState.Pressed)
            {
                Point clickPoint = e.GetPosition(MainInteractiveBoard);
                SelectElementAt(clickPoint);
                
                if (_selectedElement != null)
                {
                    _selectionStartPoint = clickPoint;
                    _isDraggingElement = true;
                    MainInteractiveBoard.CaptureMouse();
                }
            }
            // Text tool mode - insert text box on click
            else if (_textToolEnabled && e.LeftButton == MouseButtonState.Pressed)
            {
                Point clickPoint = e.GetPosition(MainInteractiveBoard);
                InsertTextBox(clickPoint);
            }
            // Shape drawing mode
            else if (_shapeDrawingEnabled && e.LeftButton == MouseButtonState.Pressed)
            {
                _shapeStartPoint = e.GetPosition(MainInteractiveBoard);
                _isDrawing = true;
                
                // Create preview shape based on selected shape type
                _previewShape = CreateShapePreview(_currentShape);
                
                if (_previewShape != null)
                {
                    MainInteractiveBoard.Children.Add(_previewShape);
                }
                
                // Capture mouse
                MainInteractiveBoard.CaptureMouse();
            }
            // Eraser mode
            else if (_eraserEnabled && e.LeftButton == MouseButtonState.Pressed)
            {
                Point clickPoint = e.GetPosition(MainInteractiveBoard);
                
                if (_eraserMode == "Stroke")
                {
                    // Stroke mode: hold & drag to erase strokes under cursor
                    _isDrawing = true;
                    MainInteractiveBoard.CaptureMouse();
                    EraseStrokeAt(clickPoint);
                }
                else if (_eraserMode == "Drag")
                {
                    // Drag mode: draw selection rectangle, erase all on mouse-up
                    _dragEraseStartPoint = clickPoint;
                    _isDrawing = true;

                    _dragErasePreview = new Rectangle
                    {
                        Stroke = new SolidColorBrush(Color.FromRgb(220, 53, 69)),   // Red border
                        StrokeThickness = 2,
                        StrokeDashArray = new DoubleCollection { 6, 3 },
                        Fill = new SolidColorBrush(Color.FromArgb(40, 220, 53, 69)) // Light red fill
                    };

                    Canvas.SetLeft(_dragErasePreview, clickPoint.X);
                    Canvas.SetTop(_dragErasePreview, clickPoint.Y);
                    _dragErasePreview.Width = 0;
                    _dragErasePreview.Height = 0;

                    MainInteractiveBoard.Children.Add(_dragErasePreview);
                    Canvas.SetZIndex(_dragErasePreview, 9998);
                    MainInteractiveBoard.CaptureMouse();
                }
                // Note: ClearAll mode is handled immediately when selected in submenu
            }
            // Drawing mode
            else if (_drawingEnabled && e.LeftButton == MouseButtonState.Pressed)
            {
                _objectSelectionMode = false;
                _isDraggingElement = false;
                _draggedSelectionObject = null;
                if (_selectionManager?.SelectedObjects.Count > 0)
                {
                    _selectionManager.DeselectAll();
                }

                _isDrawing = true;
                _lastPoint = e.GetPosition(MainInteractiveBoard);
                
                // âœ¨ Multi-user mode: Override color based on zone
                Color drawingColor = _currentPenColor;
                StudentProfile? assignedStudent = null;
                
                if (_isMultiUserModeActive)
                {
                    assignedStudent = GetStudentByPosition(_lastPoint);
                    
                    // 🔒 Zone Isolation: Block drawing outside assigned zone
                    if (_zoneIsolationEnabled && assignedStudent == null)
                    {
                        System.Diagnostics.Debug.WriteLine($"🚫 Zone isolation: Drawing blocked outside zones");
                        return;
                    }
                    
                    if (assignedStudent != null)
                    {
                        drawingColor = assignedStudent.Color;
                        System.Diagnostics.Debug.WriteLine($"✏️ {assignedStudent.Name} drawing at ({_lastPoint.X:F0}, {_lastPoint.Y:F0})");
                    }
                }
                
                // âœ¨ OPTIMIZATION: Initialize temporary point collection
                _tempStrokePoints.Clear();
                _tempStrokePoints.Add(_lastPoint);
                
                // Create new stroke based on brush type
                _currentStroke = CreateStrokeByBrushType();
                
                // âœ¨ Override stroke color for multi-user mode
                if (_isMultiUserModeActive && assignedStudent != null)
                {
                    _currentStroke.Stroke = new SolidColorBrush(drawingColor);
                }
                
                // Add first point
                _currentStroke.Points.Add(_lastPoint);
                
                // Add stroke to canvas
                MainInteractiveBoard.Children.Add(_currentStroke);
                // ✅ QC_4.2_STROKE_ABOVE_TABLE (NV-1): Nét vẽ hiển thị TRÊN Table/TextBox (500) nhưng DƯỚI Widget nhúng (1000+)
                Panel.SetZIndex(_currentStroke, ZIndexConstants.UserContentMax);
                
                // Capture mouse to continue tracking even if it leaves the canvas
                MainInteractiveBoard.CaptureMouse();
            }
        }

        private void MainInteractiveBoard_MouseMove(object sender, MouseEventArgs e)
        {
            Point currentPoint = e.GetPosition(MainInteractiveBoard);

            if (_isPointerModeActive)
            {
                UpdatePointerPosition(currentPoint);
                return;
            }
            
            // Pan mode - drag canvas
            if (_isPanning && e.LeftButton == MouseButtonState.Pressed && _panTransform != null)
            {
                Point currentWindowPoint = e.GetPosition(this);
                double deltaX = currentWindowPoint.X - _panStartPoint.X;
                double deltaY = currentWindowPoint.Y - _panStartPoint.Y;
                
                _panTransform.X += deltaX;
                _panTransform.Y += deltaY;
                
                _panStartPoint = currentWindowPoint;
                System.Diagnostics.Debug.WriteLine($"📍 Panning: ({_panTransform.X:F0}, {_panTransform.Y:F0})");
                return;
            }
            
            // Zoom Area Selection - update preview rectangle
            if (_zoomAreaSelectionEnabled && _isDrawing && _zoomAreaPreview != null && e.LeftButton == MouseButtonState.Pressed)
            {
                UpdateZoomAreaPreview(_zoomAreaPreview, _zoomAreaStartPoint, currentPoint);
                return;
            }
            
            // Object Selection Mode - delegate to selection handler for drag/rectangle
            if (_objectSelectionMode && e.LeftButton == MouseButtonState.Pressed)
            {
                MainBoard_SelectionMouseMove(sender, e);
                return;
            }
            
            // Update eraser cursor preview position
            if (_eraserEnabled)
            {
                UpdateEraserCursorPreview(currentPoint);
            }
            
            // Selection tool - drag selected element
            if (_selectionToolEnabled && _isDraggingElement && _selectedElement != null && e.LeftButton == MouseButtonState.Pressed)
            {
                MoveElement(_selectedElement, currentPoint);
            }
            // Shape drawing mode - update preview
            else if (_shapeDrawingEnabled && _isDrawing && _previewShape != null && e.LeftButton == MouseButtonState.Pressed)
            {
                UpdateShapePreview(_previewShape, _shapeStartPoint, currentPoint);
            }
            // Eraser Stroke mode: erase while mouse is held & dragged
            else if (_eraserEnabled && _eraserMode == "Stroke" && _isDrawing && e.LeftButton == MouseButtonState.Pressed)
            {
                var canvasBounds = new Rect(0, 0, MainInteractiveBoard.ActualWidth, MainInteractiveBoard.ActualHeight);
                if (!canvasBounds.Contains(currentPoint))
                {
                    _isDrawing = false;
                    MainInteractiveBoard.ReleaseMouseCapture();
                    return;
                }
                EraseStrokeAt(currentPoint);
            }
            // Eraser Drag mode: update selection rectangle preview only (erase happens on MouseUp)
            else if (_eraserEnabled && _eraserMode == "Drag" && _isDrawing && _dragErasePreview != null && e.LeftButton == MouseButtonState.Pressed)
            {
                // Clamp current position to canvas boundaries to avoid sudden cancel if pen leaves screen edge
                double clampedX = Math.Clamp(currentPoint.X, 0, MainInteractiveBoard.ActualWidth);
                double clampedY = Math.Clamp(currentPoint.Y, 0, MainInteractiveBoard.ActualHeight);

                // Update preview rectangle to show selected area
                double x = Math.Min(_dragEraseStartPoint.X, clampedX);
                double y = Math.Min(_dragEraseStartPoint.Y, clampedY);
                double w = Math.Abs(clampedX - _dragEraseStartPoint.X);
                double h = Math.Abs(clampedY - _dragEraseStartPoint.Y);

                Canvas.SetLeft(_dragErasePreview, x);
                Canvas.SetTop(_dragErasePreview, y);
                _dragErasePreview.Width = w;
                _dragErasePreview.Height = h;
            }
            // Continue drawing if mouse is pressed and drawing is enabled
            else if (_isDrawing && e.LeftButton == MouseButtonState.Pressed && _currentStroke != null)
            {
                // âœ¨ OPTIMIZATION: Use StrokeOptimizer to filter points
                // Only add point if it's far enough from last point (reduces jitter)
                if (_strokeOptimizer != null && _strokeOptimizer.ShouldAddPoint(currentPoint, _lastPoint))
                {
                    // Add to temporary collection
                    _tempStrokePoints.Add(currentPoint);
                    
                    // Add point to current stroke for real-time preview
                    _currentStroke.Points.Add(currentPoint);
                    
                    _lastPoint = currentPoint;
                }
                // If point is too close, skip it (this reduces jitter significantly)
            }
        }

        private void MainInteractiveBoard_MouseUp(object sender, MouseButtonEventArgs e)
        {
            // QC_4.2_TOUCH_ERASER_FIX: Thống nhất guard với MouseDown
            // Chặn touch-promoted mouse events cho CẢ drawing VÀ eraser (Stroke mode)
            if ((_drawingEnabled || _eraserEnabled) && (e.StylusDevice != null || (_touchHandler?.HasActiveTouches == true)))
                return;

            // Pan mode - finish panning
            if (_isPanning)
            {
                _isPanning = false;
                MainInteractiveBoard.Cursor = Cursors.Hand; // Back to hand cursor (indicates can pan)
                MainInteractiveBoard.ReleaseMouseCapture();
                System.Diagnostics.Debug.WriteLine("🖐️ Pan mode ended");
                return;
            }
            
            // Object Selection Mode - delegate to selection handler for completing drag/rectangle
            if (_objectSelectionMode)
            {
                MainBoard_SelectionMouseUp(sender, e);
                MainInteractiveBoard.ReleaseMouseCapture();
                // Đảm bảo SelectionBox không bị kẹt trạng thái _isMoving sau khi MainDashboard xử lý xong
                _selectionBox?.ResetMoveState();
                return;
            }
            
            // Zoom Area Selection - finalize and zoom to selected region
            if (_zoomAreaSelectionEnabled && _isDrawing && _zoomAreaPreview != null)
            {
                Point endPoint = e.GetPosition(MainInteractiveBoard);
                
                // Calculate selected area bounds
                double left = Math.Min(_zoomAreaStartPoint.X, endPoint.X);
                double top = Math.Min(_zoomAreaStartPoint.Y, endPoint.Y);
                double width = Math.Abs(endPoint.X - _zoomAreaStartPoint.X);
                double height = Math.Abs(endPoint.Y - _zoomAreaStartPoint.Y);
                
                // Remove preview rectangle
                MainInteractiveBoard.Children.Remove(_zoomAreaPreview);
                _zoomAreaPreview = null;
                
                // Apply zoom to selected area (if area is large enough)
                if (width > 50 && height > 50)
                {
                    ZoomToArea(left, top, width, height);
                }
                
                // Disable zoom area selection mode
                _zoomAreaSelectionEnabled = false;
                _isDrawing = false;
                MainInteractiveBoard.ReleaseMouseCapture();
                MainInteractiveBoard.Cursor = Cursors.Arrow;
                
                System.Diagnostics.Debug.WriteLine($"🎯 Zoom Area: Completed selection ({width:F0}x{height:F0})");
                return;
            }
            
            // Selection tool - finish dragging
            if (_selectionToolEnabled && _isDraggingElement)
            {
                _isDraggingElement = false;
                MainInteractiveBoard.ReleaseMouseCapture();
            }
            // Eraser Drag mode - erase all objects inside selection rectangle on release
            else if (_eraserEnabled && _eraserMode == "Drag" && _isDrawing)
            {
                _isDrawing = false;
                MainInteractiveBoard.ReleaseMouseCapture();

                if (_dragErasePreview != null)
                {
                    // Get final selection rectangle
                    Point endPoint = e.GetPosition(MainInteractiveBoard);
                    double left   = Math.Min(_dragEraseStartPoint.X, endPoint.X);
                    double top    = Math.Min(_dragEraseStartPoint.Y, endPoint.Y);
                    double width  = Math.Abs(endPoint.X - _dragEraseStartPoint.X);
                    double height = Math.Abs(endPoint.Y - _dragEraseStartPoint.Y);

                    // Remove preview rectangle first
                    MainInteractiveBoard.Children.Remove(_dragErasePreview);
                    _dragErasePreview = null;

                    // Only erase if selection is meaningful (> 5px)
                    if (width > 5 && height > 5)
                    {
                        var eraseRect = new Rect(left, top, width, height);
                        EraseElementsInRect(eraseRect);
                        System.Diagnostics.Debug.WriteLine($"🧹 Drag erase: removed objects in ({left:F0},{top:F0}) {width:F0}×{height:F0}");
                    }
                }
            }
            // Eraser Stroke mode - always release capture and reset drawing state
            else if (_eraserEnabled && _eraserMode == "Stroke")
            {
                _isDrawing = false;
                if (MainInteractiveBoard.IsMouseCaptured)
                    MainInteractiveBoard.ReleaseMouseCapture();
            }
            // Shape drawing mode - finalize shape
            else if (_shapeDrawingEnabled && _isDrawing && _previewShape != null)
            {
                bool isTooSmall = false;
                if (_previewShape is Line line)
                {
                    double length = Math.Sqrt(Math.Pow(line.X2 - line.X1, 2) + Math.Pow(line.Y2 - line.Y1, 2));
                    if (length < 5) isTooSmall = true;
                }
                else if (_previewShape is Polygon poly)
                {
                    if (poly.Points.Count < 2) isTooSmall = true;
                    else
                    {
                        double minX = poly.Points.Min(p => p.X);
                        double maxX = poly.Points.Max(p => p.X);
                        double minY = poly.Points.Min(p => p.Y);
                        double maxY = poly.Points.Max(p => p.Y);
                        if ((maxX - minX) < 5 || (maxY - minY) < 5) isTooSmall = true;
                    }
                }
                else if (_previewShape is System.Windows.Shapes.Path path)
                {
                    var bounds = path.Data?.Bounds ?? Rect.Empty;
                    if (bounds.Width < 5 || bounds.Height < 5) isTooSmall = true;
                }
                else
                {
                    if (_previewShape.Width < 5 || _previewShape.Height < 5) isTooSmall = true;
                }

                if (isTooSmall)
                {
                    MainInteractiveBoard.Children.Remove(_previewShape);
                    System.Diagnostics.Debug.WriteLine("🧹 Discarded micro-shape drawing (accidental tap)");
                }
                else
                {
                    // Add completed shape to undo stack
                    RecordAddAction(_previewShape, $"Draw {_currentShape}");
                    
                    // BUGFIX: Register new shape with SelectionManager
                    RegisterNewObjectWithSelectionManager(_previewShape);
                }
                
                _isDrawing = false;
                _previewShape = null;
                MainInteractiveBoard.ReleaseMouseCapture();
            }
            // Stop drawing and add to undo stack
            else if (_isDrawing && _currentStroke != null)
            {
                // âœ¨ BALANCED OPTIMIZATION: Apply light smoothing to reduce hardware jitter
                // Decimation is DISABLED to preserve stroke shape
                // Only light smoothing (20%) is applied to reduce jitter from touch hardware
                if (_strokeOptimizer != null && _tempStrokePoints.Count > 2)
                {
                    int originalCount = _tempStrokePoints.Count;
                    
                    // Step 1: Skip decimation (keep all points for shape accuracy)
                    // Step 2: Apply light smoothing to reduce hardware jitter
                    var smoothedPoints = _strokeOptimizer.SmoothPoints(_tempStrokePoints);
                    
                    // Step 3: Replace stroke points with smoothed version
                    _currentStroke.Points.Clear();
                    foreach (var point in smoothedPoints)
                    {
                        _currentStroke.Points.Add(point);
                    }
                    
                    // Debug output
                    System.Diagnostics.Debug.WriteLine($"âœ¨ Stroke smoothed: {originalCount} points (no decimation, 20% smoothing)");
                }

                // Add completed stroke to undo stack
                RecordAddAction(_currentStroke, "Draw stroke");
                
                // BUGFIX: Register new Polyline with SelectionManager
                RegisterNewObjectWithSelectionManager(_currentStroke);
                
                _isDrawing = false;
                _currentStroke = null;
                _tempStrokePoints.Clear(); // Clear temporary collection
                MainInteractiveBoard.ReleaseMouseCapture();
            }
        }

        /// <summary>
        /// ✅ G2.1: Tính vị trí tối ưu cho Context Toolbar theo thuật toán Auto-Flip
        /// 1. Ưu tiên hiển thị phía dưới Bounding Box
        /// 2. Nếu sát mép dưới → lật lên trên
        /// 3. Nếu cả trên/dưới đều chật → Side-Docking bên phải
        /// </summary>
        private Point CalculateOptimalToolbarPosition(Rect bounds, double toolbarWidth = 400, double toolbarHeight = 45)
        {
            double canvasWidth = MainInteractiveBoard.ActualWidth > 0 ? MainInteractiveBoard.ActualWidth : 1920;
            double canvasHeight = MainInteractiveBoard.ActualHeight > 0 ? MainInteractiveBoard.ActualHeight : 1080;

            double centerX = bounds.Left + (bounds.Width - toolbarWidth) / 2;
            // Clamp X: không tràn trái/phải
            centerX = Math.Max(10, Math.Min(centerX, canvasWidth - toolbarWidth - 10));

            double distanceBottom = canvasHeight - bounds.Bottom;
            double distanceTop = bounds.Top;

            if (distanceBottom >= toolbarHeight + 15)
            {
                // Ưu tiên: Hiển thị phía dưới
                return new Point(centerX, bounds.Bottom + 10);
            }
            else if (distanceTop >= toolbarHeight + 15)
            {
                // Auto-Flip: Lật lên phía trên
                return new Point(centerX, bounds.Top - toolbarHeight - 10);
            }
            else
            {
                // Side-Docking: Đặt bên phải Bounding Box
                double sideX = bounds.Right + 10;
                if (sideX + toolbarWidth > canvasWidth)
                    sideX = bounds.Left - toolbarWidth - 10;
                double sideY = bounds.Top + (bounds.Height - toolbarHeight) / 2;
                sideY = Math.Max(10, Math.Min(sideY, canvasHeight - toolbarHeight - 10));
                return new Point(sideX, sideY);
            }
        }

