        private double CalculatePrismBaseArea(string baseType, double size)
        {
            return baseType switch
            {
                "Triangle" => (Math.Sqrt(3) / 4) * size * size,
                "Square" => size * size,
                "Pentagon" => (1.0 / 4.0) * Math.Sqrt(5 * (5 + 2 * Math.Sqrt(5))) * size * size,
                "Hexagon" => (3 * Math.Sqrt(3) / 2) * size * size,
                _ => size * size
            };
        }

        private string GetPrismBaseAreaFormula(string baseType)
        {
            return baseType switch
            {
                "Triangle" => "S = (√3/4) × cạnh²",
                "Square" => "S = cạnh²",
                "Pentagon" => "S = (1/4)√[5(5+2√5)] × cạnh²",
                "Hexagon" => "S = (3√3/2) × cạnh²",
                _ => "S = cạnh²"
            };
        }

        // Helper methods for 3D cube rendering
        private double[,] GetCubeVertices3D(double size)
        {
            double s = size / 2;
            return new double[,]
            {
                { -s, -s, -s }, { s, -s, -s }, { s, s, -s }, { -s, s, -s },
                { -s, -s, s }, { s, -s, s }, { s, s, s }, { -s, s, s }
            };
        }

        private double[] RotateXYZ(double[] point, double angleX, double angleY, double angleZ)
        {
            // Rotate X
            double radX = angleX * Math.PI / 180;
            double cosX = Math.Cos(radX), sinX = Math.Sin(radX);
            double y1 = point[1] * cosX - point[2] * sinX;
            double z1 = point[1] * sinX + point[2] * cosX;
            
            // Rotate Y
            double radY = angleY * Math.PI / 180;
            double cosY = Math.Cos(radY), sinY = Math.Sin(radY);
            double x2 = point[0] * cosY + z1 * sinY;
            double z2 = -point[0] * sinY + z1 * cosY;
            
            // Rotate Z
            double radZ = angleZ * Math.PI / 180;
            double cosZ = Math.Cos(radZ), sinZ = Math.Sin(radZ);
            double x3 = x2 * cosZ - y1 * sinZ;
            double y3 = x2 * sinZ + y1 * cosZ;
            
            return new double[] { x3, y3, z2 };
        }

        private Point Project3DTo2D(double[] point3D, double centerX, double centerY)
        {
            double distance = 600;
            double z = point3D[2] + distance;
            if (z < 1) z = 1;
            double scale = distance / z;
            return new Point(point3D[0] * scale + centerX, point3D[1] * scale + centerY);
        }

        private double[] CalculateFaceNormal(double[] v1, double[] v2, double[] v3)
        {
            double[] edge1 = { v2[0] - v1[0], v2[1] - v1[1], v2[2] - v1[2] };
            double[] edge2 = { v3[0] - v1[0], v3[1] - v1[1], v3[2] - v1[2] };
            return new double[]
            {
                edge1[1] * edge2[2] - edge1[2] * edge2[1],
                edge1[2] * edge2[0] - edge1[0] * edge2[2],
                edge1[0] * edge2[1] - edge1[1] * edge2[0]
            };
        }

        private void EnableTextTool()
        {
            // Enable text tool mode
            _textToolEnabled = true;
            _drawingEnabled = false; // Disable pen drawing
            
            // Disable eraser with proper cleanup
            if (_eraserEnabled)
                DisableEraserMode();
            
            _shapeDrawingEnabled = false; // Disable shape drawing
            _selectionToolEnabled = false; // Disable selection
            
            // Set TouchHandler to None tool mode to prevent drawing freehand lines during text input
            if (_touchHandler != null)
            {
                _touchHandler.SetToolMode(QASmartTouch.Handlers.TouchToolMode.None);
            }
            
            // Change cursor to IBeam for text input
            MainInteractiveBoard.Cursor = Cursors.IBeam;
        }

        private void EnableSelectionTool()
        {
            // Enable selection tool mode
            _selectionToolEnabled = true;
            _drawingEnabled = false; // Disable pen drawing
            
            // Disable eraser with proper cleanup
            if (_eraserEnabled)
                DisableEraserMode();
            
            _shapeDrawingEnabled = false; // Disable shape drawing
            _textToolEnabled = false; // Disable text tool
            
            // Set TouchHandler to None tool mode to prevent drawing freehand lines during object selection
            if (_touchHandler != null)
            {
                _touchHandler.SetToolMode(QASmartTouch.Handlers.TouchToolMode.None);
            }
            
            // Change cursor to arrow for selection
            MainInteractiveBoard.Cursor = Cursors.Arrow;
        }

        private void SelectElementAt(Point clickPoint)
        {
            System.Diagnostics.Debug.WriteLine($"🔍 SelectElementAt called at ({clickPoint.X:F0}, {clickPoint.Y:F0})");

            // ✅ QC_4.2_SELECTION_BOUNDS_FIX: Làm tươi danh sách đối tượng & bounds trước khi HitTest
            RefreshSelectableObjects();

            // Clear previous selection
            ClearSelection();

            // Hit test to find element at click point
            _selectedElement = null;

            // ────────────────────────────────────────────────────────────────
            // PATH 1: Ưu tiên SelectionManager HitTest (đã có tolerance 15px)
            // ────────────────────────────────────────────────────────────────
            if (_selectionManager != null)
            {
                var selectableObj = _selectionManager.HitTest(clickPoint);
                if (selectableObj != null)
                {
                    _selectedElement = selectableObj.Element;
                    HighlightElement(selectableObj.Element);
                    _selectionManager.SelectObject(selectableObj); // → fire SelectionChanged → _selectionBox.AttachTo()
                    System.Diagnostics.Debug.WriteLine($"✅ Selection Tool: Selected {selectableObj.Type} via SelectionManager HitTest");
                    return;
                }
            }

            // ────────────────────────────────────────────────────────────────
            // PATH 2: Fallback — duyệt Canvas children từ trên xuống dưới
            // ────────────────────────────────────────────────────────────────
            for (int i = MainInteractiveBoard.Children.Count - 1; i >= 0; i--)
            {
                var element = MainInteractiveBoard.Children[i];

                // Skip system UI / preview controls
                if (element == panelWelcomeState || element == _selectionBox || element == _contextToolbar)
                    continue;

                // ✅ Bỏ qua element ẩn & sub-Canvas
                if (element.Visibility != Visibility.Visible) continue;
                if (element is Canvas) continue;

                // Check if click point hits this element
                if (IsPointInElement(element, clickPoint))
                {
                    _selectedElement = element;
                    HighlightElement(element);

                    System.Diagnostics.Debug.WriteLine($"   Element found via Fallback: {element.GetType().Name}");

                    // ✅ Tạo SelectableObject fallback từ BoundsHelper
                    var absBounds = QASmartTouch.Helpers.BoundsHelper.GetAbsoluteBounds(element, MainInteractiveBoard);
                    if (!absBounds.IsEmpty && absBounds.Width > 0 && absBounds.Height > 0)
                    {
                        // Xác định đúng ObjectType theo loại element thực tế
                        ObjectType objType;
                        if (element is Polyline) objType = ObjectType.Stroke;
                        else if (element is System.Windows.Shapes.Path) objType = ObjectType.Drawing;
                        else if (element is System.Windows.Controls.Image) objType = ObjectType.Image;
                        else if (element is System.Windows.Shapes.Line) objType = ObjectType.Shape;
                        else if (element is System.Windows.Controls.TextBlock || element is System.Windows.Controls.TextBox) objType = ObjectType.Text;
                        else if (element is System.Windows.Shapes.Shape) objType = ObjectType.Shape;
                        else objType = ObjectType.Other;

                        var selectableObj = new SelectableObject
                        {
                            Element = element,
                            Type = objType,
                            Bounds = absBounds,
                            Position = new Point(absBounds.Left, absBounds.Top),
                            Size = new Size(absBounds.Width, absBounds.Height),
                            ZIndex = Panel.GetZIndex(element)
                        };

                        if (_selectionManager != null)
                        {
                            _selectionManager.AddObject(selectableObj);
                            _selectionManager.SelectObject(selectableObj); // → fire SelectionChanged → _selectionBox.AttachTo()
                            System.Diagnostics.Debug.WriteLine($"✅ Selection Tool: Selected {objType} via Fallback + SelectObject");
                        }
                    }
                    else
                    {
                        System.Diagnostics.Debug.WriteLine($"⚠️ Selection Tool: Element found but BoundsHelper returned empty/zero bounds");
                    }

                    break;
                }
            }

            if (_selectedElement == null)
            {
                System.Diagnostics.Debug.WriteLine($"   No element found at click point");
            }
        }

        private bool IsPointInElement(UIElement element, Point point)
        {
            // Get element bounds
            if (element is FrameworkElement frameworkElement)
            {
                double left = Canvas.GetLeft(element);
                double top = Canvas.GetTop(element);
                
                // Handle NaN values
                if (double.IsNaN(left)) left = 0;
                if (double.IsNaN(top)) top = 0;
                
                double right = left + frameworkElement.ActualWidth;
                double bottom = top + frameworkElement.ActualHeight;
                
                return point.X >= left && point.X <= right && point.Y >= top && point.Y <= bottom;
            }
            
            return false;
        }

        private void HighlightElement(UIElement element)
        {
            // Add visual indicator (e.g., border or background)
            if (element is FrameworkElement frameworkElement)
            {
                // Store original effect
                frameworkElement.Effect = new System.Windows.Media.Effects.DropShadowEffect
                {
                    Color = Colors.Blue,
                    BlurRadius = 10,
                    ShadowDepth = 0,
                    Opacity = 0.8
                };
            }
        }

        private void ClearSelection()
        {
            if (_selectedElement != null && _selectedElement is FrameworkElement frameworkElement)
            {
                // Remove highlight effect
                frameworkElement.Effect = null;
                _selectedElement = null;
            }
        }

        private void MoveElement(UIElement element, Point currentPoint)
        {
            // Calculate offset from start point
            double offsetX = currentPoint.X - _selectionStartPoint.X;
            double offsetY = currentPoint.Y - _selectionStartPoint.Y;
            
            // Get current position
            double currentLeft = Canvas.GetLeft(element);
            double currentTop = Canvas.GetTop(element);
            
            // Handle NaN values
            if (double.IsNaN(currentLeft)) currentLeft = 0;
            if (double.IsNaN(currentTop)) currentTop = 0;
            
            // Set new position
            Canvas.SetLeft(element, currentLeft + offsetX);
            Canvas.SetTop(element, currentTop + offsetY);
            
            // Update start point for next move
            _selectionStartPoint = currentPoint;
        }

        private void InsertTextBox(Point position)
        {
            // Create a TextBox for user input
            var textBox = new TextBox
            {
                Width = 200,
                MinHeight = 30,
                FontFamily = new System.Windows.Media.FontFamily(_currentFontFamily),
                FontSize = _currentFontSize,
                Foreground = new SolidColorBrush(_currentTextColor),
                Background = Brushes.Transparent,
                BorderBrush = new SolidColorBrush(Colors.Gray),
                BorderThickness = new Thickness(1),
                TextWrapping = TextWrapping.Wrap,
                AcceptsReturn = true,
                Padding = new Thickness(5)
            };

            // Position the TextBox at click location
            Canvas.SetLeft(textBox, position.X);
            Canvas.SetTop(textBox, position.Y);

            // Add to canvas
            MainInteractiveBoard.Children.Add(textBox);

            // Focus the TextBox for immediate typing (QC_4.2_TOUCH: Bọc Dispatcher để hoàn tất layout pass trên IFP)
            Dispatcher.BeginInvoke(new Action(() =>
            {
                textBox.Focus();
                ShowTouchKeyboard();
            }), System.Windows.Threading.DispatcherPriority.Input);

            // When user finishes editing (loses focus), add to undo stack
            textBox.LostFocus += (s, e) =>
            {
                // Only add to undo stack if text is not empty
                if (!string.IsNullOrWhiteSpace(textBox.Text))
                {
                    // Convert TextBox to TextBlock for permanent display
                    var textBlock = new TextBlock
                    {
                        Text = textBox.Text,
                        Width = textBox.ActualWidth,
                        FontFamily = textBox.FontFamily,
                        FontSize = textBox.FontSize,
                        Foreground = textBox.Foreground,
                        Background = Brushes.Transparent,
                        TextWrapping = TextWrapping.Wrap,
                        Padding = new Thickness(5)
                    };

                    // Position at same location
                    Canvas.SetLeft(textBlock, Canvas.GetLeft(textBox));
                    Canvas.SetTop(textBlock, Canvas.GetTop(textBox));

                    // Replace TextBox with TextBlock
                    MainInteractiveBoard.Children.Remove(textBox);
                    MainInteractiveBoard.Children.Add(textBlock);

                    // ✅ QC_4.2_TEXTBOX_SELECTION_FIX: Đăng ký TextBlock mới với SelectionManager
                    // để giáo viên có thể Chọn, Di chuyển, Thay đổi kích thước/phông chữ ngay lập tức
                    RegisterNewObjectWithSelectionManager(textBlock);

                    // Add to undo stack
                    RecordAddAction(textBlock, "Draw");
                }
                else
                {
                    // Remove empty TextBox
                    MainInteractiveBoard.Children.Remove(textBox);
                }
            };
        }

                public void InsertGraphToCanvas(BitmapImage graphImage, object? graphConfig = null)
        {
            try
            {
                // Create Grid container
                var graphContainer = new Grid
                {
                    Width = 600,
                    Height = 450,
                    Cursor = Cursors.Hand
                };
                
                // Store config in Tag for later editing
                graphContainer.Tag = graphConfig;
                
                // Create Image control
                var image = new Image
                {
                    Source = graphImage,
                    Stretch = Stretch.Uniform,
                    Width = 600,
                    Height = 450
                };
                graphContainer.Children.Add(image);
                
                // Create Top Drag Handle Bar
                var dragHandleBar = new Border
                {
                    Height = 34,
                    Background = new SolidColorBrush(Color.FromRgb(41, 128, 185)),
                    CornerRadius = new CornerRadius(6, 6, 0, 0),
                    Cursor = Cursors.SizeAll,
                    ToolTip = "Nhấn giữ để di chuyển Đồ thị 2D"
                };

                var dragGrid = new Grid();
                var titleText = new TextBlock
                {
                    Text = "📈 Đồ thị 2D - Kéo để di chuyển",
                    Foreground = Brushes.White,
                    FontSize = 12,
                    FontWeight = FontWeights.SemiBold,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(10, 0, 0, 0)
                };
                dragGrid.Children.Add(titleText);

                // Create button panel (top-right corner)
                var buttonPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 0, 4, 0)
                };
                
                // Edit button
                var btnEdit = new Button
                {
                    Content = "✏️",
                    Width = 26,
                    Height = 26,
                    Margin = new Thickness(2, 0, 2, 0),
                    ToolTip = "Sửa đồ thị",
                    Background = new SolidColorBrush(Color.FromArgb(160, 255, 255, 255)),
                    Foreground = Brushes.Black,
                    BorderBrush = Brushes.Transparent,
                    FontSize = 13,
                    Cursor = Cursors.Hand
                };
                btnEdit.Click += (s, e) => EditGraph(graphContainer);
                buttonPanel.Children.Add(btnEdit);
                
                // Delete button
                var btnDelete = new Button
                {
                    Content = "❌",
                    Width = 26,
                    Height = 26,
                    Margin = new Thickness(2, 0, 2, 0),
                    ToolTip = "Xóa đồ thị",
                    Background = new SolidColorBrush(Color.FromRgb(231, 76, 60)),
                    Foreground = Brushes.White,
                    BorderBrush = Brushes.Transparent,
                    FontSize = 13,
                    Cursor = Cursors.Hand
                };
                
                dragGrid.Children.Add(buttonPanel);
                dragHandleBar.Child = dragGrid;

                var finalGraphContainer = new StackPanel
                {
                    Orientation = Orientation.Vertical,
                    Width = 600
                };
                finalGraphContainer.Children.Add(dragHandleBar);
                finalGraphContainer.Children.Add(graphContainer);

                btnDelete.Click += (s, e) => DeleteGraph(finalGraphContainer);
                buttonPanel.Children.Add(btnDelete);

                // Enable Drag-to-Move on dragHandleBar
                bool isDragging = false;
                Point dragStartPoint = new Point();

                dragHandleBar.MouseLeftButtonDown += (s, e) =>
                {
                    isDragging = true;
                    dragStartPoint = e.GetPosition(MainInteractiveBoard);
                    dragHandleBar.CaptureMouse();
                    e.Handled = true;
                };

                dragHandleBar.MouseMove += (s, e) =>
                {
                    if (isDragging)
                    {
                        Point currentPoint = e.GetPosition(MainInteractiveBoard);
                        double left = Canvas.GetLeft(finalGraphContainer) + (currentPoint.X - dragStartPoint.X);
                        double top = Canvas.GetTop(finalGraphContainer) + (currentPoint.Y - dragStartPoint.Y);

                        left = Math.Max(0, Math.Min(left, MainInteractiveBoard.ActualWidth - 600));
                        top = Math.Max(0, Math.Min(top, MainInteractiveBoard.ActualHeight - 484));

                        Canvas.SetLeft(finalGraphContainer, left);
                        Canvas.SetTop(finalGraphContainer, top);
                        dragStartPoint = currentPoint;
                    }
                };

                dragHandleBar.MouseLeftButtonUp += (s, e) =>
                {
                    if (isDragging)
                    {
                        isDragging = false;
                        dragHandleBar.ReleaseMouseCapture();
                    }
                };

                dragHandleBar.PreviewTouchDown += (s, e) =>
                {
                    isDragging = true;
                    dragStartPoint = e.GetTouchPoint(MainInteractiveBoard).Position;
                    dragHandleBar.CaptureTouch(e.TouchDevice);
                    e.Handled = true;
                };

                dragHandleBar.TouchMove += (s, e) =>
                {
                    if (isDragging)
                    {
                        Point currentPoint = e.GetTouchPoint(MainInteractiveBoard).Position;
                        double left = Canvas.GetLeft(finalGraphContainer) + (currentPoint.X - dragStartPoint.X);
                        double top = Canvas.GetTop(finalGraphContainer) + (currentPoint.Y - dragStartPoint.Y);

                        left = Math.Max(0, Math.Min(left, MainInteractiveBoard.ActualWidth - 600));
                        top = Math.Max(0, Math.Min(top, MainInteractiveBoard.ActualHeight - 484));

                        Canvas.SetLeft(finalGraphContainer, left);
                        Canvas.SetTop(finalGraphContainer, top);
                        dragStartPoint = currentPoint;
                        e.Handled = true;
                    }
                };

                dragHandleBar.TouchUp += (s, e) =>
                {
                    if (isDragging)
                    {
                        isDragging = false;
                        dragHandleBar.ReleaseTouchCapture(e.TouchDevice);
                        e.Handled = true;
                    }
                };

                // Position container at center of canvas
                double leftPos = (MainInteractiveBoard.ActualWidth - 600) / 2;
                double topPos = (MainInteractiveBoard.ActualHeight - 484) / 2;

                Canvas.SetLeft(finalGraphContainer, Math.Max(0, leftPos));
                Canvas.SetTop(finalGraphContainer, Math.Max(0, topPos));

                // Add to canvas
                MainInteractiveBoard.Children.Add(finalGraphContainer);

                // Add to undo stack
                RecordAddAction(finalGraphContainer, "Graph");

                System.Diagnostics.Debug.WriteLine($"✅ Graph inserted with DragHandle at ({leftPos:F0}, {topPos:F0})");
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Lỗi chèn đồ thị: {ex.Message}", "Lỗi",
                              MessageBoxButton.OK, MessageBoxImage.Error);
                System.Diagnostics.Debug.WriteLine($"❌ InsertGraphToCanvas error: {ex.Message}");
            }
        }
        
        private void EditGraph(Grid graphContainer)
        {
            try
            {
                var config = graphContainer.Tag;
                if (config == null)
                {
                    MessageBox.Show("Đồ thị không có thông tin cấu hình để chỉnh sửa.", "Thông báo",
                                  MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                
                // Open editor with existing config
                var graphEditor = new Form2_GraphEditorUnified(config);
                bool? result = graphEditor.ShowDialog();
                
                if (result == true && graphEditor.ExportedGraphImage != null)
                {
                    // Update image
                    var image = graphContainer.Children.OfType<Image>().FirstOrDefault();
                    if (image != null)
                    {
                        image.Source = graphEditor.ExportedGraphImage;
                        graphContainer.Tag = graphEditor.ExportedConfig;
                        System.Diagnostics.Debug.WriteLine("✅ Graph updated");
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Lỗi chỉnh sửa đồ thị: {ex.Message}", "Lỗi",
                              MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }
        
        private void DeleteGraph(FrameworkElement graphContainer)
        {
            var result = MessageBox.Show("Bạn có chắc muốn xóa đồ thị này?", "Xác nhận",
                                        MessageBoxButton.YesNo, MessageBoxImage.Question);
            if (result == MessageBoxResult.Yes)
            {
                MainInteractiveBoard.Children.Remove(graphContainer);
                RecordRemoveAction(graphContainer, "Graph");
                System.Diagnostics.Debug.WriteLine("✅ Graph deleted");
            }
        }

        #region Container Drag & Element Attachment Helpers

        /// <summary>
        /// Retrieves all canvas UI elements located inside or overlapping the bounding box of a container (e.g. Table, Text Box)
        /// </summary>
        private List<UIElement> GetElementsInsideContainer(FrameworkElement container)
        {
            var list = new List<UIElement>();
            if (MainInteractiveBoard == null || container == null) return list;

            double cLeft = Canvas.GetLeft(container);
            double cTop = Canvas.GetTop(container);
            if (double.IsNaN(cLeft)) cLeft = 0;
            if (double.IsNaN(cTop)) cTop = 0;
            double cWidth = container.ActualWidth > 0 ? container.ActualWidth : container.Width;
            double cHeight = container.ActualHeight > 0 ? container.ActualHeight : container.Height;

            if (cWidth <= 0) cWidth = 200;
            if (cHeight <= 0) cHeight = 100;

            Rect cRect = new Rect(cLeft, cTop, cWidth, cHeight);
            cRect.Inflate(15, 15); // Slight margin to capture strokes on borders

            foreach (UIElement child in MainInteractiveBoard.Children)
            {
                if (child == container) continue;
                if (child == _zoomAreaOverlay) continue;

                // ✅ QC_4.2_GRID_PROTECT (GR-1): KHÔNG BAO GIỜ đính kèm background elements
                // bgRect/patternRect phủ toàn Canvas → luôn intersect → PHẢI skip
                if (child is FrameworkElement bgCheck && 
                    SelectionManager.IsBackgroundElement(bgCheck))
                    continue;

                // Skip child elements that are inside container
                if (child is FrameworkElement feChild && IsDescendantOf(feChild, container)) continue;

                Rect elemRect = Rect.Empty;

                if (child is Polyline polyline)
                {
                    if (polyline.Points == null || polyline.Points.Count == 0) continue;
                    // Skip selection rectangle or lasso visuals
                    if (Panel.GetZIndex(polyline) >= ZIndexConstants.SystemUIBase) continue;

                    double minX = double.MaxValue, maxX = double.MinValue;
                    double minY = double.MaxValue, maxY = double.MinValue;
                    foreach (var pt in polyline.Points)
                    {
                        if (pt.X < minX) minX = pt.X;
                        if (pt.X > maxX) maxX = pt.X;
                        if (pt.Y < minY) minY = pt.Y;
                        if (pt.Y > maxY) maxY = pt.Y;
                    }
                    elemRect = new Rect(minX, minY, Math.Max(1, maxX - minX), Math.Max(1, maxY - minY));
                }
                else if (child is System.Windows.Shapes.Path path)
                {
                    var bounds = path.RenderedGeometry?.Bounds ?? Rect.Empty;
                    if (!bounds.IsEmpty)
                    {
                        double pLeft = double.IsNaN(Canvas.GetLeft(path)) ? 0 : Canvas.GetLeft(path);
                        double pTop = double.IsNaN(Canvas.GetTop(path)) ? 0 : Canvas.GetTop(path);
                        if (path.RenderTransform is TranslateTransform tt)
                        {
                            pLeft += tt.X;
                            pTop += tt.Y;
                        }
                        elemRect = new Rect(pLeft + bounds.X, pTop + bounds.Y, bounds.Width, bounds.Height);
                    }
                }
                else if (child is FrameworkElement fe)
                {
                    double feLeft = double.IsNaN(Canvas.GetLeft(fe)) ? 0 : Canvas.GetLeft(fe);
                    double feTop = double.IsNaN(Canvas.GetTop(fe)) ? 0 : Canvas.GetTop(fe);
                    double feW = fe.ActualWidth > 0 ? fe.ActualWidth : fe.Width;
                    double feH = fe.ActualHeight > 0 ? fe.ActualHeight : fe.Height;
                    elemRect = new Rect(feLeft, feTop, Math.Max(1, feW), Math.Max(1, feH));
                }

                if (!elemRect.IsEmpty && cRect.IntersectsWith(elemRect))
                {
                    list.Add(child);
                }
            }

            return list;
        }

        private bool IsDescendantOf(DependencyObject element, DependencyObject parent)
        {
            while (element != null)
            {
                if (element == parent) return true;
                // Safe: ContentElement dùng LogicalTreeHelper
                element = (element is System.Windows.Media.Visual || element is System.Windows.Media.Media3D.Visual3D)
                    ? VisualTreeHelper.GetParent(element)
                    : LogicalTreeHelper.GetParent(element);
            }
            return false;
        }

        /// <summary>
        /// Moves attached elements synchronously by deltaX and deltaY
        /// </summary>
        private void MoveAttachedElements(List<UIElement> elements, double deltaX, double deltaY)
        {
            if (elements == null || elements.Count == 0 || (deltaX == 0 && deltaY == 0)) return;

            foreach (var elem in elements)
            {
                // ✅ QC_4.2_GRID_PROTECT (GR-2): Guard cuối cùng — chặn di chuyển background elements
                if (elem is FrameworkElement bgElem && SelectionManager.IsBackgroundElement(bgElem))
                {
                    System.Diagnostics.Debug.WriteLine($"🛑 MoveAttachedElements BLOCKED: {bgElem.GetType().Name} Tag={bgElem.Tag}");
                    continue;
                }

                if (elem is Polyline polyline && polyline.Points != null)
                {
                    for (int i = 0; i < polyline.Points.Count; i++)
                    {
                        Point pt = polyline.Points[i];
                        polyline.Points[i] = new Point(pt.X + deltaX, pt.Y + deltaY);
                    }
                }
                else if (elem is System.Windows.Shapes.Path path)
                {
                    if (path.RenderTransform is TranslateTransform tt)
                    {
                        tt.X += deltaX;
                        tt.Y += deltaY;
                    }
                    else
                    {
                        path.RenderTransform = new TranslateTransform(deltaX, deltaY);
                    }
                }
                else if (elem is FrameworkElement fe)
                {
                    double curL = double.IsNaN(Canvas.GetLeft(fe)) ? 0 : Canvas.GetLeft(fe);
                    double curT = double.IsNaN(Canvas.GetTop(fe)) ? 0 : Canvas.GetTop(fe);
                    Canvas.SetLeft(fe, curL + deltaX);
                    Canvas.SetTop(fe, curT + deltaY);
                }
            }
        }

        #endregion

        /// <summary>
        /// Insert table to canvas from TableData
        /// </summary>
        public void InsertTableToCanvas(Models.TableData tableData)
        {
            try
            {
                // Create Grid container for the table cells
                var tableGrid = new Grid
                {
                    Background = Brushes.White,
                    Cursor = Cursors.Arrow
                };

                // Store TableData in Tag for later editing
                tableGrid.Tag = tableData;

                // Create column definitions
                for (int c = 0; c < tableData.ColumnCount; c++)
                {
                    tableGrid.ColumnDefinitions.Add(new ColumnDefinition
                    {
                        Width = new GridLength(tableData.Columns[c].Width)
                    });
                }

                // Create row definitions
                for (int r = 0; r < tableData.RowCount; r++)
                {
                    tableGrid.RowDefinitions.Add(new RowDefinition
                    {
                        Height = new GridLength(tableData.Rows[r].Height)
                    });
                }

                // Create cells
                for (int r = 0; r < tableData.RowCount; r++)
                {
                    for (int c = 0; c < tableData.ColumnCount; c++)
                    {
                        var cell = tableData.GetCell(r, c);

                        var cellBorder = new Border
                        {
                            BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(tableData.BorderColor)),
                            BorderThickness = new Thickness(tableData.BorderThickness),
                            Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString(cell.BackgroundColor)),
                            Padding = new Thickness(tableData.CellPadding),
                            Tag = cell,
                            Cursor = Cursors.IBeam
                        };

                        var textBlock = new TextBlock
                        {
                            Text = string.IsNullOrEmpty(cell.Content) ? " " : cell.Content,
                            Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString(cell.ForegroundColor)),
                            FontFamily = new FontFamily(cell.FontFamily),
                            FontSize = cell.FontSize,
                            FontWeight = cell.IsBold ? FontWeights.Bold : FontWeights.Normal,
                            FontStyle = cell.IsItalic ? FontStyles.Italic : FontStyles.Normal,
                            TextWrapping = TextWrapping.Wrap,
                            TextAlignment = GetTextAlignment(cell.HorizontalAlignment),
                            VerticalAlignment = GetVerticalAlignment(cell.VerticalAlignment)
                        };

                        if (cell.IsUnderline)
                        {
                            textBlock.TextDecorations = TextDecorations.Underline;
                        }

                        cellBorder.Child = textBlock;

                        // Double click to edit cell inline
                        cellBorder.MouseLeftButtonDown += (s, e) =>
                        {
                            if (e.ClickCount == 2)
                            {
                                EnableInlineCellEditing(cellBorder, textBlock, cell, tableData);
                                e.Handled = true;
                            }
                        };

                        Grid.SetRow(cellBorder, r);
                        Grid.SetColumn(cellBorder, c);

                        tableGrid.Children.Add(cellBorder);
                    }
                }

                // Create outer border for table grid
                var outerBorder = new Border
                {
                    BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(tableData.BorderColor)),
                    BorderThickness = new Thickness(tableData.BorderThickness),
                    Child = tableGrid,
                    Background = Brushes.White
                };

                // Main Container for Table + Drag Handle Bar
                var finalContainer = new StackPanel
                {
                    Orientation = Orientation.Vertical,
                    Background = Brushes.Transparent,
                    // ✅ QC_4.2_TABLE_TAG_FIX (T8): Gán Tag để IsDragHandleOrEmbeddedWidget nhận diện
                    Tag = "TableContainer"
                };

                // Create Top Drag Bar (Header Handle)
                var dragHandleBar = new Border
                {
                    Height = 34,
                    Background = new SolidColorBrush(Color.FromRgb(41, 128, 185)), // QA Brand Primary Blue
                    CornerRadius = new CornerRadius(6, 6, 0, 0),
                    Cursor = Cursors.SizeAll,
                    // ✅ QC_4.2_TABLE_TAG_FIX (T8): Gán Tag để IsDragHandleOrEmbeddedWidget nhận diện
                    Tag = "DragHandle",
                    ToolTip = "Nhấn giữ để di chuyển Bảng trên màn hình"
                };

                var dragHandleGrid = new Grid();
                var titleText = new TextBlock
                {
                    Text = "📊 Bảng dữ liệu - Kéo để di chuyển",
                    Foreground = Brushes.White,
                    FontSize = 12,
                    FontWeight = FontWeights.SemiBold,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(10, 0, 0, 0)
                };
                dragHandleGrid.Children.Add(titleText);

                // Button panel with 3 Function Buttons: Edit ✏️, Move 🖐️, Delete ❌
                var buttonPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 0, 4, 0)
                };

                // 1. Nút Chỉnh sửa ✏️
                var btnEdit = new Button
                {
                    Content = "✏️",
                    Width = 28,
                    Height = 26,
                    Margin = new Thickness(2, 0, 2, 0),
                    ToolTip = "Chỉnh sửa cấu trúc/nội dung bảng",
                    Background = new SolidColorBrush(Color.FromArgb(160, 255, 255, 255)),
                    Foreground = Brushes.Black,
                    BorderBrush = Brushes.Transparent,
                    FontSize = 13,
                    Cursor = Cursors.Hand
                };
                btnEdit.Click += (s, e) =>
                {
                    e.Handled = true;
                    EditTable(outerBorder);
                };
                btnEdit.PreviewTouchUp += (s, e) =>
                {
                    // ✅ QC_4.2_TABLE_TOUCHUP_FIX (T5): Dùng TouchUp thay TouchDown
                    // tránh Touch UP lọt vào Dialog khi tay còn chạm màn hình
                    e.Handled = true;
                    EditTable(outerBorder);
                };
                buttonPanel.Children.Add(btnEdit);

                // 2. Nút Di chuyển 🖐️ (Nút chuyên biệt để di chuyển Bảng)
                var btnMove = new Button
                {
                    Content = "🖐️",
                    Width = 28,
                    Height = 26,
                    Margin = new Thickness(2, 0, 2, 0),
                    ToolTip = "Click giữ hoặc chạm giữ nút này để di chuyển Bảng",
                    Background = new SolidColorBrush(Color.FromRgb(52, 152, 219)), // QA Primary Blue
                    Foreground = Brushes.White,
                    BorderBrush = Brushes.Transparent,
                    FontSize = 13,
                    Cursor = Cursors.SizeAll
                };
                buttonPanel.Children.Add(btnMove);

                // 3. Nút Xóa ❌
                var btnDelete = new Button
                {
                    Content = "❌",
                    Width = 28,
                    Height = 26,
                    Margin = new Thickness(2, 0, 2, 0),
                    ToolTip = "Xóa bảng khỏi màn hình",
                    Background = new SolidColorBrush(Color.FromRgb(231, 76, 60)),
                    Foreground = Brushes.White,
                    BorderBrush = Brushes.Transparent,
                    FontSize = 13,
                    Cursor = Cursors.Hand
                };
                btnDelete.Click += (s, e) =>
                {
                    e.Handled = true;
                    DeleteTable(finalContainer);
                };
                btnDelete.PreviewTouchUp += (s, e) =>
                {
                    // ✅ QC_4.2_TABLE_TOUCHUP_FIX (T5): Dùng TouchUp thay TouchDown
                    // tránh vô tình chọn "Có" khi nhấc tay khỏi MessageBox
                    e.Handled = true;
                    DeleteTable(finalContainer);
                };
                buttonPanel.Children.Add(btnDelete);

                dragHandleGrid.Children.Add(buttonPanel);
                dragHandleBar.Child = dragHandleGrid;

                finalContainer.Children.Add(dragHandleBar);
                finalContainer.Children.Add(outerBorder);

                // Calculate size
                double totalWidth = Math.Max(tableData.GetTotalWidth() + (tableData.BorderThickness * 2), 240);
                double totalHeight = tableData.GetTotalHeight() + (tableData.BorderThickness * 2) + 34;

                finalContainer.Width = totalWidth;

                // Enable Drag-to-Move when pressing & holding btnMove (or dragHandleBar)
                bool isDragging = false;
                Point dragStartPoint = new Point();
                List<UIElement> attachedElements = new List<UIElement>();

                Action<Point> startMove = (startPt) =>
                {
                    _isDrawing = false;
                    _currentStroke = null;
                    isDragging = true;
                    dragStartPoint = startPt;
                    attachedElements = GetElementsInsideContainer(finalContainer);
                };

                Action<Point> processMove = (currentPoint) =>
                {
                    if (isDragging)
                    {
                        double oldLeft = Canvas.GetLeft(finalContainer);
                        double oldTop = Canvas.GetTop(finalContainer);

                        double newLeft = oldLeft + (currentPoint.X - dragStartPoint.X);
                        double newTop = oldTop + (currentPoint.Y - dragStartPoint.Y);

                        // Keep within canvas bounds
                        newLeft = Math.Max(0, Math.Min(newLeft, MainInteractiveBoard.ActualWidth - totalWidth));
                        newTop = Math.Max(0, Math.Min(newTop, MainInteractiveBoard.ActualHeight - totalHeight));

                        double actualDeltaX = newLeft - oldLeft;
                        double actualDeltaY = newTop - oldTop;

                        Canvas.SetLeft(finalContainer, newLeft);
                        Canvas.SetTop(finalContainer, newTop);

                        MoveAttachedElements(attachedElements, actualDeltaX, actualDeltaY);

                        dragStartPoint = currentPoint;
                        _selectionBox?.UpdatePosition();
                    }
                };

                Action endMove = () =>
                {
                    if (isDragging)
                    {
                        isDragging = false;
                        attachedElements.Clear();
                        RefreshSelectableObjects();
                    }
                };

                // ============================================================
                // Hook Move Events on btnMove & dragHandleBar
                // QC_4.2_TABLE_MOVE_FIX_V2: Sửa toàn diện theo kết quả Review
                // ============================================================

                // --- btnMove: Mouse events ---
                btnMove.MouseLeftButtonDown += (s, e) =>
                {
                    startMove(e.GetPosition(MainInteractiveBoard));
                    btnMove.CaptureMouse();
                    e.Handled = true;
                };

                btnMove.MouseMove += (s, e) =>
                {
                    if (isDragging)
                    {
                        processMove(e.GetPosition(MainInteractiveBoard));
                        e.Handled = true; // ✅ Issue #5: Chặn event bubble khi đang kéo
                    }
                };

                btnMove.MouseLeftButtonUp += (s, e) =>
                {
                    // ✅ Issue #2: Luôn giải phóng capture bất kể isDragging
                    endMove();
                    if (btnMove.IsMouseCaptured)
                        btnMove.ReleaseMouseCapture();
                    e.Handled = true;
                };

                // ✅ Issue #2: Xử lý mất capture bất ngờ (Alt+Tab, cửa sổ hệ thống)
                btnMove.LostMouseCapture += (s, e) =>
                {
                    endMove();
                };

                // --- btnMove: Touch events ---
                btnMove.PreviewTouchDown += (s, e) =>
                {
                    startMove(e.GetTouchPoint(MainInteractiveBoard).Position);
                    btnMove.CaptureTouch(e.TouchDevice);
                    e.Handled = true;
                };

                btnMove.TouchMove += (s, e) =>
                {
                    if (isDragging)
                    {
                        processMove(e.GetTouchPoint(MainInteractiveBoard).Position);
                        e.Handled = true;
                    }
                };

                btnMove.TouchUp += (s, e) =>
                {
                    // ✅ Issue #2: Luôn giải phóng capture bất kể isDragging
                    endMove();
                    if (e.TouchDevice.Captured == btnMove)
                        btnMove.ReleaseTouchCapture(e.TouchDevice);
                    e.Handled = true;
                };

                // ✅ Issue #2: Xử lý mất touch capture bất ngờ
                btnMove.LostTouchCapture += (s, e) =>
                {
                    endMove();
                };

                // --- dragHandleBar: Mouse events ---
                dragHandleBar.MouseLeftButtonDown += (s, e) =>
                {
                    if (e.OriginalSource is DependencyObject depObj && IsDescendantOf(depObj, buttonPanel)) return;
                    startMove(e.GetPosition(MainInteractiveBoard));
                    dragHandleBar.CaptureMouse();
                    e.Handled = true;
                };

                dragHandleBar.MouseMove += (s, e) =>
                {
                    if (isDragging)
                    {
                        processMove(e.GetPosition(MainInteractiveBoard));
                        e.Handled = true; // ✅ Issue #5: Chặn event bubble khi đang kéo
                    }
                };

                dragHandleBar.MouseLeftButtonUp += (s, e) =>
                {
                    // ✅ Issue #2 & #6: Luôn giải phóng capture + e.Handled
                    endMove();
                    if (dragHandleBar.IsMouseCaptured)
                        dragHandleBar.ReleaseMouseCapture();
                    e.Handled = true;
                };

                // ✅ Issue #2: Xử lý mất capture bất ngờ
                dragHandleBar.LostMouseCapture += (s, e) =>
                {
                    endMove();
                };

                // --- dragHandleBar: Touch events --- (✅ Issue #4: Bổ sung Touch cho dragHandleBar)
                dragHandleBar.PreviewTouchDown += (s, e) =>
                {
                    if (e.OriginalSource is DependencyObject depObj && IsDescendantOf(depObj, buttonPanel)) return;
                    startMove(e.GetTouchPoint(MainInteractiveBoard).Position);
                    dragHandleBar.CaptureTouch(e.TouchDevice);
                    e.Handled = true;
                };

                dragHandleBar.TouchMove += (s, e) =>
                {
                    if (isDragging)
                    {
                        processMove(e.GetTouchPoint(MainInteractiveBoard).Position);
                        e.Handled = true;
                    }
                };

                dragHandleBar.TouchUp += (s, e) =>
                {
                    endMove();
                    if (e.TouchDevice.Captured == dragHandleBar)
                        dragHandleBar.ReleaseTouchCapture(e.TouchDevice);
                    e.Handled = true;
                };

                // ✅ Issue #2: Xử lý mất touch capture bất ngờ
                dragHandleBar.LostTouchCapture += (s, e) =>
                {
                    endMove();
                };

                // Position at center of canvas
                double leftPos = (MainInteractiveBoard.ActualWidth - totalWidth) / 2;
                double topPos = (MainInteractiveBoard.ActualHeight - totalHeight) / 2;

                Canvas.SetLeft(finalContainer, Math.Max(0, leftPos));
                Canvas.SetTop(finalContainer, Math.Max(0, topPos));

                // Add to canvas
                MainInteractiveBoard.Children.Add(finalContainer);
                // ✅ QC_4.2_TABLE_ZINDEX (T9): Đặt Z-Index cho Bảng TRÊN nét vẽ, DƯỚI Widget
                Panel.SetZIndex(finalContainer, QASmartTouch.Helpers.ZIndexConstants.TableContainer);

                // Add to undo stack
                RecordAddAction(finalContainer, "Table");

                // ✅ N21 FIX: Register finalContainer with SelectionManager so clicks do not hit-test null and deselect/remove
                RefreshSelectableObjects();

                System.Diagnostics.Debug.WriteLine($"✅ Table inserted with DragHandle at ({leftPos:F0}, {topPos:F0}), size: {totalWidth:F0}x{totalHeight:F0}");
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Lỗi chèn bảng: {ex.Message}", "Lỗi",
                              MessageBoxButton.OK, MessageBoxImage.Error);
                System.Diagnostics.Debug.WriteLine($"❌ InsertTableToCanvas error: {ex.Message}");
            }
        }

        private void EnableInlineCellEditing(Border cellBorder, TextBlock textBlock, Models.TableCell cell, Models.TableData tableData)
        {
            try
            {
                var textBox = new TextBox
                {
                    Text = cell.Content,
                    FontFamily = textBlock.FontFamily,
                    FontSize = textBlock.FontSize,
                    FontWeight = textBlock.FontWeight,
                    FontStyle = textBlock.FontStyle,
                    Foreground = textBlock.Foreground,
                    Background = Brushes.White,
                    TextWrapping = TextWrapping.Wrap,
                    AcceptsReturn = true,
                    VerticalAlignment = VerticalAlignment.Stretch,
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    Padding = new Thickness(2)
                };

                cellBorder.Child = textBox;
                textBox.Focus();
                textBox.SelectAll();

                // Trigger Virtual Keyboard for Teacher
                ShowTouchKeyboard();

                void SaveCellContent()
                {
                    cell.Content = textBox.Text;
                    textBlock.Text = string.IsNullOrEmpty(cell.Content) ? " " : cell.Content;
                    cellBorder.Child = textBlock;
                }

                textBox.LostFocus += (s, e) => SaveCellContent();
                textBox.KeyDown += (s, e) =>
                {
                    if (e.Key == Key.Enter && !Keyboard.IsKeyDown(Key.LeftShift))
                    {
                        SaveCellContent();
                        e.Handled = true;
                    }
                };
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ EnableInlineCellEditing error: {ex.Message}");
            }
        }

        public static void ShowTouchKeyboard()
        {
            try
            {
                // ✅ QC_4.2_TABLE_KEYBOARD_FIX (T11): Kiểm tra TabTip/osk đã chạy chưa
                // Tránh spawn nhiều instance khi GV chạm nhanh nhiều ô liên tiếp
                var existingTabTip = System.Diagnostics.Process.GetProcessesByName("TabTip");
                if (existingTabTip.Length > 0) return;

                var existingOsk = System.Diagnostics.Process.GetProcessesByName("osk");
                if (existingOsk.Length > 0) return;

                string tabTipPath = System.IO.Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFiles),
                    @"microsoft shared\ink\TabTip.exe");

                if (System.IO.File.Exists(tabTipPath))
                {
                    System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
                    {
                        FileName = tabTipPath,
                        UseShellExecute = true
                    });
                    return;
                }

                string oskPath = System.IO.Path.Combine(Environment.SystemDirectory, "osk.exe");
                if (System.IO.File.Exists(oskPath))
                {
                    System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
                    {
                        FileName = oskPath,
                        UseShellExecute = true
                    });
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"⚠️ ShowTouchKeyboard error: {ex.Message}");
            }
        }

        private TextAlignment GetTextAlignment(string alignment)
        {
            return alignment switch
            {
                "Left" => TextAlignment.Left,
                "Center" => TextAlignment.Center,
                "Right" => TextAlignment.Right,
                _ => TextAlignment.Left
            };
        }

        private VerticalAlignment GetVerticalAlignment(string alignment)
        {
            return alignment switch
            {
                "Top" => VerticalAlignment.Top,
                "Center" => VerticalAlignment.Center,
                "Bottom" => VerticalAlignment.Bottom,
                _ => VerticalAlignment.Center
            };
        }

        private void EditTable(Border tableContainer)
        {
            try
            {
                // Extract TableData from Tag
                var grid = tableContainer.Child as Grid;
                var tableData = grid?.Tag as Models.TableData;

                if (tableData == null)
                {
                    MessageBox.Show("Không tìm thấy dữ liệu bảng để chỉnh sửa.", "Thông báo",
                                  MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                // Open editor with existing data
                var tableDialog = new Form2_TableEditorDialog(tableData);
                tableDialog.Owner = this;
                bool? result = tableDialog.ShowDialog();

                if (result == true && tableDialog.ResultTableData != null)
                {
                    // ✅ QC_4.2_TABLE_EDIT_FIX: Sửa ép kiểu — parent thực tế là StackPanel, KHÔNG phải Grid
                    var parent = tableContainer.Parent as StackPanel;
                    if (parent != null)
                    {
                        // Get position of old table
                        double left = Canvas.GetLeft(parent);
                        double top = Canvas.GetTop(parent);

                        // Record Undo for old table removal
                        RecordRemoveAction(parent, "Table");

                        // Remove old table from Canvas
                        MainInteractiveBoard.Children.Remove(parent);

                        // Re-insert updated table (this will create new visuals)
                        InsertTableToCanvas(tableDialog.ResultTableData);

                        // ✅ QC_4.2_TABLE_EDIT_FIX: Tìm container mới — InsertTableToCanvas tạo StackPanel
                        var newContainer = MainInteractiveBoard.Children.OfType<StackPanel>().LastOrDefault();
                        if (newContainer != null)
                        {
                            Canvas.SetLeft(newContainer, left);
                            Canvas.SetTop(newContainer, top);
                        }

                        // ✅ N21 FIX: Đăng ký lại với SelectionManager
                        RefreshSelectableObjects();

                        System.Diagnostics.Debug.WriteLine("✅ Table updated successfully at position: " + left + ", " + top);
                    }
                    else
                    {
                        System.Diagnostics.Debug.WriteLine("❌ EditTable: parent is not StackPanel — type = " + tableContainer.Parent?.GetType().Name);
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Lỗi sửa bảng: {ex.Message}", "Lỗi",
                              MessageBoxButton.OK, MessageBoxImage.Error);
                System.Diagnostics.Debug.WriteLine($"❌ EditTable error: {ex.Message}");
            }
        }

        private void DeleteTable(FrameworkElement tableContainer)
        {
            try
            {
                var result = MessageBox.Show(
                    "Bạn có chắc chắn muốn xóa Bảng dữ liệu này cùng toàn bộ nội dung/nét vẽ bên trong không?",
                    "Xác nhận xóa Bảng dữ liệu",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Question);

                if (result == MessageBoxResult.Yes)
                {
                    FrameworkElement targetToDelete = tableContainer;
                    if (tableContainer != null && tableContainer.Parent is FrameworkElement parentFE && !(parentFE is Canvas))
                    {
                        targetToDelete = parentFE;
                    }

                    if (targetToDelete != null && MainInteractiveBoard.Children.Contains(targetToDelete))
                    {
                        var attached = GetElementsInsideContainer(targetToDelete);
                        // ✅ QC_4.2_TABLE_UNDO_FIX (T6): Ghi từng attached element vào Undo stack
                        // TRƯỚC khi xóa, để Ctrl+Z khôi phục cả nét vẽ đính kèm
                        foreach (var elem in attached)
                        {
                            RecordRemoveAction(elem, "TableAttachedStroke");
                        }
                        foreach (var elem in attached)
                        {
                            MainInteractiveBoard.Children.Remove(elem);
                        }

                        MainInteractiveBoard.Children.Remove(targetToDelete);
                        RecordRemoveAction(targetToDelete, "Table");
                        RefreshSelectableObjects();

                        MessageBox.Show(
                            "Đã xóa Bảng dữ liệu thành công!",
                            "Thông báo",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        System.Diagnostics.Debug.WriteLine("✅ Table deleted successfully");
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ DeleteTable error: {ex.Message}");
            }
        }

        /// <summary>
        /// Insert rich text box to canvas
        /// </summary>
        public void InsertTextBoxToCanvas(Controls.RichTextBoxControl sourceTextBoxControl)
        {
            try
            {
                // Create NEW text box control (can't reuse from dialog due to WPF parent restrictions)
                var newTextBox = new Controls.RichTextBoxControl
                {
                    MinWidth = sourceTextBoxControl.MinWidth,
                    MinHeight = sourceTextBoxControl.MinHeight
                };

                // Copy the FlowDocument content from source to new control
                var sourceRange = new TextRange(
                    sourceTextBoxControl.Document.ContentStart,
                    sourceTextBoxControl.Document.ContentEnd);
                
                var targetRange = new TextRange(
                    newTextBox.Document.ContentStart,
                    newTextBox.Document.ContentEnd);

                using (var stream = new System.IO.MemoryStream())
                {
                    sourceRange.Save(stream, DataFormats.XamlPackage);
                    stream.Seek(0, System.IO.SeekOrigin.Begin);
                    targetRange.Load(stream, DataFormats.XamlPackage);
                }

                // Explicitly clear placeholder flag on the newly populated text box
                newTextBox.ClearPlaceholder();

                // Create container for text box with drag handles
                var container = new Grid
                {
                    Width = newTextBox.MinWidth + 20,
                    Height = newTextBox.MinHeight + 40,
                    // ✅ QC_4.2_TEXTBOX_TAG_FIX (TB-1): Gán Tag để IsSystemElement nhận diện
                    Tag = "TextBoxContainer"
                };

                // Add NEW text box control
                newTextBox.Margin = new Thickness(10, 30, 10, 10);
                newTextBox.GotFocus += (s, e) => ShowTouchKeyboard();
                container.Children.Add(newTextBox);
                ShowTouchKeyboard();

                // Create drag handle (top bar)
                var dragHandle = new Border
                {
                    Height = 30,
                    Background = new SolidColorBrush(Color.FromRgb(46, 134, 222)),
                    VerticalAlignment = VerticalAlignment.Top,
                    Cursor = Cursors.SizeAll,
                    // ✅ QC_4.2_TEXTBOX_TAG_FIX (TB-1): Gán Tag để IsDragHandleOrEmbeddedWidget nhận diện
                    Tag = "DragHandle"
                };

                var dragHandleText = new TextBlock
                {
                    Text = "📝 Hộp văn bản - Kéo để di chuyển",
                    Foreground = Brushes.White,
                    FontSize = 11,
                    FontWeight = FontWeights.SemiBold,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(10, 0, 0, 0)
                };
                dragHandle.Child = dragHandleText;
                container.Children.Add(dragHandle);

                // Add delete button
                var btnDelete = new Button
                {
                    Content = "❌",
                    Width = 28,
                    Height = 28,
                    Background = new SolidColorBrush(Color.FromRgb(231, 76, 60)),
                    Foreground = Brushes.White,
                    BorderThickness = new Thickness(0),
                    FontSize = 14,
                    Cursor = Cursors.Hand,
                    ToolTip = "Xóa hộp văn bản",
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(0, 1, 1, 0)
                };
                btnDelete.Click += (s, e) => { e.Handled = true; Dispatcher.BeginInvoke(new Action(() => DeleteTextBox(container))); };
                // ✅ QC_4.2_TEXTBOX_TOUCHUP_FIX (TB-2): Dùng Dispatcher.BeginInvoke để tránh kẹt TouchCapture khi bật MessageBox
                btnDelete.PreviewTouchUp += (s, e) => { e.Handled = true; Dispatcher.BeginInvoke(new Action(() => DeleteTextBox(container))); };
                container.Children.Add(btnDelete);

                // Enable dragging
                bool isDragging = false;
                Point dragStartPoint = new Point();
                List<UIElement> attachedElements = new List<UIElement>();

                Action endMove = () =>
                {
                    if (isDragging)
                    {
                        isDragging = false;
                        attachedElements.Clear();
                        RefreshSelectableObjects();
                    }
                };

                Action<Point> startMove = (startPt) =>
                {
                    _isDrawing = false;
                    _currentStroke = null;
                    isDragging = true;
                    dragStartPoint = startPt;
                    attachedElements = GetElementsInsideContainer(container);
                };

                dragHandle.MouseLeftButtonDown += (s, e) =>
                {
                    startMove(e.GetPosition(MainInteractiveBoard));
                    dragHandle.CaptureMouse();
                    e.Handled = true;
                };

                dragHandle.MouseMove += (s, e) =>
                {
                    if (isDragging)
                    {
                        Point currentPoint = e.GetPosition(MainInteractiveBoard);
                        double oldLeft = Canvas.GetLeft(container);
                        double oldTop = Canvas.GetTop(container);

                        double newLeft = oldLeft + (currentPoint.X - dragStartPoint.X);
                        double newTop = oldTop + (currentPoint.Y - dragStartPoint.Y);

                        // Keep within canvas bounds
                        newLeft = Math.Max(0, Math.Min(newLeft, MainInteractiveBoard.ActualWidth - container.Width));
                        newTop = Math.Max(0, Math.Min(newTop, MainInteractiveBoard.ActualHeight - container.Height));

                        double actualDeltaX = newLeft - oldLeft;
                        double actualDeltaY = newTop - oldTop;

                        Canvas.SetLeft(container, newLeft);
                        Canvas.SetTop(container, newTop);

                        MoveAttachedElements(attachedElements, actualDeltaX, actualDeltaY);

                        dragStartPoint = currentPoint;
                        e.Handled = true; // ✅ Chặn event bubble khi đang kéo
                    }
                };

                dragHandle.MouseLeftButtonUp += (s, e) =>
                {
                    // ✅ QC_4.2_CAPTURE_FIX: Luôn giải phóng capture bất kể isDragging
                    endMove();
                    if (dragHandle.IsMouseCaptured)
                        dragHandle.ReleaseMouseCapture();
                    e.Handled = true;
                };

                // ✅ QC_4.2: Xử lý mất mouse capture bất ngờ (Alt+Tab, OS dialog)
                dragHandle.LostMouseCapture += (s, e) =>
                {
                    endMove();
                };

                // Add Touch support for kiosk touch displays
                dragHandle.PreviewTouchDown += (s, e) =>
                {
                    startMove(e.GetTouchPoint(MainInteractiveBoard).Position);
                    dragHandle.CaptureTouch(e.TouchDevice);
                    e.Handled = true;
                };

                dragHandle.TouchMove += (s, e) =>
                {
                    if (isDragging)
                    {
                        Point currentPoint = e.GetTouchPoint(MainInteractiveBoard).Position;
                        double oldLeft = Canvas.GetLeft(container);
                        double oldTop = Canvas.GetTop(container);

                        double newLeft = oldLeft + (currentPoint.X - dragStartPoint.X);
                        double newTop = oldTop + (currentPoint.Y - dragStartPoint.Y);

                        newLeft = Math.Max(0, Math.Min(newLeft, MainInteractiveBoard.ActualWidth - container.Width));
                        newTop = Math.Max(0, Math.Min(newTop, MainInteractiveBoard.ActualHeight - container.Height));

                        double actualDeltaX = newLeft - oldLeft;
                        double actualDeltaY = newTop - oldTop;

                        Canvas.SetLeft(container, newLeft);
                        Canvas.SetTop(container, newTop);

                        MoveAttachedElements(attachedElements, actualDeltaX, actualDeltaY);

                        dragStartPoint = currentPoint;
                        e.Handled = true;
                    }
                };

                dragHandle.TouchUp += (s, e) =>
                {
                    // ✅ QC_4.2_CAPTURE_FIX: Luôn giải phóng touch capture bất kể isDragging
                    endMove();
                    if (e.TouchDevice.Captured == dragHandle)
                        dragHandle.ReleaseTouchCapture(e.TouchDevice);
                    e.Handled = true;
                };

                // ✅ QC_4.2: Xử lý mất touch capture bất ngờ
                dragHandle.LostTouchCapture += (s, e) =>
                {
                    endMove();
                };

                // Position at center of canvas
                double left = (MainInteractiveBoard.ActualWidth - container.Width) / 2;
                double top = (MainInteractiveBoard.ActualHeight - container.Height) / 2;

                Canvas.SetLeft(container, left);
                Canvas.SetTop(container, top);

                // Add to canvas
                MainInteractiveBoard.Children.Add(container);
                // ✅ QC_4.2_TEXTBOX_ZINDEX (TB-3): Đặt Z-Index TRÊN nét vẽ, DƯỚI Widget
                Panel.SetZIndex(container, QASmartTouch.Helpers.ZIndexConstants.TableContainer);

                // Add to undo stack
                RecordAddAction(container, "Text Box");

                // ✅ N20 FIX: Register container with SelectionManager so clicks do not hit-test null and deselect/remove
                RefreshSelectableObjects();

                // ✅ QC_4.2_SMART_TOUCH_TEXTBOX_UNLOCK: Dọn dẹp trạng thái modal lock & gỡ bỏ capture dư thừa
                _selectedTool = null;
                CloseAllSubmenus();
                MainInteractiveBoard.ReleaseAllTouchCaptures();
                MainScrollViewer.ReleaseAllTouchCaptures();

                // Gán focus cho Hộp văn bản và bật bàn phím ảo
                newTextBox.Focus();
                ShowTouchKeyboard();

                System.Diagnostics.Debug.WriteLine($"✅ Text box inserted at ({left:F0}, {top:F0}), size: {container.Width:F0}x{container.Height:F0}");
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Lỗi chèn hộp văn bản: {ex.Message}", "Lỗi",
                              MessageBoxButton.OK, MessageBoxImage.Error);
                System.Diagnostics.Debug.WriteLine($"❌ InsertTextBoxToCanvas error: {ex.Message}");
            }
        }

        private void DeleteTextBox(Grid textBoxContainer)
        {
            var result = MessageBox.Show("Bạn có chắc muốn xóa hộp văn bản này?", "Xác nhận",
                                        MessageBoxButton.YesNo, MessageBoxImage.Question);
            if (result == MessageBoxResult.Yes)
            {
                // ✅ QC_4.2_TEXTBOX_UNDO_FIX (TB-4): Ghi attached strokes vào Undo stack
                // TRƯỚC khi xóa, để Ctrl+Z khôi phục cả nét vẽ đính kèm
                var attached = GetElementsInsideContainer(textBoxContainer);
                foreach (var elem in attached)
                    RecordRemoveAction(elem, "TextBoxAttachedStroke");
                foreach (var elem in attached)
                    MainInteractiveBoard.Children.Remove(elem);

                MainInteractiveBoard.Children.Remove(textBoxContainer);
                RecordRemoveAction(textBoxContainer, "Text Box");
                RefreshSelectableObjects();
                // ✅ QC_4.2_SMART_TOUCH_TEXTBOX_DELETE_FIX: Giải phóng toàn bộ Touch Capture sau khi xóa
                MainInteractiveBoard.ReleaseAllTouchCaptures();
                MainScrollViewer.ReleaseAllTouchCaptures();
                System.Diagnostics.Debug.WriteLine("✅ Text box deleted with attached strokes");
            }
        }

        private Shape? CreateShapePreview(string shapeName)
        {
            Shape? shape = null;
            
            switch (shapeName)
            {
                // PHASE 1: Lines (5) - use Line element
                case "StraightLine":
                case "Line":
                    shape = new Line
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize
                    };
                    break;

                case "DashedLine":
                    shape = new Line
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        StrokeDashArray = new DoubleCollection { 8, 4 }
                    };
                    break;
                
                case "ArrowLine":
                case "DoubleArrowLine":
                case "ElbowConnector":
                case "CurvedConnector":
                    // Use Path for complex line shapes
                    shape = new System.Windows.Shapes.Path
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = null
                    };
                    break;
                    
                // PHASE 1: Rectangles (5)
                case "Square":
                    shape = new Rectangle
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = null
                    };
                    break;

                case "Rectangle":
                    shape = new Rectangle
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = null
                    };
                    break;
                
                case "RoundedRectangle":
                    shape = new Rectangle
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = null,
                        RadiusX = 10,
                        RadiusY = 10
                    };
                    break;
                
                case "SnipSingleCornerRectangle":
                case "SnipDiagonalCornerRectangle":
                case "RoundSingleCornerRectangle":
                    // Use Path for snipped/rounded corner rectangles
                    shape = new System.Windows.Shapes.Path
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = null
                    };
                    break;
                    
                // PHASE 1: Basic Shapes (10) - Circle uses Ellipse
                case "Circle":
                    shape = new Ellipse
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = null
                    };
                    break;
                    
                // PHASE 1: Polygon-based shapes
                case "Triangle":
                case "Pentagon":
                case "Hexagon":
                case "Star":
                case "Diamond":
                case "Parallelogram":
                case "Cross":
                case "Heart":
                
                // PHASE 2A: Block Arrows (15) - All Polygon
                case "RightArrow":
                case "LeftArrow":
                case "UpArrow":
                case "DownArrow":
                case "LeftRightArrow":
                case "UpDownArrow":
                case "QuadArrow":
                case "NotchedRightArrow":
                case "PentagonArrow":
                case "ChevronArrow":
                case "StripedRightArrow":
                case "CurvedRightArrow":
                case "CurvedLeftArrow":
                case "CurvedUpArrow":
                case "CurvedDownArrow":
                
                // PHASE 2B: Stars & Banners (15) - All Polygon
                case "Star4":
                case "Star6":
                case "Star7":
                case "Star8":
                case "Star10":
                case "Star12":
                case "Star16":
                case "Star24":
                case "Star32":
                case "Explosion1":
                case "Explosion2":
                case "Wave":
                case "DoubleWave":
                case "Ribbon":
                case "Scroll":
                
                // PHASE 2C: Flowchart (20) - All Polygon
                case "FlowProcess":
                case "FlowDecision":
                case "FlowDocument":
                case "FlowData":
                case "FlowPredefinedProcess":
                case "FlowInternalStorage":
                case "FlowSequentialData":
                case "FlowDirectData":
                case "FlowManualInput":
                case "FlowManualOperation":
                case "FlowConnector":
                case "FlowOffPageConnector":
                case "FlowSummingJunction":
                case "FlowOr":
                case "FlowSort":
                case "FlowExtract":
                case "FlowMerge":
                case "FlowStoredData":
                case "FlowDelay":
                case "FlowPreparation":
                
                // PHASE 2D: Callouts (14) - All Polygon
                case "RectangularCallout":
                case "RoundedRectangularCallout":
                case "OvalCallout":
                case "LineCallout1":
                case "LineCallout2":
                case "LineCallout3":
                case "LineCallout4":
                case "BorderlessLineCallout1":
                case "BorderlessLineCallout2":
                case "BorderlessLineCallout3":
                case "BorderlessLineCallout4":
                case "AccentCallout1":
                case "AccentCallout2":
                case "AccentCallout3":
                    // Create Polygon for all Phase 1 and Phase 2A-D shapes
                    shape = new Polygon
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = null
                    };
                    break;
                
                // PHASE 2E: Equation Shapes (15) - Use Path for multi-component
                case "Plus":
                case "Multiply":
                case "NotEqual":
                    // BUGFIX: Use stroke-only rendering for white intersection gaps
                    shape = new System.Windows.Shapes.Path
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = Math.Max(_currentPenSize * 1.5, 8),  // Thicker stroke
                        Fill = null,  // No fill - stroke only
                        StrokeLineJoin = PenLineJoin.Miter,  // Sharp corners
                        StrokeStartLineCap = PenLineCap.Round,  // Rounded ends
                        StrokeEndLineCap = PenLineCap.Round
                    };
                    break;
                
                case "Minus":
                case "Divide":
                case "Equal":
                case "LessThan":
                case "GreaterThan":
                case "LessOrEqual":
                case "GreaterOrEqual":
                    // Fill-based rendering for solid shapes
                    shape = new System.Windows.Shapes.Path
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = new SolidColorBrush(_currentPenColor)  // Filled with pen color
                    };
                    break;
                
                case "Approximately":
                case "Infinity":
                case "Radical":
                case "Summation":
                case "Integral":
                    // Advanced symbols - keep outline only
                    shape = new System.Windows.Shapes.Path
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = Brushes.Transparent
                    };
                    break;
                
                // Old shapes
                case "Arrow":
                case "Polygon":
                // 3D Shapes
                case "Cube":
                case "Sphere":
                case "Pyramid":
                case "Cylinder":
                case "Cone":
                case "Prism":
                case "Torus":
                case "Tetrahedron":
                // Charts
                case "BarChart":
                case "PieChart":
                case "LineChart":
                case "AreaChart":
                case "ScatterChart":
                case "RadarChart":
                    // Use Polygon for complex shapes, 3D shapes, and charts
                    shape = new Polygon
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = Brushes.Transparent
                    };
                    break;
                    
                default:
                    // Default to rectangle for unknown shapes
                    shape = new Rectangle
                    {
                        Stroke = new SolidColorBrush(_currentPenColor),
                        StrokeThickness = _currentPenSize,
                        Fill = Brushes.Transparent
                    };
                    break;
            }
            
            return shape;
        }

        private void UpdateShapePreview(Shape shape, Point startPoint, Point currentPoint)
        {
            if (shape is Line line)
            {
                // Update line coordinates
                line.X1 = startPoint.X;
                line.Y1 = startPoint.Y;
                line.X2 = currentPoint.X;
                line.Y2 = currentPoint.Y;
            }
            else if (shape is Rectangle rect)
            {
                double left   = Math.Min(startPoint.X, currentPoint.X);
                double top    = Math.Min(startPoint.Y, currentPoint.Y);
                double width  = Math.Abs(currentPoint.X - startPoint.X);
                double height = Math.Abs(currentPoint.Y - startPoint.Y);

                // Square: constrain to equal side (use smaller dimension)
                if (_currentShape == "Square")
                {
                    double side = Math.Min(width, height);
                    // Adjust left/top so the square expands from start corner
                    if (currentPoint.X < startPoint.X) left = startPoint.X - side;
                    if (currentPoint.Y < startPoint.Y) top  = startPoint.Y - side;
                    width  = side;
                    height = side;
                }

                Canvas.SetLeft(rect, left);
                Canvas.SetTop(rect, top);
                rect.Width  = Math.Max(1, width);
                rect.Height = Math.Max(1, height);
            }
            else if (shape is System.Windows.Shapes.Path path)
            {
                // Check if it's an equation shape (use multi-component geometry)
                if (_currentShape == "Plus" || _currentShape == "Minus" || _currentShape == "Multiply" || 
                    _currentShape == "Divide" || _currentShape == "Equal" || _currentShape == "NotEqual" ||
                    _currentShape == "LessThan" || _currentShape == "GreaterThan" || 
                    _currentShape == "LessOrEqual" || _currentShape == "GreaterOrEqual" ||
                    _currentShape == "Approximately" || _currentShape == "Infinity" || 
                    _currentShape == "Radical" || _currentShape == "Summation" || _currentShape == "Integral")
                {
                    // Update equation shape with GeometryGroup
                    UpdatePathEquationShape(path, startPoint, currentPoint);
                }
                else
                {
                    // Update Path geometry for other complex shapes
                    UpdatePathGeometry(path, startPoint, currentPoint);
                }
            }
            else if (shape is Polygon polygon)
            {
                // Update polygon points based on shape type
                UpdatePolygonPoints(polygon, startPoint, currentPoint);
            }
            else if (shape is Rectangle || shape is Ellipse)
            {
                // Calculate top-left corner and dimensions
                double left   = Math.Min(startPoint.X, currentPoint.X);
                double top    = Math.Min(startPoint.Y, currentPoint.Y);
                double width  = Math.Abs(currentPoint.X - startPoint.X);
                double height = Math.Abs(currentPoint.Y - startPoint.Y);

                // Circle: constrain to perfect circle (equal width & height)
                if (_currentShape == "Circle" && shape is Ellipse)
                {
                    double side = Math.Min(width, height);
                    // Keep the start corner fixed regardless of drag direction
                    if (currentPoint.X < startPoint.X) left = startPoint.X - side;
                    if (currentPoint.Y < startPoint.Y) top  = startPoint.Y - side;
                    width  = side;
                    height = side;
                }

                // Update position and size
                Canvas.SetLeft(shape, left);
                Canvas.SetTop(shape, top);
                shape.Width  = Math.Max(1, width);
                shape.Height = Math.Max(1, height);
            }
        }

        private void UpdatePathGeometry(System.Windows.Shapes.Path path, Point startPoint, Point currentPoint)
        {
            // Calculate bounds
            double left = Math.Min(startPoint.X, currentPoint.X);
            double top = Math.Min(startPoint.Y, currentPoint.Y);
            double width = Math.Abs(currentPoint.X - startPoint.X);
            double height = Math.Abs(currentPoint.Y - startPoint.Y);
            
            string pathData = "";
            
            // Generate path data based on current shape type
            if (_currentShape == "ArrowLine")
            {
                // Line with arrow at end - improved calculation
                double lineLength = Math.Sqrt(width * width + height * height);
                double arrowSize = Math.Max(15, lineLength * 0.08); // Minimum 15px, or 8% of line length
                
                // Calculate line direction vector
                double deltaX = currentPoint.X - startPoint.X;
                double deltaY = currentPoint.Y - startPoint.Y;
                double lineLength2 = Math.Sqrt(deltaX * deltaX + deltaY * deltaY);
                
                if (lineLength2 > 0)
                {
                    // Normalize direction vector
                    double unitX = deltaX / lineLength2;
                    double unitY = deltaY / lineLength2;
                    
                    // Calculate arrowhead points perpendicular to line direction
                    double perpX = -unitY; // Perpendicular vector
                    double perpY = unitX;
                    
                    // Arrow tip points
                    double arrowTip1X = currentPoint.X - (unitX * arrowSize) + (perpX * arrowSize * 0.5);
                    double arrowTip1Y = currentPoint.Y - (unitY * arrowSize) + (perpY * arrowSize * 0.5);
                    double arrowTip2X = currentPoint.X - (unitX * arrowSize) - (perpX * arrowSize * 0.5);
                    double arrowTip2Y = currentPoint.Y - (unitY * arrowSize) - (perpY * arrowSize * 0.5);
                    
                    pathData = System.FormattableString.Invariant($"M{startPoint.X},{startPoint.Y} L{currentPoint.X},{currentPoint.Y} ") +
                              System.FormattableString.Invariant($"M{arrowTip1X},{arrowTip1Y} L{currentPoint.X},{currentPoint.Y} L{arrowTip2X},{arrowTip2Y}");
                }
                else
                {
                    // Fallback for zero-length line
                    pathData = System.FormattableString.Invariant($"M{startPoint.X},{startPoint.Y} L{currentPoint.X},{currentPoint.Y}");
                }
            }
            else if (_currentShape == "DoubleArrowLine")
            {
                // Line with arrows at both ends - improved calculation
                double lineLength = Math.Sqrt(width * width + height * height);
                double arrowSize = Math.Max(15, lineLength * 0.08); // Minimum 15px, or 8% of line length
                
                // Calculate line direction vector
                double deltaX = currentPoint.X - startPoint.X;
                double deltaY = currentPoint.Y - startPoint.Y;
                double lineLength2 = Math.Sqrt(deltaX * deltaX + deltaY * deltaY);
                
                if (lineLength2 > 0)
                {
                    // Normalize direction vector
                    double unitX = deltaX / lineLength2;
                    double unitY = deltaY / lineLength2;
                    
                    // Calculate perpendicular vector for arrowhead width
                    double perpX = -unitY;
                    double perpY = unitX;
                    
                    // Arrow at end (currentPoint)
                    double endArrowTip1X = currentPoint.X - (unitX * arrowSize) + (perpX * arrowSize * 0.5);
                    double endArrowTip1Y = currentPoint.Y - (unitY * arrowSize) + (perpY * arrowSize * 0.5);
                    double endArrowTip2X = currentPoint.X - (unitX * arrowSize) - (perpX * arrowSize * 0.5);
                    double endArrowTip2Y = currentPoint.Y - (unitY * arrowSize) - (perpY * arrowSize * 0.5);
                    
                    // Arrow at start (startPoint) - reverse direction
                    double startArrowTip1X = startPoint.X + (unitX * arrowSize) + (perpX * arrowSize * 0.5);
                    double startArrowTip1Y = startPoint.Y + (unitY * arrowSize) + (perpY * arrowSize * 0.5);
                    double startArrowTip2X = startPoint.X + (unitX * arrowSize) - (perpX * arrowSize * 0.5);
                    double startArrowTip2Y = startPoint.Y + (unitY * arrowSize) - (perpY * arrowSize * 0.5);
                    
                    pathData = System.FormattableString.Invariant($"M{startPoint.X},{startPoint.Y} L{currentPoint.X},{currentPoint.Y} ") +
                              System.FormattableString.Invariant($"M{startArrowTip1X},{startArrowTip1Y} L{startPoint.X},{startPoint.Y} L{startArrowTip2X},{startArrowTip2Y} ") +
                              System.FormattableString.Invariant($"M{endArrowTip1X},{endArrowTip1Y} L{currentPoint.X},{currentPoint.Y} L{endArrowTip2X},{endArrowTip2Y}");
                }
                else
                {
                    // Fallback for zero-length line
                    pathData = System.FormattableString.Invariant($"M{startPoint.X},{startPoint.Y} L{currentPoint.X},{currentPoint.Y}");
                }
            }
            else if (_currentShape == "ElbowConnector")
            {
                // Elbow (right-angle) connector
                double midX = (startPoint.X + currentPoint.X) / 2;
                pathData = System.FormattableString.Invariant($"M{startPoint.X},{startPoint.Y} L{midX},{startPoint.Y} L{midX},{currentPoint.Y} L{currentPoint.X},{currentPoint.Y}");
            }
            else if (_currentShape == "CurvedConnector")
            {
                // Curved connector using quadratic Bezier
                double midX = (startPoint.X + currentPoint.X) / 2;
                double midY = (startPoint.Y + currentPoint.Y) / 2;
                double ctrlX = midX;
                double ctrlY = startPoint.Y;
                pathData = System.FormattableString.Invariant($"M{startPoint.X},{startPoint.Y} Q{ctrlX},{ctrlY} {currentPoint.X},{currentPoint.Y}");
            }
            else if (_currentShape == "SnipSingleCornerRectangle")
            {
                // Rectangle with one corner snipped (top-right)
                double snipSize = Math.Min(width, height) * 0.15;
                pathData = System.FormattableString.Invariant($"M{left},{top} L{left + width - snipSize},{top} L{left + width},{top + snipSize} L{left + width},{top + height} L{left},{top + height} Z");
            }
            else if (_currentShape == "SnipDiagonalCornerRectangle")
            {
                // Rectangle with two diagonal corners snipped (top-right and bottom-left)
                double snipSize = Math.Min(width, height) * 0.15;
                pathData = System.FormattableString.Invariant($"M{left},{top} L{left + width - snipSize},{top} L{left + width},{top + snipSize} L{left + width},{top + height} ") +
                          System.FormattableString.Invariant($"L{left + snipSize},{top + height} L{left},{top + height - snipSize} Z");
            }
            else if (_currentShape == "RoundSingleCornerRectangle")
            {
                // Rectangle with one corner rounded (top-right)
                double radius = Math.Min(width, height) * 0.15;
                pathData = System.FormattableString.Invariant($"M{left},{top} L{left + width - radius},{top} Q{left + width},{top} {left + width},{top + radius} L{left + width},{top + height} L{left},{top + height} Z");
            }
            
            if (!string.IsNullOrEmpty(pathData))
            {
                path.Data = Geometry.Parse(pathData);
            }
        }

        private void UpdatePolygonPoints(Polygon polygon, Point startPoint, Point currentPoint)
        {
            // Get bounds
            double left = Math.Min(startPoint.X, currentPoint.X);
            double top = Math.Min(startPoint.Y, currentPoint.Y);
            double width = Math.Abs(currentPoint.X - startPoint.X);
            double height = Math.Abs(currentPoint.Y - startPoint.Y);
            
            // Update points based on current shape type
            if (_currentShape == "Triangle")
            {
                polygon.Points.Clear();
                // Top center
                polygon.Points.Add(new Point(left + width / 2, top));
                // Bottom left
                polygon.Points.Add(new Point(left, top + height));
                // Bottom right
                polygon.Points.Add(new Point(left + width, top + height));
            }
            else if (_currentShape == "Star")
            {
                polygon.Points.Clear();
                double centerX = left + width / 2;
                double centerY = top + height / 2;
                double outerRadius = Math.Min(width, height) / 2;
                double innerRadius = outerRadius * 0.4;
                
                // Create 5-pointed star
                for (int i = 0; i < 10; i++)
                {
                    double angle = (i * 36 - 90) * Math.PI / 180;
                    double radius = (i % 2 == 0) ? outerRadius : innerRadius;
                    polygon.Points.Add(new Point(
                        centerX + radius * Math.Cos(angle),
                        centerY + radius * Math.Sin(angle)
                    ));
                }
            }
            else if (_currentShape == "Arrow")
            {
                polygon.Points.Clear();
                // Simple right arrow
                double midY = top + height / 2;
                polygon.Points.Add(new Point(left, midY - height / 4));
                polygon.Points.Add(new Point(left + width * 0.6, midY - height / 4));
                polygon.Points.Add(new Point(left + width * 0.6, top));
                polygon.Points.Add(new Point(left + width, midY));
                polygon.Points.Add(new Point(left + width * 0.6, top + height));
                polygon.Points.Add(new Point(left + width * 0.6, midY + height / 4));
                polygon.Points.Add(new Point(left, midY + height / 4));
            }
            else if (_currentShape == "Heart")
            {
                polygon.Points.Clear();
                // Heart shape using parametric equation for smooth curves
                double midX = left + width / 2;
                double scaleX = width / 32.0;
                double scaleY = height / 30.0;
                
                // Generate heart shape points using parametric equations
                // Heart curve: x = 16*sin^3(t), y = 13*cos(t) - 5*cos(2t) - 2*cos(3t) - cos(4t)
                for (double t = 0; t <= 2 * Math.PI; t += 0.1)
                {
                    double sinT = Math.Sin(t);
                    double cosT = Math.Cos(t);
                    
                    // Parametric heart equation
                    double x = 16 * sinT * sinT * sinT;
                    double y = -(13 * cosT - 5 * Math.Cos(2 * t) - 2 * Math.Cos(3 * t) - Math.Cos(4 * t));
                    
                    // Scale and translate to fit bounding box
                    double px = midX + x * scaleX;
                    double py = top + (y + 15) * scaleY; // +15 to center vertically
                    
                    polygon.Points.Add(new Point(px, py));
                }
            }
            else if (_currentShape == "Pentagon")
            {
                polygon.Points.Clear();
                double centerX = left + width / 2;
                double centerY = top + height / 2;
                double radius = Math.Min(width, height) / 2;
                
                for (int i = 0; i < 5; i++)
                {
                    double angle = (i * 72 - 90) * Math.PI / 180;
                    polygon.Points.Add(new Point(
                        centerX + radius * Math.Cos(angle),
                        centerY + radius * Math.Sin(angle)
                    ));
                }
            }
            else if (_currentShape == "Hexagon")
            {
                polygon.Points.Clear();
                double centerX = left + width / 2;
                double centerY = top + height / 2;
                double radius = Math.Min(width, height) / 2;
                
                for (int i = 0; i < 6; i++)
                {
                    double angle = (i * 60 - 90) * Math.PI / 180;
                    polygon.Points.Add(new Point(
                        centerX + radius * Math.Cos(angle),
                        centerY + radius * Math.Sin(angle)
                    ));
                }
            }
            // PHASE 1: New shapes
            else if (_currentShape == "Diamond")
            {
                polygon.Points.Clear();
                double midX = left + width / 2;
                double midY = top + height / 2;
                // Top, Right, Bottom, Left
                polygon.Points.Add(new Point(midX, top));
                polygon.Points.Add(new Point(left + width, midY));
                polygon.Points.Add(new Point(midX, top + height));
                polygon.Points.Add(new Point(left, midY));
            }
            else if (_currentShape == "Parallelogram")
            {
                polygon.Points.Clear();
                double offset = width * 0.2; // 20% offset for slant
                // Top left, Top right, Bottom right, Bottom left
                polygon.Points.Add(new Point(left + offset, top));
                polygon.Points.Add(new Point(left + width, top));
                polygon.Points.Add(new Point(left + width - offset, top + height));
                polygon.Points.Add(new Point(left, top + height));
            }
            else if (_currentShape == "Cross")
            {
                polygon.Points.Clear();
                double armWidth = width / 3;
                double armHeight = height / 3;
                double midX = left + width / 2;
                double midY = top + height / 2;
                
                // Create cross shape (12 points)
                // Top arm
                polygon.Points.Add(new Point(midX - armWidth / 2, top));
                polygon.Points.Add(new Point(midX + armWidth / 2, top));
                // Right side of vertical arm
                polygon.Points.Add(new Point(midX + armWidth / 2, midY - armHeight / 2));
                // Right arm
                polygon.Points.Add(new Point(left + width, midY - armHeight / 2));
                polygon.Points.Add(new Point(left + width, midY + armHeight / 2));
                // Bottom of right arm
                polygon.Points.Add(new Point(midX + armWidth / 2, midY + armHeight / 2));
                // Bottom arm
                polygon.Points.Add(new Point(midX + armWidth / 2, top + height));
                polygon.Points.Add(new Point(midX - armWidth / 2, top + height));
                // Left side of vertical arm
                polygon.Points.Add(new Point(midX - armWidth / 2, midY + armHeight / 2));
                // Left arm
                polygon.Points.Add(new Point(left, midY + armHeight / 2));
                polygon.Points.Add(new Point(left, midY - armHeight / 2));
                // Top of left arm
                polygon.Points.Add(new Point(midX - armWidth / 2, midY - armHeight / 2));
            }
            
            // ====================================================================================
            // PHASE 2: EXTENDED SHAPES (79 shapes)
            // ====================================================================================
            
            // PHASE 2A: Block Arrows (15)
            else if (_currentShape == "RightArrow" || _currentShape == "LeftArrow" || 
                     _currentShape == "UpArrow" || _currentShape == "DownArrow")
            {
                // Simple directional arrows
                DrawArrow(polygon, left, top, width, height, _currentShape);
            }
            else if (_currentShape == "LeftRightArrow" || _currentShape == "UpDownArrow")
            {
                // Bi-directional arrows
                DrawDoubleArrow(polygon, left, top, width, height, _currentShape);
            }
            else if (_currentShape == "QuadArrow")
            {
                // 4-way arrow (cross arrows)
                DrawQuadArrow(polygon, left, top, width, height);
            }
            else if (_currentShape == "NotchedRightArrow")
            {
                DrawNotchedRightArrow(polygon, left, top, width, height);
            }
            else if (_currentShape == "PentagonArrow")
            {
                DrawPentagonArrow(polygon, left, top, width, height);
            }
            else if (_currentShape == "ChevronArrow")
            {
                DrawChevronArrow(polygon, left, top, width, height);
            }
            else if (_currentShape == "StripedRightArrow")
            {
                DrawStripedRightArrow(polygon, left, top, width, height);
            }
            else if (_currentShape == "CurvedRightArrow" || _currentShape == "CurvedLeftArrow" ||
                     _currentShape == "CurvedUpArrow" || _currentShape == "CurvedDownArrow")
            {
                DrawCurvedArrow(polygon, left, top, width, height, _currentShape);
            }
            
            // PHASE 2B: Stars & Banners (15)
            else if (_currentShape.StartsWith("Star"))
            {
                // Extract number of points from shape name (e.g., "Star6" → 6)
                int points = _currentShape switch
                {
                    "Star4" => 4,
                    "Star6" => 6,
                    "Star7" => 7,
                    "Star8" => 8,
                    "Star10" => 10,
                    "Star12" => 12,
                    "Star16" => 16,
                    "Star24" => 24,
                    "Star32" => 32,
                    _ => 5 // Default
                };
                DrawStar(polygon, left, top, width, height, points);
            }
            else if (_currentShape == "Explosion1" || _currentShape == "Explosion2")
            {
                // Explosion effect (irregular star with 16 points)
                DrawStar(polygon, left, top, width, height, 16);
            }
            else if (_currentShape == "Wave" || _currentShape == "DoubleWave")
            {
                // Wave shape using sine curve
                DrawWave(polygon, left, top, width, height, _currentShape == "DoubleWave" ? 2 : 1);
            }
            else if (_currentShape == "Ribbon" || _currentShape == "Scroll")
            {
                // Ribbon/Scroll shape (rectangle with curved ends)
                DrawRibbon(polygon, left, top, width, height);
            }
            
            // PHASE 2C: Flowchart (20)
            else if (_currentShape.StartsWith("Flow"))
            {
                DrawFlowchartShape(polygon, left, top, width, height, _currentShape);
            }
            
            // PHASE 2D: Callouts (14)
            else if (_currentShape.Contains("Callout"))
            {
                DrawCallout(polygon, left, top, width, height, _currentShape);
            }
            
            // NOTE: PHASE 2E Equation Shapes (15) now use Path with GeometryGroup
            // They are handled in UpdatePathEquationShape() method, not here!
            
            // 3D Shapes (simplified 2D representations)
            else if (_currentShape == "Cube")
            {
                polygon.Points.Clear();
                
                // THUáº¬T TOÃN Váº¼ KHá»I Láº¬P PHÆ¯Æ NG 3D Vá»šI PHÃ‰P CHIáº¾U ISOMETRIC
                // Tham khảo: Hình học không gian - Phép chiếu Isometric
                
                // Bước 1: Xác định kích thước khối lập phương
                double cubeSize = Math.Min(width, height) * 0.7; // Kích thước cạnh a
                double halfSize = cubeSize / 2;
                double centerX = left + width / 2;
                double centerY = top + height / 2;
                
                // Bước 2: Định nghĩa 8 đỉnh trong không gian 3D (x, y, z)
                // Tâm khối lập phương tại gốc tọa độ
                double[,] vertices3D = new double[8, 3]
                {
                    { -halfSize, -halfSize, -halfSize }, // V0: Front-Bottom-Left
                    { +halfSize, -halfSize, -halfSize }, // V1: Front-Bottom-Right
                    { +halfSize, +halfSize, -halfSize }, // V2: Front-Top-Right
                    { -halfSize, +halfSize, -halfSize }, // V3: Front-Top-Left
                    { -halfSize, -halfSize, +halfSize }, // V4: Back-Bottom-Left
                    { +halfSize, -halfSize, +halfSize }, // V5: Back-Bottom-Right
                    { +halfSize, +halfSize, +halfSize }, // V6: Back-Top-Right
                    { -halfSize, +halfSize, +halfSize }  // V7: Back-Top-Left
                };
                
                // Bước 3: Áp dụng phép chiếu Isometric (3D → 2D)
                // Công thức: x_2d = x * cos(30°) - z * cos(30°)
                //            y_2d = y + x * sin(30Â°) + z * sin(30Â°)
                double cos30 = Math.Sqrt(3) / 2; // â‰ˆ 0.866
                double sin30 = 0.5;
                
                Point[] vertices2D = new Point[8];
                for (int i = 0; i < 8; i++)
                {
                    double x = vertices3D[i, 0];
                    double y = vertices3D[i, 1];
                    double z = vertices3D[i, 2];
                    
                    // Phép chiếu Isometric
                    double x_2d = x * cos30 - z * cos30;
                    double y_2d = y + x * sin30 + z * sin30;
                    
                    // Chuyển sang tọa độ màn hình (đảo trục Y vì màn hình Y tăng xuống dưới)
                    vertices2D[i] = new Point(centerX + x_2d, centerY - y_2d);
                }
                
                // Bước 4: Vẽ 12 cạnh của khối lập phương
                // Theo thứ tự: Mặt trước → Mặt sau → Các cạnh nối
                
                // Máº·t TRÆ¯á»šC (Front face): V0-V1-V2-V3-V0
                polygon.Points.Add(vertices2D[0]); // V0
                polygon.Points.Add(vertices2D[1]); // V1
                polygon.Points.Add(vertices2D[2]); // V2
                polygon.Points.Add(vertices2D[3]); // V3
                polygon.Points.Add(vertices2D[0]); // V0 (đóng mặt trước)
                
                // Cạnh nối: V0 → V4 (Front-Bottom-Left to Back-Bottom-Left)
                polygon.Points.Add(vertices2D[4]); // V4
                
                // Mặt SAU - Cạnh dưới: V4 → V5
                polygon.Points.Add(vertices2D[5]); // V5
                
                // Cạnh nối: V5 → V1 (quay về mặt trước)
                polygon.Points.Add(vertices2D[1]); // V1
                
                // Cạnh nối: V1 → V2 (đã có)
                polygon.Points.Add(vertices2D[2]); // V2
                
                // Cạnh nối: V2 → V6 (Front-Top-Right to Back-Top-Right)
                polygon.Points.Add(vertices2D[6]); // V6
                
                // Mặt SAU - Cạnh trên: V6 → V7
                polygon.Points.Add(vertices2D[7]); // V7
                
                // Cạnh nối: V7 → V3 (quay về mặt trước)
                polygon.Points.Add(vertices2D[3]); // V3
                
                // Hoàn thiện mặt sau: V3 → V7 → V4
                polygon.Points.Add(vertices2D[7]); // V7
                polygon.Points.Add(vertices2D[4]); // V4
                
                // Mặt SAU - Các cạnh còn lại: V4 → V5 → V6 → V7
                polygon.Points.Add(vertices2D[5]); // V5
                polygon.Points.Add(vertices2D[6]); // V6
            }
            else if (_currentShape == "Pyramid")
            {
                polygon.Points.Clear();
                // 3D pyramid with square base - isometric view
                double d = Math.Min(width, height) * 0.3;
                double midX = left + width / 2;
                
                // Apex point at top center
                Point apex = new Point(midX, top);
                
                // Square base at bottom (isometric perspective)
                Point baseFrontLeft = new Point(left + d, top + height);
                Point baseFrontRight = new Point(left + width, top + height);
                Point baseBackRight = new Point(left + width - d, top + height - d);
                Point baseBackLeft = new Point(left, top + height - d);
                
                // Draw pyramid wireframe
                // Front left edge
                polygon.Points.Add(apex);
                polygon.Points.Add(baseFrontLeft);
                
                // Base front edge
                polygon.Points.Add(baseFrontRight);
                
                // Front right edge back to apex
                polygon.Points.Add(apex);
                
                // Back right edge
                polygon.Points.Add(baseBackRight);
                
                // Base back edge
                polygon.Points.Add(baseBackLeft);
                
                // Back left edge to apex
                polygon.Points.Add(apex);
                
                // Complete base square
                polygon.Points.Add(baseBackLeft);
                polygon.Points.Add(baseFrontLeft);
                polygon.Points.Add(baseFrontRight);
                polygon.Points.Add(baseBackRight);
            }
            else if (_currentShape == "Cylinder")
            {
                polygon.Points.Clear();
                // Cylinder with ellipse top and bottom
                double ovalHeight = height * 0.15;
                int steps = 20;
                
                // Top ellipse (half visible - front)
                for (int i = 0; i <= steps / 2; i++)
                {
                    double angle = Math.PI + (i * Math.PI / (steps / 2));
                    double x = left + width / 2 + (width / 2) * Math.Cos(angle);
                    double y = top + ovalHeight / 2 + (ovalHeight / 2) * Math.Sin(angle);
                    polygon.Points.Add(new Point(x, y));
                }
                
                // Right side line down
                polygon.Points.Add(new Point(left + width, top + height - ovalHeight));
                
                // Bottom ellipse (full)
                for (int i = 0; i <= steps; i++)
                {
                    double angle = Math.PI + (i * 2 * Math.PI / steps);
                    double x = left + width / 2 + (width / 2) * Math.Cos(angle);
                    double y = top + height - ovalHeight / 2 + (ovalHeight / 2) * Math.Sin(angle);
                    polygon.Points.Add(new Point(x, y));
                }
                
                // Left side line up
                polygon.Points.Add(new Point(left, top + ovalHeight));
            }
            else if (_currentShape == "Cone")
            {
                polygon.Points.Clear();
                // Cone with circular base
                double midX = left + width / 2;
                double baseY = top + height;
                double baseRadiusX = width / 2;
                double baseRadiusY = height * 0.15;
                int steps = 20;
                
                // Apex point
                polygon.Points.Add(new Point(midX, top));
                
                // Right edge to base
                polygon.Points.Add(new Point(left + width, baseY - baseRadiusY));
                
                // Base ellipse (visible half)
                for (int i = 0; i <= steps; i++)
                {
                    double angle = (i * Math.PI / steps);
                    double x = midX + baseRadiusX * Math.Cos(angle);
                    double y = baseY - baseRadiusY / 2 + (baseRadiusY / 2) * Math.Sin(angle);
                    polygon.Points.Add(new Point(x, y));
                }
                
                // Left edge back to apex
                polygon.Points.Add(new Point(left, baseY - baseRadiusY));
            }
            else if (_currentShape == "Sphere" || _currentShape == "Torus")
            {
                polygon.Points.Clear();
                // Circle approximation for sphere/torus
                double centerX = left + width / 2;
                double centerY = top + height / 2;
                double radiusX = width / 2;
                double radiusY = height / 2;
                
                for (int i = 0; i <= 30; i++)
                {
                    double angle = (i * 2 * Math.PI / 30);
                    polygon.Points.Add(new Point(
                        centerX + radiusX * Math.Cos(angle),
                        centerY + radiusY * Math.Sin(angle)
                    ));
                }
            }
            else if (_currentShape == "Prism")
            {
                polygon.Points.Clear();
                // Triangular prism - isometric view with clear front and back triangles
                double d = width * 0.3; // depth offset
                double midX = left + width / 2;
                
                // Front triangle vertices
                Point frontTop = new Point(left + (width - d) / 2, top);
                Point frontBL = new Point(left, top + height);
                Point frontBR = new Point(left + width - d, top + height);
                
                // Back triangle vertices (offset by depth d)
                Point backTop = new Point(left + (width - d) / 2 + d, top);
                Point backBL = new Point(left + d, top + height);
                Point backBR = new Point(left + width, top + height);
                
                // Draw prism wireframe
                // Front triangle
                polygon.Points.Add(frontTop);
                polygon.Points.Add(frontBL);
                polygon.Points.Add(frontBR);
                polygon.Points.Add(frontTop);
                
                // Connect to back triangle
                polygon.Points.Add(backTop);
                polygon.Points.Add(backBL);
                polygon.Points.Add(frontBL);
                
                // Bottom edge
                polygon.Points.Add(frontBR);
                polygon.Points.Add(backBR);
                polygon.Points.Add(backBL);
                
                // Complete back triangle
                polygon.Points.Add(backBR);
                polygon.Points.Add(backTop);
            }
            else if (_currentShape == "Tetrahedron")
            {
                polygon.Points.Clear();
                // Tetrahedron (triangular pyramid) - 4 faces, 6 edges
                double midX = left + width / 2;
                double d = width * 0.25; // offset for 3D effect
                
                // 4 vertices
                Point apex = new Point(midX + d, top); // top point (offset for perspective)
                Point baseFront = new Point(midX, top + height); // front base vertex
                Point baseLeft = new Point(left, top + height * 0.7); // left base vertex  
                Point baseRight = new Point(left + width, top + height * 0.7); // right base vertex
                
                // Draw tetrahedron edges
                // Front face (apex to front base)
                polygon.Points.Add(apex);
                polygon.Points.Add(baseFront);
                
                // Front to left
                polygon.Points.Add(baseLeft);
                
                // Left to apex
                polygon.Points.Add(apex);
                
                // Apex to right
                polygon.Points.Add(baseRight);
                
                // Right to front
                polygon.Points.Add(baseFront);
                
                // Complete base triangle
                polygon.Points.Add(baseLeft);
                polygon.Points.Add(baseRight);
            }
            // Charts
            else if (_currentShape == "BarChart")
            {
                polygon.Points.Clear();
                // Simple bar chart outline (3 bars)
                double barWidth = width / 4;
                double gap = width / 12;
                // Bar 1 (60% height)
                polygon.Points.Add(new Point(left + gap, top + height * 0.4));
                polygon.Points.Add(new Point(left + gap, top + height));
                polygon.Points.Add(new Point(left + gap + barWidth, top + height));
                polygon.Points.Add(new Point(left + gap + barWidth, top + height * 0.4));
                // Gap - move to next bar
                polygon.Points.Add(new Point(left + gap + barWidth + gap, top + height * 0.4));
                // Bar 2 (80% height)
                polygon.Points.Add(new Point(left + gap + barWidth + gap, top + height * 0.2));
                polygon.Points.Add(new Point(left + gap + barWidth + gap, top + height));
                polygon.Points.Add(new Point(left + gap + barWidth * 2 + gap, top + height));
                polygon.Points.Add(new Point(left + gap + barWidth * 2 + gap, top + height * 0.2));
                // Gap - move to next bar
                polygon.Points.Add(new Point(left + gap + barWidth * 2 + gap * 2, top + height * 0.2));
                // Bar 3 (50% height)
                polygon.Points.Add(new Point(left + gap + barWidth * 2 + gap * 2, top + height * 0.5));
                polygon.Points.Add(new Point(left + gap + barWidth * 2 + gap * 2, top + height));
                polygon.Points.Add(new Point(left + gap + barWidth * 3 + gap * 2, top + height));
                polygon.Points.Add(new Point(left + gap + barWidth * 3 + gap * 2, top + height * 0.5));
            }
            else if (_currentShape == "PieChart")
            {
                polygon.Points.Clear();
                // Pie chart (circle with slice)
                double centerX = left + width / 2;
                double centerY = top + height / 2;
                double radius = Math.Min(width, height) / 2;
                
                // Draw 3/4 circle (270 degrees)
                for (int i = 0; i <= 15; i++)
                {
                    double angle = (i * 18 - 90) * Math.PI / 180;
                    polygon.Points.Add(new Point(
                        centerX + radius * Math.Cos(angle),
                        centerY + radius * Math.Sin(angle)
                    ));
                }
                // Close to center for slice effect
                polygon.Points.Add(new Point(centerX, centerY));
            }
            else if (_currentShape == "LineChart")
            {
                polygon.Points.Clear();
                // Line chart (zigzag line)
                double step = width / 4;
                polygon.Points.Add(new Point(left, top + height * 0.7));
                polygon.Points.Add(new Point(left + step, top + height * 0.4));
                polygon.Points.Add(new Point(left + step * 2, top + height * 0.6));
                polygon.Points.Add(new Point(left + step * 3, top + height * 0.2));
                polygon.Points.Add(new Point(left + width, top + height * 0.3));
            }
            else if (_currentShape == "AreaChart")
            {
                polygon.Points.Clear();
                // Area chart (filled line chart)
                double step = width / 4;
                polygon.Points.Add(new Point(left, top + height));
                polygon.Points.Add(new Point(left, top + height * 0.7));
                polygon.Points.Add(new Point(left + step, top + height * 0.4));
                polygon.Points.Add(new Point(left + step * 2, top + height * 0.6));
                polygon.Points.Add(new Point(left + step * 3, top + height * 0.2));
                polygon.Points.Add(new Point(left + width, top + height * 0.3));
                polygon.Points.Add(new Point(left + width, top + height));
            }
            else if (_currentShape == "ScatterChart")
            {
                polygon.Points.Clear();
                // Scatter chart (small squares representing points)
                double[][] points = new double[][]
                {
                    new double[] { 0.2, 0.7 }, new double[] { 0.3, 0.5 }, new double[] { 0.4, 0.6 },
                    new double[] { 0.5, 0.3 }, new double[] { 0.6, 0.4 }, new double[] { 0.7, 0.5 },
                    new double[] { 0.8, 0.2 }
                };
                
                double dotSize = Math.Min(width, height) * 0.05;
                foreach (var pt in points)
                {
                    double px = left + width * pt[0];
                    double py = top + height * pt[1];
                    // Add small square for each point
                    polygon.Points.Add(new Point(px - dotSize, py - dotSize));
                    polygon.Points.Add(new Point(px + dotSize, py - dotSize));
                    polygon.Points.Add(new Point(px + dotSize, py + dotSize));
                    polygon.Points.Add(new Point(px - dotSize, py + dotSize));
                    polygon.Points.Add(new Point(px - dotSize, py - dotSize)); // Close square
                }
            }
            else if (_currentShape == "RadarChart")
            {
                polygon.Points.Clear();
                // Radar/Spider chart (pentagon with inner data)
                double centerX = left + width / 2;
                double centerY = top + height / 2;
                double radius = Math.Min(width, height) / 2;
                
                // Outer pentagon
                for (int i = 0; i < 5; i++)
                {
                    double angle = (i * 72 - 90) * Math.PI / 180;
                    polygon.Points.Add(new Point(
                        centerX + radius * Math.Cos(angle),
                        centerY + radius * Math.Sin(angle)
                    ));
                }
            }
            else
            {
                // Default: Rectangle-like polygon
                polygon.Points.Clear();
                polygon.Points.Add(new Point(left, top));
                polygon.Points.Add(new Point(left + width, top));
                polygon.Points.Add(new Point(left + width, top + height));
                polygon.Points.Add(new Point(left, top + height));
            }
        }

        private Polyline CreateStrokeByBrushType()
        {
            var stroke = new Polyline
            {
                Stroke = new SolidColorBrush(_currentPenColor),
                StrokeThickness = _currentPenSize
            };

            // ✅ QC_4.2_STROKE_ABOVE_TABLE (NV-3): Mọi nét vẽ mặc định TRÊN Table/TextBox (500)
            Panel.SetZIndex(stroke, ZIndexConstants.UserContentMax);

            // =====================================================
            // 🚀 HARDWARE ACCELERATION FOR STROKES (Anti-Jitter)
            // Enable GPU rendering and optimize for large displays
            // =====================================================
            // EdgeMode.Unspecified: Sử dụng anti-aliasing mặc định (mượt mà, không có viền trắng)
            // CachingHint.Cache: Cache rendering để tăng hiệu suất
            RenderOptions.SetCachingHint(stroke, CachingHint.Cache);
            stroke.SnapsToDevicePixels = false;  // Tắt để tránh viền trắng
            stroke.UseLayoutRounding = false;    // Tắt để tránh shift background

            // Apply different styles based on brush type
            switch (_currentBrushType)
            {
                case "Normal":
                    // Standard smooth pen
                    stroke.StrokeLineJoin = PenLineJoin.Round;
                    stroke.StrokeStartLineCap = PenLineCap.Round;
                    stroke.StrokeEndLineCap = PenLineCap.Round;
                    break;

                case "Hoc":
                    // Educational pen - thicker, more visible
                    stroke.StrokeLineJoin = PenLineJoin.Round;
                    stroke.StrokeStartLineCap = PenLineCap.Round;
                    stroke.StrokeEndLineCap = PenLineCap.Round;
                    stroke.StrokeThickness = _currentPenSize * 1.2; // 20% thicker
                    break;

                case "Transparent":
                    // Transparent pen - smooth with slight transparency (Bút mờ)
                    stroke.StrokeLineJoin = PenLineJoin.Round;
                    stroke.StrokeStartLineCap = PenLineCap.Round;
                    stroke.StrokeEndLineCap = PenLineCap.Round;
                    stroke.Opacity = 0.85;
                    break;

                case "Simple":
                    // Simple pen - basic sharp edges
                    stroke.StrokeLineJoin = PenLineJoin.Miter;
                    stroke.StrokeStartLineCap = PenLineCap.Flat;
                    stroke.StrokeEndLineCap = PenLineCap.Flat;
                    break;

                case "Marker":
                    // Marker - semi-transparent, wider
                    stroke.StrokeLineJoin = PenLineJoin.Round;
                    stroke.StrokeStartLineCap = PenLineCap.Round;
                    stroke.StrokeEndLineCap = PenLineCap.Round;
                    stroke.Opacity = 0.6; // Semi-transparent like real marker
                    stroke.StrokeThickness = _currentPenSize * 1.5; // Wider
                    break;

                case "Mask":
                    // Mask Pen - for highlighting/masking areas
                    stroke.StrokeLineJoin = PenLineJoin.Round;
                    stroke.StrokeStartLineCap = PenLineCap.Round;
                    stroke.StrokeEndLineCap = PenLineCap.Round;
                    stroke.Opacity = 0.3; // Very transparent
                    stroke.StrokeThickness = _currentPenSize * 2; // Very wide
                    break;

                default:
                    // Fallback to normal
                    stroke.StrokeLineJoin = PenLineJoin.Round;
                    stroke.StrokeStartLineCap = PenLineCap.Round;
                    stroke.StrokeEndLineCap = PenLineCap.Round;
                    break;
            }

            return stroke;
        }

        private void EraseStrokeAt(Point point)
        {
            // Find elements to remove (within eraser radius)
            var elementsToRemove = new System.Collections.Generic.List<UIElement>();
            
            foreach (UIElement element in MainInteractiveBoard.Children)
            {
                // Skip eraser preview cursor
                if (element == _eraserPreview)
                    continue;
                
                // Skip background layer elements (grid, dots, lines, background canvas)
                if (SelectionManager.IsBackgroundElement(element, Rect.Empty, MainInteractiveBoard.ActualWidth, MainInteractiveBoard.ActualHeight))
                    continue;
                
                bool shouldRemove = false;
                
                // Check Polyline (pen strokes)
                if (element is Polyline polyline)
                {
                    // Check if any point in the polyline is within eraser radius
                    foreach (Point p in polyline.Points)
                    {
                        double distance = Math.Sqrt(Math.Pow(p.X - point.X, 2) + Math.Pow(p.Y - point.Y, 2));
                        if (distance <= _eraserSize)
                        {
                            shouldRemove = true;
                            break;
                        }
                    }
                }
                // Check Line (2D shape)
                else if (element is Line line)
                {
                    // Check distance from point to line segment
                    Point lineStart = new Point(line.X1, line.Y1);
                    Point lineEnd = new Point(line.X2, line.Y2);
                    double distance = DistanceFromPointToLineSegment(point, lineStart, lineEnd);
                    if (distance <= _eraserSize)
                    {
                        shouldRemove = true;
                    }
                }
                // Check Rectangle (2D shape)
                else if (element is Rectangle rectangle)
                {
                    double left = Canvas.GetLeft(rectangle);
                    double top = Canvas.GetTop(rectangle);
                    if (double.IsNaN(left)) left = 0;
                    if (double.IsNaN(top)) top = 0;
                    
                    double right = left + rectangle.Width;
                    double bottom = top + rectangle.Height;
                    
                    // Check if eraser point hits the rectangle edges or inside
                    bool hitTopEdge = Math.Abs(point.Y - top) <= _eraserSize && point.X >= left - _eraserSize && point.X <= right + _eraserSize;
                    bool hitBottomEdge = Math.Abs(point.Y - bottom) <= _eraserSize && point.X >= left - _eraserSize && point.X <= right + _eraserSize;
                    bool hitLeftEdge = Math.Abs(point.X - left) <= _eraserSize && point.Y >= top - _eraserSize && point.Y <= bottom + _eraserSize;
                    bool hitRightEdge = Math.Abs(point.X - right) <= _eraserSize && point.Y >= top - _eraserSize && point.Y <= bottom + _eraserSize;
                    bool hitInside = point.X >= left && point.X <= right && point.Y >= top && point.Y <= bottom;
                    
                    if (hitTopEdge || hitBottomEdge || hitLeftEdge || hitRightEdge || hitInside)
                    {
                        shouldRemove = true;
                    }
                }
                // Check Ellipse/Circle (2D shape)
                else if (element is Ellipse ellipse)
                {
                    double left = Canvas.GetLeft(ellipse);
                    double top = Canvas.GetTop(ellipse);
                    if (double.IsNaN(left)) left = 0;
                    if (double.IsNaN(top)) top = 0;
                    
                    double centerX = left + ellipse.Width / 2;
                    double centerY = top + ellipse.Height / 2;
                    
                    // For filled shapes, check if point is inside
                    bool isFilled = ellipse.Fill != null && ellipse.Fill != Brushes.Transparent;
                    
                    if (isFilled)
                    {
                        // Check if point is inside or near the ellipse
                        double dx = (point.X - centerX) / (ellipse.Width / 2);
                        double dy = (point.Y - centerY) / (ellipse.Height / 2);
                        double distance = Math.Sqrt(dx * dx + dy * dy);
                        
                        if (distance <= 1.0 + (_eraserSize / Math.Min(ellipse.Width, ellipse.Height)))
                        {
                            shouldRemove = true;
                        }
                    }
                    else
                    {
                        // For outline only, check distance to edge
                        double dx = (point.X - centerX) / (ellipse.Width / 2);
                        double dy = (point.Y - centerY) / (ellipse.Height / 2);
                        double distance = Math.Sqrt(dx * dx + dy * dy);
                        
                        // Hit if near the edge (within eraser size)
                        if (Math.Abs(distance - 1.0) * Math.Min(ellipse.Width, ellipse.Height) / 2 <= _eraserSize)
                        {
                            shouldRemove = true;
                        }
                    }
                }
                // Check Polygon (complex 2D shapes, 3D shapes, charts)
                else if (element is Polygon polygon)
                {
                    // Check if any point in the polygon is within eraser radius
                    foreach (Point p in polygon.Points)
                    {
                        // Get polygon position offset
                        double offsetX = Canvas.GetLeft(polygon);
                        double offsetY = Canvas.GetTop(polygon);
                        if (double.IsNaN(offsetX)) offsetX = 0;
                        if (double.IsNaN(offsetY)) offsetY = 0;
                        
                        Point actualPoint = new Point(p.X + offsetX, p.Y + offsetY);
                        double distance = Math.Sqrt(Math.Pow(actualPoint.X - point.X, 2) + Math.Pow(actualPoint.Y - point.Y, 2));
                        if (distance <= _eraserSize)
                        {
                            shouldRemove = true;
                            break;
                        }
                    }
                }
                // Check Path (arrows, complex shapes from gallery)
                else if (element is System.Windows.Shapes.Path path)
                {
                    // Get path bounds
                    double left = Canvas.GetLeft(path);
                    double top = Canvas.GetTop(path);
                    if (double.IsNaN(left)) left = 0;
                    if (double.IsNaN(top)) top = 0;
                    
                    // Check if eraser point is within path bounds (expanded by eraser size)
                    Rect bounds = new Rect(left, top, path.ActualWidth, path.ActualHeight);
                    bounds.Inflate(_eraserSize, _eraserSize);
                    
                    if (bounds.Contains(point))
                    {
                        shouldRemove = true;
                    }
                }
                
                if (shouldRemove)
                {
                    elementsToRemove.Add(element);
                }
            }
            
            // Remove marked elements and record to undo stack
            foreach (var element in elementsToRemove)
            {
                MainInteractiveBoard.Children.Remove(element);
                RecordRemoveAction(element, $"Erase {element.GetType().Name}");
            }
        }

        /// <summary>
        /// Erase all canvas elements that intersect with the given rectangle.
        /// Used by Drag-erase (marquee) mode.
        /// </summary>
        private void EraseElementsInRect(Rect eraseRect)
        {
            var elementsToRemove = new System.Collections.Generic.List<UIElement>();

            foreach (UIElement element in MainInteractiveBoard.Children)
            {
                // Skip system elements
                if (element == _eraserPreview) continue;
                if (element == _dragErasePreview) continue;
                if (SelectionManager.IsBackgroundElement(element, Rect.Empty, MainInteractiveBoard.ActualWidth, MainInteractiveBoard.ActualHeight)) continue;

                bool intersects = false;

                if (element is Polyline polyline && polyline.Points.Count > 0)
                {
                    // Check if any polyline point falls inside the erase rect
                    foreach (Point p in polyline.Points)
                    {
                        if (eraseRect.Contains(p)) { intersects = true; break; }
                    }
                }
                else if (element is System.Windows.Shapes.Path path)
                {
                    // Use rendered geometry bounds for Path (covers smooth-path strokes)
                    try
                    {
                        var geo = path.RenderedGeometry;
                        if (geo != null)
                        {
                            var geoBounds = geo.Bounds;
                            // Transform bounds to canvas coordinates
                            var transform = path.TransformToVisual(MainInteractiveBoard);
                            var topLeft  = transform.Transform(new Point(geoBounds.X, geoBounds.Y));
                            var bottomRight = transform.Transform(new Point(geoBounds.Right, geoBounds.Bottom));
                            var pathRect = new Rect(topLeft, bottomRight);
                            intersects = eraseRect.IntersectsWith(pathRect);
                        }
                    }
                    catch
                    {
                        // Fallback: use Canvas position
                        double l = Canvas.GetLeft(path); if (double.IsNaN(l)) l = 0;
                        double t = Canvas.GetTop(path);  if (double.IsNaN(t)) t = 0;
                        intersects = eraseRect.IntersectsWith(new Rect(l, t, path.ActualWidth, path.ActualHeight));
                    }
                }
                else if (element is Line line)
                {
                    // Check both endpoints and midpoint
                    var p1 = new Point(line.X1, line.Y1);
                    var p2 = new Point(line.X2, line.Y2);
                    var mid = new Point((line.X1 + line.X2) / 2, (line.Y1 + line.Y2) / 2);
                    intersects = eraseRect.Contains(p1) || eraseRect.Contains(p2) || eraseRect.Contains(mid)
                                 || eraseRect.IntersectsWith(new Rect(p1, p2));
                }
                else if (element is FrameworkElement fe)
                {
                    double l = Canvas.GetLeft(fe); if (double.IsNaN(l)) l = 0;
                    double t = Canvas.GetTop(fe);  if (double.IsNaN(t)) t = 0;
                    intersects = eraseRect.IntersectsWith(new Rect(l, t, fe.ActualWidth, fe.ActualHeight));
                }

                if (intersects)
                    elementsToRemove.Add(element);
            }

            if (elementsToRemove.Count > 0)
            {
                var batchAction = new UndoRedoAction
                {
                    Type = ActionType.Batch,
                    Description = $"Drag erase {elementsToRemove.Count} elements"
                };

                foreach (var element in elementsToRemove)
                {
                    MainInteractiveBoard.Children.Remove(element);
                    batchAction.BatchActions.Add(new UndoRedoAction
                    {
                        Type = ActionType.Remove,
                        Element = element,
                        Parent = MainInteractiveBoard,
                        Description = $"Drag erase sub-item {element.GetType().Name}"
                    });
                }
                RecordAction(batchAction);
            }

            System.Diagnostics.Debug.WriteLine($"🧹 EraseElementsInRect: removed {elementsToRemove.Count} elements");
        }

        // Helper method to calculate distance from point to line segment
        private double DistanceFromPointToLineSegment(Point point, Point lineStart, Point lineEnd)
        {
            double lineLength = Math.Sqrt(Math.Pow(lineEnd.X - lineStart.X, 2) + Math.Pow(lineEnd.Y - lineStart.Y, 2));
            if (lineLength == 0) return Math.Sqrt(Math.Pow(point.X - lineStart.X, 2) + Math.Pow(point.Y - lineStart.Y, 2));
            
            // Calculate projection of point onto line
            double t = Math.Max(0, Math.Min(1, 
                ((point.X - lineStart.X) * (lineEnd.X - lineStart.X) + (point.Y - lineStart.Y) * (lineEnd.Y - lineStart.Y)) / (lineLength * lineLength)));
            
            // Calculate closest point on line segment
            Point projection = new Point(
                lineStart.X + t * (lineEnd.X - lineStart.X),
                lineStart.Y + t * (lineEnd.Y - lineStart.Y)
            );
            
            // Return distance from point to projection
            return Math.Sqrt(Math.Pow(point.X - projection.X, 2) + Math.Pow(point.Y - projection.Y, 2));
        }

