            RecordAddAction(chartContainer, "Draw");
        }

        /// <summary>
        /// Apply Line Chart with Stats to canvas (DisplayStats mode)
        /// Creates 2 independent objects: Chart + Stats Panel
        /// </summary>
        private void ApplyLineChartWithStatsToCanvas(Form2_9_LineChartEditor editor)
        {
            const double pixelsToMm = 25.4 / 96.0; // 0.264583 mm per pixel

            // ========== PART 1: CREATE LINE CHART ==========
            Canvas chartContainer = new Canvas
            {
                Width = 800,
                Height = 600,
                Background = Brushes.White
            };

            // Add border
            var chartBorder = new Border
            {
                Width = 800,
                Height = 600,
                BorderBrush = new SolidColorBrush(Color.FromRgb(200, 200, 200)),
                BorderThickness = new Thickness(2),
                CornerRadius = new CornerRadius(5)
            };
            chartContainer.Children.Add(chartBorder);

            // Draw the chart
            DrawLineChartOnCanvas(chartContainer, editor);

            // Position chart
            Canvas.SetLeft(chartContainer, 50);
            Canvas.SetTop(chartContainer, 50);

            // Enable dragging for chart
            Enable3DShapeDragging(chartContainer);

            // Add to main canvas
            MainInteractiveBoard.Children.Add(chartContainer);
            RecordAddAction(chartContainer, "Create 3D object");

            // ========== PART 2: CREATE STATS PANEL ==========

            // Calculate chart dimensions in mm
            double chartWidthMm = 800 * pixelsToMm;
            double chartHeightMm = 600 * pixelsToMm;

            // Get chart data statistics
            var allDataPoints = new List<double>();
            int totalSeries = 0;
            int totalDataPoints = 0;

            if (editor != null)
            {
                // Access chart data through reflection or properties
                var seriesField = editor.GetType().GetField("lineSeries", 
                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                
                if (seriesField != null)
                {
                    var series = seriesField.GetValue(editor) as System.Collections.IList;
                    if (series != null)
                    {
                        totalSeries = series.Count;
                        foreach (var s in series)
                        {
                            var dataProperty = s.GetType().GetProperty("Data");
                            if (dataProperty != null)
                            {
                                var data = dataProperty.GetValue(s) as List<double>;
                                if (data != null)
                                {
                                    allDataPoints.AddRange(data);
                                    totalDataPoints += data.Count;
                                }
                            }
                        }
                    }
                }
            }

            double minValue = allDataPoints.Any() ? allDataPoints.Min() : 0;
            double maxValue = allDataPoints.Any() ? allDataPoints.Max() : 0;
            double avgValue = allDataPoints.Any() ? allDataPoints.Average() : 0;
            double totalValue = allDataPoints.Sum();
            double rangeValue = maxValue - minValue;

            // Create stats panel
            var statsPanel = new StackPanel
            {
                Background = new SolidColorBrush(Color.FromRgb(255, 255, 255))
            };

            // Title
            AddStatsTextBlock(statsPanel, "📈 THÔNG SỐ BIỂU ĐỒ ĐƯỜNG", 18, true, "#2C3E50");
            AddStatsSeparator(statsPanel);

            // Chart dimensions
            AddStatsTextBlock(statsPanel, "📐 KÍCH THƯỚC BIỂU ĐỒ", 14, true, "#34495E");
            AddStatsTextBlock(statsPanel, $"Chiều rộng: {chartWidthMm:N1} mm ({800} px)", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Chiều cao: {chartHeightMm:N1} mm ({600} px)", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Diện tích: {(chartWidthMm * chartHeightMm):N2} mm²", 12, false, "#555555");
            AddStatsSeparator(statsPanel);

            // Data statistics
            AddStatsTextBlock(statsPanel, "📊 THỐNG KÊ DỮ LIỆU", 14, true, "#34495E");
            AddStatsTextBlock(statsPanel, $"Số đường dữ liệu: {totalSeries:N0}", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Tổng số điểm: {totalDataPoints:N0}", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Giá trị nhỏ nhất: {minValue:N2}", 12, false, "#E74C3C");
            AddStatsTextBlock(statsPanel, $"Giá trị lớn nhất: {maxValue:N2}", 12, false, "#27AE60");
            AddStatsTextBlock(statsPanel, $"Giá trị trung bình: {avgValue:N2}", 12, false, "#3498DB");
            AddStatsTextBlock(statsPanel, $"Khoảng biến thiên: {rangeValue:N2}", 12, false, "#F39C12");
            AddStatsTextBlock(statsPanel, $"Tổng giá trị: {totalValue:N2}", 12, false, "#9B59B6");
            AddStatsSeparator(statsPanel);

            // Chart information
            AddStatsTextBlock(statsPanel, "📋 THÔNG TIN BIỂU ĐỒ", 14, true, "#34495E");
            AddStatsTextBlock(statsPanel, "Loại biểu đồ: Line Chart (Biểu đồ đường)", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, "Công dụng: Hiển thị xu hướng dữ liệu theo thời gian", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, "Ứng dụng: Phân tích chuỗi thời gian, so sánh xu hướng", 12, false, "#555555");
            AddStatsSeparator(statsPanel);

            // Mathematical formulas
            AddStatsTextBlock(statsPanel, "🧮 CÔNG THỨC THỐNG KÊ", 14, true, "#34495E");
            AddStatsTextBlock(statsPanel, "Trung bình: μ = (Σx) / n", 11, false, "#16A085");
            AddStatsTextBlock(statsPanel, $"Tính toán: ({totalValue:N2}) / {totalDataPoints} = {avgValue:N2}", 11, false, "#7F8C8D");
            AddStatsTextBlock(statsPanel, "Khoảng biến thiên: R = Max - Min", 11, false, "#16A085");
            AddStatsTextBlock(statsPanel, $"Tính toán: {maxValue:N2} - {minValue:N2} = {rangeValue:N2}", 11, false, "#7F8C8D");
            AddStatsSeparator(statsPanel);

            // Educational content
            AddStatsTextBlock(statsPanel, "📚 KIẾN THỨC MỞ RỘNG", 14, true, "#34495E");
            AddStatsTextBlock(statsPanel, "• Line Chart thể hiện sự thay đổi liên tục", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "• Đường thẳng nối các điểm dữ liệu", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "• Phù hợp cho dữ liệu chuỗi thời gian", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "• Dễ nhận diện xu hướng tăng/giảm", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "• So sánh nhiều chuỗi dữ liệu cùng lúc", 11, false, "#555555");
            AddStatsSeparator(statsPanel);

            // Advantages
            AddStatsTextBlock(statsPanel, "✅ ƯU ĐIỂM", 14, true, "#27AE60");
            AddStatsTextBlock(statsPanel, "✓ Hiển thị xu hướng rõ ràng", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "✓ So sánh nhiều dataset dễ dàng", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "✓ Dự đoán giá trị tương lai", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "✓ Nhận diện pattern và chu kỳ", 11, false, "#555555");
            AddStatsSeparator(statsPanel);

            // Usage tips
            AddStatsTextBlock(statsPanel, "💡 HƯỚNG DẪN SỬ DỤNG", 14, true, "#F39C12");
            AddStatsTextBlock(statsPanel, "• Kéo thả cả 2 đối tượng độc lập", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "• Click chọn để xóa từng đối tượng", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "• Ctrl+Z để hoàn tác", 11, false, "#555555");
            AddStatsTextBlock(statsPanel, "• Biểu đồ và bảng thống kê độc lập", 11, false, "#555555");

            // Wrap in border with styling
            var statsPanelBorder = new Border
            {
                Background = new SolidColorBrush(Color.FromRgb(255, 255, 255)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(52, 152, 219)),
                BorderThickness = new Thickness(3),
                CornerRadius = new CornerRadius(8),
                Padding = new Thickness(20),
                Child = statsPanel,
                Effect = new System.Windows.Media.Effects.DropShadowEffect
                {
                    Color = Colors.Black,
                    Direction = 315,
                    ShadowDepth = 5,
                    BlurRadius = 15,
