        public void ApplyPieChartWithStatsToCanvas(Form2_10_PieChartEditor editor)
        {
            // Create main container
            Canvas mainContainer = new Canvas
            {
                Width = 1000,
                Height = 700,
                Background = Brushes.White
            };

            // Create pie chart canvas
            Canvas pieContainer = new Canvas
            {
                Width = 600,
                Height = 600,
                Background = Brushes.Transparent
            };

            // Draw pie chart
            DrawPieChartOnCanvas(pieContainer, editor);

            // Position pie chart on left side
            Canvas.SetLeft(pieContainer, 20);
            Canvas.SetTop(pieContainer, 50);
            mainContainer.Children.Add(pieContainer);

            // Create stats panel on right
            StackPanel statsPanel = new StackPanel
            {
                Width = 350,
                Background = new SolidColorBrush(Color.FromRgb(248, 249, 250))
            };
            Canvas.SetLeft(statsPanel, 630);
            Canvas.SetTop(statsPanel, 20);

            // Title
            AddStatsTextBlock(statsPanel, "🥧 THÔNG SỐ BIỂU ĐỒ TRÒN", 18, true, "#2C3E50");
            AddStatsSeparator(statsPanel);

            // Chart info
            AddStatsTextBlock(statsPanel, "📊 THÔNG TIN CHUNG", 14, true, "#667eea");
            AddStatsTextBlock(statsPanel, $"Tiêu đề: {editor.ChartTitle}", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Loại biểu đồ: {editor.ChartType} Chart", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Kiểu hiển thị: {editor.DisplayStyle}", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Số phần: {editor.Values.Count}", 12, false, "#555555");

            double total = editor.Values.Sum();
            AddStatsTextBlock(statsPanel, $"Tổng giá trị: {total:N0}", 12, false, "#555555");
            AddStatsSeparator(statsPanel);

            // Data breakdown
            AddStatsTextBlock(statsPanel, "📈 CHI TIẾT DỮ LIỆU", 14, true, "#667eea");
            for (int i = 0; i < editor.Labels.Count; i++)
            {
                double percent = (editor.Values[i] / total) * 100;
                
                var dataPanel = new StackPanel { Margin = new Thickness(10, 5, 10, 5) };
                
                var labelText = new TextBlock
                {
                    Text = editor.Labels[i],
                    FontSize = 12,
                    FontWeight = FontWeights.Bold,
                    Foreground = new SolidColorBrush(Color.FromRgb(44, 62, 80))
                };
                dataPanel.Children.Add(labelText);

                var colorBar = new Border
                {
                    Width = 300,
                    Height = 20,
                    Background = new SolidColorBrush(editor.Colors[i]),
                    Margin = new Thickness(0, 2, 0, 2),
                    CornerRadius = new CornerRadius(3)
                };
                dataPanel.Children.Add(colorBar);

                var valueText = new TextBlock
                {
                    Text = $"Giá trị: {editor.Values[i]:N0} ({percent:F1}%)",
                    FontSize = 11,
                    Foreground = new SolidColorBrush(Color.FromRgb(85, 85, 85))
                };
                dataPanel.Children.Add(valueText);

                statsPanel.Children.Add(dataPanel);
            }

            AddStatsSeparator(statsPanel);

            // Display settings
            AddStatsTextBlock(statsPanel, "⚙️ CÀI ĐẶT HIỂN THỊ", 14, true, "#667eea");
            AddStatsTextBlock(statsPanel, $"Kích thước: {editor.ChartSize:F0}%", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Góc bắt đầu: {editor.StartAngle:F0}°", 12, false, "#555555");
            
            if (editor.ChartType == "Donut")
                AddStatsTextBlock(statsPanel, $"Độ rộng lỗ: {editor.DonutHoleSize:F0}%", 12, false, "#555555");
            
            if (editor.DisplayStyle == "Exploded")
                AddStatsTextBlock(statsPanel, $"Khoảng cách tách: {editor.ExplodeDistance:F0}px", 12, false, "#555555");

            AddStatsTextBlock(statsPanel, $"Hiển thị nhãn: {(editor.ShowLabels ? "Có" : "Không")}", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Hiển thị %: {(editor.ShowPercentages ? "Có" : "Không")}", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Hiển thị giá trị: {(editor.ShowValues ? "Có" : "Không")}", 12, false, "#555555");
            AddStatsTextBlock(statsPanel, $"Hiển thị chú thích: {(editor.ShowLegend ? "Có" : "Không")}", 12, false, "#555555");

            mainContainer.Children.Add(statsPanel);

            // Position main container
            Canvas.SetLeft(mainContainer, (MainInteractiveBoard.ActualWidth - mainContainer.Width) / 2);
            Canvas.SetTop(mainContainer, (MainInteractiveBoard.ActualHeight - mainContainer.Height) / 2);

            // Enable drag & drop
            Enable3DShapeDragging(mainContainer);

            // Add to main canvas
            MainInteractiveBoard.Children.Add(mainContainer);
        }

        private void DrawPieChartOnCanvas(Canvas canvas, Form2_10_PieChartEditor editor)
        {
            try
            {
                if (editor.Values.Count == 0 || editor.Values.Sum() == 0)
                    return;

                double canvasWidth = canvas.Width;
                double canvasHeight = canvas.Height;
                double centerX = canvasWidth / 2;
                double centerY = canvasHeight / 2;
                double radius = Math.Min(canvasWidth, canvasHeight) * (editor.ChartSize / 100.0) * 0.35;

                double total = editor.Values.Sum();
                double startAngleRad = editor.StartAngle * Math.PI / 180;

                // Draw title
                if (!string.IsNullOrWhiteSpace(editor.ChartTitle))
                {
                    var title = new TextBlock
                    {
                        Text = editor.ChartTitle,
                        FontSize = 20,
                        FontWeight = FontWeights.Bold,
                        Foreground = new SolidColorBrush(Color.FromRgb(44, 62, 80))
                    };
                    Canvas.SetLeft(title, centerX - 150);
                    Canvas.SetTop(title, 20);
                    canvas.Children.Add(title);
                }

                // Adjust center for semi-circle
                if (editor.ChartType == "Semi")
                {
                    centerY = canvasHeight * 0.65;
                    startAngleRad = Math.PI;
                }

                // Draw slices
                double currentAngle = startAngleRad;

                for (int i = 0; i < editor.Values.Count; i++)
                {
                    double sweepAngle = editor.ChartType == "Semi"
                        ? (editor.Values[i] / total) * Math.PI
                        : (editor.Values[i] / total) * 2 * Math.PI;

                    // Calculate explode offset
                    double explodeX = 0, explodeY = 0;
                    if (editor.DisplayStyle == "Exploded")
                    {
                        double midAngle = currentAngle + sweepAngle / 2;
                        explodeX = Math.Cos(midAngle) * editor.ExplodeDistance;
                        explodeY = Math.Sin(midAngle) * editor.ExplodeDistance;
                    }

                    // Draw shadow for 3D effect
                    if (editor.DisplayStyle == "3D" || editor.ShowShadow)
                    {
                        DrawPieSlice(canvas, centerX + explodeX + 5, centerY + explodeY + 5, radius,
                                    currentAngle, sweepAngle,
                                    Color.FromArgb(50, 0, 0, 0),
                                    editor.ChartType == "Donut" ? radius * (editor.DonutHoleSize / 100.0) : 0);
                    }

                    // Draw main slice
                    DrawPieSlice(canvas, centerX + explodeX, centerY + explodeY, radius,
                                currentAngle, sweepAngle,
                                editor.Colors[i],
                                editor.ChartType == "Donut" ? radius * (editor.DonutHoleSize / 100.0) : 0);

                    // Draw labels
                    if (editor.ShowLabels || editor.ShowPercentages || editor.ShowValues)
                    {
                        double midAngle = currentAngle + sweepAngle / 2;
                        double labelRadius = editor.ChartType == "Donut"
                            ? radius * (1 - editor.DonutHoleSize / 200.0)
                            : radius * 0.7;

                        double labelX = centerX + explodeX + Math.Cos(midAngle) * labelRadius;
                        double labelY = centerY + explodeY + Math.Sin(midAngle) * labelRadius;

                        string labelText = "";
                        if (editor.ShowLabels) labelText += editor.Labels[i];
                        if (editor.ShowPercentages)
                        {
                            double percent = (editor.Values[i] / total) * 100;
                            labelText += (labelText.Length > 0 ? "\n" : "") + percent.ToString("F1") + "%";
                        }
                        if (editor.ShowValues)
                        {
                            labelText += (labelText.Length > 0 ? "\n" : "") + editor.Values[i].ToString("N0");
                        }

                        if (!string.IsNullOrWhiteSpace(labelText))
                        {
                            var label = new TextBlock
                            {
                                Text = labelText,
                                FontSize = 11,
                                FontWeight = FontWeights.Bold,
                                Foreground = Brushes.White,
                                TextAlignment = TextAlignment.Center,
                                Background = new SolidColorBrush(Color.FromArgb(180, 0, 0, 0)),
                                Padding = new Thickness(6, 3, 6, 3)
                            };

                            Canvas.SetLeft(label, labelX - 40);
                            Canvas.SetTop(label, labelY - 20);
                            canvas.Children.Add(label);
                        }
                    }

                    currentAngle += sweepAngle;
                }

                // Draw legend
                if (editor.ShowLegend)
                {
                    DrawPieChartLegend(canvas, editor, canvasWidth, canvasHeight);
                }
            }
            catch (Exception ex)
            {
                var errorText = new TextBlock
                {
                    Text = $"Lỗi vẽ biểu đồ: {ex.Message}",
                    FontSize = 14,
                    Foreground = Brushes.Red
                };
                Canvas.SetLeft(errorText, 20);
                Canvas.SetTop(errorText, 20);
                canvas.Children.Add(errorText);
            }
        }

        private void DrawPieSlice(Canvas canvas, double centerX, double centerY, double radius,
                                  double startAngle, double sweepAngle,
                                  Color color, double innerRadius = 0)
        {
            if (sweepAngle <= 0) return;

            // Limit sweep angle to avoid full circle rendering issues
            if (sweepAngle >= 2 * Math.PI - 0.001)
            {
                if (innerRadius > 0)
                {
                    // Draw donut with ellipse geometry
                    var outerEllipse = new EllipseGeometry(new Point(centerX, centerY), radius, radius);
                    var innerEllipse = new EllipseGeometry(new Point(centerX, centerY), innerRadius, innerRadius);
                    var combinedGeo = new CombinedGeometry(GeometryCombineMode.Exclude, outerEllipse, innerEllipse);

                    var donutPath = new Path
                    {
                        Fill = new SolidColorBrush(color),
                        Stroke = Brushes.White,
                        StrokeThickness = 2,
                        Data = combinedGeo
                    };
                    canvas.Children.Add(donutPath);
                }
                else
                {
                    // Draw full circle
                    var ellipse = new Ellipse
                    {
                        Width = radius * 2,
                        Height = radius * 2,
                        Fill = new SolidColorBrush(color),
                        Stroke = Brushes.White,
                        StrokeThickness = 2
                    };
                    Canvas.SetLeft(ellipse, centerX - radius);
                    Canvas.SetTop(ellipse, centerY - radius);
                    canvas.Children.Add(ellipse);
                }
                return;
            }

            double endAngle = startAngle + sweepAngle;

            // Outer arc points
            Point startPointOuter = new Point(
                centerX + radius * Math.Cos(startAngle),
                centerY + radius * Math.Sin(startAngle)
            );

            Point endPointOuter = new Point(
                centerX + radius * Math.Cos(endAngle),
                centerY + radius * Math.Sin(endAngle)
            );

            PathFigure figure = new PathFigure { StartPoint = startPointOuter };

            // Outer arc
            figure.Segments.Add(new ArcSegment
            {
                Point = endPointOuter,
                Size = new Size(radius, radius),
                SweepDirection = SweepDirection.Clockwise,
                IsLargeArc = sweepAngle > Math.PI
            });

            if (innerRadius > 0)
            {
                // Inner arc points for donut
                Point endPointInner = new Point(
                    centerX + innerRadius * Math.Cos(endAngle),
                    centerY + innerRadius * Math.Sin(endAngle)
                );

                Point startPointInner = new Point(
                    centerX + innerRadius * Math.Cos(startAngle),
                    centerY + innerRadius * Math.Sin(startAngle)
                );

                figure.Segments.Add(new LineSegment { Point = endPointInner });
                figure.Segments.Add(new ArcSegment
                {
                    Point = startPointInner,
                    Size = new Size(innerRadius, innerRadius),
                    SweepDirection = SweepDirection.Counterclockwise,
                    IsLargeArc = sweepAngle > Math.PI
                });
                figure.Segments.Add(new LineSegment { Point = startPointOuter });
            }
            else
            {
                // Line to center for pie
                figure.Segments.Add(new LineSegment { Point = new Point(centerX, centerY) });
                figure.Segments.Add(new LineSegment { Point = startPointOuter });
            }

            PathGeometry geometry = new PathGeometry();
            geometry.Figures.Add(figure);

            Path path = new Path
            {
                Fill = new SolidColorBrush(color),
                Stroke = Brushes.White,
                StrokeThickness = 2,
                Data = geometry
            };

            canvas.Children.Add(path);
        }

        private void DrawPieChartLegend(Canvas canvas, Form2_10_PieChartEditor editor, double canvasWidth, double canvasHeight)
        {
            double legendX = 20;
            double legendY = canvasHeight - editor.Labels.Count * 30 - 20;

            for (int i = 0; i < editor.Labels.Count; i++)
            {
                var rect = new Rectangle
                {
                    Width = 20,
                    Height = 20,
                    Fill = new SolidColorBrush(editor.Colors[i]),
                    Stroke = new SolidColorBrush(Color.FromRgb(221, 221, 221)),
                    StrokeThickness = 1
                };
                Canvas.SetLeft(rect, legendX);
                Canvas.SetTop(rect, legendY + i * 30);
                canvas.Children.Add(rect);

                var text = new TextBlock
                {
                    Text = editor.Labels[i],
                    FontSize = 12,
                    Foreground = new SolidColorBrush(Color.FromRgb(44, 62, 80))
                };
                Canvas.SetLeft(text, legendX + 30);
                Canvas.SetTop(text, legendY + i * 30 + 2);
                canvas.Children.Add(text);
            }
        }

        #endregion

        #region Area Chart Methods

        public void ApplyAreaChartToCanvas(Form2_12_AreaChartEditor editor)
        {
            // Create container for area chart
            var chartContainer = new Canvas
            {
                Width = 900,
                Height = 550,
                Background = Brushes.White
            };

            // Render area chart from editor
            DrawAreaChartOnCanvas(chartContainer, editor);

            // Add to main canvas centered
            Canvas.SetLeft(chartContainer, (MainInteractiveBoard.ActualWidth - chartContainer.Width) / 2);
            Canvas.SetTop(chartContainer, (MainInteractiveBoard.ActualHeight - chartContainer.Height) / 2);

            MainInteractiveBoard.Children.Add(chartContainer);
        }

        private void DrawAreaChartOnCanvas(Canvas canvas, Form2_12_AreaChartEditor editor)
        {
            double canvasWidth = canvas.Width;
            double canvasHeight = canvas.Height;

            double margin = 60;
            double chartWidth = canvasWidth - 2 * margin;
            double chartHeight = canvasHeight - 2 * margin - (editor.ShowLegend ? 40 : 0);

            // Draw background
            var bgRect = new Rectangle
            {
                Width = canvasWidth,
                Height = canvasHeight,
                Fill = Brushes.White
            };
            canvas.Children.Add(bgRect);

            // Draw title
            var title = new TextBlock
            {
                Text = editor.ChartTitle,
                FontSize = 20,
                FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush(Color.FromRgb(44, 62, 80))
            };
            Canvas.SetLeft(title, (canvasWidth - title.Text.Length * 10) / 2);
            Canvas.SetTop(title, 15);
            canvas.Children.Add(title);

            // Calculate max value
            double maxValue = 0;
            if (editor.AreaType == "normal")
            {
                maxValue = editor.Series.SelectMany(s => s.Data).DefaultIfEmpty(0).Max();
            }
            else if (editor.AreaType == "stacked")
            {
                for (int i = 0; i < editor.Labels.Count; i++)
                {
                    double sum = editor.Series.Sum(s => i < s.Data.Count ? s.Data[i] : 0);
                    maxValue = Math.Max(maxValue, sum);
                }
            }
            else // percentage
            {
                maxValue = 100;
            }

            maxValue = Math.Ceiling(maxValue / 10) * 10;
            if (maxValue == 0) maxValue = 100;

            // Draw grid
            if (editor.ShowGrid)
            {
                for (int i = 0; i <= 5; i++)
                {
                    double y = margin + (chartHeight / 5) * i;
                    var line = new Line
                    {
                        X1 = margin,
                        Y1 = y,
                        X2 = margin + chartWidth,
                        Y2 = y,
                        Stroke = new SolidColorBrush(Color.FromRgb(230, 230, 230)),
                        StrokeThickness = 1
                    };
                    canvas.Children.Add(line);

                    var valueLabel = new TextBlock
                    {
                        Text = ((maxValue / 5) * (5 - i)).ToString("F0"),
                        FontSize = 11,
                        Foreground = new SolidColorBrush(Color.FromRgb(120, 120, 120))
                    };
                    Canvas.SetLeft(valueLabel, margin - 35);
                    Canvas.SetTop(valueLabel, y - 7);
                    canvas.Children.Add(valueLabel);
                }
            }

            // Draw axes
            if (editor.ShowAxes)
            {
                var xAxis = new Line
                {
                    X1 = margin,
                    Y1 = margin + chartHeight,
                    X2 = margin + chartWidth,
                    Y2 = margin + chartHeight,
                    Stroke = new SolidColorBrush(Color.FromRgb(100, 100, 100)),
                    StrokeThickness = 2
                };
                canvas.Children.Add(xAxis);

                var yAxis = new Line
                {
                    X1 = margin,
                    Y1 = margin,
                    X2 = margin,
                    Y2 = margin + chartHeight,
                    Stroke = new SolidColorBrush(Color.FromRgb(100, 100, 100)),
                    StrokeThickness = 2
                };
                canvas.Children.Add(yAxis);
            }

            // Draw labels
            for (int i = 0; i < editor.Labels.Count; i++)
            {
                double x = margin + (chartWidth / (editor.Labels.Count - 1)) * i;
                var label = new TextBlock
                {
                    Text = editor.Labels[i],
                    FontSize = 12,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(Color.FromRgb(80, 80, 80))
                };
                Canvas.SetLeft(label, x - 15);
                Canvas.SetTop(label, margin + chartHeight + 10);
                canvas.Children.Add(label);
            }

            // Draw area charts
            double[] stackedValues = new double[editor.Labels.Count];

            for (int seriesIndex = editor.Series.Count - 1; seriesIndex >= 0; seriesIndex--)
            {
                var series = editor.Series[seriesIndex];
                if (series.Data.Count == 0) continue;

                var points = new PointCollection();
                var linePoints = new PointCollection();

                for (int i = 0; i < editor.Labels.Count && i < series.Data.Count; i++)
                {
                    double x = margin + (chartWidth / (editor.Labels.Count - 1)) * i;
                    double value = series.Data[i];

                    if (editor.AreaType == "percentage")
                    {
                        double total = editor.Series.Sum(s => i < s.Data.Count ? s.Data[i] : 0);
                        value = total > 0 ? (value / total) * 100 : 0;
                    }

                    double y;
                    if (editor.AreaType == "stacked")
                    {
                        y = margin + chartHeight - ((stackedValues[i] + value) / maxValue * chartHeight);
                        stackedValues[i] += value;
                    }
                    else
                    {
                        y = margin + chartHeight - (value / maxValue * chartHeight);
                    }

                    points.Add(new Point(x, y));
                    linePoints.Add(new Point(x, y));
                }

                // Close the area polygon
                if (editor.AreaType == "stacked" && seriesIndex < editor.Series.Count - 1)
                {
                    for (int i = editor.Labels.Count - 1; i >= 0; i--)
                    {
                        double x = margin + (chartWidth / (editor.Labels.Count - 1)) * i;
                        double value = series.Data[i < series.Data.Count ? i : series.Data.Count - 1];
                        if (editor.AreaType == "percentage")
                        {
                            double total = editor.Series.Sum(s => i < s.Data.Count ? s.Data[i] : 0);
                            value = total > 0 ? (value / total) * 100 : 0;
                        }
                        double y = margin + chartHeight - ((stackedValues[i] - value) / maxValue * chartHeight);
                        points.Add(new Point(x, y));
                    }
                }
                else
                {
                    points.Add(new Point(margin + chartWidth, margin + chartHeight));
                    points.Add(new Point(margin, margin + chartHeight));
                }

                // Draw area
                Brush areaBrush;
                if (editor.UseGradient)
                {
                    var gradient = new LinearGradientBrush();
                    gradient.StartPoint = new Point(0, 0);
                    gradient.EndPoint = new Point(0, 1);
                    gradient.GradientStops.Add(new GradientStop(Color.FromArgb((byte)(series.Opacity * 255), series.Color.R, series.Color.G, series.Color.B), 0));
                    gradient.GradientStops.Add(new GradientStop(Color.FromArgb((byte)(series.Opacity * 128), series.Color.R, series.Color.G, series.Color.B), 0.5));
                    gradient.GradientStops.Add(new GradientStop(Color.FromArgb(20, series.Color.R, series.Color.G, series.Color.B), 1));
                    areaBrush = gradient;
                }
                else
                {
                    areaBrush = new SolidColorBrush(Color.FromArgb((byte)(series.Opacity * 255), series.Color.R, series.Color.G, series.Color.B));
                }

                var polygon = new Polygon
                {
                    Points = points,
                    Fill = areaBrush,
                    Stroke = new SolidColorBrush(series.Color),
                    StrokeThickness = editor.LineWidth
                };
                canvas.Children.Add(polygon);

                // Draw points
                if (editor.ShowPoints && editor.PointSize > 0)
                {
                    foreach (var point in linePoints)
                    {
                        var ellipse = new Ellipse
                        {
                            Width = editor.PointSize * 2,
                            Height = editor.PointSize * 2,
                            Fill = new SolidColorBrush(series.Color),
                            Stroke = Brushes.White,
                            StrokeThickness = 2
                        };
                        Canvas.SetLeft(ellipse, point.X - editor.PointSize);
                        Canvas.SetTop(ellipse, point.Y - editor.PointSize);
                        canvas.Children.Add(ellipse);
                    }
                }

                // Draw values
                if (editor.ShowValues)
                {
                    for (int i = 0; i < linePoints.Count && i < series.Data.Count; i++)
                    {
                        var value = series.Data[i];
                        var valueLabel = new TextBlock
                        {
                            Text = value.ToString("F0"),
                            FontSize = 10,
                            FontWeight = FontWeights.Bold,
                            Foreground = new SolidColorBrush(series.Color)
                        };
                        Canvas.SetLeft(valueLabel, linePoints[i].X - 12);
                        Canvas.SetTop(valueLabel, linePoints[i].Y - 20);
                        canvas.Children.Add(valueLabel);
                    }
                }
            }

            // Draw legend
            if (editor.ShowLegend)
            {
                double legendY = margin + chartHeight + 50;
                double legendX = margin;

                for (int i = 0; i < editor.Series.Count; i++)
                {
                    var series = editor.Series[i];

                    var legendRect = new Rectangle
                    {
                        Width = 20,
                        Height = 15,
                        Fill = new SolidColorBrush(series.Color)
                    };
                    Canvas.SetLeft(legendRect, legendX);
                    Canvas.SetTop(legendRect, legendY);
                    canvas.Children.Add(legendRect);

                    var legendText = new TextBlock
                    {
                        Text = series.Name,
                        FontSize = 11,
                        Foreground = new SolidColorBrush(Color.FromRgb(80, 80, 80))
                    };
                    Canvas.SetLeft(legendText, legendX + 25);
                    Canvas.SetTop(legendText, legendY);
                    canvas.Children.Add(legendText);

                    legendX += 25 + series.Name.Length * 7 + 20;
                }
            }
        }

        #endregion

        #region Scatter Chart Methods

        public void ApplyScatterChartToCanvas(Form2_13_ScatterChartEditor editor)
        {
            // Create container for scatter chart
            var chartContainer = new Canvas
            {
                Width = 900,
                Height = 600,
                Background = Brushes.White
            };

            // Render scatter chart from editor
            DrawScatterChartOnCanvas(chartContainer, editor);

            // Add to main canvas centered
            Canvas.SetLeft(chartContainer, (MainInteractiveBoard.ActualWidth - chartContainer.Width) / 2);
            Canvas.SetTop(chartContainer, (MainInteractiveBoard.ActualHeight - chartContainer.Height) / 2);

            MainInteractiveBoard.Children.Add(chartContainer);
        }

        private void DrawScatterChartOnCanvas(Canvas canvas, Form2_13_ScatterChartEditor editor)
        {
            double canvasWidth = canvas.Width;
            double canvasHeight = canvas.Height;
            double padding = 80;
            double chartWidth = canvasWidth - 2 * padding;
            double chartHeight = canvasHeight - 2 * padding;

            // Background
            var bgRect = new Rectangle
            {
                Width = canvasWidth,
                Height = canvasHeight,
                Fill = Brushes.White
            };
            Canvas.SetLeft(bgRect, 0);
            Canvas.SetTop(bgRect, 0);
            canvas.Children.Add(bgRect);

            // Title
            var titleText = new TextBlock
            {
                Text = editor.ChartTitle,
                FontSize = 18,
                FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush(Color.FromRgb(44, 62, 80))
            };
            Canvas.SetLeft(titleText, (canvasWidth - titleText.Text.Length * 9) / 2);
            Canvas.SetTop(titleText, 20);
            canvas.Children.Add(titleText);

            if (editor.DataPoints.Count == 0)
                return;

            // Find min/max for scaling
            double minX = editor.DataPoints.Min(p => p.X);
            double maxX = editor.DataPoints.Max(p => p.X);
            double minY = editor.DataPoints.Min(p => p.Y);
            double maxY = editor.DataPoints.Max(p => p.Y);

            double rangeX = maxX - minX;
            double rangeY = maxY - minY;

            // Add 10% padding
            minX -= rangeX * 0.1;
            maxX += rangeX * 0.1;
            minY -= rangeY * 0.1;
            maxY += rangeY * 0.1;
            rangeX = maxX - minX;
            rangeY = maxY - minY;

            // Draw grid
            if (editor.ShowGrid)
            {
                for (int i = 0; i <= 5; i++)
                {
                    double y = padding + (chartHeight / 5) * i;
                    var gridLine = new Line
                    {
                        X1 = padding,
                        Y1 = y,
                        X2 = padding + chartWidth,
                        Y2 = y,
                        Stroke = new SolidColorBrush(Color.FromRgb(230, 230, 230)),
                        StrokeThickness = 1
                    };
                    canvas.Children.Add(gridLine);

                    double value = maxY - (rangeY / 5) * i;
                    var valueText = new TextBlock
                    {
                        Text = value.ToString("F1"),
                        FontSize = 10,
                        Foreground = new SolidColorBrush(Color.FromRgb(100, 100, 100))
                    };
                    Canvas.SetLeft(valueText, padding - 40);
                    Canvas.SetTop(valueText, y - 8);
                    canvas.Children.Add(valueText);
                }

                for (int i = 0; i <= 5; i++)
                {
                    double x = padding + (chartWidth / 5) * i;
                    var gridLine = new Line
                    {
                        X1 = x,
                        Y1 = padding,
                        X2 = x,
                        Y2 = padding + chartHeight,
                        Stroke = new SolidColorBrush(Color.FromRgb(230, 230, 230)),
                        StrokeThickness = 1
                    };
                    canvas.Children.Add(gridLine);

                    double value = minX + (rangeX / 5) * i;
                    var valueText = new TextBlock
                    {
                        Text = value.ToString("F1"),
                        FontSize = 10,
                        Foreground = new SolidColorBrush(Color.FromRgb(100, 100, 100))
                    };
                    Canvas.SetLeft(valueText, x - 15);
                    Canvas.SetTop(valueText, padding + chartHeight + 10);
                    canvas.Children.Add(valueText);
                }
            }

            // Draw axes
            if (editor.ShowAxes)
            {
                var xAxis = new Line
                {
                    X1 = padding,
                    Y1 = padding + chartHeight,
                    X2 = padding + chartWidth,
                    Y2 = padding + chartHeight,
                    Stroke = Brushes.Black,
                    StrokeThickness = 2
                };
                canvas.Children.Add(xAxis);

                var yAxis = new Line
                {
                    X1 = padding,
                    Y1 = padding,
                    X2 = padding,
                    Y2 = padding + chartHeight,
                    Stroke = Brushes.Black,
                    StrokeThickness = 2
                };
                canvas.Children.Add(yAxis);

                // Axis labels
                var xLabel = new TextBlock
                {
                    Text = editor.XAxisLabel,
                    FontSize = 12,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(Color.FromRgb(60, 60, 60))
                };
                Canvas.SetLeft(xLabel, padding + chartWidth / 2 - xLabel.Text.Length * 3);
                Canvas.SetTop(xLabel, padding + chartHeight + 35);
                canvas.Children.Add(xLabel);

                var yLabel = new TextBlock
                {
                    Text = editor.YAxisLabel,
                    FontSize = 12,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(Color.FromRgb(60, 60, 60)),
                    RenderTransform = new RotateTransform(-90)
                };
                Canvas.SetLeft(yLabel, padding - 60);
                Canvas.SetTop(yLabel, padding + chartHeight / 2);
                canvas.Children.Add(yLabel);
            }

            // Draw trend line
            if (editor.ShowTrendLine && editor.DataPoints.Count >= 2)
            {
                var (correlation, slope, intercept) = CalculateCorrelationForScatter(editor.DataPoints);

                double x1Canvas = padding;
                double x2Canvas = padding + chartWidth;
                double x1Value = minX;
                double x2Value = maxX;
                double y1Value = slope * x1Value + intercept;
                double y2Value = slope * x2Value + intercept;

                double y1Canvas = padding + chartHeight - ((y1Value - minY) / rangeY) * chartHeight;
                double y2Canvas = padding + chartHeight - ((y2Value - minY) / rangeY) * chartHeight;

                var trendLine = new Line
                {
                    X1 = x1Canvas,
                    Y1 = y1Canvas,
                    X2 = x2Canvas,
                    Y2 = y2Canvas,
                    Stroke = new SolidColorBrush(Color.FromRgb(255, 100, 100)),
                    StrokeThickness = 2,
                    StrokeDashArray = new DoubleCollection { 5, 3 },
                    Opacity = 0.7
                };
                canvas.Children.Add(trendLine);
            }

            // Draw data points
            foreach (var point in editor.DataPoints)
            {
                double x = padding + ((point.X - minX) / rangeX) * chartWidth;
                double y = padding + chartHeight - ((point.Y - minY) / rangeY) * chartHeight;

                var categoryInfo = editor.Categories.ContainsKey(point.Category)
                    ? editor.Categories[point.Category]
                    : new CategoryInfo
                    {
                        Color = Color.FromRgb(102, 126, 234),
                        Shape = editor.DefaultPointShape
                    };

                var pointColor = categoryInfo.Color;
                var pointShape = categoryInfo.Shape;
                var pointSize = point.Size > 0 ? point.Size : editor.DefaultPointSize;

                DrawScatterPoint(canvas, x, y, pointSize, pointColor, pointShape, editor.PointOpacity);

                // Draw label
                if (editor.ShowLabels && !string.IsNullOrEmpty(point.Label))
                {
                    var labelText = new TextBlock
                    {
                        Text = point.Label,
                        FontSize = 9,
                        Foreground = new SolidColorBrush(Color.FromRgb(60, 60, 60))
                    };
                    Canvas.SetLeft(labelText, x + pointSize + 3);
                    Canvas.SetTop(labelText, y - pointSize - 3);
                    canvas.Children.Add(labelText);
                }
            }

            // Draw correlation info
            if (editor.ShowCorrelation && editor.DataPoints.Count >= 2)
            {
                var (correlation, _, _) = CalculateCorrelationForScatter(editor.DataPoints);
                var corrText = new TextBlock
                {
                    Text = $"r = {correlation:F3}",
                    FontSize = 12,
                    FontWeight = FontWeights.Bold,
                    Foreground = new SolidColorBrush(Color.FromRgb(102, 126, 234))
                };
                Canvas.SetLeft(corrText, padding + chartWidth - 80);
                Canvas.SetTop(corrText, padding + 10);
                canvas.Children.Add(corrText);
            }

            // Draw legend
            if (editor.ShowLegend && editor.Categories.Count > 0)
            {
                double legendX = padding + chartWidth - 150;
                double legendY = padding + 40;
                int index = 0;

                foreach (var kvp in editor.Categories)
                {
                    var categoryName = kvp.Key;
                    var categoryInfo = kvp.Value;

                    DrawScatterPoint(canvas, legendX, legendY + index * 25, 5, categoryInfo.Color, categoryInfo.Shape, editor.PointOpacity);

                    var legendText = new TextBlock
                    {
                        Text = categoryName,
                        FontSize = 11,
                        Foreground = new SolidColorBrush(Color.FromRgb(60, 60, 60))
                    };
                    Canvas.SetLeft(legendText, legendX + 15);
                    Canvas.SetTop(legendText, legendY + index * 25 - 6);
                    canvas.Children.Add(legendText);

                    index++;
                }
            }
        }

        private void DrawScatterPoint(Canvas canvas, double x, double y, double size, Color color, string shape, double opacity)
        {
            var brush = new SolidColorBrush(color) { Opacity = opacity };

            switch (shape)
            {
                case "circle":
                    var circle = new Ellipse
                    {
                        Width = size * 2,
                        Height = size * 2,
                        Fill = brush,
                        Stroke = new SolidColorBrush(color),
                        StrokeThickness = 1
                    };
                    Canvas.SetLeft(circle, x - size);
                    Canvas.SetTop(circle, y - size);
                    canvas.Children.Add(circle);
                    break;

                case "square":
                    var square = new Rectangle
                    {
                        Width = size * 2,
                        Height = size * 2,
                        Fill = brush,
                        Stroke = new SolidColorBrush(color),
                        StrokeThickness = 1
                    };
                    Canvas.SetLeft(square, x - size);
                    Canvas.SetTop(square, y - size);
                    canvas.Children.Add(square);
                    break;

                case "triangle":
                    var triangle = new Polygon
                    {
                        Points = new PointCollection
                        {
                            new Point(0, -size),
                            new Point(-size, size),
                            new Point(size, size)
                        },
                        Fill = brush,
                        Stroke = new SolidColorBrush(color),
                        StrokeThickness = 1
                    };
                    Canvas.SetLeft(triangle, x);
                    Canvas.SetTop(triangle, y);
                    canvas.Children.Add(triangle);
                    break;

                case "diamond":
                    var diamond = new Polygon
                    {
                        Points = new PointCollection
                        {
                            new Point(0, -size),
                            new Point(size, 0),
                            new Point(0, size),
                            new Point(-size, 0)
                        },
                        Fill = brush,
                        Stroke = new SolidColorBrush(color),
                        StrokeThickness = 1
                    };
                    Canvas.SetLeft(diamond, x);
                    Canvas.SetTop(diamond, y);
                    canvas.Children.Add(diamond);
                    break;

                case "cross":
                    var crossLine1 = new Line
                    {
                        X1 = x - size,
                        Y1 = y,
                        X2 = x + size,
                        Y2 = y,
                        Stroke = new SolidColorBrush(color) { Opacity = opacity },
                        StrokeThickness = 2
                    };
                    var crossLine2 = new Line
                    {
                        X1 = x,
                        Y1 = y - size,
                        X2 = x,
                        Y2 = y + size,
                        Stroke = new SolidColorBrush(color) { Opacity = opacity },
                        StrokeThickness = 2
                    };
                    canvas.Children.Add(crossLine1);
                    canvas.Children.Add(crossLine2);
                    break;

                case "star":
                    var star = new Polygon
                    {
                        Points = CreateScatterStarPoints(size),
                        Fill = brush,
                        Stroke = new SolidColorBrush(color),
                        StrokeThickness = 1
                    };
                    Canvas.SetLeft(star, x);
                    Canvas.SetTop(star, y);
                    canvas.Children.Add(star);
                    break;

                default:
                    var defaultCircle = new Ellipse
                    {
                        Width = size * 2,
                        Height = size * 2,
                        Fill = brush,
                        Stroke = new SolidColorBrush(color),
                        StrokeThickness = 1
                    };
                    Canvas.SetLeft(defaultCircle, x - size);
                    Canvas.SetTop(defaultCircle, y - size);
                    canvas.Children.Add(defaultCircle);
                    break;
            }
        }

        private PointCollection CreateScatterStarPoints(double size)
        {
            var points = new PointCollection();
            double outerRadius = size;
            double innerRadius = size * 0.4;

            for (int i = 0; i < 10; i++)
            {
                double angle = (i * 36 - 90) * Math.PI / 180;
                double radius = i % 2 == 0 ? outerRadius : innerRadius;
                points.Add(new Point(radius * Math.Cos(angle), radius * Math.Sin(angle)));
            }

            return points;
        }

        private (double correlation, double slope, double intercept) CalculateCorrelationForScatter(List<ScatterDataPoint> points)
        {
            if (points.Count < 2) return (0, 0, 0);

            int n = points.Count;
            double sumX = points.Sum(p => p.X);
            double sumY = points.Sum(p => p.Y);
            double sumXY = points.Sum(p => p.X * p.Y);
            double sumX2 = points.Sum(p => p.X * p.X);
            double sumY2 = points.Sum(p => p.Y * p.Y);

            double numerator = (n * sumXY) - (sumX * sumY);
            double denominator = Math.Sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY));

            double correlation = denominator == 0 ? 0 : numerator / denominator;

            // Linear regression
            double slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
            double intercept = (sumY - slope * sumX) / n;

            return (correlation, slope, intercept);
        }

        #endregion

        #region Radar Chart Methods

        /// <summary>
        /// Applies the configured radar chart to the canvas
        /// </summary>
        public void ApplyRadarChartToCanvas(Form2_14_RadarChartEditor editor)
        {
            if (editor == null)
                return;

            // Create a canvas with size 800x700 for the radar chart
            Canvas chartCanvas = new Canvas
            {
                Width = 800,
                Height = 700,
                Background = Brushes.White
            };

            // Draw the configured radar chart on the canvas
            DrawRadarChartOnCanvas(chartCanvas, editor);

            // Add the canvas to MainInteractiveBoard centered
            MainInteractiveBoard.Children.Add(chartCanvas);
            Canvas.SetLeft(chartCanvas, (MainInteractiveBoard.ActualWidth - 800) / 2);
            Canvas.SetTop(chartCanvas, (MainInteractiveBoard.ActualHeight - 700) / 2);
        }

        /// <summary>
        /// Draws the radar chart on the specified canvas
        /// </summary>
        private void DrawRadarChartOnCanvas(Canvas canvas, Form2_14_RadarChartEditor editor)
        {
            if (editor.Axes == null || editor.Axes.Count < 3 || editor.Datasets == null || editor.Datasets.Count == 0)
                return;

            double canvasWidth = canvas.Width;
            double canvasHeight = canvas.Height;
            double centerX = canvasWidth / 2;
            double centerY = canvasHeight / 2;
            double padding = 120;
            double maxRadius = Math.Min(canvasWidth, canvasHeight) / 2 - padding;

            // Background
            var bgRect = new System.Windows.Shapes.Rectangle
            {
                Width = canvasWidth,
                Height = canvasHeight,
                Fill = Brushes.White
            };
            Canvas.SetLeft(bgRect, 0);
            Canvas.SetTop(bgRect, 0);
            canvas.Children.Add(bgRect);

            // Title
            var titleText = new TextBlock
            {
                Text = editor.ChartTitle,
                FontSize = 20,
                FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush(Color.FromRgb(44, 62, 80))
            };
            Canvas.SetLeft(titleText, (canvasWidth - titleText.Text.Length * 10) / 2);
            Canvas.SetTop(titleText, 20);
            canvas.Children.Add(titleText);

            int axisCount = editor.Axes.Count;
            double angleStep = (2 * Math.PI) / axisCount;
            double startAngleRad = (editor.StartAngle * Math.PI) / 180;

            // Calculate angle for each axis
            List<double> angles = new List<double>();
            for (int i = 0; i < axisCount; i++)
            {
                double angle = editor.Clockwise
                    ? startAngleRad + (i * angleStep)
                    : startAngleRad - (i * angleStep);
                angles.Add(angle);
            }

            // Draw grid levels
            if (editor.ShowGrid)
            {
                for (int level = 1; level <= editor.GridLevels; level++)
                {
                    double radius = (maxRadius / editor.GridLevels) * level;
                    var polygon = new Polygon
                    {
                        Stroke = new SolidColorBrush(Color.FromRgb(224, 224, 224)),
                        StrokeThickness = 1,
                        Fill = Brushes.Transparent
                    };

                    var points = new PointCollection();
                    for (int i = 0; i < axisCount; i++)
                    {
                        double x = centerX + radius * Math.Cos(angles[i]);
                        double y = centerY + radius * Math.Sin(angles[i]);
                        points.Add(new Point(x, y));
                    }
                    polygon.Points = points;
                    canvas.Children.Add(polygon);

                    // Grid labels (percentage)
                    if (editor.ShowGridLabels && level > 0)
                    {
                        double percentage = (100.0 / editor.GridLevels) * level;
                        var labelText = new TextBlock
                        {
                            Text = $"{percentage:F0}%",
                            FontSize = 9,
                            Foreground = new SolidColorBrush(Color.FromRgb(150, 150, 150))
                        };
                        Canvas.SetLeft(labelText, centerX + 5);
                        Canvas.SetTop(labelText, centerY - radius - 5);
                        canvas.Children.Add(labelText);
                    }
                }
            }

            // Draw axes
            if (editor.ShowAxes)
            {
                for (int i = 0; i < axisCount; i++)
                {
                    double x = centerX + maxRadius * Math.Cos(angles[i]);
                    double y = centerY + maxRadius * Math.Sin(angles[i]);

                    var axisLine = new Line
                    {
                        X1 = centerX,
                        Y1 = centerY,
                        X2 = x,
                        Y2 = y,
                        Stroke = new SolidColorBrush(Color.FromRgb(153, 153, 153)),
                        StrokeThickness = 1
                    };
                    canvas.Children.Add(axisLine);
                }
            }

            // Draw labels
            if (editor.ShowLabels)
            {
                for (int i = 0; i < axisCount; i++)
                {
                    double labelRadius = maxRadius + 20;
                    double x = centerX + labelRadius * Math.Cos(angles[i]);
                    double y = centerY + labelRadius * Math.Sin(angles[i]);

                    var labelText = new TextBlock
                    {
                        Text = editor.Axes[i].Name,
                        FontSize = 12,
                        FontWeight = FontWeights.SemiBold,
                        Foreground = new SolidColorBrush(Color.FromRgb(60, 60, 60))
                    };

                    // Adjust label position based on angle
                    double angleDeg = angles[i] * 180 / Math.PI;
                    if (angleDeg > -90 && angleDeg < 90)
                    {
                        Canvas.SetLeft(labelText, x + 5);
                    }
                    else
                    {
                        Canvas.SetLeft(labelText, x - labelText.Text.Length * 6 - 5);
                    }
                    Canvas.SetTop(labelText, y - 8);

                    canvas.Children.Add(labelText);
                }
            }

            // Draw datasets
            foreach (var dataset in editor.Datasets)
            {
                if (dataset.Data.Count != axisCount)
                {
                    // Adjust data count to match axes
                    while (dataset.Data.Count < axisCount)
                        dataset.Data.Add(0);
                    while (dataset.Data.Count > axisCount)
                        dataset.Data.RemoveAt(dataset.Data.Count - 1);
                }

                var polygon = new Polygon
                {
                    Stroke = new SolidColorBrush(dataset.Color),
                    StrokeThickness = editor.LineWidth,
                    Fill = new SolidColorBrush(dataset.Color) { Opacity = editor.FillOpacity }
                };

                var points = new PointCollection();
                for (int i = 0; i < axisCount; i++)
                {
                    double value = dataset.Data[i];
                    double maxValue = editor.Axes[i].Max;
                    double normalized = Math.Max(0, Math.Min(1, value / maxValue));
                    double radius = maxRadius * normalized;

                    double x = centerX + radius * Math.Cos(angles[i]);
                    double y = centerY + radius * Math.Sin(angles[i]);
                    points.Add(new Point(x, y));
                }
                polygon.Points = points;
                canvas.Children.Add(polygon);

                // Draw points
                for (int i = 0; i < axisCount; i++)
                {
                    double value = dataset.Data[i];
                    double maxValue = editor.Axes[i].Max;
                    double normalized = Math.Max(0, Math.Min(1, value / maxValue));
                    double radius = maxRadius * normalized;

                    double x = centerX + radius * Math.Cos(angles[i]);
                    double y = centerY + radius * Math.Sin(angles[i]);

                    var point = new Ellipse
                    {
                        Width = editor.PointSize * 2,
                        Height = editor.PointSize * 2,
                        Fill = new SolidColorBrush(dataset.Color),
                        Stroke = Brushes.White,
                        StrokeThickness = 2
                    };
                    Canvas.SetLeft(point, x - editor.PointSize);
                    Canvas.SetTop(point, y - editor.PointSize);
                    canvas.Children.Add(point);

                    // Draw values
                    if (editor.ShowValues)
                    {
                        var valueText = new TextBlock
                        {
                            Text = value.ToString("F1"),
                            FontSize = 9,
                            Foreground = new SolidColorBrush(dataset.Color),
                            FontWeight = FontWeights.Bold
                        };
                        Canvas.SetLeft(valueText, x + editor.PointSize + 3);
                        Canvas.SetTop(valueText, y - editor.PointSize - 3);
                        canvas.Children.Add(valueText);
                    }
                }
            }

            // Draw legend
            if (editor.ShowLegend)
            {
                double legendX = 50;
                double legendY = canvasHeight - 50 - (editor.Datasets.Count * 25);

                for (int i = 0; i < editor.Datasets.Count; i++)
                {
                    var dataset = editor.Datasets[i];

                    var colorBox = new System.Windows.Shapes.Rectangle
                    {
                        Width = 20,
                        Height = 15,
                        Fill = new SolidColorBrush(dataset.Color),
                        Stroke = new SolidColorBrush(dataset.Color),
                        StrokeThickness = 1
                    };
                    Canvas.SetLeft(colorBox, legendX);
                    Canvas.SetTop(colorBox, legendY + i * 25);
                    canvas.Children.Add(colorBox);

                    var legendText = new TextBlock
                    {
                        Text = dataset.Label,
                        FontSize = 12,
                        Foreground = new SolidColorBrush(Color.FromRgb(60, 60, 60))
                    };
                    Canvas.SetLeft(legendText, legendX + 30);
                    Canvas.SetTop(legendText, legendY + i * 25);
                    canvas.Children.Add(legendText);
                }
            }
        }

        #endregion

        #region Canvas Size Optimization

        /// <summary>
        /// Calculates the bounding box of all content in canvas (without modifying content)
        /// </summary>
        private Rect CalculateContentBounds(Canvas canvas)
        {
            if (canvas.Children.Count == 0) 
                return new Rect(0, 0, 100, 100);

            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;

            foreach (UIElement child in canvas.Children)
            {
                if (child is Line line)
                {
                    minX = Math.Min(minX, Math.Min(line.X1, line.X2));
                    minY = Math.Min(minY, Math.Min(line.Y1, line.Y2));
                    maxX = Math.Max(maxX, Math.Max(line.X1, line.X2));
                    maxY = Math.Max(maxY, Math.Max(line.Y1, line.Y2));
                }
                else if (child is Polygon polygon)
                {
                    foreach (Point pt in polygon.Points)
                    {
                        minX = Math.Min(minX, pt.X);
                        minY = Math.Min(minY, pt.Y);
                        maxX = Math.Max(maxX, pt.X);
                        maxY = Math.Max(maxY, pt.Y);
                    }
                }
                else if (child is Polyline polyline)
                {
                    foreach (Point pt in polyline.Points)
                    {
                        minX = Math.Min(minX, pt.X);
                        minY = Math.Min(minY, pt.Y);
                        maxX = Math.Max(maxX, pt.X);
                        maxY = Math.Max(maxY, pt.Y);
                    }
                }
                else if (child is Ellipse ellipse)
                {
                    double left = Canvas.GetLeft(ellipse);
                    double top = Canvas.GetTop(ellipse);
                    if (double.IsNaN(left)) left = 0;
                    if (double.IsNaN(top)) top = 0;
                    
                    minX = Math.Min(minX, left);
                    minY = Math.Min(minY, top);
                    maxX = Math.Max(maxX, left + ellipse.Width);
                    maxY = Math.Max(maxY, top + ellipse.Height);
                }
            }

            if (minX == double.MaxValue) return new Rect(0, 0, 100, 100);

            return new Rect(minX, minY, maxX - minX, maxY - minY);
        }

        /// <summary>
        /// Trims canvas to fit content with minimal padding (removes white space completely)
        /// Includes StrokeThickness in bounds calculation
        /// </summary>
        private void TrimCanvasToContent(Canvas canvas, double padding = 10)
        {
            if (canvas.Children.Count == 0) return;

            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;

            // Calculate bounding box of all children INCLUDING stroke thickness
            foreach (UIElement child in canvas.Children)
            {
                double left = Canvas.GetLeft(child);
                double top = Canvas.GetTop(child);
                
                // Handle NaN values (use 0)
                if (double.IsNaN(left)) left = 0;
                if (double.IsNaN(top)) top = 0;

                double right = left;
                double bottom = top;

                // Get actual dimensions (Check Shape first to override general FrameworkElement bounds)
                if (child is Shape shape)
                {
                    double strokeThickness = shape.StrokeThickness;
                    double halfStroke = strokeThickness / 2.0;

                    // For shapes, check their geometry bounds + stroke thickness
                    if (shape is Line line)
                    {
                        minX = Math.Min(minX, Math.Min(line.X1, line.X2) - halfStroke);
                        minY = Math.Min(minY, Math.Min(line.Y1, line.Y2) - halfStroke);
                        maxX = Math.Max(maxX, Math.Max(line.X1, line.X2) + halfStroke);
                        maxY = Math.Max(maxY, Math.Max(line.Y1, line.Y2) + halfStroke);
                        continue;
                    }
                    else if (shape is Polygon polygon)
                    {
                        foreach (Point pt in polygon.Points)
                        {
                            minX = Math.Min(minX, pt.X - halfStroke);
                            minY = Math.Min(minY, pt.Y - halfStroke);
                            maxX = Math.Max(maxX, pt.X + halfStroke);
                            maxY = Math.Max(maxY, pt.Y + halfStroke);
                        }
                        continue;
                    }
                    else if (shape is Polyline polyline)
                    {
                        foreach (Point pt in polyline.Points)
                        {
                            minX = Math.Min(minX, pt.X - halfStroke);
                            minY = Math.Min(minY, pt.Y - halfStroke);
                            maxX = Math.Max(maxX, pt.X + halfStroke);
                            maxY = Math.Max(maxY, pt.Y + halfStroke);
                        }
                        continue;
                    }
                    else if (shape is Ellipse ellipse)
                    {
                        // Ellipse vertices (used for dots on shapes)
                        minX = Math.Min(minX, left - halfStroke);
                        minY = Math.Min(minY, top - halfStroke);
                        maxX = Math.Max(maxX, left + ellipse.Width + halfStroke);
                        maxY = Math.Max(maxY, top + ellipse.Height + halfStroke);
                        continue;
                    }
                    
                    right = left + (shape.ActualWidth > 0 ? shape.ActualWidth : shape.Width) + strokeThickness;
                    bottom = top + (shape.ActualHeight > 0 ? shape.ActualHeight : shape.Height) + strokeThickness;
                }
                else if (child is FrameworkElement frameworkElement)
                {
                    right = left + (frameworkElement.ActualWidth > 0 ? frameworkElement.ActualWidth : frameworkElement.Width);
                    bottom = top + (frameworkElement.ActualHeight > 0 ? frameworkElement.ActualHeight : frameworkElement.Height);
                }

                minX = Math.Min(minX, left);
                minY = Math.Min(minY, top);
                maxX = Math.Max(maxX, right);
                maxY = Math.Max(maxY, bottom);
            }

            // If no valid bounds found, keep original size
            if (minX == double.MaxValue || minY == double.MaxValue || 
                maxX == double.MinValue || maxY == double.MinValue)
                return;

            // Adjust all children positions to account for removed white space
            double offsetX = minX - padding;
            double offsetY = minY - padding;

            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    // For Lines, adjust X1, Y1, X2, Y2
                    if (shape is Line line)
                    {
                        line.X1 -= offsetX;
                        line.Y1 -= offsetY;
                        line.X2 -= offsetX;
                        line.Y2 -= offsetY;
                    }
                    // For Polygons/Polylines, adjust all points
                    else if (shape is Polygon polygon)
                    {
                        var newPoints = new PointCollection();
                        foreach (Point pt in polygon.Points)
                        {
                            newPoints.Add(new Point(pt.X - offsetX, pt.Y - offsetY));
                        }
                        polygon.Points = newPoints;
                    }
                    else if (shape is Polyline polyline)
                    {
                        var newPoints = new PointCollection();
                        foreach (Point pt in polyline.Points)
                        {
                            newPoints.Add(new Point(pt.X - offsetX, pt.Y - offsetY));
                        }
                        polyline.Points = newPoints;
                    }
                    else
                    {
                        // For other shapes (Rectangle, Ellipse), adjust Canvas position
                        double left = Canvas.GetLeft(shape);
                        double top = Canvas.GetTop(shape);
                        if (!double.IsNaN(left)) Canvas.SetLeft(shape, left - offsetX);
                        if (!double.IsNaN(top)) Canvas.SetTop(shape, top - offsetY);
                    }
                }
                else
                {
                    // For other elements, adjust Canvas position
                    double left = Canvas.GetLeft(child);
                    double top = Canvas.GetTop(child);
                    if (!double.IsNaN(left)) Canvas.SetLeft(child, left - offsetX);
                    if (!double.IsNaN(top)) Canvas.SetTop(child, top - offsetY);
                }
            }

            // Set new canvas size (content size + padding on all sides)
            double newWidth = (maxX - minX) + (padding * 2);
            double newHeight = (maxY - minY) + (padding * 2);
            
            if (double.IsNaN(newWidth) || double.IsInfinity(newWidth) || newWidth < 10) newWidth = 200;
            if (double.IsNaN(newHeight) || double.IsInfinity(newHeight) || newHeight < 10) newHeight = 200;

            canvas.Width = newWidth;
            canvas.Height = newHeight;
        }

        /// <summary>
        /// Trims canvas to a perfect square centered on sphere
        /// Square side = diameter of sphere on canvas
        /// Sphere center = center of square
        /// </summary>
        private void TrimCanvasToSquare(Canvas canvas, double padding = 10)
        {
            if (canvas.Children.Count == 0) return;

            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;

            // Calculate bounding box including stroke thickness
            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    double strokeThickness = shape.StrokeThickness;
                    double halfStroke = strokeThickness / 2.0;

                    if (shape is Line line)
                    {
                        minX = Math.Min(minX, Math.Min(line.X1, line.X2) - halfStroke);
                        minY = Math.Min(minY, Math.Min(line.Y1, line.Y2) - halfStroke);
                        maxX = Math.Max(maxX, Math.Max(line.X1, line.X2) + halfStroke);
                        maxY = Math.Max(maxY, Math.Max(line.Y1, line.Y2) + halfStroke);
                    }
                    else if (shape is Polygon polygon)
                    {
                        foreach (Point pt in polygon.Points)
                        {
                            minX = Math.Min(minX, pt.X - halfStroke);
                            minY = Math.Min(minY, pt.Y - halfStroke);
                            maxX = Math.Max(maxX, pt.X + halfStroke);
                            maxY = Math.Max(maxY, pt.Y + halfStroke);
                        }
                    }
                    else if (shape is Polyline polyline)
                    {
                        foreach (Point pt in polyline.Points)
                        {
                            minX = Math.Min(minX, pt.X - halfStroke);
                            minY = Math.Min(minY, pt.Y - halfStroke);
                            maxX = Math.Max(maxX, pt.X + halfStroke);
                            maxY = Math.Max(maxY, pt.Y + halfStroke);
                        }
                    }
                    else if (shape is Ellipse ellipse)
                    {
                        double left = Canvas.GetLeft(ellipse);
                        double top = Canvas.GetTop(ellipse);
                        if (double.IsNaN(left)) left = 0;
                        if (double.IsNaN(top)) top = 0;

                        double width = ellipse.ActualWidth > 0 ? ellipse.ActualWidth : ellipse.Width;
                        double height = ellipse.ActualHeight > 0 ? ellipse.ActualHeight : ellipse.Height;

                        minX = Math.Min(minX, left - halfStroke);
                        minY = Math.Min(minY, top - halfStroke);
                        maxX = Math.Max(maxX, left + width + halfStroke);
                        maxY = Math.Max(maxY, top + height + halfStroke);
                    }
                }
            }

            if (minX == double.MaxValue || minY == double.MaxValue || 
                maxX == double.MinValue || maxY == double.MinValue)
                return;

            // Calculate content dimensions
            double contentWidth = maxX - minX;
            double contentHeight = maxY - minY;

            // Find the diameter (max of width/height)
            double diameter = Math.Max(contentWidth, contentHeight);

            // Calculate center of current content
            double centerX = (minX + maxX) / 2.0;
            double centerY = (minY + maxY) / 2.0;

            // Create square bounds: center remains same, side = diameter
            double squareMinX = centerX - (diameter / 2.0);
            double squareMinY = centerY - (diameter / 2.0);
            double squareMaxX = centerX + (diameter / 2.0);
            double squareMaxY = centerY + (diameter / 2.0);

            // Adjust all children to new origin (squareMinX, squareMinY)
            double offsetX = squareMinX - padding;
            double offsetY = squareMinY - padding;

            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    if (shape is Line line)
                    {
                        line.X1 -= offsetX;
                        line.Y1 -= offsetY;
                        line.X2 -= offsetX;
                        line.Y2 -= offsetY;
                    }
                    else if (shape is Polygon polygon)
                    {
                        var newPoints = new PointCollection();
                        foreach (Point pt in polygon.Points)
                        {
                            newPoints.Add(new Point(pt.X - offsetX, pt.Y - offsetY));
                        }
                        polygon.Points = newPoints;
                    }
                    else if (shape is Polyline polyline)
                    {
                        var newPoints = new PointCollection();
                        foreach (Point pt in polyline.Points)
                        {
                            newPoints.Add(new Point(pt.X - offsetX, pt.Y - offsetY));
                        }
                        polyline.Points = newPoints;
                    }
                    else
                    {
                        double left = Canvas.GetLeft(shape);
                        double top = Canvas.GetTop(shape);
                        if (!double.IsNaN(left)) Canvas.SetLeft(shape, left - offsetX);
                        if (!double.IsNaN(top)) Canvas.SetTop(shape, top - offsetY);
                    }
                }
                else
                {
                    double left = Canvas.GetLeft(child);
                    double top = Canvas.GetTop(child);
                    if (!double.IsNaN(left)) Canvas.SetLeft(child, left - offsetX);
                    if (!double.IsNaN(top)) Canvas.SetTop(child, top - offsetY);
                }
            }

            // Set canvas to perfect square: side = diameter + padding * 2
            double squareSize = diameter + (padding * 2);
            canvas.Width = Math.Max(squareSize, 10);
            canvas.Height = Math.Max(squareSize, 10);
        }

        /// <summary>
        /// Trims canvas to a perfect square for cube based on space diagonal
        /// Square side = space diagonal of cube (a × √3)
        /// Cube center = center of square
        /// </summary>
        private void TrimCanvasToCubeDiagonal(Canvas canvas, double cubeSize, double padding = 10)
        {
            if (canvas.Children.Count == 0) return;

            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;

            // Calculate bounding box including stroke thickness
            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    double strokeThickness = shape.StrokeThickness;
                    double halfStroke = strokeThickness / 2.0;

                    if (shape is Line line)
                    {
                        minX = Math.Min(minX, Math.Min(line.X1, line.X2) - halfStroke);
                        minY = Math.Min(minY, Math.Min(line.Y1, line.Y2) - halfStroke);
                        maxX = Math.Max(maxX, Math.Max(line.X1, line.X2) + halfStroke);
                        maxY = Math.Max(maxY, Math.Max(line.Y1, line.Y2) + halfStroke);
                    }
                    else if (shape is Polygon polygon)
                    {
                        foreach (Point pt in polygon.Points)
                        {
                            minX = Math.Min(minX, pt.X - halfStroke);
                            minY = Math.Min(minY, pt.Y - halfStroke);
                            maxX = Math.Max(maxX, pt.X + halfStroke);
                            maxY = Math.Max(maxY, pt.Y + halfStroke);
                        }
                    }
                    else if (shape is Ellipse ellipse)
                    {
                        double left = Canvas.GetLeft(ellipse);
                        double top = Canvas.GetTop(ellipse);
                        if (double.IsNaN(left)) left = 0;
                        if (double.IsNaN(top)) top = 0;

                        double width = ellipse.ActualWidth > 0 ? ellipse.ActualWidth : ellipse.Width;
                        double height = ellipse.ActualHeight > 0 ? ellipse.ActualHeight : ellipse.Height;

                        minX = Math.Min(minX, left - halfStroke);
                        minY = Math.Min(minY, top - halfStroke);
                        maxX = Math.Max(maxX, left + width + halfStroke);
                        maxY = Math.Max(maxY, top + height + halfStroke);
                    }
                }
            }

            if (minX == double.MaxValue || minY == double.MaxValue || 
                maxX == double.MinValue || maxY == double.MinValue)
                return;

            // Calculate center of current content
            double centerX = (minX + maxX) / 2.0;
            double centerY = (minY + maxY) / 2.0;

            // Calculate space diagonal of cube: diagonal = cubeSize × √3
            // This is the diagonal from one vertex to the opposite vertex in 3D space
            double spaceDiagonal = cubeSize * Math.Sqrt(3);

            // For 2D projection, we need to account for the perspective
            // The projected size should fit within this diagonal
            // Use the actual content size but ensure minimum is the space diagonal
            double contentWidth = maxX - minX;
            double contentHeight = maxY - minY;
            double currentDiagonal = Math.Sqrt(contentWidth * contentWidth + contentHeight * contentHeight);
            
            // Use the larger of actual diagonal or theoretical space diagonal
            double targetDiagonal = Math.Max(currentDiagonal, spaceDiagonal);
            
            // Convert diagonal to square side (for a square, diagonal = side × √2)
            // So side = diagonal / √2
            double squareSide = targetDiagonal / Math.Sqrt(2);

            // Create square bounds centered on cube
            double squareMinX = centerX - (squareSide / 2.0);
            double squareMinY = centerY - (squareSide / 2.0);

            // Adjust all children to new origin
            double offsetX = squareMinX - padding;
            double offsetY = squareMinY - padding;

            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    if (shape is Line line)
                    {
                        line.X1 -= offsetX;
                        line.Y1 -= offsetY;
                        line.X2 -= offsetX;
                        line.Y2 -= offsetY;
                    }
                    else if (shape is Polygon polygon)
                    {
                        var newPoints = new PointCollection();
                        foreach (Point pt in polygon.Points)
                        {
                            newPoints.Add(new Point(pt.X - offsetX, pt.Y - offsetY));
                        }
                        polygon.Points = newPoints;
                    }
                    else
                    {
                        double left = Canvas.GetLeft(shape);
                        double top = Canvas.GetTop(shape);
                        if (!double.IsNaN(left)) Canvas.SetLeft(shape, left - offsetX);
                        if (!double.IsNaN(top)) Canvas.SetTop(shape, top - offsetY);
                    }
                }
                else
                {
                    double left = Canvas.GetLeft(child);
                    double top = Canvas.GetTop(child);
                    if (!double.IsNaN(left)) Canvas.SetLeft(child, left - offsetX);
                    if (!double.IsNaN(top)) Canvas.SetTop(child, top - offsetY);
                }
            }

            // Set canvas to perfect square
            double finalSize = squareSide + (padding * 2);
            canvas.Width = Math.Max(finalSize, 10);
            canvas.Height = Math.Max(finalSize, 10);
        }

        /// <summary>
        /// Trims canvas to a rectangle for pyramid
        /// Rectangle: width = base width, height = pyramid height
        /// </summary>
        private void TrimCanvasToPyramidRectangle(Canvas canvas, double baseSize, double pyramidHeight, double padding = 10)
        {
            if (canvas.Children.Count == 0) return;

            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;

            // Calculate bounding box including stroke thickness
            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    double strokeThickness = shape.StrokeThickness;
                    double halfStroke = strokeThickness / 2.0;

                    if (shape is Line line)
                    {
                        minX = Math.Min(minX, Math.Min(line.X1, line.X2) - halfStroke);
                        minY = Math.Min(minY, Math.Min(line.Y1, line.Y2) - halfStroke);
                        maxX = Math.Max(maxX, Math.Max(line.X1, line.X2) + halfStroke);
                        maxY = Math.Max(maxY, Math.Max(line.Y1, line.Y2) + halfStroke);
                    }
                    else if (shape is Polygon polygon)
                    {
                        foreach (Point pt in polygon.Points)
                        {
                            minX = Math.Min(minX, pt.X - halfStroke);
                            minY = Math.Min(minY, pt.Y - halfStroke);
                            maxX = Math.Max(maxX, pt.X + halfStroke);
                            maxY = Math.Max(maxY, pt.Y + halfStroke);
                        }
                    }
                    else if (shape is Ellipse ellipse)
                    {
                        double left = Canvas.GetLeft(ellipse);
                        double top = Canvas.GetTop(ellipse);
                        if (double.IsNaN(left)) left = 0;
                        if (double.IsNaN(top)) top = 0;

                        double width = ellipse.ActualWidth > 0 ? ellipse.ActualWidth : ellipse.Width;
                        double height = ellipse.ActualHeight > 0 ? ellipse.ActualHeight : ellipse.Height;

                        minX = Math.Min(minX, left - halfStroke);
                        minY = Math.Min(minY, top - halfStroke);
                        maxX = Math.Max(maxX, left + width + halfStroke);
                        maxY = Math.Max(maxY, top + height + halfStroke);
                    }
                }
            }

            if (minX == double.MaxValue || minY == double.MaxValue || 
                maxX == double.MinValue || maxY == double.MinValue)
                return;

            // Calculate center of current content
            double centerX = (minX + maxX) / 2.0;
            double centerY = (minY + maxY) / 2.0;

            // Calculate actual content dimensions
            double contentWidth = maxX - minX;
            double contentHeight = maxY - minY;

            // For pyramid: width should fit the base, height should fit the pyramid height
            // The base is typically the circumradius × 2 (for regular polygons)
            // Use the actual projected size but ensure it's at least the theoretical size
            double theoreticalBaseWidth = baseSize * 1.5; // Account for projection and rotation
            double theoreticalHeight = pyramidHeight * 1.2; // Account for projection

            double targetWidth = Math.Max(contentWidth, theoreticalBaseWidth);
            double targetHeight = Math.Max(contentHeight, theoreticalHeight);

            // Create rectangle bounds centered on pyramid
            double rectMinX = centerX - (targetWidth / 2.0);
            double rectMinY = centerY - (targetHeight / 2.0);

            // Adjust all children to new origin
            double offsetX = rectMinX - padding;
            double offsetY = rectMinY - padding;

            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    if (shape is Line line)
                    {
                        line.X1 -= offsetX;
                        line.Y1 -= offsetY;
                        line.X2 -= offsetX;
                        line.Y2 -= offsetY;
                    }
                    else if (shape is Polygon polygon)
                    {
                        var newPoints = new PointCollection();
                        foreach (Point pt in polygon.Points)
                        {
                            newPoints.Add(new Point(pt.X - offsetX, pt.Y - offsetY));
                        }
                        polygon.Points = newPoints;
                    }
                    else
                    {
                        double left = Canvas.GetLeft(shape);
                        double top = Canvas.GetTop(shape);
                        if (!double.IsNaN(left)) Canvas.SetLeft(shape, left - offsetX);
                        if (!double.IsNaN(top)) Canvas.SetTop(shape, top - offsetY);
                    }
                }
                else
                {
                    double left = Canvas.GetLeft(child);
                    double top = Canvas.GetTop(child);
                    if (!double.IsNaN(left)) Canvas.SetLeft(child, left - offsetX);
                    if (!double.IsNaN(top)) Canvas.SetTop(child, top - offsetY);
                }
            }

            // Set canvas to rectangle
            canvas.Width = Math.Max(targetWidth + (padding * 2), 10);
            canvas.Height = Math.Max(targetHeight + (padding * 2), 10);
        }

        /// <summary>
        /// Trims canvas to a rectangle for cylinder
        /// Rectangle: width = diameter (2 × radius), height = cylinder height
        /// </summary>
        private void TrimCanvasToCylinderRectangle(Canvas canvas, double radius, double cylinderHeight, double padding = 10)
        {
            if (canvas.Children.Count == 0) return;

            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;

            // Calculate bounding box including stroke thickness
            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    double strokeThickness = shape.StrokeThickness;
                    double halfStroke = strokeThickness / 2.0;

                    if (shape is Line line)
                    {
                        minX = Math.Min(minX, Math.Min(line.X1, line.X2) - halfStroke);
                        minY = Math.Min(minY, Math.Min(line.Y1, line.Y2) - halfStroke);
                        maxX = Math.Max(maxX, Math.Max(line.X1, line.X2) + halfStroke);
                        maxY = Math.Max(maxY, Math.Max(line.Y1, line.Y2) + halfStroke);
                    }
                    else if (shape is Polygon polygon)
                    {
                        foreach (Point pt in polygon.Points)
                        {
                            minX = Math.Min(minX, pt.X - halfStroke);
                            minY = Math.Min(minY, pt.Y - halfStroke);
                            maxX = Math.Max(maxX, pt.X + halfStroke);
                            maxY = Math.Max(maxY, pt.Y + halfStroke);
                        }
                    }
                    else if (shape is Ellipse ellipse)
                    {
                        double left = Canvas.GetLeft(ellipse);
                        double top = Canvas.GetTop(ellipse);
                        if (double.IsNaN(left)) left = 0;
                        if (double.IsNaN(top)) top = 0;

                        double width = ellipse.ActualWidth > 0 ? ellipse.ActualWidth : ellipse.Width;
                        double height = ellipse.ActualHeight > 0 ? ellipse.ActualHeight : ellipse.Height;

                        minX = Math.Min(minX, left - halfStroke);
                        minY = Math.Min(minY, top - halfStroke);
                        maxX = Math.Max(maxX, left + width + halfStroke);
                        maxY = Math.Max(maxY, top + height + halfStroke);
                    }
                }
            }

            if (minX == double.MaxValue || minY == double.MaxValue || 
                maxX == double.MinValue || maxY == double.MinValue)
                return;

            // Calculate center of current content
            double centerX = (minX + maxX) / 2.0;
            double centerY = (minY + maxY) / 2.0;

            // Calculate actual content dimensions
            double contentWidth = maxX - minX;
            double contentHeight = maxY - minY;

            // For cylinder: width = diameter (2 × radius), height = cylinder height
            double theoreticalDiameter = radius * 2.0 * 1.2; // Account for projection
            double theoreticalHeight = cylinderHeight * 1.2; // Account for projection

            double targetWidth = Math.Max(contentWidth, theoreticalDiameter);
            double targetHeight = Math.Max(contentHeight, theoreticalHeight);

            // Create rectangle bounds centered on cylinder
            double rectMinX = centerX - (targetWidth / 2.0);
            double rectMinY = centerY - (targetHeight / 2.0);

            // Adjust all children to new origin
            double offsetX = rectMinX - padding;
            double offsetY = rectMinY - padding;

            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    if (shape is Line line)
                    {
                        line.X1 -= offsetX;
                        line.Y1 -= offsetY;
                        line.X2 -= offsetX;
                        line.Y2 -= offsetY;
                    }
                    else if (shape is Polygon polygon)
                    {
                        var newPoints = new PointCollection();
                        foreach (Point pt in polygon.Points)
                        {
                            newPoints.Add(new Point(pt.X - offsetX, pt.Y - offsetY));
                        }
                        polygon.Points = newPoints;
                    }
                    else
                    {
                        double left = Canvas.GetLeft(shape);
                        double top = Canvas.GetTop(shape);
                        if (!double.IsNaN(left)) Canvas.SetLeft(shape, left - offsetX);
                        if (!double.IsNaN(top)) Canvas.SetTop(shape, top - offsetY);
                    }
                }
                else
                {
                    double left = Canvas.GetLeft(child);
                    double top = Canvas.GetTop(child);
                    if (!double.IsNaN(left)) Canvas.SetLeft(child, left - offsetX);
                    if (!double.IsNaN(top)) Canvas.SetTop(child, top - offsetY);
                }
            }

            // Set canvas to rectangle
            canvas.Width = Math.Max(targetWidth + (padding * 2), 10);
            canvas.Height = Math.Max(targetHeight + (padding * 2), 10);
        }

        /// <summary>
        /// Trims canvas to a rectangle for prism
        /// Rectangle: width = base diagonal, height = hypotenuse of triangle(diagonal, prism height)
        /// hypotenuse = √(diagonal² + height²)
        /// </summary>
        private void TrimCanvasToPrismRectangle(Canvas canvas, double baseSize, double prismHeight, string baseType, double padding = 10)
        {
            if (canvas.Children.Count == 0) return;

            // Get number of sides from base type
            int sides = baseType switch
            {
                "Triangle" => 3,
                "Square" => 4,
                "Pentagon" => 5,
                "Hexagon" => 6,
                _ => 4
            };

            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;

            // Calculate bounding box including stroke thickness
            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    double strokeThickness = shape.StrokeThickness;
                    double halfStroke = strokeThickness / 2.0;

                    if (shape is Line line)
                    {
                        minX = Math.Min(minX, Math.Min(line.X1, line.X2) - halfStroke);
                        minY = Math.Min(minY, Math.Min(line.Y1, line.Y2) - halfStroke);
                        maxX = Math.Max(maxX, Math.Max(line.X1, line.X2) + halfStroke);
                        maxY = Math.Max(maxY, Math.Max(line.Y1, line.Y2) + halfStroke);
                    }
                    else if (shape is Polygon polygon)
                    {
                        foreach (Point pt in polygon.Points)
                        {
                            minX = Math.Min(minX, pt.X - halfStroke);
                            minY = Math.Min(minY, pt.Y - halfStroke);
                            maxX = Math.Max(maxX, pt.X + halfStroke);
                            maxY = Math.Max(maxY, pt.Y + halfStroke);
                        }
                    }
                    else if (shape is Ellipse ellipse)
                    {
                        double left = Canvas.GetLeft(ellipse);
                        double top = Canvas.GetTop(ellipse);
                        if (double.IsNaN(left)) left = 0;
                        if (double.IsNaN(top)) top = 0;

                        double width = ellipse.ActualWidth > 0 ? ellipse.ActualWidth : ellipse.Width;
                        double height = ellipse.ActualHeight > 0 ? ellipse.ActualHeight : ellipse.Height;

                        minX = Math.Min(minX, left - halfStroke);
                        minY = Math.Min(minY, top - halfStroke);
                        maxX = Math.Max(maxX, left + width + halfStroke);
                        maxY = Math.Max(maxY, top + height + halfStroke);
                    }
                }
            }

            if (minX == double.MaxValue || minY == double.MaxValue || 
                maxX == double.MinValue || maxY == double.MinValue)
                return;

            // Calculate center of current content
            double centerX = (minX + maxX) / 2.0;
            double centerY = (minY + maxY) / 2.0;

            // Calculate actual content dimensions
            double contentWidth = maxX - minX;
            double contentHeight = maxY - minY;

            // For prism base diagonal calculation
            // For regular polygon: diagonal depends on number of sides
            // For n-sided polygon inscribed in circle of radius r:
            // Maximum diagonal â‰ˆ 2 × r (for opposite vertices)
            double circumradius = baseSize / (2.0 * Math.Sin(Math.PI / sides));
            double baseDiagonal = 2.0 * circumradius;

            // Calculate hypotenuse: √(diagonal² + height²)
            double hypotenuse = Math.Sqrt(baseDiagonal * baseDiagonal + prismHeight * prismHeight);

            // Account for projection
            double theoreticalWidth = baseDiagonal * 1.2;
            double theoreticalHeight = hypotenuse * 1.2;

            double targetWidth = Math.Max(contentWidth, theoreticalWidth);
            double targetHeight = Math.Max(contentHeight, theoreticalHeight);

            // Create rectangle bounds centered on prism
            double rectMinX = centerX - (targetWidth / 2.0);
            double rectMinY = centerY - (targetHeight / 2.0);

            // Adjust all children to new origin
            double offsetX = rectMinX - padding;
            double offsetY = rectMinY - padding;

            foreach (UIElement child in canvas.Children)
            {
                if (child is Shape shape)
                {
                    if (shape is Line line)
                    {
                        line.X1 -= offsetX;
                        line.Y1 -= offsetY;
                        line.X2 -= offsetX;
                        line.Y2 -= offsetY;
                    }
                    else if (shape is Polygon polygon)
                    {
                        var newPoints = new PointCollection();
                        foreach (Point pt in polygon.Points)
                        {
                            newPoints.Add(new Point(pt.X - offsetX, pt.Y - offsetY));
                        }
                        polygon.Points = newPoints;
                    }
                    else
                    {
                        double left = Canvas.GetLeft(shape);
                        double top = Canvas.GetTop(shape);
                        if (!double.IsNaN(left)) Canvas.SetLeft(shape, left - offsetX);
                        if (!double.IsNaN(top)) Canvas.SetTop(shape, top - offsetY);
                    }
                }
                else
                {
                    double left = Canvas.GetLeft(child);
                    double top = Canvas.GetTop(child);
                    if (!double.IsNaN(left)) Canvas.SetLeft(child, left - offsetX);
                    if (!double.IsNaN(top)) Canvas.SetTop(child, top - offsetY);
                }
            }

            // Set canvas to rectangle
            canvas.Width = Math.Max(targetWidth + (padding * 2), 10);
            canvas.Height = Math.Max(targetHeight + (padding * 2), 10);
        }

