        #region Object Action Buttons (Copy & Delete)

        /// <summary>
        /// Shows Copy and Delete buttons at the top-right corner of selected object
        /// </summary>
        private void ShowActionButtons(UIElement targetObject)
        {
            // Hide previous action buttons if any
            HideActionButtons();

            var mainCanvas = this.FindName("MainInteractiveBoard") as Canvas;
            if (mainCanvas == null) return;

            _currentSelectedObject = targetObject;

            // Get object position and size
            double objLeft = Canvas.GetLeft(targetObject);
            double objTop = Canvas.GetTop(targetObject);
            double objWidth = 0;
            double objHeight = 0;

            if (targetObject is FrameworkElement frameworkElement)
            {
                objWidth = frameworkElement.ActualWidth > 0 ? frameworkElement.ActualWidth : frameworkElement.Width;
                objHeight = frameworkElement.ActualHeight > 0 ? frameworkElement.ActualHeight : frameworkElement.Height;
            }

            // Defensive check against NaN or infinity values
            if (double.IsNaN(objLeft) || double.IsInfinity(objLeft)) objLeft = 300;
            if (double.IsNaN(objTop) || double.IsInfinity(objTop)) objTop = 300;
            if (double.IsNaN(objWidth) || double.IsInfinity(objWidth) || objWidth < 10) objWidth = 200;
            if (double.IsNaN(objHeight) || double.IsInfinity(objHeight) || objHeight < 10) objHeight = 200;

            // Create container for action buttons
            _actionButtonsContainer = new Canvas
            {
                Width = 120,
                Height = 40
            };

            // Position at top-right corner of object (closer to object)
            // Place buttons at top-right, slightly outside the object
            Canvas.SetLeft(_actionButtonsContainer, objLeft + objWidth + 5);
            Canvas.SetTop(_actionButtonsContainer, objTop - 10);
            Canvas.SetZIndex(_actionButtonsContainer, ZIndexConstants.SystemUIBase); // Always on top

            // Create Copy button
            var copyButton = new Button
            {
                Content = "📋 Copy",
                Width = 55,
                Height = 35,
                Background = new SolidColorBrush(Color.FromRgb(76, 175, 80)), // Green
                Foreground = Brushes.White,
                FontSize = 11,
                FontWeight = FontWeights.Bold,
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                Style = (Style)Application.Current.Resources["RoundedButtonStyle"]
            };
            copyButton.Click += (s, e) => CopyObject(targetObject);
            Canvas.SetLeft(copyButton, 0);
            Canvas.SetTop(copyButton, 0);
            _actionButtonsContainer.Children.Add(copyButton);

            // Create Delete button
            var deleteButton = new Button
            {
                Content = "🗑️ Xóa",
                Width = 55,
                Height = 35,
                Background = new SolidColorBrush(Color.FromRgb(244, 67, 54)), // Red
                Foreground = Brushes.White,
                FontSize = 11,
                FontWeight = FontWeights.Bold,
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                Style = (Style)Application.Current.Resources["RoundedButtonStyle"]
            };
            deleteButton.Click += (s, e) => DeleteObject(targetObject);
            Canvas.SetLeft(deleteButton, 65);
            Canvas.SetTop(deleteButton, 0);
            _actionButtonsContainer.Children.Add(deleteButton);

            // Add to main canvas
            mainCanvas.Children.Add(_actionButtonsContainer);
        }

        /// <summary>
        /// Hides action buttons
        /// </summary>
        private void HideActionButtons()
        {
            if (_actionButtonsContainer != null)
            {
                var mainCanvas = this.FindName("MainInteractiveBoard") as Canvas;
                if (mainCanvas != null && mainCanvas.Children.Contains(_actionButtonsContainer))
                {
                    mainCanvas.Children.Remove(_actionButtonsContainer);
                }
                _actionButtonsContainer = null;
            }
            _currentSelectedObject = null;
        }

        /// <summary>
        /// Updates action buttons position to follow the selected object
        /// </summary>
        private void UpdateActionButtonsPosition()
        {
            if (_actionButtonsContainer == null || _currentSelectedObject == null) return;

            // Get current object position and size
            double objLeft = Canvas.GetLeft(_currentSelectedObject);
            double objTop = Canvas.GetTop(_currentSelectedObject);
            double objWidth = 0;
            double objHeight = 0;

            if (_currentSelectedObject is FrameworkElement frameworkElement)
            {
                objWidth = frameworkElement.ActualWidth > 0 ? frameworkElement.ActualWidth : frameworkElement.Width;
                objHeight = frameworkElement.ActualHeight > 0 ? frameworkElement.ActualHeight : frameworkElement.Height;
            }

            // Defensive check against NaN or infinity values
            if (double.IsNaN(objLeft) || double.IsInfinity(objLeft)) objLeft = 300;
            if (double.IsNaN(objTop) || double.IsInfinity(objTop)) objTop = 300;
            if (double.IsNaN(objWidth) || double.IsInfinity(objWidth) || objWidth < 10) objWidth = 200;
            if (double.IsNaN(objHeight) || double.IsInfinity(objHeight) || objHeight < 10) objHeight = 200;

            // Update button container position to follow object
            Canvas.SetLeft(_actionButtonsContainer, objLeft + objWidth + 5);
            Canvas.SetTop(_actionButtonsContainer, objTop - 10);
        }

        /// <summary>
        /// Copies the selected object and places it slightly offset
        /// </summary>
        private void CopyObject(UIElement sourceObject)
        {
            var mainCanvas = this.FindName("MainInteractiveBoard") as Canvas;
            if (mainCanvas == null) return;

            try
            {
                UIElement? clonedObject = null;
                double offsetX = 20;
                double offsetY = 20;

                // Clone based on object type
                if (sourceObject is Canvas canvas)
                {
                    // Clone Canvas container (for 3D shapes, charts, etc.)
                    var newCanvas = new Canvas
                    {
                        Width = canvas.Width,
                        Height = canvas.Height,
                        Background = canvas.Background,
                        ClipToBounds = canvas.ClipToBounds
                    };

                    // Clone all children
                    foreach (UIElement child in canvas.Children)
                    {
                        if (child is Shape shape)
                        {
                            var clonedShape = CloneShape(shape);
                            if (clonedShape != null)
                                newCanvas.Children.Add(clonedShape);
                        }
                        else if (child is TextBlock textBlock)
                        {
                            var clonedText = new TextBlock
                            {
                                Text = textBlock.Text,
                                FontSize = textBlock.FontSize,
                                FontWeight = textBlock.FontWeight,
                                FontFamily = textBlock.FontFamily,
                                Foreground = textBlock.Foreground,
                                Background = textBlock.Background,
                                TextWrapping = textBlock.TextWrapping,
                                Width = textBlock.Width,
                                Height = textBlock.Height
                            };
                            Canvas.SetLeft(clonedText, Canvas.GetLeft(textBlock));
                            Canvas.SetTop(clonedText, Canvas.GetTop(textBlock));
                            newCanvas.Children.Add(clonedText);
                        }
                        else if (child is Border border)
                        {
                            var clonedBorder = new Border
                            {
                                Width = border.Width,
                                Height = border.Height,
                                Background = border.Background,
                                BorderBrush = border.BorderBrush,
                                BorderThickness = border.BorderThickness,
                                CornerRadius = border.CornerRadius,
                                Child = border.Child // Note: This is shallow copy
                            };
                            Canvas.SetLeft(clonedBorder, Canvas.GetLeft(border));
                            Canvas.SetTop(clonedBorder, Canvas.GetTop(border));
                            newCanvas.Children.Add(clonedBorder);
                        }
                    }

                    clonedObject = newCanvas;

                    // Enable dragging for cloned 3D shape
                    Enable3DShapeDragging(newCanvas);
                }
                else if (sourceObject is Shape shape)
                {
                    // Clone basic shapes
                    clonedObject = CloneShape(shape);
                }
                else if (sourceObject is TextBlock textBlock)
                {
                    // Clone text
                    clonedObject = new TextBlock
                    {
                        Text = textBlock.Text,
                        FontSize = textBlock.FontSize,
                        FontWeight = textBlock.FontWeight,
                        FontFamily = textBlock.FontFamily,
                        Foreground = textBlock.Foreground
                    };
                }

                // Add cloned object to canvas
                if (clonedObject != null)
                {
                    double currentLeft = Canvas.GetLeft(sourceObject);
                    double currentTop = Canvas.GetTop(sourceObject);

                    Canvas.SetLeft(clonedObject, currentLeft + offsetX);
                    Canvas.SetTop(clonedObject, currentTop + offsetY);
                    Canvas.SetZIndex(clonedObject, Canvas.GetZIndex(sourceObject));

                    mainCanvas.Children.Add(clonedObject);

                    // Add to undo stack
                    RecordAddAction(clonedObject, "Clone object");

                    // Hide action buttons and show for new object
                    HideActionButtons();
                    ShowActionButtons(clonedObject);
                }
            }
            catch (Exception ex)
            {
                // Silent fail - no need to show error to user
                System.Diagnostics.Debug.WriteLine($"Copy error: {ex.Message}");
            }
        }

        /// <summary>
        /// Helper method to clone Shape objects
        /// </summary>
        private Shape? CloneShape(Shape source)
        {
            Shape? cloned = null;

            if (source is Line line)
            {
                cloned = new Line
                {
                    X1 = line.X1,
                    Y1 = line.Y1,
                    X2 = line.X2,
                    Y2 = line.Y2,
                    Stroke = line.Stroke,
                    StrokeThickness = line.StrokeThickness,
                    StrokeDashArray = line.StrokeDashArray
                };
            }
            else if (source is Ellipse ellipse)
            {
                cloned = new Ellipse
                {
                    Width = ellipse.Width,
                    Height = ellipse.Height,
                    Fill = ellipse.Fill,
                    Stroke = ellipse.Stroke,
                    StrokeThickness = ellipse.StrokeThickness
                };
            }
            else if (source is Rectangle rectangle)
            {
                cloned = new Rectangle
                {
                    Width = rectangle.Width,
                    Height = rectangle.Height,
                    Fill = rectangle.Fill,
                    Stroke = rectangle.Stroke,
                    StrokeThickness = rectangle.StrokeThickness,
                    RadiusX = rectangle.RadiusX,
                    RadiusY = rectangle.RadiusY
                };
            }
            else if (source is Polygon polygon)
            {
                cloned = new Polygon
                {
                    Points = polygon.Points.Clone(),
                    Fill = polygon.Fill,
                    Stroke = polygon.Stroke,
                    StrokeThickness = polygon.StrokeThickness
                };
            }
            else if (source is Polyline polyline)
            {
                cloned = new Polyline
                {
                    Points = polyline.Points.Clone(),
                    Stroke = polyline.Stroke,
                    StrokeThickness = polyline.StrokeThickness
                };
            }
            else if (source is Path path)
            {
                cloned = new Path
                {
                    Data = path.Data.Clone(),
                    Fill = path.Fill,
                    Stroke = path.Stroke,
                    StrokeThickness = path.StrokeThickness
                };
            }

            if (cloned != null)
            {
                Canvas.SetLeft(cloned, Canvas.GetLeft(source));
                Canvas.SetTop(cloned, Canvas.GetTop(source));
            }

            return cloned;
        }

        /// <summary>
        /// Deletes the selected object from canvas
        /// </summary>
        private void DeleteObject(UIElement targetObject)
        {
            var mainCanvas = this.FindName("MainInteractiveBoard") as Canvas;
            if (mainCanvas == null) return;

            // Remove object from canvas immediately (no confirmation)
            if (mainCanvas.Children.Contains(targetObject))
            {
                mainCanvas.Children.Remove(targetObject);
                
                // Add to undo stack (for potential undo functionality)
                RecordAddAction(targetObject, "Delete object");
                
                // Hide action buttons
                HideActionButtons();
            }
        }

        #endregion
        
        #region Phase 2 Shape Drawing Helper Methods
        
        /// <summary>
        /// Draws an arrow pointing in specified direction
        /// </summary>
        private void DrawArrow(Polygon polygon, double left, double top, double width, double height, string direction)
        {
            polygon.Points.Clear();
            double midX = left + width / 2;
            double midY = top + height / 2;
            double shaftWidth = height * 0.3;
            double arrowWidth = height * 0.7;
            
            if (direction == "RightArrow")
            {
                // Right-pointing arrow: shaft (left) + triangle (right)
                polygon.Points.Add(new Point(left, midY - shaftWidth / 2));
                polygon.Points.Add(new Point(left + width * 0.6, midY - shaftWidth / 2));
                polygon.Points.Add(new Point(left + width * 0.6, top));
                polygon.Points.Add(new Point(left + width, midY));
                polygon.Points.Add(new Point(left + width * 0.6, top + height));
                polygon.Points.Add(new Point(left + width * 0.6, midY + shaftWidth / 2));
                polygon.Points.Add(new Point(left, midY + shaftWidth / 2));
            }
            else if (direction == "LeftArrow")
            {
                polygon.Points.Add(new Point(left + width, midY - shaftWidth / 2));
                polygon.Points.Add(new Point(left + width * 0.4, midY - shaftWidth / 2));
                polygon.Points.Add(new Point(left + width * 0.4, top));
                polygon.Points.Add(new Point(left, midY));
                polygon.Points.Add(new Point(left + width * 0.4, top + height));
                polygon.Points.Add(new Point(left + width * 0.4, midY + shaftWidth / 2));
                polygon.Points.Add(new Point(left + width, midY + shaftWidth / 2));
            }
            else if (direction == "UpArrow")
            {
                polygon.Points.Add(new Point(midX - shaftWidth / 2, top + height));
                polygon.Points.Add(new Point(midX - shaftWidth / 2, top + height * 0.4));
                polygon.Points.Add(new Point(left, top + height * 0.4));
                polygon.Points.Add(new Point(midX, top));
                polygon.Points.Add(new Point(left + width, top + height * 0.4));
                polygon.Points.Add(new Point(midX + shaftWidth / 2, top + height * 0.4));
                polygon.Points.Add(new Point(midX + shaftWidth / 2, top + height));
            }
            else if (direction == "DownArrow")
            {
                polygon.Points.Add(new Point(midX - shaftWidth / 2, top));
                polygon.Points.Add(new Point(midX - shaftWidth / 2, top + height * 0.6));
                polygon.Points.Add(new Point(left, top + height * 0.6));
                polygon.Points.Add(new Point(midX, top + height));
                polygon.Points.Add(new Point(left + width, top + height * 0.6));
                polygon.Points.Add(new Point(midX + shaftWidth / 2, top + height * 0.6));
                polygon.Points.Add(new Point(midX + shaftWidth / 2, top));
            }
        }
        
        private void DrawDoubleArrow(Polygon polygon, double left, double top, double width, double height, string direction)
        {
            polygon.Points.Clear();
            double midX = left + width / 2;
            double midY = top + height / 2;
            double shaftWidth = height * 0.3;
            
            if (direction == "LeftRightArrow")
            {
                // Left arrow head
                polygon.Points.Add(new Point(left, midY));
                polygon.Points.Add(new Point(left + width * 0.2, top));
                polygon.Points.Add(new Point(left + width * 0.2, midY - shaftWidth / 2));
                // Shaft
                polygon.Points.Add(new Point(left + width * 0.8, midY - shaftWidth / 2));
                // Right arrow head
                polygon.Points.Add(new Point(left + width * 0.8, top));
                polygon.Points.Add(new Point(left + width, midY));
                polygon.Points.Add(new Point(left + width * 0.8, top + height));
                polygon.Points.Add(new Point(left + width * 0.8, midY + shaftWidth / 2));
                // Shaft back
                polygon.Points.Add(new Point(left + width * 0.2, midY + shaftWidth / 2));
                polygon.Points.Add(new Point(left + width * 0.2, top + height));
            }
            else if (direction == "UpDownArrow")
            {
                // Up arrow head
                polygon.Points.Add(new Point(midX, top));
                polygon.Points.Add(new Point(left + width, top + height * 0.2));
                polygon.Points.Add(new Point(midX + shaftWidth / 2, top + height * 0.2));
                // Shaft
                polygon.Points.Add(new Point(midX + shaftWidth / 2, top + height * 0.8));
                // Down arrow head
                polygon.Points.Add(new Point(left + width, top + height * 0.8));
                polygon.Points.Add(new Point(midX, top + height));
                polygon.Points.Add(new Point(left, top + height * 0.8));
                polygon.Points.Add(new Point(midX - shaftWidth / 2, top + height * 0.8));
                // Shaft back
                polygon.Points.Add(new Point(midX - shaftWidth / 2, top + height * 0.2));
                polygon.Points.Add(new Point(left, top + height * 0.2));
            }
        }
        
        private void DrawQuadArrow(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double midX = left + width / 2;
            double midY = top + height / 2;
            double inset = Math.Min(width, height) * 0.35;
            double shaftWidth = Math.Min(width, height) * 0.15;
            
            // 4-way cross arrow - 12 points creating + shape with arrow heads
            
            // Top arrow head
            polygon.Points.Add(new Point(midX, top));
            polygon.Points.Add(new Point(midX + inset, top + inset));
            polygon.Points.Add(new Point(midX + shaftWidth / 2, top + inset));
            
            // Right arrow head
            polygon.Points.Add(new Point(midX + shaftWidth / 2, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(left + width - inset, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(left + width, midY));
            polygon.Points.Add(new Point(left + width - inset, midY + shaftWidth / 2));
            polygon.Points.Add(new Point(midX + shaftWidth / 2, midY + shaftWidth / 2));
            
            // Bottom arrow head
            polygon.Points.Add(new Point(midX + shaftWidth / 2, top + height - inset));
            polygon.Points.Add(new Point(midX + inset, top + height - inset));
            polygon.Points.Add(new Point(midX, top + height));
            polygon.Points.Add(new Point(midX - inset, top + height - inset));
            polygon.Points.Add(new Point(midX - shaftWidth / 2, top + height - inset));
            
            // Left arrow head
            polygon.Points.Add(new Point(midX - shaftWidth / 2, midY + shaftWidth / 2));
            polygon.Points.Add(new Point(left + inset, midY + shaftWidth / 2));
            polygon.Points.Add(new Point(left, midY));
            polygon.Points.Add(new Point(left + inset, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(midX - shaftWidth / 2, midY - shaftWidth / 2));
            
            // Back to top
            polygon.Points.Add(new Point(midX - shaftWidth / 2, top + inset));
            polygon.Points.Add(new Point(midX - inset, top + inset));
        }
        
        private void DrawNotchedRightArrow(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double midY = top + height / 2;
            double shaftWidth = height * 0.3;
            double notchDepth = width * 0.1;
            
            // Right arrow with notch (7 points)
            polygon.Points.Add(new Point(left, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(left + width * 0.6, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(left + width * 0.6, top));
            polygon.Points.Add(new Point(left + width, midY));
            polygon.Points.Add(new Point(left + width * 0.6, top + height));
            polygon.Points.Add(new Point(left + width * 0.6, midY + shaftWidth / 2));
            polygon.Points.Add(new Point(left, midY + shaftWidth / 2));
            polygon.Points.Add(new Point(left + notchDepth, midY)); // Notch point
        }
        
        private void DrawPentagonArrow(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double midY = top + height / 2;
            
            // Pentagon arrow (5 points)
            polygon.Points.Add(new Point(left, top));
            polygon.Points.Add(new Point(left + width * 0.7, top));
            polygon.Points.Add(new Point(left + width, midY));
            polygon.Points.Add(new Point(left + width * 0.7, top + height));
            polygon.Points.Add(new Point(left, top + height));
        }
        
        private void DrawChevronArrow(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double midY = top + height / 2;
            double inset = width * 0.2;
            
            // Chevron (V-shaped arrow, 6 points)
            polygon.Points.Add(new Point(left, top));
            polygon.Points.Add(new Point(left + width * 0.7, top));
            polygon.Points.Add(new Point(left + width, midY));
            polygon.Points.Add(new Point(left + width * 0.7, top + height));
            polygon.Points.Add(new Point(left, top + height));
            polygon.Points.Add(new Point(left + inset, midY)); // Inner V point
        }
        
        private void DrawStripedRightArrow(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double midY = top + height / 2;
            double shaftWidth = height * 0.3;
            double stripeWidth = width * 0.05;
            
            // Right arrow with stripe gap (10 points)
            polygon.Points.Add(new Point(left, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(left + width * 0.25, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(left + width * 0.25, midY - shaftWidth / 2 - height * 0.05)); // Gap up
            polygon.Points.Add(new Point(left + width * 0.3, midY - shaftWidth / 2 - height * 0.05));
            polygon.Points.Add(new Point(left + width * 0.3, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(left + width * 0.6, midY - shaftWidth / 2));
            polygon.Points.Add(new Point(left + width * 0.6, top));
            polygon.Points.Add(new Point(left + width, midY));
            polygon.Points.Add(new Point(left + width * 0.6, top + height));
            polygon.Points.Add(new Point(left + width * 0.6, midY + shaftWidth / 2));
            polygon.Points.Add(new Point(left + width * 0.3, midY + shaftWidth / 2));
            polygon.Points.Add(new Point(left + width * 0.3, midY + shaftWidth / 2 + height * 0.05)); // Gap down
            polygon.Points.Add(new Point(left + width * 0.25, midY + shaftWidth / 2 + height * 0.05));
            polygon.Points.Add(new Point(left + width * 0.25, midY + shaftWidth / 2));
            polygon.Points.Add(new Point(left, midY + shaftWidth / 2));
        }
        
        private void DrawCurvedArrow(Polygon polygon, double left, double top, double width, double height, string direction)
        {
            polygon.Points.Clear();
            int curvePoints = 30;
            
            if (direction == "CurvedRightArrow")
            {
                // Curved right arrow using Bezier-like curve
                for (int i = 0; i <= curvePoints; i++)
                {
                    double t = i / (double)curvePoints;
                    double x = left + width * 0.7 * t;
                    double y = top + height * 0.2 + height * 0.3 * Math.Sin(t * Math.PI);
                    polygon.Points.Add(new Point(x, y));
                }
                // Arrow head
                polygon.Points.Add(new Point(left + width * 0.7, top + height * 0.2));
                polygon.Points.Add(new Point(left + width, top + height * 0.5));
                polygon.Points.Add(new Point(left + width * 0.7, top + height * 0.8));
                
                // Return curve (bottom)
                for (int i = curvePoints; i >= 0; i--)
                {
                    double t = i / (double)curvePoints;
                    double x = left + width * 0.7 * t;
                    double y = top + height * 0.8 + height * 0.1 * Math.Sin(t * Math.PI);
                    polygon.Points.Add(new Point(x, y));
                }
            }
            else if (direction == "CurvedLeftArrow")
            {
                // Mirror of right
                for (int i = 0; i <= curvePoints; i++)
                {
                    double t = i / (double)curvePoints;
                    double x = left + width - width * 0.7 * t;
                    double y = top + height * 0.2 + height * 0.3 * Math.Sin(t * Math.PI);
                    polygon.Points.Add(new Point(x, y));
                }
                polygon.Points.Add(new Point(left + width * 0.3, top + height * 0.2));
                polygon.Points.Add(new Point(left, top + height * 0.5));
                polygon.Points.Add(new Point(left + width * 0.3, top + height * 0.8));
                
                for (int i = curvePoints; i >= 0; i--)
                {
                    double t = i / (double)curvePoints;
                    double x = left + width - width * 0.7 * t;
                    double y = top + height * 0.8 + height * 0.1 * Math.Sin(t * Math.PI);
                    polygon.Points.Add(new Point(x, y));
                }
            }
            else if (direction == "CurvedUpArrow")
            {
                // Vertical curved arrow (up)
                for (int i = 0; i <= curvePoints; i++)
                {
                    double t = i / (double)curvePoints;
                    double y = top + height - height * 0.7 * t;
                    double x = left + width * 0.2 + width * 0.3 * Math.Sin(t * Math.PI);
                    polygon.Points.Add(new Point(x, y));
                }
                polygon.Points.Add(new Point(left + width * 0.2, top + height * 0.3));
                polygon.Points.Add(new Point(left + width * 0.5, top));
                polygon.Points.Add(new Point(left + width * 0.8, top + height * 0.3));
                
                for (int i = curvePoints; i >= 0; i--)
                {
                    double t = i / (double)curvePoints;
                    double y = top + height - height * 0.7 * t;
                    double x = left + width * 0.8 + width * 0.1 * Math.Sin(t * Math.PI);
                    polygon.Points.Add(new Point(x, y));
                }
            }
            else // CurvedDownArrow
            {
                for (int i = 0; i <= curvePoints; i++)
                {
                    double t = i / (double)curvePoints;
                    double y = top + height * 0.7 * t;
                    double x = left + width * 0.2 + width * 0.3 * Math.Sin(t * Math.PI);
                    polygon.Points.Add(new Point(x, y));
                }
                polygon.Points.Add(new Point(left + width * 0.2, top + height * 0.7));
                polygon.Points.Add(new Point(left + width * 0.5, top + height));
                polygon.Points.Add(new Point(left + width * 0.8, top + height * 0.7));
                
                for (int i = curvePoints; i >= 0; i--)
                {
                    double t = i / (double)curvePoints;
                    double y = top + height * 0.7 * t;
                    double x = left + width * 0.8 + width * 0.1 * Math.Sin(t * Math.PI);
                    polygon.Points.Add(new Point(x, y));
                }
            }
        }
        
        private void DrawStar(Polygon polygon, double left, double top, double width, double height, int points)
        {
            polygon.Points.Clear();
            double centerX = left + width / 2;
            double centerY = top + height / 2;
            double outerRadius = Math.Min(width, height) / 2;
            double innerRadius = outerRadius * 0.4;
            
            for (int i = 0; i < points * 2; i++)
            {
                double angle = (i * 180.0 / points - 90) * Math.PI / 180;
                double radius = (i % 2 == 0) ? outerRadius : innerRadius;
                polygon.Points.Add(new Point(
                    centerX + radius * Math.Cos(angle),
                    centerY + radius * Math.Sin(angle)
                ));
            }
        }
        
        private void DrawWave(Polygon polygon, double left, double top, double width, double height, int waves)
        {
            polygon.Points.Clear();
            int points = 50;
            double amplitude = height / (waves * 2);
            
            for (int i = 0; i <= points; i++)
            {
                double x = left + (width * i / points);
                double t = (i * waves * 2 * Math.PI) / points;
                double y = top + height / 2 + amplitude * Math.Sin(t);
                polygon.Points.Add(new Point(x, y));
            }
        }
        
        private void DrawRibbon(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double curve = width * 0.1;
            // Simple rectangle with slight curves
            polygon.Points.Add(new Point(left + curve, top));
            polygon.Points.Add(new Point(left + width - curve, top));
            polygon.Points.Add(new Point(left + width, top + height / 2));
            polygon.Points.Add(new Point(left + width - curve, top + height));
            polygon.Points.Add(new Point(left + curve, top + height));
            polygon.Points.Add(new Point(left, top + height / 2));
        }
        
        private void DrawFlowchartShape(Polygon polygon, double left, double top, double width, double height, string shapeName)
        {
            polygon.Points.Clear();
            double midX = left + width / 2;
            double midY = top + height / 2;
            
            switch (shapeName)
            {
                case "FlowProcess":
                    // Rectangle
                    polygon.Points.Add(new Point(left, top));
                    polygon.Points.Add(new Point(left + width, top));
                    polygon.Points.Add(new Point(left + width, top + height));
                    polygon.Points.Add(new Point(left, top + height));
                    break;
                    
                case "FlowDecision":
                    // Diamond
                    polygon.Points.Add(new Point(midX, top));
                    polygon.Points.Add(new Point(left + width, midY));
                    polygon.Points.Add(new Point(midX, top + height));
                    polygon.Points.Add(new Point(left, midY));
                    break;
                    
                case "FlowDocument":
                    // Rectangle with wavy bottom
                    polygon.Points.Add(new Point(left, top));
                    polygon.Points.Add(new Point(left + width, top));
                    polygon.Points.Add(new Point(left + width, top + height * 0.8));
                    polygon.Points.Add(new Point(midX, top + height));
                    polygon.Points.Add(new Point(left, top + height * 0.8));
                    break;
                    
                default:
                    // Default to rectangle for all other flowchart shapes
                    polygon.Points.Add(new Point(left, top));
                    polygon.Points.Add(new Point(left + width, top));
                    polygon.Points.Add(new Point(left + width, top + height));
                    polygon.Points.Add(new Point(left, top + height));
                    break;
            }
        }
        
        private void DrawCallout(Polygon polygon, double left, double top, double width, double height, string shapeName)
        {
            polygon.Points.Clear();
            
            switch (shapeName)
            {
                case "RectangularCallout":
                    // Simple rectangle with bottom pointer
                    polygon.Points.Add(new Point(left, top));
                    polygon.Points.Add(new Point(left + width, top));
                    polygon.Points.Add(new Point(left + width, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.6, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.5, top + height));  // Pointer tip
                    polygon.Points.Add(new Point(left + width * 0.4, top + height * 0.7));
                    polygon.Points.Add(new Point(left, top + height * 0.7));
                    break;
                
                case "RoundedRectangularCallout":
                    // Rounded corners approximation + pointer
                    polygon.Points.Add(new Point(left + width * 0.1, top));
                    polygon.Points.Add(new Point(left + width * 0.9, top));
                    polygon.Points.Add(new Point(left + width, top + height * 0.1));
                    polygon.Points.Add(new Point(left + width, top + height * 0.6));
                    polygon.Points.Add(new Point(left + width * 0.9, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.55, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.5, top + height));  // Pointer
                    polygon.Points.Add(new Point(left + width * 0.45, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.1, top + height * 0.7));
                    polygon.Points.Add(new Point(left, top + height * 0.6));
                    polygon.Points.Add(new Point(left, top + height * 0.1));
                    break;
                
                case "OvalCallout":
                    // Simplified oval (octagon) with pointer
                    polygon.Points.Add(new Point(left + width * 0.3, top));
                    polygon.Points.Add(new Point(left + width * 0.7, top));
                    polygon.Points.Add(new Point(left + width, top + height * 0.2));
                    polygon.Points.Add(new Point(left + width, top + height * 0.5));
                    polygon.Points.Add(new Point(left + width * 0.7, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.55, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.5, top + height));  // Pointer
                    polygon.Points.Add(new Point(left + width * 0.45, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.3, top + height * 0.7));
                    polygon.Points.Add(new Point(left, top + height * 0.5));
                    polygon.Points.Add(new Point(left, top + height * 0.2));
                    break;
                
                case "CloudCallout":
                    // Simplified cloud (wavy edges) with pointer
                    polygon.Points.Add(new Point(left + width * 0.2, top));
                    polygon.Points.Add(new Point(left + width * 0.4, top + height * 0.05));
                    polygon.Points.Add(new Point(left + width * 0.6, top));
                    polygon.Points.Add(new Point(left + width * 0.8, top + height * 0.05));
                    polygon.Points.Add(new Point(left + width, top + height * 0.2));
                    polygon.Points.Add(new Point(left + width * 0.95, top + height * 0.4));
                    polygon.Points.Add(new Point(left + width, top + height * 0.6));
                    polygon.Points.Add(new Point(left + width * 0.8, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.55, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.5, top + height));  // Pointer
                    polygon.Points.Add(new Point(left + width * 0.45, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.2, top + height * 0.7));
                    polygon.Points.Add(new Point(left, top + height * 0.6));
                    polygon.Points.Add(new Point(left + width * 0.05, top + height * 0.4));
                    polygon.Points.Add(new Point(left, top + height * 0.2));
                    break;
                
                case "LineCallout1":
                case "BorderCallout1":
                case "AccentCallout1":
                    // Rectangle with straight line pointer extending down-right
                    polygon.Points.Add(new Point(left, top));
                    polygon.Points.Add(new Point(left + width * 0.7, top));
                    polygon.Points.Add(new Point(left + width * 0.7, top + height * 0.6));
                    polygon.Points.Add(new Point(left, top + height * 0.6));
                    break;
                
                case "LineCallout2":
                case "BorderCallout2":
                case "AccentCallout2":
                    // Rectangle with angled pointer to right
                    polygon.Points.Add(new Point(left, top));
                    polygon.Points.Add(new Point(left + width * 0.65, top));
                    polygon.Points.Add(new Point(left + width * 0.65, top + height * 0.6));
                    polygon.Points.Add(new Point(left, top + height * 0.6));
                    break;
                
                case "LineCallout3":
                case "BorderCallout3":
                case "AccentCallout3":
                    // Rectangle with longer pointer
                    polygon.Points.Add(new Point(left, top));
                    polygon.Points.Add(new Point(left + width * 0.6, top));
                    polygon.Points.Add(new Point(left + width * 0.6, top + height * 0.5));
                    polygon.Points.Add(new Point(left, top + height * 0.5));
                    break;
                
                case "LineCallout4":
                    // Rectangle with bordered edge
                    polygon.Points.Add(new Point(left + width * 0.05, top + height * 0.05));
                    polygon.Points.Add(new Point(left + width * 0.65, top + height * 0.05));
                    polygon.Points.Add(new Point(left + width * 0.65, top + height * 0.55));
                    polygon.Points.Add(new Point(left + width * 0.05, top + height * 0.55));
                    break;
                
                default:
                    // Fallback: simple rectangle callout
                    polygon.Points.Add(new Point(left, top));
                    polygon.Points.Add(new Point(left + width, top));
                    polygon.Points.Add(new Point(left + width, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.6, top + height * 0.7));
                    polygon.Points.Add(new Point(left + width * 0.5, top + height));
                    polygon.Points.Add(new Point(left + width * 0.4, top + height * 0.7));
                    polygon.Points.Add(new Point(left, top + height * 0.7));
                    break;
            }
        }
        
        private void DrawCross(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double armWidth = width / 3;
            double armHeight = height / 3;
            double midX = left + width / 2;
            double midY = top + height / 2;
            
            // Top arm
            polygon.Points.Add(new Point(midX - armWidth / 2, top));
            polygon.Points.Add(new Point(midX + armWidth / 2, top));
            polygon.Points.Add(new Point(midX + armWidth / 2, midY - armHeight / 2));
            // Right arm
            polygon.Points.Add(new Point(left + width, midY - armHeight / 2));
            polygon.Points.Add(new Point(left + width, midY + armHeight / 2));
            polygon.Points.Add(new Point(midX + armWidth / 2, midY + armHeight / 2));
            // Bottom arm
            polygon.Points.Add(new Point(midX + armWidth / 2, top + height));
            polygon.Points.Add(new Point(midX - armWidth / 2, top + height));
            polygon.Points.Add(new Point(midX - armWidth / 2, midY + armHeight / 2));
            // Left arm
            polygon.Points.Add(new Point(left, midY + armHeight / 2));
            polygon.Points.Add(new Point(left, midY - armHeight / 2));
            polygon.Points.Add(new Point(midX - armWidth / 2, midY - armHeight / 2));
        }
        
        private void DrawHorizontalLines(Polygon polygon, double left, double top, double width, double height, string shapeName)
        {
            polygon.Points.Clear();
            double midY = top + height / 2;
            double lineThickness = height * 0.08;
            
            if (shapeName == "Approximately")
            {
                // â‰ˆ symbol - Just top wavy line (simplified)
                int points = 30;
                double waveHeight = height * 0.08;
                double gap = height * 0.15;
                
                // Top wavy line
                for (int i = 0; i <= points; i++)
                {
                    double t = (double)i / points;
                    double x = left + width * t;
                    double y = midY - gap + waveHeight * Math.Sin(t * Math.PI * 4);
                    polygon.Points.Add(new Point(x, y));
                }
                // Return path (thickness)
                for (int i = points; i >= 0; i--)
                {
                    double t = (double)i / points;
                    double x = left + width * t;
                    double y = midY - gap + waveHeight * Math.Sin(t * Math.PI * 4) + lineThickness;
                    polygon.Points.Add(new Point(x, y));
                }
            }
            else if (shapeName == "Equal")
            {
                // = symbol - Just top line (simplified)
                double gap = height * 0.15;
                
                // Top line only
                polygon.Points.Add(new Point(left, midY - gap - lineThickness / 2));
                polygon.Points.Add(new Point(left + width, midY - gap - lineThickness / 2));
                polygon.Points.Add(new Point(left + width, midY - gap + lineThickness / 2));
                polygon.Points.Add(new Point(left, midY - gap + lineThickness / 2));
            }
            else // Minus
            {
                // − symbol - Simple rectangle
                polygon.Points.Add(new Point(left, midY - lineThickness / 2));
                polygon.Points.Add(new Point(left + width, midY - lineThickness / 2));
                polygon.Points.Add(new Point(left + width, midY + lineThickness / 2));
                polygon.Points.Add(new Point(left, midY + lineThickness / 2));
            }
        }
        
        private void DrawDivide(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double midX = left + width / 2;
            double midY = top + height / 2;
            double lineThickness = height * 0.05;
            
            // Ã· symbol: Just horizontal line (simplified)
            polygon.Points.Add(new Point(left, midY - lineThickness / 2));
            polygon.Points.Add(new Point(left + width, midY - lineThickness / 2));
            polygon.Points.Add(new Point(left + width, midY + lineThickness / 2));
            polygon.Points.Add(new Point(left, midY + lineThickness / 2));
        }
        
        private void DrawComparison(Polygon polygon, double left, double top, double width, double height, string shapeName)
        {
            polygon.Points.Clear();
            double midY = top + height / 2;
            double lineThickness = Math.Min(width, height) * 0.08;
            
            if (shapeName == "LessThan")
            {
                // < symbol - V shape pointing left (6 points for thickness)
                polygon.Points.Add(new Point(left + width * 0.8, top + height * 0.1));
                polygon.Points.Add(new Point(left + width * 0.2, midY));
                polygon.Points.Add(new Point(left + width * 0.8, top + height * 0.9));
                polygon.Points.Add(new Point(left + width, top + height * 0.9));
                polygon.Points.Add(new Point(left + width * 0.4, midY));
                polygon.Points.Add(new Point(left + width, top + height * 0.1));
            }
            else // GreaterThan
            {
                // > symbol - V shape pointing right (6 points for thickness)
                polygon.Points.Add(new Point(left + width * 0.2, top + height * 0.1));
                polygon.Points.Add(new Point(left + width * 0.8, midY));
                polygon.Points.Add(new Point(left + width * 0.2, top + height * 0.9));
                polygon.Points.Add(new Point(left, top + height * 0.9));
                polygon.Points.Add(new Point(left + width * 0.6, midY));
                polygon.Points.Add(new Point(left, top + height * 0.1));
            }
        }
        
        private void DrawComparisonEqual(Polygon polygon, double left, double top, double width, double height, string shapeName)
        {
            polygon.Points.Clear();
            double midY = top + height * 0.35;
            
            if (shapeName.Contains("Less"))
            {
                // â‰¤ symbol: Just < V-shape (simplified)
                polygon.Points.Add(new Point(left + width * 0.8, top + height * 0.05));
                polygon.Points.Add(new Point(left + width, top + height * 0.05));
                polygon.Points.Add(new Point(left + width * 0.4, midY));
                polygon.Points.Add(new Point(left + width, top + height * 0.55));
                polygon.Points.Add(new Point(left + width * 0.8, top + height * 0.55));
                polygon.Points.Add(new Point(left + width * 0.2, midY));
            }
            else
            {
                // â‰¥ symbol: Just > V-shape (simplified)
                polygon.Points.Add(new Point(left + width * 0.2, top + height * 0.05));
                polygon.Points.Add(new Point(left, top + height * 0.05));
                polygon.Points.Add(new Point(left + width * 0.6, midY));
                polygon.Points.Add(new Point(left, top + height * 0.55));
                polygon.Points.Add(new Point(left + width * 0.2, top + height * 0.55));
                polygon.Points.Add(new Point(left + width * 0.8, midY));
            }
        }
        
        private void DrawNotEqual(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double slashWidth = width * 0.08;
            
            // â‰  symbol: Just the slash (simplified)
            polygon.Points.Add(new Point(left + width * 0.2, top + height));
            polygon.Points.Add(new Point(left + width * 0.2 + slashWidth, top + height));
            polygon.Points.Add(new Point(left + width * 0.8 + slashWidth, top));
            polygon.Points.Add(new Point(left + width * 0.8, top));
        }
        
        private void DrawInfinity(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            // Figure-8 shape
            int points = 50;
            double midX = left + width / 2;
            double midY = top + height / 2;
            
            for (int i = 0; i <= points; i++)
            {
                double t = (i * 2 * Math.PI) / points;
                double x = midX + width * 0.4 * Math.Cos(t) / (1 + Math.Sin(t) * Math.Sin(t));
                double y = midY + height * 0.4 * Math.Sin(t) * Math.Cos(t) / (1 + Math.Sin(t) * Math.Sin(t));
                polygon.Points.Add(new Point(x, y));
            }
        }
        
        private void DrawRadical(Polygon polygon, double left, double top, double width, double height)
        {
            polygon.Points.Clear();
            double lineThickness = Math.Min(width, height) * 0.08;
            
            // √ symbol - Square root with proper thickness (8 points)
            // Left diagonal down
            polygon.Points.Add(new Point(left, top + height * 0.4));
            polygon.Points.Add(new Point(left + width * 0.15, top + height * 0.8));
            
            // Bottom V point  
            polygon.Points.Add(new Point(left + width * 0.25, top + height));
            polygon.Points.Add(new Point(left + width * 0.35, top + height));
            
            // Right diagonal up
            polygon.Points.Add(new Point(left + width * 0.45, top + height * 0.1));
            
            // Top horizontal line
            polygon.Points.Add(new Point(left + width, top + height * 0.1));
            polygon.Points.Add(new Point(left + width, top + height * 0.2));
            
            // Return path
            polygon.Points.Add(new Point(left + width * 0.45, top + height * 0.2));
            polygon.Points.Add(new Point(left + width * 0.3, top + height * 0.9));
            polygon.Points.Add(new Point(left + width * 0.2, top + height * 0.9));
            polygon.Points.Add(new Point(left + width * 0.1, top + height * 0.5));
        }
        
        private void DrawMathSymbol(Polygon polygon, double left, double top, double width, double height, string shapeName)
        {
            polygon.Points.Clear();
            double midX = left + width / 2;
            
            if (shapeName == "Summation")
            {
                // Î£ (Sigma) symbol - proper thickness (10 points)
                double lineThickness = width * 0.12;
                
                // Top horizontal line
                polygon.Points.Add(new Point(left, top));
                polygon.Points.Add(new Point(left + width, top));
                polygon.Points.Add(new Point(left + width, top + lineThickness));
                
                // Right diagonal to middle
                polygon.Points.Add(new Point(left + width * 0.5, top + height * 0.5));
                
                // Right diagonal to bottom
                polygon.Points.Add(new Point(left + width, top + height - lineThickness));
                
                // Bottom horizontal line
                polygon.Points.Add(new Point(left + width, top + height));
                polygon.Points.Add(new Point(left, top + height));
                polygon.Points.Add(new Point(left, top + height - lineThickness));
                
                // Left diagonal from bottom to middle
                polygon.Points.Add(new Point(left + width * 0.35, top + height * 0.5));
                
                // Left diagonal from middle to top
                polygon.Points.Add(new Point(left, top + lineThickness));
            }
            else // Integral (âˆ«)
            {
                // S-curve with proper thickness
                int points = 30;
                double curveWidth = width * 0.3;
                
                // Outer S-curve
                for (int i = 0; i <= points; i++)
                {
                    double t = (double)i / points;
                    // Parametric S-curve: x follows sine, y is linear
                    double x = midX + curveWidth * Math.Sin(t * Math.PI * 2 - Math.PI / 2);
                    double y = top + height * t;
                    polygon.Points.Add(new Point(x, y));
                }
                
                // Inner S-curve (return path) - offset for thickness
                for (int i = points; i >= 0; i--)
                {
                    double t = (double)i / points;
                    double offset = width * 0.12;
                    double x = midX + curveWidth * Math.Sin(t * Math.PI * 2 - Math.PI / 2) - offset;
                    double y = top + height * t;
                    polygon.Points.Add(new Point(x, y));
                }
            }
        }
        
