        #region Path-based Equation Shape Helpers (Multi-Component)
        
        private void UpdatePathEquationShape(System.Windows.Shapes.Path path, Point startPoint, Point currentPoint)
        {
            double left = Math.Min(startPoint.X, currentPoint.X);
            double top = Math.Min(startPoint.Y, currentPoint.Y);
            double width = Math.Abs(currentPoint.X - startPoint.X);
            double height = Math.Abs(currentPoint.Y - startPoint.Y);
            
            GeometryGroup geometryGroup = new GeometryGroup();
            
            if (_currentShape == "Approximately")
            {
                // â‰ˆ symbol - TWO wavy lines
                geometryGroup.Children.Add(CreateWavyLine(left, top + height * 0.35, width, height * 0.08));
                geometryGroup.Children.Add(CreateWavyLine(left, top + height * 0.65, width, height * 0.08));
            }
            else if (_currentShape == "Equal")
            {
                // = symbol - TWO horizontal lines
                double lineThickness = height * 0.08;
                geometryGroup.Children.Add(CreateRectangle(left, top + height * 0.35, width, lineThickness));
                geometryGroup.Children.Add(CreateRectangle(left, top + height * 0.65, width, lineThickness));
            }
            else if (_currentShape == "Minus")
            {
                // − symbol - ONE horizontal line
                double lineThickness = height * 0.08;
                geometryGroup.Children.Add(CreateRectangle(left, top + height * 0.46, width, lineThickness));
            }
            else if (_currentShape == "Multiply")
            {
                // × symbol - TWO diagonal lines with white intersection gap
                double lineThickness = height * 0.12; // Thicker for visibility
                
                // Create path with two crossing lines
                PathGeometry pathGeo = new PathGeometry();
                
                // First diagonal (top-left to bottom-right)
                PathFigure line1 = new PathFigure();
                line1.StartPoint = new Point(left + width * 0.15, top + height * 0.15);
                line1.Segments.Add(new LineSegment(new Point(left + width * 0.85, top + height * 0.85), true));
                pathGeo.Figures.Add(line1);
                
                // Second diagonal (top-right to bottom-left)
                PathFigure line2 = new PathFigure();
                line2.StartPoint = new Point(left + width * 0.85, top + height * 0.15);
                line2.Segments.Add(new LineSegment(new Point(left + width * 0.15, top + height * 0.85), true));
                pathGeo.Figures.Add(line2);
                
                geometryGroup.Children.Add(pathGeo);
            }
            else if (_currentShape == "Divide")
            {
                // Ã· symbol - Line + TWO dots
                double lineThickness = height * 0.05;
                double dotRadius = height * 0.08;
                double midX = left + width * 0.5;
                double midY = top + height * 0.5;
                
                geometryGroup.Children.Add(CreateRectangle(left, midY - lineThickness / 2, width, lineThickness));
                geometryGroup.Children.Add(CreateCircle(midX, midY - height * 0.25, dotRadius));
                geometryGroup.Children.Add(CreateCircle(midX, midY + height * 0.25, dotRadius));
            }
            else if (_currentShape == "NotEqual")
            {
                // â‰  symbol - TWO lines + diagonal slash with white intersections
                double lineThickness = height * 0.12;
                
                // Create path with three lines
                PathGeometry pathGeo = new PathGeometry();
                
                // Top horizontal line
                PathFigure line1 = new PathFigure();
                line1.StartPoint = new Point(left, top + height * 0.35);
                line1.Segments.Add(new LineSegment(new Point(left + width, top + height * 0.35), true));
                pathGeo.Figures.Add(line1);
                
                // Bottom horizontal line
                PathFigure line2 = new PathFigure();
                line2.StartPoint = new Point(left, top + height * 0.65);
                line2.Segments.Add(new LineSegment(new Point(left + width, top + height * 0.65), true));
                pathGeo.Figures.Add(line2);
                
                // Diagonal slash
                PathFigure line3 = new PathFigure();
                line3.StartPoint = new Point(left + width * 0.3, top);
                line3.Segments.Add(new LineSegment(new Point(left + width * 0.7, top + height), true));
                pathGeo.Figures.Add(line3);
                
                geometryGroup.Children.Add(pathGeo);
            }
            else if (_currentShape == "LessOrEqual")
            {
                // â‰¤ symbol - < V-shape + horizontal line below
                double lineThickness = height * 0.08;
                geometryGroup.Children.Add(CreateVShape(left, top + height * 0.25, width, height * 0.4, true)); // pointing left
                geometryGroup.Children.Add(CreateRectangle(left + width * 0.1, top + height * 0.75, width * 0.8, lineThickness));
            }
            else if (_currentShape == "GreaterOrEqual")
            {
                // â‰¥ symbol - > V-shape + horizontal line below
                double lineThickness = height * 0.08;
                geometryGroup.Children.Add(CreateVShape(left, top + height * 0.25, width, height * 0.4, false)); // pointing right
                geometryGroup.Children.Add(CreateRectangle(left + width * 0.1, top + height * 0.75, width * 0.8, lineThickness));
            }
            else if (_currentShape == "LessThan")
            {
                // < symbol - V-shape pointing left
                geometryGroup.Children.Add(CreateVShape(left, top, width, height, true));
            }
            else if (_currentShape == "GreaterThan")
            {
                // > symbol - V-shape pointing right
                geometryGroup.Children.Add(CreateVShape(left, top, width, height, false));
            }
            else if (_currentShape == "Plus")
            {
                // + symbol - Vertical + Horizontal lines with white intersection gap
                double lineThickness = height * 0.12;
                
                // Create path with two crossing lines
                PathGeometry pathGeo = new PathGeometry();
                
                // Vertical line
                PathFigure vLine = new PathFigure();
                vLine.StartPoint = new Point(left + width * 0.5, top);
                vLine.Segments.Add(new LineSegment(new Point(left + width * 0.5, top + height), true));
                pathGeo.Figures.Add(vLine);
                
                // Horizontal line
                PathFigure hLine = new PathFigure();
                hLine.StartPoint = new Point(left, top + height * 0.5);
                hLine.Segments.Add(new LineSegment(new Point(left + width, top + height * 0.5), true));
                pathGeo.Figures.Add(hLine);
                
                geometryGroup.Children.Add(pathGeo);
            }
            else if (_currentShape == "Infinity")
            {
                geometryGroup.Children.Add(CreateInfinitySymbol(left, top, width, height));
            }
            else if (_currentShape == "Radical")
            {
                geometryGroup.Children.Add(CreateRadicalSymbol(left, top, width, height));
            }
            else if (_currentShape == "Summation")
            {
                geometryGroup.Children.Add(CreateSummationSymbol(left, top, width, height));
            }
            else if (_currentShape == "Integral")
            {
                geometryGroup.Children.Add(CreateIntegralSymbol(left, top, width, height));
            }
            
            path.Data = geometryGroup;
            
            // BUGFIX: Store intersection data for white overlay (to be drawn after finalization)
            if (_currentShape == "Plus" || _currentShape == "Multiply" || _currentShape == "NotEqual")
            {
                // Store shape type and bounds for later white intersection drawing
                path.Tag = new
                {
                    ShapeType = _currentShape,
                    Left = left,
                    Top = top,
                    Width = width,
                    Height = height,
                    LineThickness = height * 0.08,
                    NeedsWhiteIntersection = true
                };
            }
        }
        
        // Helper: Create wavy line geometry
        private Geometry CreateWavyLine(double x, double y, double width, double thickness)
        {
            PathGeometry pathGeo = new PathGeometry();
            PathFigure figure = new PathFigure();
            figure.StartPoint = new Point(x, y);
            
            int waves = 4;
            double waveHeight = thickness * 2;
            
            for (int i = 0; i <= 30; i++)
            {
                double t = (double)i / 30;
                double px = x + width * t;
                double py = y + waveHeight * Math.Sin(t * Math.PI * waves);
                figure.Segments.Add(new LineSegment(new Point(px, py), true));
            }
            
            // Return path for thickness
            for (int i = 30; i >= 0; i--)
            {
                double t = (double)i / 30;
                double px = x + width * t;
                double py = y + waveHeight * Math.Sin(t * Math.PI * waves) + thickness;
                figure.Segments.Add(new LineSegment(new Point(px, py), true));
            }
            
            figure.IsClosed = true;
            pathGeo.Figures.Add(figure);
            return pathGeo;
        }
        
        // Helper: Create rectangle geometry
        private Geometry CreateRectangle(double x, double y, double width, double height)
        {
            return new RectangleGeometry(new Rect(x, y, width, height));
        }
        
        // Helper: Create circle geometry
        private Geometry CreateCircle(double centerX, double centerY, double radius)
        {
            return new EllipseGeometry(new Point(centerX, centerY), radius, radius);
        }
        
        // Helper: Create rotated rectangle (for X and slash)
        private Geometry CreateRotatedRectangle(double centerX, double centerY, double length, double thickness, double angleDegrees)
        {
            RectangleGeometry rect = new RectangleGeometry(new Rect(-length / 2, -thickness / 2, length, thickness));
            RotateTransform rotate = new RotateTransform(angleDegrees);
            TranslateTransform translate = new TranslateTransform(centerX, centerY);
            TransformGroup transformGroup = new TransformGroup();
            transformGroup.Children.Add(rotate);
            transformGroup.Children.Add(translate);
            rect.Transform = transformGroup;
            return rect;
        }
        
        // Helper: Create V-shape (< or >)
        private Geometry CreateVShape(double x, double y, double width, double height, bool pointingLeft)
        {
            PathGeometry pathGeo = new PathGeometry();
            PathFigure figure = new PathFigure();
            
            double thickness = Math.Min(width, height) * 0.08;
            double midY = y + height * 0.5;
            
            if (pointingLeft)
            {
                // < shape
                figure.StartPoint = new Point(x + width * 0.8, y + height * 0.1);
                figure.Segments.Add(new LineSegment(new Point(x + width * 0.2, midY), true));
                figure.Segments.Add(new LineSegment(new Point(x + width * 0.8, y + height * 0.9), true));
                figure.Segments.Add(new LineSegment(new Point(x + width, y + height * 0.9), true));
                figure.Segments.Add(new LineSegment(new Point(x + width * 0.4, midY), true));
                figure.Segments.Add(new LineSegment(new Point(x + width, y + height * 0.1), true));
            }
            else
            {
                // > shape
                figure.StartPoint = new Point(x + width * 0.2, y + height * 0.1);
                figure.Segments.Add(new LineSegment(new Point(x + width * 0.8, midY), true));
                figure.Segments.Add(new LineSegment(new Point(x + width * 0.2, y + height * 0.9), true));
                figure.Segments.Add(new LineSegment(new Point(x, y + height * 0.9), true));
                figure.Segments.Add(new LineSegment(new Point(x + width * 0.6, midY), true));
                figure.Segments.Add(new LineSegment(new Point(x, y + height * 0.1), true));
            }
            
            figure.IsClosed = true;
            pathGeo.Figures.Add(figure);
            return pathGeo;
        }
        
        // Helper: Create infinity symbol (âˆž)
        private Geometry CreateInfinitySymbol(double x, double y, double width, double height)
        {
            // Create infinity using two ellipse loops
            GeometryGroup group = new GeometryGroup();
            
            double loopWidth = width * 0.45;
            double loopHeight = height * 0.8;
            
            // Left loop
            EllipseGeometry leftLoop = new EllipseGeometry(
                new Point(x + width * 0.25, y + height * 0.5),
                loopWidth / 2,
                loopHeight / 2
            );
            
            // Right loop
            EllipseGeometry rightLoop = new EllipseGeometry(
                new Point(x + width * 0.75, y + height * 0.5),
                loopWidth / 2,
                loopHeight / 2
            );
            
            group.Children.Add(leftLoop);
            group.Children.Add(rightLoop);
            
            return group;
        }
        
        // Helper: Create radical symbol (√)
        private Geometry CreateRadicalSymbol(double x, double y, double width, double height)
        {
            PathGeometry pathGeo = new PathGeometry();
            PathFigure figure = new PathFigure();
            
            double thickness = height * 0.05;
            
            // √ shape: Short vertical, diagonal down, diagonal up, horizontal bar
            figure.StartPoint = new Point(x + width * 0.1, y + height * 0.5);
            figure.Segments.Add(new LineSegment(new Point(x + width * 0.25, y + height * 0.9), true));
            figure.Segments.Add(new LineSegment(new Point(x + width * 0.4, y + height * 0.1), true));
            figure.Segments.Add(new LineSegment(new Point(x + width, y + height * 0.1), true));
            figure.Segments.Add(new LineSegment(new Point(x + width, y + height * 0.1 + thickness), true));
            figure.Segments.Add(new LineSegment(new Point(x + width * 0.42, y + height * 0.1 + thickness), true));
            figure.Segments.Add(new LineSegment(new Point(x + width * 0.27, y + height * 0.85), true));
            figure.Segments.Add(new LineSegment(new Point(x + width * 0.15, y + height * 0.5), true));
            
            figure.IsClosed = true;
            pathGeo.Figures.Add(figure);
            return pathGeo;
        }
        
        // Helper: Create summation symbol (Î£)
        private Geometry CreateSummationSymbol(double x, double y, double width, double height)
        {
            PathGeometry pathGeo = new PathGeometry();
            PathFigure figure = new PathFigure();
            
            double thickness = height * 0.08;
            
            // Î£ shape
            figure.StartPoint = new Point(x, y);
            figure.Segments.Add(new LineSegment(new Point(x + width, y), true));
            figure.Segments.Add(new LineSegment(new Point(x + width, y + thickness), true));
            figure.Segments.Add(new LineSegment(new Point(x + width * 0.3, y + height * 0.5), true));
            figure.Segments.Add(new LineSegment(new Point(x + width, y + height - thickness), true));
            figure.Segments.Add(new LineSegment(new Point(x + width, y + height), true));
            figure.Segments.Add(new LineSegment(new Point(x, y + height), true));
            figure.Segments.Add(new LineSegment(new Point(x + width * 0.5, y + height * 0.5), true));
            
            figure.IsClosed = true;
            pathGeo.Figures.Add(figure);
            return pathGeo;
        }
        
        // Helper: Create integral symbol (âˆ«)
        private Geometry CreateIntegralSymbol(double x, double y, double width, double height)
        {
            PathGeometry pathGeo = new PathGeometry();
            PathFigure figure = new PathFigure();
            
            double midX = x + width * 0.5;
            
            // âˆ« shape using Bezier curve
            figure.StartPoint = new Point(midX + width * 0.2, y);
            figure.Segments.Add(new BezierSegment(
                new Point(midX - width * 0.1, y + height * 0.2),
                new Point(midX - width * 0.1, y + height * 0.4),
                new Point(midX, y + height * 0.5),
                true));
            figure.Segments.Add(new BezierSegment(
                new Point(midX + width * 0.1, y + height * 0.6),
                new Point(midX + width * 0.1, y + height * 0.8),
                new Point(midX - width * 0.2, y + height),
                true));
            
            // Add thickness by creating return path
            figure.Segments.Add(new LineSegment(new Point(midX - width * 0.15, y + height), true));
            figure.Segments.Add(new BezierSegment(
                new Point(midX + width * 0.15, y + height * 0.8),
                new Point(midX + width * 0.15, y + height * 0.6),
                new Point(midX + width * 0.05, y + height * 0.5),
                true));
            figure.Segments.Add(new BezierSegment(
                new Point(midX - width * 0.05, y + height * 0.4),
                new Point(midX - width * 0.05, y + height * 0.2),
                new Point(midX + width * 0.15, y),
                true));
            
            figure.IsClosed = true;
            pathGeo.Figures.Add(figure);
            return pathGeo;
        }
        
        #endregion

        #region Object Selection Event Handlers

        /// <summary>
        /// Called when selection changes (single object selected/deselected)
        /// </summary>
        private void OnSelectionChanged(object? sender, SelectableObject? selectedObject)
        {
            _selectionManager?.HideAllAdorners();

            if (selectedObject != null)
            {
                System.Diagnostics.Debug.WriteLine($"🎯 OnSelectionChanged: Object selected");
                System.Diagnostics.Debug.WriteLine($"   Type: {selectedObject.Type}");
                System.Diagnostics.Debug.WriteLine($"   Bounds: {selectedObject.Bounds}");
                System.Diagnostics.Debug.WriteLine($"   Position: {selectedObject.Position}");
                System.Diagnostics.Debug.WriteLine($"   Size: {selectedObject.Size}");
                System.Diagnostics.Debug.WriteLine($"   Element: {selectedObject.Element?.GetType().Name ?? "null"}");
                
                // Show selection box
                if (_selectionBox != null)
                {
                    System.Diagnostics.Debug.WriteLine($"   Calling _selectionBox.AttachTo()...");
                    _selectionBox.AttachTo(selectedObject);
                    System.Diagnostics.Debug.WriteLine($"   SelectionBox Visibility: {_selectionBox.Visibility}");
                    System.Diagnostics.Debug.WriteLine($"   SelectionBox Width: {_selectionBox.Width}");
                    System.Diagnostics.Debug.WriteLine($"   SelectionBox Height: {_selectionBox.Height}");
                    System.Diagnostics.Debug.WriteLine($"   SelectionBox Left: {Canvas.GetLeft(_selectionBox)}");
                    System.Diagnostics.Debug.WriteLine($"   SelectionBox Top: {Canvas.GetTop(_selectionBox)}");
                }
                else
                {
                    System.Diagnostics.Debug.WriteLine($"   ❌ _selectionBox is NULL!");
                }
                
                // ✅ G2.1: Auto-Flip toolbar position
                var bounds = selectedObject.Bounds;
                var toolbarPosition = CalculateOptimalToolbarPosition(bounds);
                _contextToolbar?.ShowAt(toolbarPosition, selectedObject);
                
                // Update toolbar UI
                _contextToolbar?.UpdateLockIcon(selectedObject.IsLocked);
                _contextToolbar?.UpdateColorPreview(selectedObject.StrokeColor);
                
                System.Diagnostics.Debug.WriteLine($"✅ Selected: {selectedObject.Id}, Type: {selectedObject.Type}");
            }
            else
            {
                // Hide all selection UI
                _selectionBox?.Detach();
                _contextToolbar?.Hide();
                _thicknessPicker?.Hide();
                _colorPicker?.Hide();
                _moreMenu?.Hide();
                _floatingTouchKeyboard?.HideKeyboard();
                
                System.Diagnostics.Debug.WriteLine("❌ Selection cleared");
            }
        }

        /// <summary>
        /// Called when multiple objects are selected
        /// </summary>
        private void OnMultiSelectionChanged(object? sender, List<SelectableObject> selectedObjects)
        {
            if (selectedObjects == null || selectedObjects.Count == 0)
            {
                _selectionBox?.Detach();
                _contextToolbar?.Hide();
                System.Diagnostics.Debug.WriteLine("📦 Multi-selection: 0 objects - hiding selection box & toolbar");
                return;
            }

            System.Diagnostics.Debug.WriteLine($"📦 Multi-selection: {selectedObjects.Count} objects");

            try
            {
                if (selectedObjects.Count == 1)
                {
                    var singleObj = selectedObjects[0];
                    singleObj.UpdateBounds();

                    // Đảm bảo Bounds và Size chính xác trước khi Attach SelectionBox
                    if (singleObj.Bounds.IsEmpty || singleObj.Size.Width <= 0 || singleObj.Size.Height <= 0)
                    {
                        if (singleObj.Element is FrameworkElement fe)
                        {
                            double left = Canvas.GetLeft(fe);
                            double top = Canvas.GetTop(fe);
                            if (double.IsNaN(left)) left = 0;
                            if (double.IsNaN(top)) top = 0;
                            double w = fe.ActualWidth > 0 ? fe.ActualWidth : (double.IsNaN(fe.Width) ? 30 : fe.Width);
                            double h = fe.ActualHeight > 0 ? fe.ActualHeight : (double.IsNaN(fe.Height) ? 30 : fe.Height);
                            
                            singleObj.Position = new Point(left, top);
                            singleObj.Size = new Size(w, h);
                            singleObj.Bounds = new Rect(left, top, w, h);
                        }
                    }

                    if (_selectionBox != null)
                    {
                        _selectionBox.AttachTo(singleObj);
                    }
                    if (_contextToolbar != null)
                    {
                        var bounds = singleObj.Bounds;
                        var position = CalculateOptimalToolbarPosition(bounds);
                        _contextToolbar.ShowAt(position, singleObj);
                    }
                }
                else
                {
                    // Multi-selection (2 or more objects)
                    double minX = double.MaxValue;
                    double minY = double.MaxValue;
                    double maxX = double.MinValue;
                    double maxY = double.MinValue;

                    foreach (var obj in selectedObjects)
                    {
                        obj.UpdateBounds();
                        var bounds = obj.Bounds;
                        if (!bounds.IsEmpty)
                        {
                            minX = Math.Min(minX, bounds.Left);
                            minY = Math.Min(minY, bounds.Top);
                            maxX = Math.Max(maxX, bounds.Right);
                            maxY = Math.Max(maxY, bounds.Bottom);
                        }
                    }

                    if (minX < double.MaxValue && minY < double.MaxValue)
                    {
                        var groupRect = new Rect(minX, minY, maxX - minX, maxY - minY);
                        
                        // Tạo đối tượng ảo đại diện cho nhóm để hiển thị SelectionBox bao ngoài
                        var groupContainer = new SelectableObject
                        {
                            Position = new Point(groupRect.X, groupRect.Y),
                            Size = new Size(groupRect.Width, groupRect.Height),
                            Bounds = groupRect,
                            Type = ObjectType.Group,
                            IsGroup = true,
                            GroupMembers = selectedObjects.ToList()
                        };

                        if (_selectionBox != null)
                        {
                            _selectionBox.AttachTo(groupContainer);
                        }

                        if (_contextToolbar != null)
                        {
                            var position = CalculateOptimalToolbarPosition(groupRect);
                            _contextToolbar.ShowAt(position, selectedObjects[0]);
                            _contextToolbar.UpdateLockIcon(selectedObjects.All(o => o.IsLocked));
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ Error in OnMultiSelectionChanged: {ex.Message}");
            }
        }

        /// <summary>
        /// Mouse down handler for object selection & rectangle selection
        /// </summary>
        private void MainBoard_SelectionMouseDown(object sender, MouseButtonEventArgs e)
        {
            if (!_objectSelectionMode || _selectionManager == null || _isLassoMode)
                return;

            Point clickPoint = e.GetPosition(MainInteractiveBoard);
            bool isCtrlPressed = Keyboard.Modifiers.HasFlag(ModifierKeys.Control);
            var hitObject = _selectionManager.HitTest(clickPoint);
            
            // 🪄 Magic Wand Mode handling (N27 FIX: Support both Single Click Wand & Drag Rectangle Wand)
            if (_isMagicWandMode)
            {
                _rectangleSelectionStartPoint = clickPoint;
                _isRectangleSelecting = false;
                _draggedSelectionObject = null;
                _pendingHitObject = hitObject;
                _pendingIsCtrl = isCtrlPressed;
                return;
            }
            
            // ✅ QC_4.2_WIDGET_DRAG_FIX: Kiểm tra xem người dùng có bấm vào đối tượng ĐÃ ĐƯỢC CHỌN hay không
            // Ưu tiên cho phép kéo di chuyển đối tượng/bảng/widget (Data Table, 3D Graph...) bất kể chạm vào cell hay nội dung bên trong!
            var currentSelection = _selectionManager.GetSelectedObjects();
            bool isClickOnSelectedObject = hitObject != null && currentSelection != null && currentSelection.Contains(hitObject);

            if (isClickOnSelectedObject && !isCtrlPressed)
            {
                // Nếu bấm vào nút chức năng cụ thể (như nút Edit ✏️, Move 🖐️ hay Delete ❌), nhường event cho nút xử lý
                if (e.OriginalSource is DependencyObject depObj && QASmartTouch.Utilities.InputValidationHelper.IsEventFromButton(depObj, MainInteractiveBoard))
                {
                    _isDraggingSelection = false;
                    _draggedSelectionObject = null;
                    return;
                }

                // ✅ QC_4.2_TABLE_BODY_NO_DRAG: Nếu là Bảng dữ liệu / Container dạng StackPanel, 
                // chạm vào thân bảng sẽ HIỂN THỊ nút thao tác và cho phép viết/vẽ, KHÔNG di chuyển bảng khi quệt thân!
                // Muốn di chuyển thì giáo viên click giữ nút Di chuyển 🖐️ trên thanh thao tác.
                if (hitObject != null && hitObject.Element is StackPanel)
                {
                    _draggedSelectionObject = null;
                    _isDraggingSelection = false;
                    _pendingHitObject = null;
                    return;
                }

                // Với đối tượng vẽ thông thường: Click vào đối tượng ĐÃ CHỌN -> Chuẩn bị kéo di chuyển
                _draggedSelectionObject = hitObject;
                _selectionDragStartPoint = clickPoint;
                _isDraggingSelection = false;
                _pendingHitObject = null;
                System.Diagnostics.Debug.WriteLine($"🔒 Dragging existing selection - anchor: {hitObject.Type}");
                return;
            }

            // Nếu chạm vào thanh công cụ / hệ thống ngoài canvas, không vẽ vùng chọn rectangle
            if (QASmartTouch.Utilities.InputValidationHelper.IsEventFromInteractiveControl(e.OriginalSource, MainInteractiveBoard))
            {
                _isDraggingSelection = false;
                _draggedSelectionObject = null;
                return;
            }

            // Otherwise (clicked empty space OR clicked an unselected object):
            // Prepare for potential Rectangle Selection OR single-click selection
            _rectangleSelectionStartPoint = clickPoint;
            _isRectangleSelecting = false;
            _draggedSelectionObject = null;
            _pendingHitObject = hitObject;
            _pendingIsCtrl = isCtrlPressed;
            
            System.Diagnostics.Debug.WriteLine($"🖱️ Selection click at ({clickPoint.X:F0}, {clickPoint.Y:F0}), hit={hitObject?.Type.ToString() ?? "null"}, Ctrl={isCtrlPressed}");
        }
        
        /// <summary>
        /// ✅ GĐ1-FIX: Helper method di chuyển 1 SelectableObject theo dragVector
        /// Hỗ trợ Polyline, Line, FrameworkElement (Rectangle, Ellipse, Image, TextBlock, Border)
        /// </summary>
        private void MoveSelectableObject(SelectableObject obj, Vector dragVector)
        {
            if (obj?.Element == null) return;
            
            if (obj.Element is Polyline polyline)
            {
                // Di chuyển tất cả points
                for (int i = 0; i < polyline.Points.Count; i++)
                {
                    Point oldPoint = polyline.Points[i];
                    polyline.Points[i] = new Point(oldPoint.X + dragVector.X, oldPoint.Y + dragVector.Y);
                }
                // Recalculate bounds
                if (polyline.Points.Count > 0)
                {
                    double minX = double.MaxValue, minY = double.MaxValue;
                    double maxX = double.MinValue, maxY = double.MinValue;
                    foreach (var p in polyline.Points)
                    {
                        minX = Math.Min(minX, p.X); minY = Math.Min(minY, p.Y);
                        maxX = Math.Max(maxX, p.X); maxY = Math.Max(maxY, p.Y);
                    }
                    obj.Position = new Point(minX, minY);
                    obj.Size = new Size(maxX - minX, maxY - minY);
                }
            }
            else if (obj.Element is System.Windows.Shapes.Line line)
            {
                // Di chuyển Line endpoints
                line.X1 += dragVector.X; line.Y1 += dragVector.Y;
                line.X2 += dragVector.X; line.Y2 += dragVector.Y;
                double minX = Math.Min(line.X1, line.X2);
                double minY = Math.Min(line.Y1, line.Y2);
                double w = Math.Max(Math.Abs(line.X2 - line.X1), line.StrokeThickness);
                double h = Math.Max(Math.Abs(line.Y2 - line.Y1), line.StrokeThickness);

                if (!double.IsNaN(Canvas.GetLeft(line))) Canvas.SetLeft(line, minX);
                if (!double.IsNaN(Canvas.GetTop(line))) Canvas.SetTop(line, minY);

                obj.Position = new Point(minX, minY);
                obj.Size = new Size(w, h);
            }
            else if (obj.Element is System.Windows.Shapes.Path path && path.Data != null)
            {
                // ✅ QC_4.2_TOUCH_MOVE_FIX: Di chuyển TranslateTransform cho Path
                if (path.RenderTransform is TransformGroup tg)
                {
                    var tt = tg.Children.OfType<TranslateTransform>().FirstOrDefault();
                    if (tt == null)
                    {
                        tt = new TranslateTransform();
                        tg.Children.Add(tt);
                    }
                    tt.X += dragVector.X;
                    tt.Y += dragVector.Y;
                }
                else if (path.RenderTransform is TranslateTransform tt)
                {
                    tt.X += dragVector.X;
                    tt.Y += dragVector.Y;
                }
                else
                {
                    var tgNew = new TransformGroup();
                    if (path.RenderTransform != null && path.RenderTransform != Transform.Identity)
                        tgNew.Children.Add(path.RenderTransform);
                    tgNew.Children.Add(new TranslateTransform(dragVector.X, dragVector.Y));
                    path.RenderTransform = tgNew;
                }
                obj.Position = new Point(obj.Position.X + dragVector.X, obj.Position.Y + dragVector.Y);
            }
            else if (obj.Element is FrameworkElement fe)
            {
                // Di chuyển Canvas position (Rectangle, Ellipse, Image, TextBlock, Border)
                double cX = Canvas.GetLeft(fe), cY = Canvas.GetTop(fe);
                if (double.IsNaN(cX)) cX = 0;
                if (double.IsNaN(cY)) cY = 0;
                double newX = cX + dragVector.X, newY = cY + dragVector.Y;
                Canvas.SetLeft(fe, newX);
                Canvas.SetTop(fe, newY);
                obj.Position = new Point(newX, newY);
            }
            obj.UpdateBounds();
        }

        /// <summary>
        /// Handle mouse move for dragging selected objects or drawing rectangle selection
        /// </summary>
        private void MainBoard_SelectionMouseMove(object sender, MouseEventArgs e)
        {
            if (!_objectSelectionMode || _isLassoMode)
                return;

            Point currentPoint = e.GetPosition(MainInteractiveBoard);
            
            // 1. Handle object drag & drop (moving ALREADY SELECTED objects)
            if (_draggedSelectionObject != null && e.LeftButton == MouseButtonState.Pressed)
            {
                Vector dragVector = currentPoint - _selectionDragStartPoint;
                if (!_isDraggingSelection && (Math.Abs(dragVector.X) > 3 || Math.Abs(dragVector.Y) > 3))
                {
                    _isDraggingSelection = true;
                    System.Diagnostics.Debug.WriteLine($"🎯 Started dragging object: {_draggedSelectionObject.Type}");
                }
                
                if (_isDraggingSelection && _draggedSelectionObject.Element != null)
                {
                    var selectedObjects = _selectionManager?.GetSelectedObjects();
                    bool isMultiDrag = selectedObjects != null && selectedObjects.Count > 1;
                    
                    if (isMultiDrag)
                    {
                        foreach (var obj in selectedObjects!)
                        {
                            MoveSelectableObject(obj, dragVector);
                        }
                        System.Diagnostics.Debug.WriteLine(
                            $"🎯 Group moved: {selectedObjects.Count} objects by ({dragVector.X:F0}, {dragVector.Y:F0})");
                    }
                    else
                    {
                        MoveSelectableObject(_draggedSelectionObject, dragVector);
                        System.Diagnostics.Debug.WriteLine(
                            $"🎯 {_draggedSelectionObject.Type} moved by ({dragVector.X:F0}, {dragVector.Y:F0})");
                    }
                    
                    _selectionDragStartPoint = currentPoint;
                    
                    if (isMultiDrag)
                    {
                        _selectionManager?.RefreshGroupAdorner();
                        
                        double gMinX = double.MaxValue, gMinY = double.MaxValue;
                        double gMaxX = double.MinValue, gMaxY = double.MinValue;
                        foreach (var obj in selectedObjects!)
                        {
                            var b = obj.Bounds;
                            gMinX = Math.Min(gMinX, b.Left);  gMinY = Math.Min(gMinY, b.Top);
                            gMaxX = Math.Max(gMaxX, b.Right);  gMaxY = Math.Max(gMaxY, b.Bottom);
                        }
                        var groupRect = new Rect(gMinX, gMinY, gMaxX - gMinX, gMaxY - gMinY);

                        // ✅ QC_4.2_TOUCH_MOVE_FIX: Cập nhật vị trí & kích thước cho groupObject đang được attach với _selectionBox
                        if (_selectionBox != null && _selectionBox.Visibility == Visibility.Visible)
                        {
                            var attachedGroup = _selectionBox.AttachedObject;
                            if (attachedGroup != null && (attachedGroup.IsGroup || attachedGroup.Type == ObjectType.Group))
                            {
                                attachedGroup.Position = new Point(gMinX, gMinY);
                                attachedGroup.Size = new Size(groupRect.Width, groupRect.Height);
                                attachedGroup.Bounds = groupRect;
                            }
                            _selectionBox.UpdatePosition();
                        }

                        var toolbarPos = CalculateOptimalToolbarPosition(groupRect);
                        _contextToolbar?.ShowAt(toolbarPos, _draggedSelectionObject);
                    }
                    else
                    {
                        _selectionBox?.UpdatePosition();
                        if (_draggedSelectionObject.Bounds != Rect.Empty)
                        {
                            var bounds = _draggedSelectionObject.Bounds;
                            var toolbarPosition = CalculateOptimalToolbarPosition(bounds);
                            _contextToolbar?.ShowAt(toolbarPosition, _draggedSelectionObject);
                        }
                    }
                }
                return;
            }

            // ✅ QC_4.2_WIDGET_DRAG_FIX: Chỉ kiểm tra IsEventFromInteractiveControl nếu KHÔNG đang kéo di chuyển đối tượng
            if (QASmartTouch.Utilities.InputValidationHelper.IsEventFromInteractiveControl(e.OriginalSource, MainInteractiveBoard))
            {
                _isDraggingSelection = false;
                _draggedSelectionObject = null;
                if (MainInteractiveBoard.IsMouseCaptured)
                    MainInteractiveBoard.ReleaseMouseCapture();
                return;
            }
            
            // 2. Handle Rectangle Selection Drag (when dragging on canvas)
            if (e.LeftButton == MouseButtonState.Pressed && _draggedSelectionObject == null)
            {
                // ✅ CRITICAL FIX: Đang kéo chốt resize hoặc xoay SelectionBox -> Không tạo khung khoanh vùng chọn rectangle
                if (_selectionBox != null && _selectionBox.IsTransforming)
                {
                    if (_rectangleSelectionPreview != null)
                    {
                        MainInteractiveBoard.Children.Remove(_rectangleSelectionPreview);
                        _rectangleSelectionPreview = null;
                    }
                    _isRectangleSelecting = false;
                    return;
                }

                Vector dragVector = currentPoint - _rectangleSelectionStartPoint;
                if (!_isRectangleSelecting && (Math.Abs(dragVector.X) > 5 || Math.Abs(dragVector.Y) > 5))
                {
                    _isRectangleSelecting = true;
                    
                    // Create preview rectangle if needed
                    if (_rectangleSelectionPreview == null)
                    {
                        _rectangleSelectionPreview = new Rectangle
                        {
                            Stroke = new SolidColorBrush(Color.FromRgb(52, 152, 219)), // Dodger blue
                            StrokeThickness = 2,
                            StrokeDashArray = new DoubleCollection { 5, 3 },
                            Fill = new SolidColorBrush(Color.FromArgb(30, 52, 152, 219)),
                            RadiusX = 3,
                            RadiusY = 3
                        };
                        MainInteractiveBoard.Children.Add(_rectangleSelectionPreview);
                        Canvas.SetZIndex(_rectangleSelectionPreview, 9999);
                    }
                }
                
                if (_isRectangleSelecting && _rectangleSelectionPreview != null)
                {
                    double left = Math.Min(_rectangleSelectionStartPoint.X, currentPoint.X);
                    double top = Math.Min(_rectangleSelectionStartPoint.Y, currentPoint.Y);
                    double width = Math.Abs(currentPoint.X - _rectangleSelectionStartPoint.X);
                    double height = Math.Abs(currentPoint.Y - _rectangleSelectionStartPoint.Y);
                    
                    Canvas.SetLeft(_rectangleSelectionPreview, left);
                    Canvas.SetTop(_rectangleSelectionPreview, top);
                    _rectangleSelectionPreview.Width = width;
                    _rectangleSelectionPreview.Height = height;
                }
            }
        }
        
        /// <summary>
        /// Handle mouse up to complete drag operation or rectangle selection
        /// </summary>
        private void MainBoard_SelectionMouseUp(object sender, MouseButtonEventArgs e)
        {
            if (_isLassoMode)
                return;
            // 1. Handle Rectangle Selection completion
            if (_rectangleSelectionPreview != null || _isRectangleSelecting)
            {
                Point endPoint = e.GetPosition(MainInteractiveBoard);
                
                double left = Math.Min(_rectangleSelectionStartPoint.X, endPoint.X);
                double top = Math.Min(_rectangleSelectionStartPoint.Y, endPoint.Y);
                double right = Math.Max(_rectangleSelectionStartPoint.X, endPoint.X);
                double bottom = Math.Max(_rectangleSelectionStartPoint.Y, endPoint.Y);
                Rect selectionRect = new Rect(left, top, right - left, bottom - top);
                _lastDraggedSelectionRect = selectionRect;
                
                double rectW = right - left;
                double rectH = bottom - top;

                // Remove preview rectangle
                if (_rectangleSelectionPreview != null)
                {
                    MainInteractiveBoard.Children.Remove(_rectangleSelectionPreview);
                    _rectangleSelectionPreview = null;
                }
                _isRectangleSelecting = false;

                if (rectW > 5 || rectH > 5)
                {
                    // Dragged rectangle selection
                    var objectsInRect = _selectionManager?.GetObjectsInRect(selectionRect);
                    if (objectsInRect != null && objectsInRect.Count > 0)
                    {
                        _selectionManager?.SelectMultiple(objectsInRect);
                        System.Diagnostics.Debug.WriteLine($"📐 Rectangle selection: {objectsInRect.Count} object(s) selected");
                    }
                    else
                    {
                        _selectionManager?.DeselectAll();
                        System.Diagnostics.Debug.WriteLine("📐 Rectangle selection: No objects found, deselected all");
                    }
                    _pendingHitObject = null;

                    // Trigger pending smart action if user initiated OCR/Translate/Read/Search/AIChat
                    if (_pendingSmartAction.HasValue)
                    {
                        var pendingAction = _pendingSmartAction.Value;
                        _pendingSmartAction = null;
                        _ = Dispatcher.BeginInvoke(new Action(async () =>
                        {
                            await ExecuteSmartActionAsync(pendingAction);
                        }), System.Windows.Threading.DispatcherPriority.Background);
                    }

                    return;
                }
            }
            
            // 2. Handle Single Click Selection (if user released mouse without dragging a rectangle)
            if (_isDraggingSelection)
            {
                _isDraggingSelection = false;
                _draggedSelectionObject = null;
                // ✅ N23 FIX: Rebuild QuadTree spatial index immediately after dragging objects finish
                _selectionManager?.RebuildQuadTree();
                System.Diagnostics.Debug.WriteLine("🌳 Selection drag ended: Rebuilt QuadTree spatial index.");
            }

            if (_isMagicWandMode && !_isRectangleSelecting)
            {
                Point clickPoint = e.GetPosition(MainInteractiveBoard);
                PerformMagicWandSelection(clickPoint);
                return;
            }

            if (!_isDraggingSelection)
            {
                if (_pendingHitObject != null)
                {
                    if (_pendingIsCtrl)
                    {
                        _selectionManager?.ToggleSelection(_pendingHitObject);
                    }
                    else
                    {
                        _selectionManager?.SelectObject(_pendingHitObject);
                    }
                }
                else
                {
                    if (!_pendingIsCtrl)
                    {
                        _selectionManager?.DeselectAll();
                    }
                }
            }
            
            // Cleanup drag states
            _isDraggingSelection = false;
            _draggedSelectionObject = null;
            _pendingHitObject = null;
        }

