        private void OnToolbarSpotlightClicked(object? sender, EventArgs e)
        {
            try
            {
                System.Diagnostics.Debug.WriteLine("OnToolbarSpotlightClicked called");
                
                // Toggle Spotlight Mode
                if (_currentSpotlightOverlay != null)
                {
                    // Turn off if already on
                    MainInteractiveBoard.Children.Remove(_currentSpotlightOverlay);
                    _currentSpotlightOverlay = null;
                    System.Diagnostics.Debug.WriteLine("Spotlight Mode deactivated");
                    return;
                }

                // Turn on Spotlight Mode for selected object
                var selectedObj = _selectionManager?.SelectedObject;
                if (selectedObj == null)
                {
                    var list = _selectionManager?.GetSelectedObjects();
                    if (list != null && list.Count > 0)
                    {
                        selectedObj = list[0];
                    }
                }

                if (selectedObj == null)
                {
                    MessageBox.Show("Vui lòng chọn một đối tượng để bật chế độ tiêu điểm (Spotlight).", "Thông báo", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                // Get selected object's bounds
                Rect bounds = selectedObj.Bounds;
                
                // Create the geometry for the overlay: whole canvas minus the selected bounds
                var outerGeometry = new System.Windows.Media.RectangleGeometry(new Rect(0, 0, MainInteractiveBoard.ActualWidth, MainInteractiveBoard.ActualHeight));
                var innerGeometry = new System.Windows.Media.RectangleGeometry(bounds, 8, 8);
                var combined = new System.Windows.Media.CombinedGeometry(System.Windows.Media.GeometryCombineMode.Exclude, outerGeometry, innerGeometry);
                
                var path = new System.Windows.Shapes.Path
                {
                    Fill = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(180, 0, 0, 0)), // 70% opacity black
                    Data = combined,
                    IsHitTestVisible = true
                };
                
                path.MouseLeftButtonDown += (s, args) =>
                {
                    MainInteractiveBoard.Children.Remove(path);
                    if (_currentSpotlightOverlay == path)
                    {
                        _currentSpotlightOverlay = null;
                    }
                    args.Handled = true;
                };

                MainInteractiveBoard.Children.Add(path);
                _currentSpotlightOverlay = path;
                
                System.Diagnostics.Debug.WriteLine("Spotlight Mode activated");
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[Spotlight Error] {ex.Message}");
            }
        }

        /// <summary>
        /// ✅ BUG #12 FIX: Dùng kích thước cố định thay vì Measure() trên control Collapsed.
        /// MoreMenu.xaml: d:DesignWidth="280", ScrollViewer MaxHeight=500 + Border Padding 8×2 = 520.
        /// </summary>
        private void OnToolbarMoreClicked(object? sender, EventArgs e)
        {
            if (_contextToolbar != null && _moreMenu != null)
            {
                // ✅ BUG #12 FIX: Kích thước cố định — Measure() trên Collapsed control trả về (0,0)
                const double menuWidth = 280;
                const double menuHeight = 520;

                double boardWidth = MainInteractiveBoard.ActualWidth > 0 ? MainInteractiveBoard.ActualWidth : 1920;
                double boardHeight = MainInteractiveBoard.ActualHeight > 0 ? MainInteractiveBoard.ActualHeight : 1080;

                double toolbarLeft = Canvas.GetLeft(_contextToolbar);
                double toolbarTop = Canvas.GetTop(_contextToolbar);
                if (double.IsNaN(toolbarLeft)) toolbarLeft = 100;
                if (double.IsNaN(toolbarTop)) toolbarTop = 100;

                double toolbarHeight = _contextToolbar.ActualHeight > 0 ? _contextToolbar.ActualHeight : 45;

                // Calculate smart X position aligned with ContextToolbar
                double posX = Math.Max(10, Math.Min(toolbarLeft + 50, boardWidth - menuWidth - 10));

                // Calculate smart Y position (Above or Below toolbar based on screen space)
                double posY;
                if (toolbarTop + toolbarHeight + menuHeight > boardHeight - 20)
                {
                    // Position ABOVE context toolbar if toolbar is in lower screen area
                    posY = Math.Max(10, toolbarTop - menuHeight - 10);
                }
                else
                {
                    // Position BELOW context toolbar
                    posY = toolbarTop + toolbarHeight + 5;
                }

                _moreMenu.ShowAt(new Point(posX, posY));

                // Hide pickers
                _thicknessPicker?.Hide();
                _colorPicker?.Hide();

                System.Diagnostics.Debug.WriteLine($"📋 MoreMenu shown at ({posX:F0}, {posY:F0}), board: {boardWidth:F0}×{boardHeight:F0}");
            }
        }

        // ThicknessPicker handler
        private void OnThicknessChanged(object? sender, double thickness)
        {
            if (_selectionManager == null)
                return;

            // Get all selected objects (support multi-selection)
            var selectedObjects = _selectionManager.GetSelectedObjects();
            
            if (selectedObjects.Count == 0)
                return;

            System.Diagnostics.Debug.WriteLine($"📏 Applying thickness to {selectedObjects.Count} object(s)");

            foreach (var obj in selectedObjects)
            {
                var oldThickness = obj.StrokeThickness;
                
                // Update model
                obj.StrokeThickness = thickness;
                
                // Update actual UIElement
                if (obj.Element is Polyline polyline)
                {
                    polyline.StrokeThickness = thickness;
                    System.Diagnostics.Debug.WriteLine($"   ✓ Polyline thickness changed: {oldThickness:F0}px → {thickness:F0}px");
                }
                else if (obj.Element is System.Windows.Shapes.Shape shape)
                {
                    shape.StrokeThickness = thickness;
                    System.Diagnostics.Debug.WriteLine($"   ✓ Shape thickness changed: {oldThickness:F0}px → {thickness:F0}px");
                }
                else if (obj.Element is Border border)
                {
                    border.BorderThickness = new Thickness(thickness);
                    System.Diagnostics.Debug.WriteLine($"   ✓ Border thickness changed: {oldThickness:F0}px → {thickness:F0}px");
                }
                
                // Record for undo/redo
                RecordModifyAction(obj.Element, oldThickness, thickness, $"Change Thickness {oldThickness:F0}→{thickness:F0}px");
            }
            
            System.Diagnostics.Debug.WriteLine($"✅ Thickness changed for {selectedObjects.Count} object(s): → {thickness:F0}px");
        }

        // ColorPicker handler
        private void OnColorSelected(object? sender, Color color)
        {
            if (_selectionManager == null)
                return;

            // Get all selected objects (support multi-selection)
            var selectedObjects = _selectionManager.GetSelectedObjects();
            
            if (selectedObjects.Count == 0)
                return;

            System.Diagnostics.Debug.WriteLine($"🎨 Applying color to {selectedObjects.Count} object(s)");

            foreach (var obj in selectedObjects)
            {
                var oldColor = obj.StrokeColor;
                
                // Update model
                obj.StrokeColor = color;
                
                // Update actual UIElement color
                if (obj.Element is Polyline polyline)
                {
                    polyline.Stroke = new SolidColorBrush(color);
                    System.Diagnostics.Debug.WriteLine($"   ✓ Polyline color changed: {oldColor} → {color}");
                }
                else if (obj.Element is System.Windows.Shapes.Shape shape)
                {
                    shape.Stroke = new SolidColorBrush(color);
                    System.Diagnostics.Debug.WriteLine($"   ✓ Shape color changed: {oldColor} → {color}");
                }
                else if (obj.Element is Border border)
                {
                    border.BorderBrush = new SolidColorBrush(color);
                    System.Diagnostics.Debug.WriteLine($"   ✓ Border color changed: {oldColor} → {color}");
                }
                
                // Record for undo/redo
                RecordModifyAction(obj.Element, oldColor, color, $"Change Color {oldColor} → {color}");
            }

            // Update toolbar preview
            _contextToolbar?.UpdateColorPreview(color);
            
            System.Diagnostics.Debug.WriteLine($"✅ Color changed for {selectedObjects.Count} object(s): → {color}");
        }

