        private void OnMoreMenuRotateCustom(object? sender, EventArgs e)
        {
            if (_selectionManager?.SelectedObject != null && _transformService != null)
            {
                var obj = _selectionManager.SelectedObject;
                var oldAngle = obj.RotationAngle;
                
                // Simple input dialog using TextBox in Window
                var inputWindow = new Window
                {
                    Title = "Custom Rotation",
                    Width = 350,
                    Height = 180,
                    WindowStartupLocation = WindowStartupLocation.CenterScreen,
                    ResizeMode = System.Windows.ResizeMode.NoResize,
                    Background = new SolidColorBrush(Color.FromRgb(45, 45, 48))
                };

                var stackPanel = new StackPanel { Margin = new Thickness(20) };
                
                var labelCurrent = new TextBlock
                {
                    Text = $"Current angle: {oldAngle:F0}Â°",
                    Foreground = Brushes.White,
                    FontSize = 14,
                    Margin = new Thickness(0, 0, 0, 10)
                };
                
                var labelPrompt = new TextBlock
                {
                    Text = "Enter new rotation angle (0-360):",
                    Foreground = Brushes.White,
                    FontSize = 14,
                    Margin = new Thickness(0, 0, 0, 5)
                };
                
                var textBox = new TextBox
                {
                    Text = oldAngle.ToString("F0"),
                    FontSize = 16,
                    Padding = new Thickness(5),
                    Margin = new Thickness(0, 0, 0, 15)
                };
                textBox.SelectAll();
                textBox.Focus();
                
                var buttonPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    HorizontalAlignment = HorizontalAlignment.Right
                };
                
                var btnOK = new Button
                {
                    Content = "OK",
                    Width = 80,
                    Height = 30,
                    Margin = new Thickness(0, 0, 10, 0),
                    IsDefault = true
                };
                
                var btnCancel = new Button
                {
                    Content = "Cancel",
                    Width = 80,
                    Height = 30,
                    IsCancel = true
                };
                
                bool dialogResult = false;
                btnOK.Click += (s, args) => { dialogResult = true; inputWindow.Close(); };
                btnCancel.Click += (s, args) => { dialogResult = false; inputWindow.Close(); };
                
                buttonPanel.Children.Add(btnOK);
                buttonPanel.Children.Add(btnCancel);
                
                stackPanel.Children.Add(labelCurrent);
                stackPanel.Children.Add(labelPrompt);
                stackPanel.Children.Add(textBox);
                stackPanel.Children.Add(buttonPanel);
                
                inputWindow.Content = stackPanel;
                inputWindow.ShowDialog();
                
                if (dialogResult && double.TryParse(textBox.Text, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out double newAngle))
                {
                    // Clamp to 0-360
                    newAngle = ((newAngle % 360) + 360) % 360;
                    
                    // Apply rotation
                    double delta = newAngle - oldAngle;
                    _transformService.RotateInPlace(obj, delta);
                    if (_selectionBox != null) _selectionBox.AttachTo(obj);
                    RefreshSelectableObjects();

                    if (_contextToolbar != null)
                    {
                        var pos = CalculateOptimalToolbarPosition(obj.Bounds);
                        _contextToolbar.ShowAt(pos, obj);
                    }
                    
                    // Record for undo/redo
                    RecordModifyAction(obj.Element, "RotationAngle", oldAngle, newAngle, $"Rotate Custom {newAngle:F0}°");
                    
                    // Visual feedback
                    AnimateRotation(obj.Element, oldAngle, newAngle);
                    
                    System.Diagnostics.Debug.WriteLine($"🔄 Rotated custom: {oldAngle:F0}° → {newAngle:F0}°");
                }
                
                _moreMenu?.Hide();
            }
        }

        // Visual feedback animations
        /// <summary>
        /// Fade in animation for new objects (Copy)
        /// </summary>
        private void AnimateFadeIn(UIElement? element)
        {
            if (element == null)
            {
                System.Diagnostics.Debug.WriteLine("âš ï¸ AnimateFadeIn: element is null");
                return;
            }
            
            element.Opacity = 0;
            var animation = new System.Windows.Media.Animation.DoubleAnimation
            {
                From = 0,
                To = 1,
                Duration = TimeSpan.FromMilliseconds(300),
                EasingFunction = new System.Windows.Media.Animation.QuadraticEase { EasingMode = System.Windows.Media.Animation.EasingMode.EaseOut }
            };
            element.BeginAnimation(UIElement.OpacityProperty, animation);
        }

        /// <summary>
        /// Fade out animation with optional callback (Delete, SendToBack)
        /// </summary>
        private void AnimateFadeOut(UIElement? element, double fromOpacity, double toOpacity, Action? onComplete = null)
        {
            if (element == null)
            {
                System.Diagnostics.Debug.WriteLine("⚠️ AnimateFadeOut: element is null");
                onComplete?.Invoke();
                return;
            }
            
            var animation = new System.Windows.Media.Animation.DoubleAnimation
            {
                From = fromOpacity,
                To = toOpacity,
                Duration = TimeSpan.FromMilliseconds(250),
                EasingFunction = new System.Windows.Media.Animation.QuadraticEase { EasingMode = System.Windows.Media.Animation.EasingMode.EaseIn }
            };
            
            if (onComplete != null)
            {
                animation.Completed += (s, e) => onComplete();
            }
            
            element.BeginAnimation(UIElement.OpacityProperty, animation);
        }

        /// <summary>
        /// Pop animation for layer changes (BringToFront)
        /// </summary>
        private void AnimatePop(UIElement element)
        {
            var scaleTransform = element.RenderTransform as System.Windows.Media.ScaleTransform;
            if (scaleTransform == null)
            {
                scaleTransform = new System.Windows.Media.ScaleTransform(1, 1);
                element.RenderTransform = scaleTransform;
                element.RenderTransformOrigin = new Point(0.5, 0.5);
            }

            var scaleUpX = new System.Windows.Media.Animation.DoubleAnimation
            {
                From = 1,
                To = 1.1,
                Duration = TimeSpan.FromMilliseconds(150),
                AutoReverse = true,
                EasingFunction = new System.Windows.Media.Animation.BackEase { Amplitude = 0.3, EasingMode = System.Windows.Media.Animation.EasingMode.EaseOut }
            };
            
            var scaleUpY = new System.Windows.Media.Animation.DoubleAnimation
            {
                From = 1,
                To = 1.1,
                Duration = TimeSpan.FromMilliseconds(150),
                AutoReverse = true,
                EasingFunction = new System.Windows.Media.Animation.BackEase { Amplitude = 0.3, EasingMode = System.Windows.Media.Animation.EasingMode.EaseOut }
            };

            scaleTransform.BeginAnimation(System.Windows.Media.ScaleTransform.ScaleXProperty, scaleUpX);
            scaleTransform.BeginAnimation(System.Windows.Media.ScaleTransform.ScaleYProperty, scaleUpY);
        }

        /// <summary>
        /// Rotation animation (Rotate90)
        /// </summary>
        private void AnimateRotation(UIElement element, double fromAngle, double toAngle)
        {
            var rotateTransform = element.RenderTransform as System.Windows.Media.RotateTransform;
            if (rotateTransform == null)
            {
                rotateTransform = new System.Windows.Media.RotateTransform(fromAngle);
                element.RenderTransform = rotateTransform;
                element.RenderTransformOrigin = new Point(0.5, 0.5);
            }

            var animation = new System.Windows.Media.Animation.DoubleAnimation
            {
                From = fromAngle,
                To = toAngle,
                Duration = TimeSpan.FromMilliseconds(300),
                EasingFunction = new System.Windows.Media.Animation.CubicEase { EasingMode = System.Windows.Media.Animation.EasingMode.EaseInOut }
            };

            rotateTransform.BeginAnimation(System.Windows.Media.RotateTransform.AngleProperty, animation);
        }

        /// <summary>
        /// Lock toggle animation (pulse effect)
        /// </summary>
        private void AnimateLockToggle(UIElement element, bool isLocked)
        {
            var animation = new System.Windows.Media.Animation.DoubleAnimation
            {
                From = 1,
                To = 0.7,
                Duration = TimeSpan.FromMilliseconds(200),
                AutoReverse = true,
                RepeatBehavior = new System.Windows.Media.Animation.RepeatBehavior(2)
            };

            element.BeginAnimation(UIElement.OpacityProperty, animation);
        }

        /// <summary>
        /// Flip animation (FlipHorizontal/FlipVertical)
        /// </summary>
        private void AnimateFlip(UIElement? element, bool isHorizontal)
        {
            if (element == null)
                return;

            var scaleTransform = element.RenderTransform as System.Windows.Media.ScaleTransform;
            if (scaleTransform == null)
            {
                scaleTransform = new System.Windows.Media.ScaleTransform(1, 1);
                element.RenderTransform = scaleTransform;
                element.RenderTransformOrigin = new Point(0.5, 0.5);
            }

            var property = isHorizontal
                ? System.Windows.Media.ScaleTransform.ScaleXProperty
                : System.Windows.Media.ScaleTransform.ScaleYProperty;

            var currentScale = isHorizontal ? scaleTransform.ScaleX : scaleTransform.ScaleY;

            var animation = new System.Windows.Media.Animation.DoubleAnimation
            {
                From = currentScale,
                To = 0.1,
                Duration = TimeSpan.FromMilliseconds(150),
                AutoReverse = true,
                EasingFunction = new System.Windows.Media.Animation.QuadraticEase
                {
                    EasingMode = System.Windows.Media.Animation.EasingMode.EaseInOut
                }
            };

            scaleTransform.BeginAnimation(property, animation);
        }

        /// <summary>
        /// Dọn dẹp hình chữ nhật xem trước vùng chọn (blue dashed rectangle) triệt để khỏi Canvas
        /// </summary>
        private void ClearRectangleSelectionPreview()
        {
            if (_rectangleSelectionPreview != null)
            {
                if (MainInteractiveBoard?.Children.Contains(_rectangleSelectionPreview) == true)
                {
                    MainInteractiveBoard.Children.Remove(_rectangleSelectionPreview);
