        /// <summary>
        /// Convert selected text to UPPERCASE
        /// For drawing objects: recognize handwriting first, then convert
        /// </summary>
        private async void OnMoreMenuUpperCase(object? sender, EventArgs e)
        {
            var selectedObjs = _selectionManager?.SelectedObjects.ToList();
            if (selectedObjs == null || selectedObjs.Count == 0)
            {
                System.Diagnostics.Debug.WriteLine("⚠️ UpperCase: No object selected");
                return;
            }

            _moreMenu?.Hide();
            ClearRectangleSelectionPreview();

            var drawingObjs = selectedObjs.Where(o => o.Element is Polyline || o.Element is System.Windows.Shapes.Path || o.Element is System.Windows.Shapes.Shape).ToList();
            var textObjs = selectedObjs.Except(drawingObjs).ToList();

            // 1. Xử lý các đối tượng văn bản có sẵn
            foreach (var obj in textObjs)
            {
                if (obj.Element is System.Windows.Controls.TextBlock textBlock)
                {
                    string oldText = textBlock.Text;
                    string newText = oldText?.ToUpper() ?? "";
                    if (newText != oldText)
                    {
                        textBlock.Text = newText;
                        obj.TextContent = newText;
                        RecordModifyAction(obj.Element, oldText, newText, "Convert to UPPERCASE");
                    }
                }
                else if (obj.Element is System.Windows.Controls.TextBox textBox)
                {
                    string oldText = textBox.Text;
                    string newText = oldText?.ToUpper() ?? "";
                    if (newText != oldText)
                    {
                        textBox.Text = newText;
                        obj.TextContent = newText;
                        RecordModifyAction(obj.Element, oldText, newText, "Convert to UPPERCASE");
                    }
                }
                else if (obj.Element is System.Windows.Controls.Border border)
                {
                    var childTextBlock = FindVisualChild<System.Windows.Controls.TextBlock>(border);
                    if (childTextBlock != null)
                    {
                        string oldText = childTextBlock.Text;
                        string newText = oldText?.ToUpper() ?? "";
                        if (newText != oldText)
                        {
                            childTextBlock.Text = newText;
                            obj.TextContent = newText;
                            RecordModifyAction(obj.Element, oldText, newText, "Convert to UPPERCASE");
                        }
                    }
                }
            }

            // 2. Nhận dạng nguyên chuỗi các nét vẽ được chọn cùng lúc (chỉ mở 1 Dialog duy nhất cho toàn bộ chuỗi)
            if (drawingObjs.Count > 0)
            {
                await RecognizeAndReplaceWithText(drawingObjs, TextCaseMode.UpperCase);
            }
        }

