        /// <summary>
        /// Sprint 3 Module 3.1: Web Search - Search selected text on Google/Bing
        /// </summary>
        private void OnMoreMenuWebSearch(object? sender, EventArgs e)
        {
            System.Diagnostics.Debug.WriteLine("🔍 Web Search clicked");

            try
            {
                var obj = _selectionManager?.SelectedObjects.FirstOrDefault();
