                {
                    MessageBox.Show("Please select an object first.", "No Selection", 
                        MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                // Extract text from selected object
                string? searchText = ExtractTextFromObject(obj);

                if (string.IsNullOrWhiteSpace(searchText))
                {
                    MessageBox.Show("No text found in selected object.", "No Text", 
                        MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                // Show search engine selection dialog
                var searchDialog = new Window
                {
                    Title = "Web Search",
                    Width = 400,
                    Height = 250,
                    WindowStartupLocation = WindowStartupLocation.CenterScreen,
                    ResizeMode = System.Windows.ResizeMode.NoResize
                };

