                };
                stackPanel.Children.Add(engineLabel);

                var buttonsPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    Margin = new Thickness(0, 10, 0, 0)
                };

                // Google Search button
                var googleButton = new System.Windows.Controls.Button
                {
                    Content = "🔍 Google",
                    Width = 100,
                    Height = 35,
                    Margin = new Thickness(5)
                };
                googleButton.Click += (s, args) =>
                {
                    string encodedText = Uri.EscapeDataString(searchText);
                    string url = $"https://www.google.com/search?q={encodedText}";
                    System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
                    {
                        FileName = url,
                        UseShellExecute = true
                    });
