                {
                    string encodedText = Uri.EscapeDataString(searchText);
                    string url = $"https://www.bing.com/search?q={encodedText}";
                    System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
                    {
                        FileName = url,
                        UseShellExecute = true
                    });
                    searchDialog.Close();
                };

                // Cancel button
                var cancelButton = new System.Windows.Controls.Button
                {
                    Content = "Cancel",
                    Width = 100,
                    Height = 35,
                    Margin = new Thickness(5)
                };
                cancelButton.Click += (s, args) => searchDialog.Close();

                buttonsPanel.Children.Add(googleButton);
                buttonsPanel.Children.Add(bingButton);
                buttonsPanel.Children.Add(cancelButton);
                stackPanel.Children.Add(buttonsPanel);

                searchDialog.Content = stackPanel;
                searchDialog.ShowDialog();

                System.Diagnostics.Debug.WriteLine($"🔍 Web search launched for: '{searchText}'");
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ Web Search Error: {ex.Message}");
                MessageBox.Show($"Failed to launch web search: {ex.Message}", "Error", 
                    MessageBoxButton.OK, MessageBoxImage.Error);
