        /// <summary>
        /// Sprint 3 Module 3.3: Text-to-Speech - Read selected text aloud
        /// </summary>
        private void OnMoreMenuTextToSpeech(object? sender, EventArgs e)
        {
            System.Diagnostics.Debug.WriteLine("🔊 Text-to-Speech clicked");

            try
            {
                var obj = _selectionManager?.SelectedObjects.FirstOrDefault();
                if (obj == null || obj.Element == null)
                {
                    MessageBox.Show("Please select an object first.", "No Selection", 
                        MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                // Extract text from selected object
                string? textToSpeak = ExtractTextFromObject(obj);

                if (string.IsNullOrWhiteSpace(textToSpeak))
                {
                    MessageBox.Show("No text found in selected object.", "No Text", 
                        MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                // Use System.Speech for Text-to-Speech
                var synthesizer = new System.Speech.Synthesis.SpeechSynthesizer();
                
                // Show TTS control dialog
                var ttsDialog = new Window
                {
                    Title = "Text-to-Speech",
                    Width = 450,
                    Height = 280,
                    WindowStartupLocation = WindowStartupLocation.CenterScreen,
                    ResizeMode = System.Windows.ResizeMode.NoResize
                };

                var stackPanel = new StackPanel { Margin = new Thickness(20) };

                // Display text
                var textLabel = new Label
                {
                    Content = "Text to speak:",
                    FontWeight = FontWeights.Bold
                };
                stackPanel.Children.Add(textLabel);

                var textBox = new TextBox
                {
                    Text = textToSpeak,
                    Height = 80,
                    TextWrapping = TextWrapping.Wrap,
                    VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                    IsReadOnly = true,
                    Margin = new Thickness(0, 5, 0, 15)
                };
                stackPanel.Children.Add(textBox);

                // Voice selection
                var voicePanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 10, 0, 10)
                };
                
                var voiceLabel = new Label { Content = "Voice:", Width = 80 };
                var voiceCombo = new ComboBox { Width = 250 };
                
                foreach (var voice in synthesizer.GetInstalledVoices())
                {
                    voiceCombo.Items.Add(new ComboBoxItem 
                    { 
                        Content = voice.VoiceInfo.Name,
                        Tag = voice.VoiceInfo
                    });
                }
                if (voiceCombo.Items.Count > 0)
                    voiceCombo.SelectedIndex = 0;

                voicePanel.Children.Add(voiceLabel);
                voicePanel.Children.Add(voiceCombo);
                stackPanel.Children.Add(voicePanel);

                // Speed control
                var speedPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 5, 0, 15)
                };
                
                var speedLabel = new Label { Content = "Speed:", Width = 80 };
                var speedSlider = new Slider
                {
                    Width = 150,
                    Minimum = -10,
                    Maximum = 10,
                    Value = 0,
                    TickFrequency = 1,
                    IsSnapToTickEnabled = true
                };
                var speedValueLabel = new Label { Content = "Normal", Width = 100 };
                
                speedSlider.ValueChanged += (s, args) =>
                {
                    int speed = (int)speedSlider.Value;
                    speedValueLabel.Content = speed == 0 ? "Normal" : 
                        (speed > 0 ? $"+{speed}" : speed.ToString());
                };

                speedPanel.Children.Add(speedLabel);
                speedPanel.Children.Add(speedSlider);
                speedPanel.Children.Add(speedValueLabel);
                stackPanel.Children.Add(speedPanel);

                // Control buttons
                var buttonsPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    Margin = new Thickness(0, 10, 0, 0)
                };

                var speakButton = new System.Windows.Controls.Button
                {
                    Content = "â–¶ï¸ Speak",
                    Width = 100,
                    Height = 35,
                    Margin = new Thickness(5)
                };
                speakButton.Click += (s, args) =>
                {
                    try
                    {
                        synthesizer.SpeakAsyncCancelAll();
                        
                        // Set voice
                        var selectedVoice = voiceCombo.SelectedItem as ComboBoxItem;
                        if (selectedVoice != null)
                        {
                            var voiceInfo = selectedVoice.Tag as System.Speech.Synthesis.VoiceInfo;
                            if (voiceInfo != null)
                                synthesizer.SelectVoice(voiceInfo.Name);
                        }
                        
                        // Set speed
                        synthesizer.Rate = (int)speedSlider.Value;
                        
                        // Speak
                        synthesizer.SpeakAsync(textToSpeak);
                        System.Diagnostics.Debug.WriteLine($"🔊 Speaking: '{textToSpeak}'");
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Failed to speak: {ex.Message}", "Error");
                    }
                };

                var stopButton = new System.Windows.Controls.Button
                {
                    Content = "â¹ï¸ Stop",
                    Width = 100,
                    Height = 35,
                    Margin = new Thickness(5)
                };
                stopButton.Click += (s, args) =>
                {
                    synthesizer.SpeakAsyncCancelAll();
                    System.Diagnostics.Debug.WriteLine("â¹ï¸ Speech stopped");
                };

                var closeButton = new System.Windows.Controls.Button
                {
                    Content = "Close",
                    Width = 100,
                    Height = 35,
                    Margin = new Thickness(5)
                };
                closeButton.Click += (s, args) =>
                {
                    synthesizer.SpeakAsyncCancelAll();
                    synthesizer.Dispose();
                    ttsDialog.Close();
                };

                buttonsPanel.Children.Add(speakButton);
                buttonsPanel.Children.Add(stopButton);
                buttonsPanel.Children.Add(closeButton);
                stackPanel.Children.Add(buttonsPanel);

                ttsDialog.Content = stackPanel;
                ttsDialog.Closed += (s, args) => synthesizer.Dispose();
                ttsDialog.ShowDialog();
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ TTS Error: {ex.Message}");
                MessageBox.Show($"Failed to initialize Text-to-Speech: {ex.Message}", "Error", 
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally
            {
                _moreMenu?.Hide();
            }
        }

