        /// <summary>
        /// Sprint 5 Module 5.1/5.2: Group selected objects
        /// </summary>
        private void OnMoreMenuGroup(object? sender, EventArgs e)
        {
            System.Diagnostics.Debug.WriteLine("📦 Group clicked");

            try
            {
                var selectedObjects = _selectionManager?.SelectedObjects;
                
                if (selectedObjects == null || selectedObjects.Count < 2)
                {
                    MessageBox.Show(
                        "Please select at least 2 objects to group.\n\n" +
                        "Tip: Hold Ctrl and click multiple objects to select them.",
                        "Group Objects",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information
                    );
                    return;
                }

                // Create new group ID
                string groupId = Guid.NewGuid().ToString();
                
                // Assign group ID to all selected objects
                foreach (var obj in selectedObjects)
                {
                    obj.GroupId = groupId;
                }

                // Calculate group bounds
                double minX = selectedObjects.Min(o => o.Position.X);
                double minY = selectedObjects.Min(o => o.Position.Y);
                double maxX = selectedObjects.Max(o => o.Position.X + o.Size.Width);
                double maxY = selectedObjects.Max(o => o.Position.Y + o.Size.Height);

                System.Diagnostics.Debug.WriteLine(
                    $"📦 Grouped {selectedObjects.Count} objects with GroupId: {groupId}\n" +
                    $"   Bounds: ({minX}, {minY}) - ({maxX}, {maxY})"
                );

                MessageBox.Show(
                    $"Successfully grouped {selectedObjects.Count} objects!\n\n" +
                    $"Group ID: {groupId.ToString().Substring(0, 8)}...\n" +
                    $"Size: {maxX - minX:F0} x {maxY - minY:F0}",
                    "Group Created",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information
                );
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ Group Error: {ex.Message}");
                MessageBox.Show($"Failed to group objects: {ex.Message}", "Error", 
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally
            {
                _moreMenu?.Hide();
            }
        }

        /// <summary>
        /// Sprint 5 Module 5.2: Ungroup selected objects
        /// </summary>
        private void OnMoreMenuUngroup(object? sender, EventArgs e)
        {
            System.Diagnostics.Debug.WriteLine("📂 Ungroup clicked");

            try
            {
                var selectedObjects = _selectionManager?.SelectedObjects;
                
                if (selectedObjects == null || selectedObjects.Count == 0)
                {
                    MessageBox.Show(
                        "Please select grouped objects to ungroup.",
                        "Ungroup Objects",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information
                    );
                    return;
                }

                // Find objects with GroupId
                var groupedObjects = selectedObjects.Where(o => o.GroupId != null).ToList();
                
                if (groupedObjects.Count == 0)
                {
                    MessageBox.Show(
                        "Selected objects are not grouped.",
                        "Ungroup Objects",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information
                    );
                    return;
                }

                // Get unique group IDs
                var groupIds = groupedObjects.Select(o => o.GroupId).Distinct().ToList();
                
                // Remove group IDs from all objects
                foreach (var obj in groupedObjects)
                {
                    obj.GroupId = null;
                }

                System.Diagnostics.Debug.WriteLine($"📂 Ungrouped {groupedObjects.Count} objects from {groupIds.Count} group(s)");

                MessageBox.Show(
                    $"Successfully ungrouped {groupedObjects.Count} objects!\n\n" +
                    $"Groups removed: {groupIds.Count}",
                    "Ungroup Complete",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information
                );
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ Ungroup Error: {ex.Message}");
                MessageBox.Show($"Failed to ungroup objects: {ex.Message}", "Error", 
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally
            {
                _moreMenu?.Hide();
            }
        }

        /// <summary>
        /// Sao chép nhiều lần — clone N copies with offset
        /// </summary>
        private void OnMoreMenuDuplicate(object? sender, EventArgs e)
        {
            System.Diagnostics.Debug.WriteLine("📋 Duplicate Multiple clicked");
            var obj = _selectionManager?.SelectedObject;
            if (obj?.Element == null)
            {
                MessageBox.Show("Vui lòng chọn một đối tượng để sao chép.", "Sao chép nhiều lần",
                    MessageBoxButton.OK, MessageBoxImage.Information);
                _moreMenu?.Hide();
                return;
            }

            try
            {
                // Dialog nhập số lần và offset
                var inputWindow = new Window
                {
                    Title = "Sao chép nhiều lần",
                    Width = 380, Height = 280,
                    WindowStartupLocation = WindowStartupLocation.CenterScreen,
                    ResizeMode = System.Windows.ResizeMode.NoResize,
                    Background = new SolidColorBrush(Color.FromRgb(45, 45, 48))
                };

                var stackPanel = new StackPanel { Margin = new Thickness(20) };

                // Number of copies
                stackPanel.Children.Add(new TextBlock { Text = "Số lần sao chép:", Foreground = Brushes.White, FontSize = 14 });
                var txtCopies = new TextBox { Text = "3", FontSize = 14, Padding = new Thickness(5), Margin = new Thickness(0, 4, 0, 12) };
                stackPanel.Children.Add(txtCopies);

                // Offset X
                stackPanel.Children.Add(new TextBlock { Text = "Khoảng cách X (px):", Foreground = Brushes.White, FontSize = 14 });
                var txtOffsetX = new TextBox { Text = "30", FontSize = 14, Padding = new Thickness(5), Margin = new Thickness(0, 4, 0, 12) };
                stackPanel.Children.Add(txtOffsetX);

                // Offset Y
                stackPanel.Children.Add(new TextBlock { Text = "Khoảng cách Y (px):", Foreground = Brushes.White, FontSize = 14 });
                var txtOffsetY = new TextBox { Text = "30", FontSize = 14, Padding = new Thickness(5), Margin = new Thickness(0, 4, 0, 12) };
                stackPanel.Children.Add(txtOffsetY);

                // Buttons
                var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
                var btnOK = new Button
                {
                    Content = "Sao chép", Width = 90, Height = 32, Margin = new Thickness(0, 0, 8, 0),
                    Background = new SolidColorBrush(Color.FromRgb(0, 122, 204)), Foreground = Brushes.White,
                    BorderThickness = new Thickness(0), Cursor = Cursors.Hand
                };
                var btnCancel = new Button
                {
                    Content = "Hủy", Width = 70, Height = 32,
                    Background = new SolidColorBrush(Color.FromRgb(100, 100, 100)), Foreground = Brushes.White,
                    BorderThickness = new Thickness(0), Cursor = Cursors.Hand
                };
                btnOK.Click += (s, args) => { inputWindow.DialogResult = true; };
                btnCancel.Click += (s, args) => { inputWindow.DialogResult = false; };
                btnPanel.Children.Add(btnOK);
                btnPanel.Children.Add(btnCancel);
                stackPanel.Children.Add(btnPanel);

                inputWindow.Content = stackPanel;

                if (inputWindow.ShowDialog() == true)
                {
                    if (int.TryParse(txtCopies.Text, out int copies) && copies > 0 && copies <= 50 &&
                        double.TryParse(txtOffsetX.Text, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out double offsetX) &&
                        double.TryParse(txtOffsetY.Text, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out double offsetY))
                    {
                        var sourceElement = obj.Element as FrameworkElement;
                        if (sourceElement == null) return;

                        for (int i = 1; i <= copies; i++)
                        {
                            UIElement? clone = CloneUIElement(sourceElement);
                            if (clone != null)
                            {
                                double newX = obj.Position.X + (offsetX * i);
                                double newY = obj.Position.Y + (offsetY * i);
                                Canvas.SetLeft(clone, newX);
                                Canvas.SetTop(clone, newY);
                                Panel.SetZIndex(clone, obj.ZIndex);

                                MainInteractiveBoard.Children.Add(clone);
                                RecordAddAction(clone, $"Duplicate copy #{i}");
                                RegisterNewObjectWithSelectionManager(clone);
                            }
                        }

                        System.Diagnostics.Debug.WriteLine($"📋 Duplicated {copies} copies with offset ({offsetX}, {offsetY})");
                    }
                    else
                    {
                        MessageBox.Show("Giá trị không hợp lệ. Số lần: 1-50, offset: số thực.", "Lỗi",
                            MessageBoxButton.OK, MessageBoxImage.Warning);
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ Duplicate Error: {ex.Message}");
            }
            finally
            {
                _moreMenu?.Hide();
            }
        }

        /// <summary>
        /// Clone a UIElement (supports Polyline, Path, Line, Shape, Image, TextBlock, Border)
        /// </summary>
        private UIElement? CloneUIElement(FrameworkElement source)
        {
            try
            {
                if (source is Polyline polyline)
                {
                    var clone = new Polyline
                    {
                        Stroke = polyline.Stroke?.Clone(),
                        StrokeThickness = polyline.StrokeThickness,
                        StrokeLineJoin = polyline.StrokeLineJoin,
                        StrokeStartLineCap = polyline.StrokeStartLineCap,
                        StrokeEndLineCap = polyline.StrokeEndLineCap,
                        Opacity = polyline.Opacity
                    };
                    foreach (var pt in polyline.Points) clone.Points.Add(pt);
                    return clone;
                }
                else if (source is System.Windows.Shapes.Path path && path.Data != null)
                {
                    var clone = new System.Windows.Shapes.Path
                    {
                        Data = path.Data.Clone(),
                        Stroke = path.Stroke?.Clone(),
                        StrokeThickness = path.StrokeThickness,
                        StrokeLineJoin = path.StrokeLineJoin,
                        StrokeStartLineCap = path.StrokeStartLineCap,
                        StrokeEndLineCap = path.StrokeEndLineCap,
                        Fill = path.Fill?.Clone(),
                        Opacity = path.Opacity
                    };
                    return clone;
                }
                else if (source is System.Windows.Shapes.Line line)
                {
                    return new System.Windows.Shapes.Line
                    {
                        X1 = line.X1, Y1 = line.Y1, X2 = line.X2, Y2 = line.Y2,
                        Stroke = line.Stroke?.Clone(),
                        StrokeThickness = line.StrokeThickness,
                        Opacity = line.Opacity
                    };
                }
                else if (source is System.Windows.Shapes.Rectangle rect)
                {
                    return new System.Windows.Shapes.Rectangle
                    {
                        Width = rect.Width, Height = rect.Height,
                        Stroke = rect.Stroke?.Clone(), Fill = rect.Fill?.Clone(),
                        StrokeThickness = rect.StrokeThickness,
                        RadiusX = rect.RadiusX, RadiusY = rect.RadiusY,
                        Opacity = rect.Opacity
                    };
                }
                else if (source is System.Windows.Shapes.Ellipse ellipse)
                {
                    return new System.Windows.Shapes.Ellipse
                    {
                        Width = ellipse.Width, Height = ellipse.Height,
                        Stroke = ellipse.Stroke?.Clone(), Fill = ellipse.Fill?.Clone(),
                        StrokeThickness = ellipse.StrokeThickness,
                        Opacity = ellipse.Opacity
                    };
                }
                else if (source is System.Windows.Controls.Image img && img.Source != null)
                {
                    return new System.Windows.Controls.Image
                    {
                        Source = img.Source.Clone(),
                        Width = img.Width, Height = img.Height,
                        Stretch = img.Stretch,
                        Opacity = img.Opacity
                    };
                }
                else if (source is System.Windows.Controls.TextBlock tb)
                {
                    return new System.Windows.Controls.TextBlock
                    {
                        Text = tb.Text,
                        FontSize = tb.FontSize, FontFamily = tb.FontFamily,
                        FontWeight = tb.FontWeight, FontStyle = tb.FontStyle,
                        Foreground = tb.Foreground?.Clone(),
                        Background = tb.Background?.Clone(),
                        Opacity = tb.Opacity
                    };
                }

                // Fallback: use XamlWriter/XamlReader
                string xaml = System.Windows.Markup.XamlWriter.Save(source);
                var cloned = System.Windows.Markup.XamlReader.Parse(xaml) as UIElement;
                return cloned;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"âš ï¸ CloneUIElement failed: {ex.Message}");
                return null;
            }
        }

