        /// <summary>
        /// Kích thước & vị trí — edit X, Y, Width, Height precisely
        /// </summary>
        private void OnMoreMenuSizePosition(object? sender, EventArgs e)
        {
            System.Diagnostics.Debug.WriteLine("📏 Size/Position clicked");
            var obj = _selectionManager?.SelectedObject;
            if (obj?.Element == null)
            {
                _moreMenu?.Hide();
                return;
            }

            try
            {
                var inputWindow = new Window
                {
                    Title = "Kích thước & Vị trí",
                    Width = 360, Height = 340,
                    WindowStartupLocation = WindowStartupLocation.CenterScreen,
                    ResizeMode = System.Windows.ResizeMode.NoResize,
                    Background = new SolidColorBrush(Color.FromRgb(45, 45, 48))
                };

                var stackPanel = new StackPanel { Margin = new Thickness(20) };

                // X position
                stackPanel.Children.Add(new TextBlock { Text = "Vị trí X:", Foreground = Brushes.White, FontSize = 14 });
                var txtX = new TextBox { Text = obj.Position.X.ToString("F0"), FontSize = 14, Padding = new Thickness(5), Margin = new Thickness(0, 4, 0, 8) };
                stackPanel.Children.Add(txtX);

                // Y position
                stackPanel.Children.Add(new TextBlock { Text = "Vị trí Y:", Foreground = Brushes.White, FontSize = 14 });
                var txtY = new TextBox { Text = obj.Position.Y.ToString("F0"), FontSize = 14, Padding = new Thickness(5), Margin = new Thickness(0, 4, 0, 8) };
                stackPanel.Children.Add(txtY);

                // Width
                stackPanel.Children.Add(new TextBlock { Text = "Chiều rộng:", Foreground = Brushes.White, FontSize = 14 });
                var txtW = new TextBox { Text = obj.Size.Width.ToString("F0"), FontSize = 14, Padding = new Thickness(5), Margin = new Thickness(0, 4, 0, 8) };
                stackPanel.Children.Add(txtW);

                // Height
                stackPanel.Children.Add(new TextBlock { Text = "Chiều cao:", Foreground = Brushes.White, FontSize = 14 });
                var txtH = new TextBox { Text = obj.Size.Height.ToString("F0"), FontSize = 14, Padding = new Thickness(5), Margin = new Thickness(0, 4, 0, 12) };
                stackPanel.Children.Add(txtH);

                // Buttons
                var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
                var btnOK = new Button
                {
                    Content = "Áp dụng", Width = 90, Height = 32, Margin = new Thickness(0, 0, 8, 0),
                    Background = new SolidColorBrush(Color.FromRgb(0, 122, 204)), Foreground = Brushes.White,
                    BorderThickness = new Thickness(0), Cursor = Cursors.Hand
                };
                var btnCancel = new Button
                {
                    Content = "Hủy", Width = 70, Height = 32,
                    Background = new SolidColorBrush(Color.FromRgb(100, 100, 100)), Foreground = Brushes.White,
                    BorderThickness = new Thickness(0), Cursor = Cursors.Hand
                };
                btnOK.Click += (s, args) => { inputWindow.DialogResult = true; };
                btnCancel.Click += (s, args) => { inputWindow.DialogResult = false; };
                btnPanel.Children.Add(btnOK);
                btnPanel.Children.Add(btnCancel);
                stackPanel.Children.Add(btnPanel);

                inputWindow.Content = stackPanel;

                if (inputWindow.ShowDialog() == true)
                {
                    if (double.TryParse(txtX.Text, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out double newX) &&
                        double.TryParse(txtY.Text, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out double newY) &&
                        double.TryParse(txtW.Text, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out double newW) && newW > 0 &&
                        double.TryParse(txtH.Text, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out double newH) && newH > 0)
                    {
                        // Apply position
                        if (_transformService != null)
                        {
                            _transformService.Move(obj, new Point(newX, newY));
                            _transformService.Resize(obj, new Size(newW, newH));
                        }

                        _selectionBox?.UpdatePosition();

                        // ✅ G2.1: Auto-Flip toolbar position
                        var toolbarPos = CalculateOptimalToolbarPosition(obj.Bounds);
                        _contextToolbar?.ShowAt(toolbarPos, obj);

                        RecordModifyAction(obj.Element, "SizePosition",
                            $"({newX:F0},{newY:F0}) {newW:F0}×{newH:F0}", "Edit Size & Position");

                        System.Diagnostics.Debug.WriteLine(
                            $"📏 Size/Position set: ({newX:F0},{newY:F0}) {newW:F0}×{newH:F0}");
                    }
                    else
                    {
                        MessageBox.Show("Giá trị không hợp lệ. Kích thước phải > 0.", "Lỗi",
                            MessageBoxButton.OK, MessageBoxImage.Warning);
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ SizePosition Error: {ex.Message}");
            }
            finally
            {
                _moreMenu?.Hide();
            }
        }

