        #region Board Management - Background

        /// <summary>
        /// Apply background to MainInteractiveBoard (âœ¨ Updated to support color + pattern combination + dynamic spacing)
        /// </summary>
        public void ApplyCanvasBackground(string? color, string? pattern, int lineSpacing = 40, int lineOpacity = 10)
        {
            try
            {
                // Store line spacing and opacity for pattern creation
                _currentLineSpacing = lineSpacing;
                _currentLineOpacity = lineOpacity;
                
                // âœ¨ Remove old background rectangles if any
                var oldBgRects = MainInteractiveBoard.Children.OfType<Rectangle>()
                    .Where(r => r.Tag?.ToString() == "BackgroundLayer")
                    .ToList();
                foreach (var rect in oldBgRects)
                {
                    MainInteractiveBoard.Children.Remove(rect);
                }
                
                if (!string.IsNullOrEmpty(pattern))
                {
                    // Create background color rectangle with dynamic bindings
                    var bgRect = new Rectangle
                    {
                        Tag = "BackgroundLayer",
                        // ✅ QC_4.2_GRID_PROTECT (G-1): Grid không bao giờ nhận touch/click
                        IsHitTestVisible = false
                    };
                    bgRect.SetBinding(FrameworkElement.WidthProperty, new System.Windows.Data.Binding("ActualWidth") { Source = MainInteractiveBoard });
                    bgRect.SetBinding(FrameworkElement.HeightProperty, new System.Windows.Data.Binding("ActualHeight") { Source = MainInteractiveBoard });
                    
                    if (!string.IsNullOrEmpty(color))
                    {
                        try
                        {
                            bgRect.Fill = new SolidColorBrush(
                                (Color)ColorConverter.ConvertFromString(color)
                            );
                        }
                        catch
                        {
                            bgRect.Fill = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3D6D64"));
                        }
                    }
                    else
                    {
                        bgRect.Fill = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3D6D64"));
                    }
                    
                    // Create pattern rectangle with dynamic bindings
                    var patternRect = new Rectangle
                    {
                        Fill = CreatePatternBrushByName(pattern),
                        Tag = "BackgroundLayer",
                        // ✅ QC_4.2_GRID_PROTECT (G-1): Grid không bao giờ nhận touch/click
                        IsHitTestVisible = false
                    };
                    patternRect.SetBinding(FrameworkElement.WidthProperty, new System.Windows.Data.Binding("ActualWidth") { Source = MainInteractiveBoard });
                    patternRect.SetBinding(FrameworkElement.HeightProperty, new System.Windows.Data.Binding("ActualHeight") { Source = MainInteractiveBoard });
                    
                    // Add to canvas at index 0 (bottom layer)
                    MainInteractiveBoard.Children.Insert(0, bgRect);
                    MainInteractiveBoard.Children.Insert(1, patternRect);
                    // ✅ QC_4.2_GRID_PROTECT (G-2): Pin tại (0,0) tránh NaN position khi layout thay đổi
                    Canvas.SetLeft(bgRect, 0);
                    Canvas.SetTop(bgRect, 0);
                    Canvas.SetLeft(patternRect, 0);
                    Canvas.SetTop(patternRect, 0);
                    Panel.SetZIndex(bgRect, ZIndexConstants.Background);
                    Panel.SetZIndex(patternRect, ZIndexConstants.GridOverlay);
                    
                    // Set canvas background to transparent
                    MainInteractiveBoard.Background = Brushes.Transparent;
                }
                else if (!string.IsNullOrEmpty(color))
                {
                    // Only color, no pattern - use Canvas.Background
                    MainInteractiveBoard.Background = new SolidColorBrush(
                        (Color)ColorConverter.ConvertFromString(color)
                    );
                }
                else
                {
                    // Default chalkboard green
                    MainInteractiveBoard.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3D6D64"));
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Lỗi khi áp dụng nền: {ex.Message}", "Lỗi", 
                              MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        /// <summary>
        /// âœ¨ Apply default background on startup
        /// </summary>
        private void ApplyDefaultBackground()
        {
            try
            {
                // Load default values from Settings
                string defaultColor = QASmartClass.Properties.Settings.Default.DefaultBackgroundColor;
                string defaultPattern = QASmartClass.Properties.Settings.Default.DefaultBackgroundPattern;
                
                System.Diagnostics.Debug.WriteLine($"🔍 Loading defaults from Settings: Color='{defaultColor}', Pattern='{defaultPattern}'");
                
                // âœ¨ TEMPORARY: Hard-code for testing
                if (string.IsNullOrEmpty(defaultColor))
                {
                    defaultColor = "#3D6D64"; // Traditional chalkboard green
                    System.Diagnostics.Debug.WriteLine($"âš ï¸ Color was empty, using hard-coded: {defaultColor}");
                }
                if (string.IsNullOrEmpty(defaultPattern))
                {
                    defaultPattern = "Grid";
                    System.Diagnostics.Debug.WriteLine($"âš ï¸ Pattern was empty, using hard-coded: {defaultPattern}");
                }
                
                // Apply if valid
                if (!string.IsNullOrEmpty(defaultColor) || !string.IsNullOrEmpty(defaultPattern))
                {
                    System.Diagnostics.Debug.WriteLine($"📝 Applying background: Color={defaultColor}, Pattern={defaultPattern}, Spacing=40px");
                    ApplyCanvasBackground(defaultColor, defaultPattern, 40); // Default spacing 40px
                    System.Diagnostics.Debug.WriteLine($"✅ Applied default background successfully");
                }
                else
                {
                    System.Diagnostics.Debug.WriteLine($"âš ï¸ No default background to apply (both empty)");
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"❌ Failed to apply default background: {ex.Message}");
                System.Diagnostics.Debug.WriteLine($"Stack trace: {ex.StackTrace}");
                // Fallback to chalkboard green if error
                MainInteractiveBoard.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3D6D64"));
            }
        }

        /// <summary>
        /// âœ¨ NEW: Apply custom background image to MainInteractiveBoard
        /// </summary>
        public void ApplyCanvasBackgroundImage(System.Windows.Media.Imaging.BitmapImage? backgroundImage, string? pattern = null)
        {
            try
            {
                // Remove old background rectangles
                var oldBgRects = MainInteractiveBoard.Children.OfType<Rectangle>()
                    .Where(r => r.Tag?.ToString() == "BackgroundLayer")
                    .ToList();
                foreach (var rect in oldBgRects)
                {
                    MainInteractiveBoard.Children.Remove(rect);
                }

                if (backgroundImage != null)
                {
                    // Create image background rectangle
                    var imageBrush = new ImageBrush
                    {
                        ImageSource = backgroundImage,
                        Stretch = Stretch.UniformToFill
                    };

                    var bgRect = new Rectangle
                    {
                        Fill = imageBrush,
                        Tag = "BackgroundLayer",
                        // ✅ QC_4.2_GRID_PROTECT (G-1): Grid không bao giờ nhận touch/click
                        IsHitTestVisible = false
                    };
                    bgRect.SetBinding(FrameworkElement.WidthProperty, new System.Windows.Data.Binding("ActualWidth") { Source = MainInteractiveBoard });
                    bgRect.SetBinding(FrameworkElement.HeightProperty, new System.Windows.Data.Binding("ActualHeight") { Source = MainInteractiveBoard });

                    // Add to canvas at index 0 (bottom layer)
                    MainInteractiveBoard.Children.Insert(0, bgRect);
                    // ✅ QC_4.2_GRID_PROTECT (G-2): Pin tại (0,0) tránh NaN position
                    Canvas.SetLeft(bgRect, 0);
                    Canvas.SetTop(bgRect, 0);
                    Panel.SetZIndex(bgRect, ZIndexConstants.Background);

                    // Optionally add pattern overlay
                    if (!string.IsNullOrEmpty(pattern))
                    {
                        var patternRect = new Rectangle
                        {
                            Fill = CreatePatternBrushByName(pattern),
                            Tag = "BackgroundLayer",
                            // ✅ QC_4.2_GRID_PROTECT (G-1): Grid không bao giờ nhận touch/click
                            IsHitTestVisible = false
                        };
                        patternRect.SetBinding(FrameworkElement.WidthProperty, new System.Windows.Data.Binding("ActualWidth") { Source = MainInteractiveBoard });
                        patternRect.SetBinding(FrameworkElement.HeightProperty, new System.Windows.Data.Binding("ActualHeight") { Source = MainInteractiveBoard });
                        MainInteractiveBoard.Children.Insert(1, patternRect);
                        // ✅ QC_4.2_GRID_PROTECT (G-2): Pin tại (0,0) tránh NaN position
                        Canvas.SetLeft(patternRect, 0);
                        Canvas.SetTop(patternRect, 0);
                        Panel.SetZIndex(patternRect, ZIndexConstants.GridOverlay);
                    }

                    // Set canvas background to transparent
                    MainInteractiveBoard.Background = Brushes.Transparent;
                }
                else
                {
                    // No image, fallback to chalkboard green
                    MainInteractiveBoard.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3D6D64"));
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Lỗi khi áp dụng ảnh nền: {ex.Message}", "Lỗi",
                              MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        /// <summary>
        /// âœ¨ Create combined brush with background color + pattern overlay
        /// </summary>
        private Brush CreateCombinedBrush(string? backgroundColor, string pattern)
        {
            // Get the pattern brush first to determine viewport size
            var patternBrush = CreatePatternBrushByName(pattern);
            
            // Determine viewport size from pattern
            Rect viewport = new Rect(0, 0, 20, 20); // Default
            if (patternBrush is DrawingBrush pb)
            {
                viewport = pb.Viewport;
            }
            
            // Create a new DrawingBrush for the combined result
            var combinedBrush = new DrawingBrush
            {
                TileMode = TileMode.Tile,
                Viewport = viewport,
                ViewportUnits = BrushMappingMode.Absolute
            };
            
            var drawingGroup = new DrawingGroup();
            
            // Layer 1: Background color (full tile)
            if (!string.IsNullOrEmpty(backgroundColor))
            {
                try
                {
                    var color = (Color)ColorConverter.ConvertFromString(backgroundColor);
                    drawingGroup.Children.Add(new GeometryDrawing
                    {
                        Brush = new SolidColorBrush(color),
                        Geometry = new RectangleGeometry(viewport)
                    });
                }
                catch
                {
                    // Fallback to white if color parsing fails
                    drawingGroup.Children.Add(new GeometryDrawing
                    {
                        Brush = Brushes.White,
                        Geometry = new RectangleGeometry(viewport)
                    });
                }
            }
            
            // Layer 2: Pattern overlay
            if (patternBrush is DrawingBrush patternDb && patternDb.Drawing is DrawingGroup patternGroup)
            {
                foreach (var child in patternGroup.Children)
                {
                    drawingGroup.Children.Add(child);
                }
            }
            
            combinedBrush.Drawing = drawingGroup;
            return combinedBrush;
        }

        /// <summary>
        /// ✨ Refactor: Tách logic tạo pattern thành method riêng
        /// </summary>
        private Brush? CreatePatternBrushByName(string pattern)
        {
            switch (pattern)
            {
                case "Grid": return CreateGridPattern();
                case "Dots": return CreateDotsPattern();
                case "Lines": return CreateLinesPattern();
                case "MusicStaff": return CreateMusicStaffPattern();
                default: return null;
            }
        }

        private Brush CreateGridPattern()
        {
            var drawingBrush = new DrawingBrush
            {
                TileMode = TileMode.Tile,
                Viewport = new Rect(0, 0, _currentLineSpacing, _currentLineSpacing), // Dynamic spacing
                ViewportUnits = BrushMappingMode.Absolute
            };

            var drawingGroup = new DrawingGroup();
            
            // Calculate alpha from opacity percentage (0-100 → 0-255)
            byte alpha = (byte)(_currentLineOpacity * 255 / 100);
            
            // Vertical line
            drawingGroup.Children.Add(new GeometryDrawing
            {
                Pen = new Pen(new SolidColorBrush(Color.FromArgb(alpha, 0, 0, 0)), 1),
                Geometry = new LineGeometry(new Point(0, 0), new Point(0, _currentLineSpacing))
            });
            
            // Horizontal line
            drawingGroup.Children.Add(new GeometryDrawing
            {
                Pen = new Pen(new SolidColorBrush(Color.FromArgb(alpha, 0, 0, 0)), 1),
                Geometry = new LineGeometry(new Point(0, 0), new Point(_currentLineSpacing, 0))
            });

            drawingBrush.Drawing = drawingGroup;
            return drawingBrush;
        }

        private Brush CreateDotsPattern()
        {
            var drawingBrush = new DrawingBrush
            {
                TileMode = TileMode.Tile,
                Viewport = new Rect(0, 0, 30, 30),
                ViewportUnits = BrushMappingMode.Absolute
            };

            var drawingGroup = new DrawingGroup();
            
            // Dot
            drawingGroup.Children.Add(new GeometryDrawing
            {
                Brush = new SolidColorBrush(Color.FromArgb(40, 0, 0, 0)),
                Geometry = new EllipseGeometry(new Point(15, 15), 0.5, 0.5)
            });

            drawingBrush.Drawing = drawingGroup;
            return drawingBrush;
        }

        /// <summary>
        /// Create horizontal lines pattern (with dynamic spacing)
        /// </summary>
        private Brush CreateLinesPattern()
        {
            // Create drawing brush with dynamic spacing
            var brush = new DrawingBrush
            {
                TileMode = TileMode.Tile,
                Viewport = new Rect(0, 0, 1, _currentLineSpacing), // Dynamic spacing
                ViewportUnits = BrushMappingMode.Absolute,
                Stretch = Stretch.None
            };

            // Create drawing group
            var group = new DrawingGroup();
            
            // Calculate alpha from opacity percentage (0-100 → 0-255)
            byte alpha = (byte)(_currentLineOpacity * 255 / 100);
            
            // Draw a single horizontal line at the top of the tile
            var linePen = new Pen(new SolidColorBrush(Color.FromArgb(alpha, 0, 0, 0)), 1);
            linePen.Freeze(); // Freeze for performance
            
            group.Children.Add(new GeometryDrawing
            {
                Pen = linePen,
                Geometry = new LineGeometry(new Point(0, 0), new Point(1, 0))
            });

            brush.Drawing = group;
            brush.Freeze(); // Freeze for performance
            
            return brush;
        }

        private Brush CreateMusicStaffPattern()
        {
            // Calculate total height for 5 lines with dynamic spacing
            int totalHeight = _currentLineSpacing * 4; // 4 gaps between 5 lines
            
            var drawingBrush = new DrawingBrush
            {
                TileMode = TileMode.Tile,
                Viewport = new Rect(0, 0, 100, totalHeight),
                ViewportUnits = BrushMappingMode.Absolute
            };

            var drawingGroup = new DrawingGroup();
            
            // Calculate alpha from opacity percentage (0-100 → 0-255)
            byte alpha = (byte)(_currentLineOpacity * 255 / 100);
            
            // 5 lines for music staff with dynamic spacing
            for (int i = 0; i < 5; i++)
            {
                drawingGroup.Children.Add(new GeometryDrawing
                {
                    Pen = new Pen(new SolidColorBrush(Color.FromArgb(alpha, 0, 0, 0)), 1),
                    Geometry = new LineGeometry(new Point(0, i * _currentLineSpacing), new Point(100, i * _currentLineSpacing))
                });
            }

            drawingBrush.Drawing = drawingGroup;
            return drawingBrush;
        }

