        #region Pan Mode (Drag to Scroll)

        private bool _isPanModeActive = false;
        private Point _scrollPanStartPoint;
        private double _scrollPanStartHorizontalOffset;
        private double _scrollPanStartVerticalOffset;

        /// <summary>
        /// Enable pan mode - allows dragging to scroll the canvas
        /// </summary>
        public void EnablePanMode()
        {
            if (_isPanModeActive)
            {
                // Disable pan mode
                DisablePanMode();
                return;
            }

            // QC_4.2_PAN_MODE_CLEANUP: Tắt hoàn toàn chế độ Bút vẽ và dọn dẹp stroke khi bắt đầu Pan Mode
            _drawingEnabled = false;
            _isDrawing = false;
            _currentStroke = null;
            _eraserEnabled = false;

            _isPanModeActive = true;

            // Change cursor to hand
            MainScrollViewer.Cursor = Cursors.Hand;
            MainInteractiveBoard.Cursor = Cursors.Hand;

            // Subscribe to mouse events for dragging
            MainScrollViewer.PreviewMouseLeftButtonDown += ScrollViewer_PreviewMouseLeftButtonDown;
            MainScrollViewer.PreviewMouseMove += ScrollViewer_PreviewMouseMove;
            MainScrollViewer.PreviewMouseLeftButtonUp += ScrollViewer_PreviewMouseLeftButtonUp;

            // Subscribe to ESC key to exit pan mode
            this.PreviewKeyDown += PanMode_PreviewKeyDown;

            System.Diagnostics.Debug.WriteLine("✅ Pan mode enabled - drag to scroll, ESC to exit");
        }

        private void DisablePanMode()
        {
            _isPanModeActive = false;

            // Release capture if held
            if (MainScrollViewer.IsMouseCaptured)
                MainScrollViewer.ReleaseMouseCapture();
            if (MainInteractiveBoard.IsMouseCaptured)
                MainInteractiveBoard.ReleaseMouseCapture();

            // Restore cursor based on current tool mode
            Cursor defaultCursor = _drawingEnabled ? Cursors.Pen : Cursors.Arrow;
            MainScrollViewer.Cursor = defaultCursor;
            MainInteractiveBoard.Cursor = defaultCursor;

            // Unsubscribe from events
            MainScrollViewer.PreviewMouseLeftButtonDown -= ScrollViewer_PreviewMouseLeftButtonDown;
            MainScrollViewer.PreviewMouseMove -= ScrollViewer_PreviewMouseMove;
            MainScrollViewer.PreviewMouseLeftButtonUp -= ScrollViewer_PreviewMouseLeftButtonUp;
            this.PreviewKeyDown -= PanMode_PreviewKeyDown;

            System.Diagnostics.Debug.WriteLine("✅ Pan mode disabled - restored cursor & released mouse capture");
        }

        #region Pointer Mode (Chỉ Bảng) Implementation
        public bool _isPointerModeActive = false;
        private Grid? _pointerGraphicContainer;

        /// <summary>
        /// Enable Pointer Tool (Chỉ Bảng) - High-visibility animated laser pointer arrow for teaching
        /// </summary>
        public void EnablePointerMode()
        {
            if (_isPointerModeActive)
            {
                DisablePointerMode();
                return;
            }

            // Mode Guard: Turn off all other active tools
            if (_isPanModeActive) DisablePanMode();
            if (_eraserEnabled) DisableEraserMode();

            if (MainScrollViewer.IsMouseCaptured) MainScrollViewer.ReleaseMouseCapture();
            if (MainInteractiveBoard.IsMouseCaptured) MainInteractiveBoard.ReleaseMouseCapture();

            _isDrawing = false;
            _currentStroke = null;

            _drawingEnabled = false;
            _eraserEnabled = false;
            _shapeDrawingEnabled = false;
            _textToolEnabled = false;
            _selectionToolEnabled = false;
            _objectSelectionMode = false;
            _isPointerModeActive = true;

            _selectionManager?.DeselectAll();

            MainInteractiveBoard.Cursor = Cursors.None;
            MainScrollViewer.Cursor = Cursors.None;

            if (_touchHandler != null)
            {
                _touchHandler.SetToolMode(QASmartTouch.Handlers.TouchToolMode.Pointer);
                _touchHandler.SetUpdatePointerAction(UpdatePointerPosition);
            }

            CreatePointerGraphic();
            ShowSmartStatusBadge("📌 Đang bật công cụ Chỉ bảng - Chạm hoặc di chuyển để chỉ điểm");
            System.Diagnostics.Debug.WriteLine("📌 Pointer mode enabled");
        }

        /// <summary>
        /// Disable Pointer Tool (Chỉ Bảng)
        /// </summary>
        public void DisablePointerMode()
        {
            _isPointerModeActive = false;
            RemovePointerGraphic();
            HideSmartStatusBadge();

            MainInteractiveBoard.Cursor = Cursors.Arrow;
            MainScrollViewer.Cursor = Cursors.Arrow;
            System.Diagnostics.Debug.WriteLine("📌 Pointer mode disabled");
        }

        private void CreatePointerGraphic()
        {
            RemovePointerGraphic();

            _pointerGraphicContainer = new Grid
            {
                Width = 72,
                Height = 72,
                IsHitTestVisible = false,
                Tag = "PointerGraphicOverlay"
            };

            // 1. Glowing Laser Pulsing Outer Ring
            var laserPulse = new System.Windows.Shapes.Ellipse
            {
                Width = 28,
                Height = 28,
                Fill = new SolidColorBrush(Color.FromArgb(120, 255, 0, 80)),
                HorizontalAlignment = HorizontalAlignment.Left,
                VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(-14, -14, 0, 0)
            };

            // 2. Center Laser Red Dot
            var laserDot = new System.Windows.Shapes.Ellipse
            {
                Width = 14,
                Height = 14,
                Fill = new SolidColorBrush(Color.FromRgb(255, 30, 60)),
                Stroke = new SolidColorBrush(Colors.White),
                StrokeThickness = 2,
                HorizontalAlignment = HorizontalAlignment.Left,
                VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(-7, -7, 0, 0)
            };

            // 3. Large High-Contrast Pointer Arrow (Mũi tên Đỏ + Viền Vàng + Bóng Đổ 3D)
            var pointerArrow = new System.Windows.Shapes.Polygon
            {
                Points = new PointCollection
                {
                    new Point(0, 0),       // Arrow Tip
                    new Point(0, 48),      // Bottom Left
                    new Point(14, 34),     // Inner notch
                    new Point(28, 56),     // Tail tip
                    new Point(38, 50),     // Tail right
                    new Point(24, 28),     // Tail inner
                    new Point(42, 28)      // Right tip
                },
                Fill = new LinearGradientBrush(
                    Color.FromRgb(255, 45, 85),
                    Color.FromRgb(220, 0, 50),
                    90),
                Stroke = new SolidColorBrush(Color.FromRgb(255, 215, 0)),
                StrokeThickness = 3.5,
                StrokeLineJoin = PenLineJoin.Round,
                Effect = new System.Windows.Media.Effects.DropShadowEffect
                {
                    Color = Colors.Black,
                    BlurRadius = 10,
                    ShadowDepth = 4,
                    Opacity = 0.6
                }
            };

            _pointerGraphicContainer.Children.Add(laserPulse);
            _pointerGraphicContainer.Children.Add(pointerArrow);
            _pointerGraphicContainer.Children.Add(laserDot);

            Canvas.SetLeft(_pointerGraphicContainer, MainInteractiveBoard.ActualWidth / 2);
            Canvas.SetTop(_pointerGraphicContainer, MainInteractiveBoard.ActualHeight / 2);
            Panel.SetZIndex(_pointerGraphicContainer, 999999);

            MainInteractiveBoard.Children.Add(_pointerGraphicContainer);
        }

        public void UpdatePointerPosition(Point pos)
        {
            if (_pointerGraphicContainer == null || !_isPointerModeActive) return;

            Canvas.SetLeft(_pointerGraphicContainer, pos.X);
            Canvas.SetTop(_pointerGraphicContainer, pos.Y);
        }

        private void RemovePointerGraphic()
        {
            if (_pointerGraphicContainer != null)
            {
                if (MainInteractiveBoard.Children.Contains(_pointerGraphicContainer))
                {
                    MainInteractiveBoard.Children.Remove(_pointerGraphicContainer);
                }
                _pointerGraphicContainer = null;
            }
        }
        #endregion

        private void ScrollViewer_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            if (!_isPanModeActive || _drawingEnabled)
            {
                if (MainScrollViewer.IsMouseCaptured)
                    MainScrollViewer.ReleaseMouseCapture();
                return;
            }

            // Ensure no drawing occurs during pan drag
            _isDrawing = false;
            _currentStroke = null;

            _scrollPanStartPoint = e.GetPosition(MainScrollViewer);
            _scrollPanStartHorizontalOffset = MainScrollViewer.HorizontalOffset;
            _scrollPanStartVerticalOffset = MainScrollViewer.VerticalOffset;

            MainScrollViewer.CaptureMouse();
            MainScrollViewer.Cursor = Cursors.ScrollAll; // Change to move cursor while dragging
        }

        private void ScrollViewer_PreviewMouseMove(object sender, MouseEventArgs e)
        {
            // QC_4.2_PREVENT_AUTO_SCROLL: Tuyệt đối không cuộn màn hình nếu đang vẽ nét bút hoặc ngắt Pan Mode
            if (!_isPanModeActive || _drawingEnabled || _isDrawing || !MainScrollViewer.IsMouseCaptured)
            {
                return;
            }

            Point currentPoint = e.GetPosition(MainScrollViewer);
            double deltaX = _scrollPanStartPoint.X - currentPoint.X;
            double deltaY = _scrollPanStartPoint.Y - currentPoint.Y;

            MainScrollViewer.ScrollToHorizontalOffset(_scrollPanStartHorizontalOffset + deltaX);
            MainScrollViewer.ScrollToVerticalOffset(_scrollPanStartVerticalOffset + deltaY);
        }

        private void ScrollViewer_PreviewMouseLeftButtonUp(object sender, MouseButtonEventArgs e)
        {
            if (MainScrollViewer.IsMouseCaptured)
            {
                MainScrollViewer.ReleaseMouseCapture();
            }

            if (!_isPanModeActive) return;

            MainScrollViewer.Cursor = Cursors.Hand; // Restore hand cursor
        }

        private void PanMode_PreviewKeyDown(object sender, KeyEventArgs e)
        {
            if (e.Key == Key.Escape && _isPanModeActive)
            {
                DisablePanMode();
                e.Handled = true;
            }
        }

        #endregion

        #region Multi-User Mode (Split Screen for 2 Students)

        private bool _isMultiUserModeActive = false;
        private bool _isCustomColorSelected = false; // Flag to allow custom color override
        private SplitMode _currentSplitMode;
        private StudentProfile? _student1;
        private StudentProfile? _student2;
        private Border? _splitLine;
        private TextBlock? _student1Label;
        private TextBlock? _student2Label;
        private bool _zoneIsolationEnabled = false;
        private bool _showSplitLine = true;

        /// <summary>
        /// Enable multi-user mode with split screen
        /// </summary>
        public void EnableMultiUserMode(SplitMode splitMode, StudentProfile student1, StudentProfile student2, bool zoneIsolation = false, bool showSplitLine = true)
        {
            _isMultiUserModeActive = true;
            _isCustomColorSelected = false; // Reset to use student team colors initially
            _currentSplitMode = splitMode;
            _student1 = student1;
            _student2 = student2;
            _zoneIsolationEnabled = zoneIsolation;
            _showSplitLine = showSplitLine;

            // Create visual split line
            CreateSplitLine();

            // Create student labels
            CreateStudentLabels();

            System.Diagnostics.Debug.WriteLine($"✅ Multi-user mode enabled - {splitMode}, {student1.Name} vs {student2.Name}, Isolation={zoneIsolation}, ShowLine={showSplitLine}");
        }

        /// <summary>
        /// Disable multi-user mode
        /// </summary>
        public void DisableMultiUserMode()
        {
            _isMultiUserModeActive = false;
            _isCustomColorSelected = false;
            _student1 = null;
            _student2 = null;

            // Remove split line
            if (_splitLine != null && MainInteractiveBoard.Children.Contains(_splitLine))
            {
                MainInteractiveBoard.Children.Remove(_splitLine);
                _splitLine = null;
            }

            // Remove labels
            if (_student1Label != null && MainInteractiveBoard.Children.Contains(_student1Label))
            {
                MainInteractiveBoard.Children.Remove(_student1Label);
                _student1Label = null;
            }

            if (_student2Label != null && MainInteractiveBoard.Children.Contains(_student2Label))
            {
                MainInteractiveBoard.Children.Remove(_student2Label);
                _student2Label = null;
            }

            System.Diagnostics.Debug.WriteLine("✅ Multi-user mode disabled");
        }

        private void CreateSplitLine()
        {
            // Remove old split line if exists
            if (_splitLine != null && MainInteractiveBoard.Children.Contains(_splitLine))
            {
                MainInteractiveBoard.Children.Remove(_splitLine);
            }

            _splitLine = new Border
            {
                Tag = "MultiUserSplitLine",
                Background = new SolidColorBrush(Color.FromArgb(100, 0, 0, 0)), // Semi-transparent
                BorderBrush = new SolidColorBrush(Colors.Gray),
                BorderThickness = new Thickness(2),
                Visibility = _showSplitLine ? Visibility.Visible : Visibility.Collapsed
            };

            if (_currentSplitMode == SplitMode.Vertical)
            {
                // Vertical split line (middle of canvas)
                _splitLine.Width = 4;
                _splitLine.Height = MainInteractiveBoard.ActualHeight;
                Canvas.SetLeft(_splitLine, MainInteractiveBoard.ActualWidth / 2 - 2);
                Canvas.SetTop(_splitLine, 0);
            }
            else
            {
                // Horizontal split line (middle of canvas)
                _splitLine.Width = MainInteractiveBoard.ActualWidth;
                _splitLine.Height = 4;
                Canvas.SetLeft(_splitLine, 0);
                Canvas.SetTop(_splitLine, MainInteractiveBoard.ActualHeight / 2 - 2);
            }

            MainInteractiveBoard.Children.Add(_splitLine);
        }

        private void CreateStudentLabels()
        {
            // Remove old labels
            if (_student1Label != null && MainInteractiveBoard.Children.Contains(_student1Label))
            {
                MainInteractiveBoard.Children.Remove(_student1Label);
            }
            if (_student2Label != null && MainInteractiveBoard.Children.Contains(_student2Label))
            {
                MainInteractiveBoard.Children.Remove(_student2Label);
            }

            if (_student1 == null || _student2 == null) return;

            // Create student 1 label
            _student1Label = new TextBlock
            {
                Tag = "MultiUserLabel",
                Text = _student1.Name,
                FontSize = 24,
                FontWeight = FontWeights.Bold,
                Foreground = _student1.GetBrush(),
                Background = new SolidColorBrush(Color.FromArgb(200, 255, 255, 255)),
                Padding = new Thickness(15, 8, 15, 8)
            };

            // Create student 2 label
            _student2Label = new TextBlock
            {
                Tag = "MultiUserLabel",
                Text = _student2.Name,
                FontSize = 24,
                FontWeight = FontWeights.Bold,
                Foreground = _student2.GetBrush(),
                Background = new SolidColorBrush(Color.FromArgb(200, 255, 255, 255)),
                Padding = new Thickness(15, 8, 15, 8)
            };

            if (_currentSplitMode == SplitMode.Vertical)
            {
                // Position labels for vertical split
                Canvas.SetLeft(_student1Label, 20);
                Canvas.SetTop(_student1Label, 20);

                Canvas.SetLeft(_student2Label, MainInteractiveBoard.ActualWidth / 2 + 20);
                Canvas.SetTop(_student2Label, 20);
            }
            else
            {
                // Position labels for horizontal split
                Canvas.SetLeft(_student1Label, 20);
                Canvas.SetTop(_student1Label, 20);

                Canvas.SetLeft(_student2Label, 20);
                Canvas.SetTop(_student2Label, MainInteractiveBoard.ActualHeight / 2 + 20);
            }

            MainInteractiveBoard.Children.Add(_student1Label);
            MainInteractiveBoard.Children.Add(_student2Label);
        }

        /// <summary>
        /// Get student profile based on touch position
        /// </summary>
        private StudentProfile? GetStudentByPosition(Point position)
        {
            if (!_isMultiUserModeActive || _student1 == null || _student2 == null || _isCustomColorSelected)
                return null;

            if (_currentSplitMode == SplitMode.Vertical)
            {
                // Left half = Student 1, Right half = Student 2
                return position.X < MainInteractiveBoard.ActualWidth / 2 ? _student1 : _student2;
            }
            else
            {
                // Top half = Student 1, Bottom half = Student 2
                return position.Y < MainInteractiveBoard.ActualHeight / 2 ? _student1 : _student2;
            }
        }

