            };
            btnZoomOut.Content = CreateButtonIcon("M19,13H5V11H19V13Z", Colors.White);
            btnZoomOut.Click += BtnPhETZoomOut_Click;
            panel.Children.Add(btnZoomOut);

            // Delete Button
            var btnDelete = new Button
            {
                Width = 44,
