                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = "Xóa"
            };
            btnDelete.Content = CreateButtonIcon("M19,4H15.5L14.5,3H9.5L8.5,4H5V6H19M6,19A2,2 0 0,0 8,21H16A2,2 0 0,0 18,19V7H6V19Z", Colors.White);
            btnDelete.Click += BtnPhETDelete_Click;
